impl NativeArrayPointerOperation {
    fn from_tag(operation: u8) -> Result<Self, NativeArrayLvalueResult> {
        match operation {
            NATIVE_ARRAY_LVALUE_POINTER_CURRENT => Ok(Self::Current),
            NATIVE_ARRAY_LVALUE_POINTER_KEY => Ok(Self::Key),
            NATIVE_ARRAY_LVALUE_POINTER_NEXT => Ok(Self::Next),
            NATIVE_ARRAY_LVALUE_POINTER_PREV => Ok(Self::Prev),
            NATIVE_ARRAY_LVALUE_POINTER_RESET => Ok(Self::Reset),
            NATIVE_ARRAY_LVALUE_POINTER_END => Ok(Self::End),
            _ => Err(NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                format!("array lvalue pointer/cursor operation tag {operation} is not supported"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Current => "current",
            Self::Key => "key",
            Self::Next => "next",
            Self::Prev => "prev",
            Self::Reset => "reset",
            Self::End => "end",
        }
    }

    fn mutates_owner(self) -> bool {
        !matches!(self, Self::Current | Self::Key)
    }
}

impl PhpArraySortOperation {
    pub fn callable(self) -> &'static str {
        match self {
            Self::Sort => "sort()",
            Self::Rsort => "rsort()",
            Self::Asort => "asort()",
            Self::Arsort => "arsort()",
            Self::Ksort => "ksort()",
            Self::Krsort => "krsort()",
            Self::Natsort => "natsort()",
            Self::Natcasesort => "natcasesort()",
        }
    }

    fn native_operation(self) -> NativeArraySortOperation {
        match self {
            Self::Sort => NativeArraySortOperation::Sort,
            Self::Rsort => NativeArraySortOperation::Rsort,
            Self::Asort => NativeArraySortOperation::Asort,
            Self::Arsort => NativeArraySortOperation::Arsort,
            Self::Ksort => NativeArraySortOperation::Ksort,
            Self::Krsort => NativeArraySortOperation::Krsort,
            Self::Natsort => NativeArraySortOperation::Natsort,
            Self::Natcasesort => NativeArraySortOperation::Natcasesort,
        }
    }

    fn accepts_sort_flag(self) -> bool {
        matches!(
            self,
            Self::Sort | Self::Rsort | Self::Asort | Self::Arsort | Self::Ksort | Self::Krsort
        )
    }

    fn sorts_keys(self) -> bool {
        matches!(self, Self::Ksort | Self::Krsort)
    }

    fn preserves_keys(self) -> bool {
        matches!(
            self,
            Self::Asort
                | Self::Arsort
                | Self::Ksort
                | Self::Krsort
                | Self::Natsort
                | Self::Natcasesort
        )
    }

    fn reverses_order(self) -> bool {
        matches!(self, Self::Rsort | Self::Arsort | Self::Krsort)
    }
}

impl NativeArraySortOperation {
    fn from_tag(operation: u8) -> Result<Self, NativeArrayLvalueResult> {
        match operation {
            NATIVE_ARRAY_LVALUE_SORT_SORT => Ok(Self::Sort),
            NATIVE_ARRAY_LVALUE_SORT_RSORT => Ok(Self::Rsort),
            NATIVE_ARRAY_LVALUE_SORT_ASORT => Ok(Self::Asort),
            NATIVE_ARRAY_LVALUE_SORT_ARSORT => Ok(Self::Arsort),
            NATIVE_ARRAY_LVALUE_SORT_KSORT => Ok(Self::Ksort),
            NATIVE_ARRAY_LVALUE_SORT_KRSORT => Ok(Self::Krsort),
            NATIVE_ARRAY_LVALUE_SORT_NATSORT => Ok(Self::Natsort),
            NATIVE_ARRAY_LVALUE_SORT_NATCASESORT => Ok(Self::Natcasesort),
            NATIVE_ARRAY_LVALUE_SORT_USORT => Ok(Self::Usort),
            NATIVE_ARRAY_LVALUE_SORT_UASORT => Ok(Self::Uasort),
            NATIVE_ARRAY_LVALUE_SORT_UKSORT => Ok(Self::Uksort),
            _ => Err(NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                format!("array lvalue sort operation tag {operation} is not supported"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Sort => "sort",
            Self::Rsort => "rsort",
            Self::Asort => "asort",
            Self::Arsort => "arsort",
            Self::Ksort => "ksort",
            Self::Krsort => "krsort",
            Self::Natsort => "natsort",
            Self::Natcasesort => "natcasesort",
            Self::Usort => "usort",
            Self::Uasort => "uasort",
            Self::Uksort => "uksort",
        }
    }

    fn callable(self) -> &'static str {
        match self {
            Self::Sort => "sort()",
            Self::Rsort => "rsort()",
            Self::Asort => "asort()",
            Self::Arsort => "arsort()",
            Self::Ksort => "ksort()",
            Self::Krsort => "krsort()",
            Self::Natsort => "natsort()",
            Self::Natcasesort => "natcasesort()",
            Self::Usort => "usort()",
            Self::Uasort => "uasort()",
            Self::Uksort => "uksort()",
        }
    }

    fn operand_count_is_supported(self, operand_count: usize) -> bool {
        match self {
            Self::Sort | Self::Rsort | Self::Asort | Self::Arsort | Self::Ksort | Self::Krsort => {
                operand_count <= 1
            }
            Self::Natsort | Self::Natcasesort => operand_count == 0,
            Self::Usort | Self::Uasort | Self::Uksort => operand_count == 1,
        }
    }

    fn uses_mode_sort(self) -> bool {
        matches!(
            self,
            Self::Sort | Self::Rsort | Self::Asort | Self::Arsort | Self::Ksort | Self::Krsort
        )
    }

    fn uses_natural_sort(self) -> bool {
        matches!(self, Self::Natsort | Self::Natcasesort)
    }

    fn uses_comparator_sort(self) -> bool {
        matches!(self, Self::Usort | Self::Uasort | Self::Uksort)
    }

    fn uses_comparator_free_sort(self) -> bool {
        self.uses_mode_sort() || self.uses_natural_sort()
    }

    fn sorts_keys(self) -> bool {
        matches!(self, Self::Ksort | Self::Krsort | Self::Uksort)
    }

    fn preserves_keys(self) -> bool {
        matches!(
            self,
            Self::Asort | Self::Arsort | Self::Ksort | Self::Krsort | Self::Uasort | Self::Uksort
        )
    }

    fn reverses_order(self) -> bool {
        matches!(self, Self::Rsort | Self::Arsort | Self::Krsort)
    }

    fn supports_runtime_callable_writeback(self) -> bool {
        matches!(
            self,
            Self::Sort
                | Self::Rsort
                | Self::Asort
                | Self::Arsort
                | Self::Ksort
                | Self::Krsort
                | Self::Natsort
                | Self::Natcasesort
                | Self::Usort
                | Self::Uasort
                | Self::Uksort
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PhpArraySortFlagMode {
    Regular,
    Numeric,
    String { case_insensitive: bool },
    Natural { case_insensitive: bool },
}

fn php_array_sort_mode_from_flag(
    operation: PhpArraySortOperation,
    flag: Option<&Value>,
) -> RuntimeResult<PhpArraySortFlagMode> {
    if !operation.accepts_sort_flag() {
        if let Some(flag) = flag {
            return Err(RuntimeError::unsupported_call(
                operation.callable(),
                format!(
                    "{} does not accept a sort flag argument in the current subset, got {}",
                    operation.callable(),
                    flag.type_name()
                ),
            ));
        }
        return Ok(PhpArraySortFlagMode::Natural {
            case_insensitive: matches!(operation, PhpArraySortOperation::Natcasesort),
        });
    }

    let Some(flag) = flag else {
        return Ok(PhpArraySortFlagMode::Regular);
    };
    let raw = native_array_sort_flag_integer(operation.native_operation(), flag)
        .map_err(|message| RuntimeError::unsupported_call(operation.callable(), message))?;

    match raw {
        0 => Ok(PhpArraySortFlagMode::Regular),
        1 => Ok(PhpArraySortFlagMode::Numeric),
        2 => Ok(PhpArraySortFlagMode::String {
            case_insensitive: false,
        }),
        6 => Ok(PhpArraySortFlagMode::Natural {
            case_insensitive: false,
        }),
        10 => Ok(PhpArraySortFlagMode::String {
            case_insensitive: true,
        }),
        14 => Ok(PhpArraySortFlagMode::Natural {
            case_insensitive: true,
        }),
        other => Err(RuntimeError::unsupported_call(
            operation.callable(),
            format!(
                "sort flag parameter {other} is not supported; only SORT_REGULAR (0), SORT_NUMERIC (1), SORT_STRING (2), SORT_NATURAL (6), and SORT_FLAG_CASE combinations with SORT_STRING/SORT_NATURAL are implemented"
            ),
        )),
    }
}

impl NativeArrayMutationOperation {
    fn from_tag(operation: u8) -> Result<Self, NativeArrayLvalueResult> {
        match operation {
            NATIVE_ARRAY_LVALUE_MUTATION_PUSH => Ok(Self::Push),
            NATIVE_ARRAY_LVALUE_MUTATION_POP => Ok(Self::Pop),
            NATIVE_ARRAY_LVALUE_MUTATION_SHIFT => Ok(Self::Shift),
            NATIVE_ARRAY_LVALUE_MUTATION_UNSHIFT => Ok(Self::Unshift),
            _ => Err(NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                format!("array lvalue mutation operation tag {operation} is not supported"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Push => "array_push",
            Self::Pop => "array_pop",
            Self::Shift => "array_shift",
            Self::Unshift => "array_unshift",
        }
    }

    fn operand_count_is_supported(self, operand_count: usize) -> bool {
        match self {
            Self::Push | Self::Unshift => operand_count >= 1,
            Self::Pop | Self::Shift => operand_count == 0,
        }
    }
}

impl NativeValueArrayCallbackOperation {
    fn from_tag(operation: u8) -> Result<Self, NativeArrayLvalueResult> {
        match operation {
            NATIVE_VALUE_ARRAY_CALLBACK_FILTER => Ok(Self::Filter),
            NATIVE_VALUE_ARRAY_CALLBACK_MAP => Ok(Self::Map),
            NATIVE_VALUE_ARRAY_CALLBACK_REDUCE => Ok(Self::Reduce),
            _ => Err(NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                format!("native value array callback operation tag {operation} is not supported"),
            )),
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Filter => "array_filter",
            Self::Map => "array_map",
            Self::Reduce => "array_reduce",
        }
    }

    fn operand_count_is_supported(self, count: usize) -> bool {
        match self {
            Self::Filter => (2..=3).contains(&count),
            Self::Map => count >= 2,
            Self::Reduce => (2..=3).contains(&count),
        }
    }
}

impl NativeValueArrayQueryOperation {
    fn from_tag(operation: u8) -> Result<Self, RuntimeError> {
        match operation {
            NATIVE_VALUE_ARRAY_QUERY_COUNT => Ok(Self::Count),
            NATIVE_VALUE_ARRAY_QUERY_KEYS_MATCHING => Ok(Self::KeysMatching),
            NATIVE_VALUE_ARRAY_QUERY_CONTAINS => Ok(Self::Contains),
            NATIVE_VALUE_ARRAY_QUERY_SEARCH => Ok(Self::Search),
            NATIVE_VALUE_ARRAY_QUERY_FLIP => Ok(Self::Flip),
            NATIVE_VALUE_ARRAY_QUERY_COUNT_VALUES => Ok(Self::CountValues),
            NATIVE_VALUE_ARRAY_QUERY_SUM => Ok(Self::Sum),
            NATIVE_VALUE_ARRAY_QUERY_PRODUCT => Ok(Self::Product),
            NATIVE_VALUE_ARRAY_QUERY_FILL_KEYS => Ok(Self::FillKeys),
            NATIVE_VALUE_ARRAY_QUERY_COMBINE => Ok(Self::Combine),
            NATIVE_VALUE_ARRAY_QUERY_CHANGE_KEY_CASE => Ok(Self::ChangeKeyCase),
            NATIVE_VALUE_ARRAY_QUERY_COLUMN => Ok(Self::Column),
            _ => Err(RuntimeError::invalid_array_access(
                "native value array query operation failed: unsupported operation tag",
            )),
        }
    }

    fn callable(self) -> &'static str {
        match self {
            Self::Count => "count()",
            Self::KeysMatching => "array_keys()",
            Self::Contains => "in_array()",
            Self::Search => "array_search()",
            Self::Flip => "array_flip()",
            Self::CountValues => "array_count_values()",
            Self::Sum => "array_sum()",
            Self::Product => "array_product()",
            Self::FillKeys => "array_fill_keys()",
            Self::Combine => "array_combine()",
            Self::ChangeKeyCase => "array_change_key_case()",
            Self::Column => "array_column()",
        }
    }

    fn array_argument_label(self) -> &'static str {
        match self {
            Self::Count => "argument",
            Self::Column => "first argument",
            Self::KeysMatching
            | Self::Contains
            | Self::Search
            | Self::Flip
            | Self::CountValues
            | Self::Sum
            | Self::Product
            | Self::FillKeys
            | Self::Combine
            | Self::ChangeKeyCase => "argument",
        }
    }

    fn min_operand_count(self) -> usize {
        match self {
            Self::KeysMatching
            | Self::Contains
            | Self::Search
            | Self::FillKeys
            | Self::Combine
            | Self::Column => 1,
            Self::Count
            | Self::Flip
            | Self::CountValues
            | Self::Sum
            | Self::Product
            | Self::ChangeKeyCase => 0,
        }
    }

    fn max_operand_count(self) -> usize {
        match self {
            Self::KeysMatching
            | Self::Contains
            | Self::Search
            | Self::FillKeys
            | Self::Combine
            | Self::ChangeKeyCase => 1,
            Self::Column => 2,
            Self::Count | Self::Flip | Self::CountValues | Self::Sum | Self::Product => 0,
        }
    }

    fn accepts_flags(self) -> bool {
        matches!(self, Self::KeysMatching | Self::Contains | Self::Search)
    }
}

impl NativeReferencePredicate {
    fn from_tag(predicate: u8) -> RuntimeResult<Self> {
        match predicate {
            NATIVE_REFERENCE_PREDICATE_ISSET => Ok(Self::Isset),
            NATIVE_REFERENCE_PREDICATE_EMPTY => Ok(Self::Empty),
            NATIVE_REFERENCE_PREDICATE_TRUTHY => Ok(Self::Truthy),
            _ => Err(RuntimeError::invalid_string_conversion(format!(
                "native reference predicate tag {predicate} is not supported"
            ))),
        }
    }

    fn evaluate(self, value: &Value) -> bool {
        match self {
            Self::Isset => !matches!(value, Value::Null),
            Self::Empty => !value.is_truthy(),
            Self::Truthy => value.is_truthy(),
        }
    }
}

