impl NativeStringOffsetOperation {
    fn from_tag(tag: u8) -> RuntimeResult<Self> {
        match tag {
            tag if tag == Self::Read as u8 => Ok(Self::Read),
            tag if tag == Self::Isset as u8 => Ok(Self::Isset),
            tag if tag == Self::Empty as u8 => Ok(Self::Empty),
            _ => Err(RuntimeError::invalid_string_conversion(
                "native string offset operation failed: unsupported operation tag",
            )),
        }
    }
}

impl NativeArrayAccessOffsetWriteOperation {
    fn from_tag(tag: u8) -> RuntimeResult<Self> {
        match tag {
            tag if tag == Self::Write as u8 => Ok(Self::Write),
            tag if tag == Self::Append as u8 => Ok(Self::Append),
            tag if tag == Self::Unset as u8 => Ok(Self::Unset),
            _ => Err(RuntimeError::invalid_array_access(
                "native ArrayAccess offset write dispatch failed: unsupported operation tag",
            )),
        }
    }

    fn method_name(self) -> &'static str {
        match self {
            Self::Write | Self::Append => "offsetSet",
            Self::Unset => "offsetUnset",
        }
    }

    fn replacement_label(self) -> &'static str {
        match self {
            Self::Write => "write",
            Self::Append => "append",
            Self::Unset => "unset",
        }
    }
}

impl NativeArrayAccessOffsetReadOperation {
    fn from_tag(tag: u8) -> RuntimeResult<Self> {
        match tag {
            tag if tag == Self::Get as u8 => Ok(Self::Get),
            tag if tag == Self::Exists as u8 => Ok(Self::Exists),
            _ => Err(RuntimeError::invalid_array_access(
                "native ArrayAccess offset read dispatch failed: unsupported operation tag",
            )),
        }
    }

    fn method_name(self) -> &'static str {
        match self {
            Self::Get => "offsetGet",
            Self::Exists => "offsetExists",
        }
    }

    fn offset_label(self) -> &'static str {
        match self {
            Self::Get => "get",
            Self::Exists => "exists",
        }
    }
}

