impl NativeRequestState {
    fn empty() -> Self {
        Self {
            superglobals: HashMap::new(),
            root_values: HashMap::new(),
            unset_roots: HashSet::new(),
        }
    }

    fn clear_superglobal_root_override(&mut self, bag: NativeRequestStateBag) {
        self.root_values.remove(&bag);
        self.unset_roots.remove(&bag);
    }

    fn insert_superglobal_value(
        &mut self,
        bag: NativeRequestStateBag,
        key: impl AsRef<[u8]>,
        value: Value,
    ) -> bool {
        let Some(key) = request_state_array_key(key.as_ref()) else {
            return false;
        };
        self.clear_superglobal_root_override(bag);
        self.superglobals.entry(bag).or_default().insert(key, value);
        true
    }

    fn superglobal_root_value(
        &self,
        bag: NativeRequestStateBag,
    ) -> Result<Value, NativeRequestStateOperationStatus> {
        if self.unset_roots.contains(&bag) {
            return Err(NativeRequestStateOperationStatus::MissingRoot);
        }
        Ok(self.superglobal_snapshot_value(bag))
    }

    fn superglobal_root_exists(&self, bag: NativeRequestStateBag) -> bool {
        !self.unset_roots.contains(&bag)
    }

    fn superglobal_root_is_set(&self, bag: NativeRequestStateBag) -> bool {
        self.superglobal_root_value(bag)
            .ok()
            .is_some_and(|value| !matches!(value, Value::Null))
    }

    fn superglobal_value(
        &self,
        bag: NativeRequestStateBag,
        key: &[u8],
    ) -> Result<Option<Value>, NativeRequestStateOperationStatus> {
        let key =
            request_state_array_key(key).ok_or(NativeRequestStateOperationStatus::InvalidAbi)?;
        if self.unset_roots.contains(&bag) {
            return Err(NativeRequestStateOperationStatus::MissingRoot);
        }
        if let Some(root_value) = self.root_values.get(&bag).map(ArraySlot::value_cloned) {
            return request_state_get_path_cloned_from_root(&root_value, &[key]);
        }
        Ok(self
            .superglobals
            .get(&bag)
            .and_then(|values| values.get_cloned(key)))
    }

    fn superglobal_path_value(
        &self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
    ) -> Result<Option<Value>, NativeRequestStateOperationStatus> {
        if self.unset_roots.contains(&bag) {
            return Err(NativeRequestStateOperationStatus::MissingRoot);
        }
        if let Some(root_value) = self.root_values.get(&bag).map(ArraySlot::value_cloned) {
            return request_state_get_path_cloned_from_root(&root_value, keys);
        }
        let Some(values) = self.superglobals.get(&bag) else {
            return Ok(None);
        };

        request_state_get_path_cloned(values, keys)
    }

    fn superglobal_runtime_value(&self, bag: NativeRequestStateBag, key: &[u8]) -> Value {
        self.superglobal_value(bag, key)
            .ok()
            .flatten()
            .unwrap_or(Value::Null)
    }

    fn superglobal_array(&self, bag: NativeRequestStateBag) -> PhpArray {
        if self.unset_roots.contains(&bag) {
            return PhpArray::new();
        }
        self.superglobals
            .get(&bag)
            .cloned()
            .unwrap_or_else(PhpArray::new)
    }

    fn superglobal_snapshot_value(&self, bag: NativeRequestStateBag) -> Value {
        if self.unset_roots.contains(&bag) {
            return Value::Null;
        }
        self.root_values
            .get(&bag)
            .map(ArraySlot::value_cloned)
            .unwrap_or_else(|| Value::Array(self.superglobal_array(bag)))
    }

    fn replace_superglobal_value(&mut self, bag: NativeRequestStateBag, value: Value) {
        self.unset_roots.remove(&bag);
        if let Some(root_value) = self.root_values.get_mut(&bag) {
            if root_value.is_reference() {
                root_value.set_value(value);
                self.superglobals.remove(&bag);
                return;
            }
        }

        match value {
            Value::Array(array) => {
                self.superglobals.insert(bag, array);
                self.root_values.remove(&bag);
            }
            value => {
                self.superglobals.remove(&bag);
                self.root_values.insert(bag, ArraySlot::new(value));
            }
        }
    }

    fn replace_superglobal_reference(
        &mut self,
        bag: NativeRequestStateBag,
        reference: PhpReferenceCell,
    ) {
        self.unset_roots.remove(&bag);
        self.superglobals.remove(&bag);
        self.root_values
            .insert(bag, ArraySlot::from_reference_cell(reference));
    }

    fn superglobal_root_reference(&mut self, bag: NativeRequestStateBag) -> PhpReferenceCell {
        self.unset_roots.remove(&bag);
        if !self.root_values.contains_key(&bag) {
            let snapshot = self.superglobal_array(bag);
            self.superglobals.remove(&bag);
            self.root_values
                .insert(bag, ArraySlot::new(Value::Array(snapshot)));
        }

        self.root_values
            .get_mut(&bag)
            .expect("request root reference slot was just initialized")
            .promote_to_reference_cell()
    }

    fn superglobal_root_is_reference(&self, bag: NativeRequestStateBag) -> bool {
        self.root_values
            .get(&bag)
            .is_some_and(ArraySlot::is_reference)
    }

    fn mutate_reference_backed_superglobal_array<F>(
        &mut self,
        bag: NativeRequestStateBag,
        mutation: F,
    ) -> NativeRequestStateOperationResult
    where
        F: FnOnce(
            &mut PhpArray,
        )
            -> Result<NativeRequestStateOperationResult, NativeRequestStateOperationStatus>,
    {
        let Some(root_value) = self.root_values.get_mut(&bag) else {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::UnsupportedKeyedValue,
            );
        };
        if !root_value.is_reference() {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::UnsupportedKeyedValue,
            );
        }

        let mut array = match root_value.value_cloned() {
            Value::Array(array) => array,
            Value::Null | Value::Bool(false) => PhpArray::new(),
            _ => {
                return NativeRequestStateOperationResult::unsupported(
                    NativeRequestStateOperationStatus::UnsupportedKeyedValue,
                )
            }
        };

        match mutation(&mut array) {
            Ok(result) => {
                root_value.set_value(Value::Array(array));
                result
            }
            Err(status) => NativeRequestStateOperationResult::unsupported(status),
        }
    }

    fn prepare_superglobal_keyed_write(
        &mut self,
        bag: NativeRequestStateBag,
    ) -> Result<(), NativeRequestStateOperationStatus> {
        self.unset_roots.remove(&bag);
        let Some(root_value) = self.root_values.get(&bag) else {
            return Ok(());
        };
        if root_value.reference_cell_id().is_some() {
            return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue);
        }
        match root_value.value_cloned() {
            Value::Null | Value::Bool(false) => {
                self.root_values.remove(&bag);
                Ok(())
            }
            _ => Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue),
        }
    }

    fn write_superglobal_key(
        &mut self,
        bag: NativeRequestStateBag,
        key: ArrayKey,
        value: Value,
    ) -> NativeRequestStateOperationResult {
        if self.superglobal_root_is_reference(bag) {
            return self.mutate_reference_backed_superglobal_array(bag, |array| {
                let is_set = !matches!(value, Value::Null);
                array.insert(key, value);
                Ok(NativeRequestStateOperationResult::presence(
                    is_set,
                    true,
                    NativeRequestStateOperationStatus::Ok,
                ))
            });
        }

        if let Err(status) = self.prepare_superglobal_keyed_write(bag) {
            return NativeRequestStateOperationResult::unsupported(status);
        }
        let is_set = !matches!(value, Value::Null);
        self.superglobals.entry(bag).or_default().insert(key, value);
        NativeRequestStateOperationResult::presence(
            is_set,
            true,
            NativeRequestStateOperationStatus::Ok,
        )
    }

    fn unset_superglobal_key(
        &mut self,
        bag: NativeRequestStateBag,
        key: ArrayKey,
    ) -> NativeRequestStateOperationResult {
        if self.superglobal_root_is_reference(bag) {
            return self.mutate_reference_backed_superglobal_array(bag, |array| {
                array.remove(key);
                Ok(NativeRequestStateOperationResult::presence(
                    false,
                    false,
                    NativeRequestStateOperationStatus::Ok,
                ))
            });
        }

        if self.root_values.contains_key(&bag) {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::UnsupportedKeyedValue,
            );
        }
        if let Some(values) = self.superglobals.get_mut(&bag) {
            values.remove(key);
        }

        NativeRequestStateOperationResult::presence(
            false,
            false,
            NativeRequestStateOperationStatus::Ok,
        )
    }

    fn write_superglobal_path(
        &mut self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
        value: Value,
    ) -> NativeRequestStateOperationResult {
        if keys.is_empty() {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::InvalidAbi,
            );
        }

        if self.superglobal_root_is_reference(bag) {
            return self.mutate_reference_backed_superglobal_array(bag, |array| {
                request_state_write_path_value(array, keys, value)?;
                request_state_path_mutation_result_from_array(array, keys)
            });
        }

        if let Err(status) = self.prepare_superglobal_keyed_write(bag) {
            return NativeRequestStateOperationResult::unsupported(status);
        }
        let values = self.superglobals.entry(bag).or_default();
        let status = request_state_write_path_value(values, keys, value)
            .map(|()| NativeRequestStateOperationStatus::Ok)
            .unwrap_or_else(|status| status);
        request_state_path_mutation_result(self, bag, keys, status)
    }

    fn append_superglobal_path(
        &mut self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
        value: Value,
    ) -> NativeRequestStateOperationResult {
        if self.superglobal_root_is_reference(bag) {
            return self.mutate_reference_backed_superglobal_array(bag, |array| {
                let appended_is_set = !matches!(value, Value::Null);
                array
                    .append_path(keys, value)
                    .map_err(|_| NativeRequestStateOperationStatus::UnsupportedKeyedValue)?;
                if keys.is_empty() {
                    return Ok(NativeRequestStateOperationResult::presence(
                        appended_is_set,
                        true,
                        NativeRequestStateOperationStatus::Ok,
                    ));
                }
                request_state_path_mutation_result_from_array(array, keys)
            });
        }

        if let Err(status) = self.prepare_superglobal_keyed_write(bag) {
            return NativeRequestStateOperationResult::unsupported(status);
        }

        let appended_is_set = !matches!(value, Value::Null);
        let values = self.superglobals.entry(bag).or_default();
        let status = values
            .append_path(keys, value)
            .map(|_| NativeRequestStateOperationStatus::Ok)
            .unwrap_or(NativeRequestStateOperationStatus::UnsupportedKeyedValue);
        if status != NativeRequestStateOperationStatus::Ok {
            return NativeRequestStateOperationResult::unsupported(status);
        }
        if keys.is_empty() {
            return NativeRequestStateOperationResult::presence(appended_is_set, true, status);
        }

        request_state_path_mutation_result(self, bag, keys, status)
    }

    fn unset_superglobal_path(
        &mut self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
    ) -> NativeRequestStateOperationResult {
        if keys.is_empty() {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::InvalidAbi,
            );
        }

        if self.superglobal_root_is_reference(bag) {
            return self.mutate_reference_backed_superglobal_array(bag, |array| {
                request_state_unset_path_value(array, keys)?;
                request_state_path_mutation_result_from_array(array, keys)
            });
        }

        if self.root_values.contains_key(&bag) {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::UnsupportedKeyedValue,
            );
        }
        let status = self
            .superglobals
            .get_mut(&bag)
            .map(|values| request_state_unset_path_value(values, keys))
            .transpose()
            .map(|_| NativeRequestStateOperationStatus::Ok)
            .unwrap_or_else(|status| status);
        request_state_path_mutation_result(self, bag, keys, status)
    }

    fn unset_superglobal_root(
        &mut self,
        bag: NativeRequestStateBag,
    ) -> NativeRequestStateOperationResult {
        self.superglobals.remove(&bag);
        self.root_values.remove(&bag);
        self.unset_roots.insert(bag);
        NativeRequestStateOperationResult::presence(
            false,
            false,
            NativeRequestStateOperationStatus::Ok,
        )
    }

    fn reference_superglobal_path(
        &mut self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
    ) -> Result<PhpReferenceCell, NativeRequestStateOperationStatus> {
        if keys.is_empty() {
            return Err(NativeRequestStateOperationStatus::InvalidAbi);
        }

        self.unset_roots.remove(&bag);
        if self.superglobal_root_is_reference(bag) {
            let Some(root_value) = self.root_values.get_mut(&bag) else {
                return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue);
            };
            let mut array = match root_value.value_cloned() {
                Value::Array(array) => array,
                Value::Null | Value::Bool(false) => PhpArray::new(),
                _ => return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue),
            };
            let reference = array
                .reference_path(keys)
                .map_err(|_| NativeRequestStateOperationStatus::UnsupportedKeyedValue)?;
            root_value.set_value(Value::Array(array));
            return Ok(reference);
        }

        self.prepare_superglobal_keyed_write(bag)?;
        self.superglobals
            .entry(bag)
            .or_default()
            .reference_path(keys)
            .map_err(|_| NativeRequestStateOperationStatus::UnsupportedKeyedValue)
    }

    fn bind_superglobal_path_reference(
        &mut self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
        reference: PhpReferenceCell,
    ) -> Result<bool, NativeRequestStateOperationStatus> {
        if keys.is_empty() {
            return Err(NativeRequestStateOperationStatus::InvalidAbi);
        }

        if self.superglobal_root_is_reference(bag) {
            let Some(root_value) = self.root_values.get_mut(&bag) else {
                return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue);
            };
            let mut array = match root_value.value_cloned() {
                Value::Array(array) => array,
                Value::Null | Value::Bool(false) => PhpArray::new(),
                _ => return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue),
            };
            array
                .materialize_path(keys)
                .map_err(|_| NativeRequestStateOperationStatus::UnsupportedKeyedValue)?;
            if !array.write_existing_path_reference(keys, reference) {
                return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue);
            }
            root_value.set_value(Value::Array(array));
            return Ok(true);
        }

        self.prepare_superglobal_keyed_write(bag)?;
        let values = self.superglobals.entry(bag).or_default();
        values
            .materialize_path(keys)
            .map_err(|_| NativeRequestStateOperationStatus::UnsupportedKeyedValue)?;
        if !values.write_existing_path_reference(keys, reference) {
            return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue);
        }
        Ok(true)
    }

    fn append_superglobal_path_reference(
        &mut self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
        reference: PhpReferenceCell,
    ) -> Result<Vec<ArrayKey>, NativeRequestStateOperationStatus> {
        if self.superglobal_root_is_reference(bag) {
            let Some(root_value) = self.root_values.get_mut(&bag) else {
                return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue);
            };
            let mut array = match root_value.value_cloned() {
                Value::Array(array) => array,
                Value::Null | Value::Bool(false) => PhpArray::new(),
                _ => return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue),
            };
            let appended_keys = array
                .append_path_reference(keys, reference)
                .map_err(|_| NativeRequestStateOperationStatus::UnsupportedKeyedValue)?;
            root_value.set_value(Value::Array(array));
            return Ok(appended_keys);
        }

        self.prepare_superglobal_keyed_write(bag)?;
        self.superglobals
            .entry(bag)
            .or_default()
            .append_path_reference(keys, reference)
            .map_err(|_| NativeRequestStateOperationStatus::UnsupportedKeyedValue)
    }

    fn populate_superglobal_from_symbol_table(
        &mut self,
        bag: NativeRequestStateBag,
        source: &NativeSymbolTable,
    ) -> bool {
        self.root_values.remove(&bag);
        self.superglobals
            .insert(bag, native_symbol_table_snapshot_array(source));
        true
    }

    fn rebuild_request_from_order(&mut self, order: &[u8]) -> bool {
        let mut request = PhpArray::new();
        for bag in request_population_sources(order) {
            let Some(source) = self.superglobals.get(&bag) else {
                continue;
            };
            for entry in source.entries() {
                request.insert(entry.key.clone(), entry.value_cloned());
            }
        }
        self.root_values.remove(&NativeRequestStateBag::Request);
        self.superglobals
            .insert(NativeRequestStateBag::Request, request);
        true
    }
}

fn request_population_sources(order: &[u8]) -> impl Iterator<Item = NativeRequestStateBag> + '_ {
    order.iter().filter_map(|byte| match byte {
        b'G' | b'g' => Some(NativeRequestStateBag::Get),
        b'P' | b'p' => Some(NativeRequestStateBag::Post),
        b'C' | b'c' => Some(NativeRequestStateBag::Cookie),
        _ => None,
    })
}

fn request_population_policy_order<'a>(
    request_order: Option<&'a NativeString>,
    variables_order: Option<&'a NativeString>,
) -> Option<&'a [u8]> {
    request_order
        .filter(|order| !order.bytes.is_empty())
        .or(variables_order)
        .map(|order| order.bytes.as_slice())
}

impl NativeSymbolTableHandle {
    pub const fn null() -> Self {
        Self {
            ptr: ptr::null_mut(),
        }
    }

    pub fn new() -> Self {
        Self {
            ptr: Box::into_raw(Box::new(NativeSymbolTable {
                values: HashMap::new(),
                insertion_order: Vec::new(),
            })),
        }
    }

    pub fn is_null(&self) -> bool {
        self.ptr.is_null()
    }

    unsafe fn as_ref(&self) -> Option<&NativeSymbolTable> {
        unsafe { self.ptr.as_ref() }
    }

    unsafe fn as_mut(&mut self) -> Option<&mut NativeSymbolTable> {
        unsafe { self.ptr.as_mut() }
    }
}

impl NativeScalarValue {
    pub const fn null() -> Self {
        Self {
            tag: NativeScalarTag::Null,
            bool_value: 0,
            int_value: 0,
            float_value: 0.0,
        }
    }

    pub const fn bool(value: bool) -> Self {
        Self {
            tag: NativeScalarTag::Bool,
            bool_value: value as u8,
            int_value: 0,
            float_value: 0.0,
        }
    }

    pub const fn int(value: i64) -> Self {
        Self {
            tag: NativeScalarTag::Int,
            bool_value: 0,
            int_value: value,
            float_value: 0.0,
        }
    }

    pub const fn float(value: f64) -> Self {
        Self {
            tag: NativeScalarTag::Float,
            bool_value: 0,
            int_value: 0,
            float_value: value,
        }
    }

    pub fn tag(&self) -> NativeScalarTag {
        self.tag
    }

    pub fn to_value(self) -> Value {
        match self.tag {
            NativeScalarTag::Null => Value::Null,
            NativeScalarTag::Bool => Value::Bool(self.bool_value != 0),
            NativeScalarTag::Int => Value::Int(self.int_value),
            NativeScalarTag::Float => Value::Float(self.float_value),
        }
    }

    pub fn echo_string(self) -> String {
        self.to_value().echo_string()
    }
}

