/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. The returned value handle owns a clone of the PHP
/// array value; ownership of `handle` remains with the caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_from_array(
    handle: NativeArrayHandle,
) -> NativeValueHandle {
    unsafe { handle.as_ref() }
        .map(|array| NativeValueHandle::from_value(Value::Array(array.value.clone())))
        .unwrap_or_else(NativeValueHandle::null)
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Array values are cloned into a new array handle;
/// ownership of `handle` remains with the caller. Non-array and null handles
/// return a null array handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_clone(
    handle: NativeValueHandle,
) -> NativeArrayHandle {
    match unsafe { handle.as_ref() } {
        Some(Value::Array(array)) => NativeArrayHandle::from_array(array.clone()),
        Some(_) | None => NativeArrayHandle::null(),
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The returned handle owns a clone of the value. Null
/// handles clone to null.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_clone(handle: NativeValueHandle) -> NativeValueHandle {
    unsafe { handle.as_ref() }
        .cloned()
        .map(NativeValueHandle::from_value)
        .unwrap_or_else(NativeValueHandle::null)
}

#[no_mangle]
pub extern "C" fn phpc_native_value_from_closure_descriptor(
    descriptor: NativeClosureDescriptor,
) -> NativeValueHandle {
    if !descriptor.is_invokable() {
        return NativeValueHandle::null();
    }
    let Ok(source_signature) = (unsafe { descriptor.source_signature() }) else {
        return NativeValueHandle::null();
    };

    NativeValueHandle::from_value(Value::Closure(
        PhpClosure::new_with_descriptor_and_source_signature(
            NEXT_NATIVE_CLOSURE_ID.fetch_add(1, AtomicOrdering::Relaxed),
            false,
            Vec::new(),
            descriptor,
            source_signature,
        ),
    ))
}

/// # Safety
///
/// `capture_names` and `capture_values` must be null when `capture_count` is
/// zero, or point to `capture_count` initialized handles previously returned
/// by the runtime ABI and not yet freed. The helper clones every capture value
/// into the closure object and frees all provided capture name/value handles
/// before returning.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_from_closure_descriptor_captures_and_free(
    descriptor: NativeClosureDescriptor,
    capture_names: *const NativeStringHandle,
    capture_values: *const NativeValueHandle,
    capture_count: usize,
) -> NativeValueHandle {
    let captures = unsafe {
        native_closure_captures_from_handles(capture_names, capture_values, capture_count)
    };
    unsafe { native_closure_capture_handles_free(capture_names, capture_values, capture_count) };

    if !descriptor.is_invokable() {
        return NativeValueHandle::null();
    }
    let Ok(source_signature) = (unsafe { descriptor.source_signature() }) else {
        return NativeValueHandle::null();
    };

    let Some(captures) = captures else {
        return NativeValueHandle::null();
    };

    NativeValueHandle::from_value(Value::Closure(
        PhpClosure::new_with_descriptor_and_source_signature(
            NEXT_NATIVE_CLOSURE_ID.fetch_add(1, AtomicOrdering::Relaxed),
            false,
            captures,
            descriptor,
            source_signature,
        ),
    ))
}

/// # Safety
///
/// `capture_names` and `capture_args` must be null when `capture_count` is
/// zero, or point to `capture_count` initialized handles previously returned
/// by the runtime ABI and not yet freed. By-value capture arguments are cloned
/// into fresh closure capture cells. By-reference capture arguments store the
/// same reference cell in the closure object. The helper frees all provided
/// capture name/value/reference handles before returning.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_from_closure_descriptor_capture_arguments_and_free(
    descriptor: NativeClosureDescriptor,
    capture_names: *const NativeStringHandle,
    capture_args: *const NativeClosureArgument,
    capture_count: usize,
) -> NativeValueHandle {
    let captures = unsafe {
        native_closure_captures_from_arguments(capture_names, capture_args, capture_count)
    };
    unsafe { native_closure_capture_arguments_free(capture_names, capture_args, capture_count) };

    if !descriptor.is_invokable() {
        return NativeValueHandle::null();
    }
    let Ok(source_signature) = (unsafe { descriptor.source_signature() }) else {
        return NativeValueHandle::null();
    };

    let Some(captures) = captures else {
        return NativeValueHandle::null();
    };

    NativeValueHandle::from_value(Value::Closure(
        PhpClosure::new_with_descriptor_and_source_signature(
            NEXT_NATIVE_CLOSURE_ID.fetch_add(1, AtomicOrdering::Relaxed),
            false,
            captures,
            descriptor,
            source_signature,
        ),
    ))
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_is_descriptor_closure(
    handle: NativeValueHandle,
) -> bool {
    matches!(
        unsafe { handle.as_ref() },
        Some(Value::Closure(closure)) if closure.descriptor().is_some_and(|descriptor| descriptor.is_invokable())
    )
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_closure_value_param_is_by_reference(
    handle: NativeValueHandle,
    index: usize,
) -> bool {
    match unsafe { handle.as_ref() } {
        Some(Value::Closure(closure)) => closure
            .descriptor()
            .is_some_and(|descriptor| descriptor.param_is_by_reference(index)),
        _ => false,
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. On return, `diagnostic` owns a diagnostic handle when
/// non-null.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_closure_reference_argument_failure_with_diagnostic(
    handle: NativeValueHandle,
    index: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let type_name = unsafe { handle.as_ref() }
        .map(Value::type_name)
        .unwrap_or("null");
    unsafe {
        native_store_diagnostic_message(
            diagnostic,
            RuntimeError::unsupported_call(
                "Closure::__invoke()",
                format!(
                    "by-reference parameter ${index} requires a supported lvalue argument for descriptor-backed closure invocation, got {type_name} callable"
                ),
            )
            .message(),
        )
    };
}

