#[no_mangle]
pub extern "C" fn phpc_native_closure_result_report_diagnostic(
    result: NativeClosureInvocationResult,
) -> usize {
    if result.diagnostic.is_null() {
        return 0;
    }
    unsafe { phpc_native_diagnostic_report(result.diagnostic) }
}

#[no_mangle]
pub unsafe extern "C" fn phpc_native_closure_result_free(result: NativeClosureInvocationResult) {
    unsafe { phpc_native_value_free(result.value) };
    unsafe { phpc_native_reference_free(result.reference) };
    unsafe { phpc_native_diagnostic_free(result.diagnostic) };
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. When `arg_count` is non-zero, `args` must point to an
/// array of `arg_count` native closure arguments that remain valid for the duration
/// of the callback. The returned result owns any non-null value, reference, and
/// diagnostic handles and must be consumed or freed by the caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_closure_invoke_result(
    handle: NativeValueHandle,
    call_depth: c_int,
    args: *const NativeClosureArgument,
    arg_count: usize,
) -> NativeClosureInvocationResult {
    if arg_count > 0 && args.is_null() {
        return NativeClosureInvocationResult::diagnostic(
            "native closure invocation failed: argument handle array is null",
        );
    }

    let Some(Value::Closure(closure)) = (unsafe { handle.as_ref() }) else {
        let type_name = unsafe { handle.as_ref() }
            .map(Value::type_name)
            .unwrap_or("null");
        return NativeClosureInvocationResult::diagnostic(
            RuntimeError::unsupported_call(
                "dynamic function call",
                format!("callable must be a descriptor-backed closure, got {type_name}"),
            )
            .message(),
        );
    };

    let Some(descriptor) = closure.descriptor() else {
        return NativeClosureInvocationResult::diagnostic(
            RuntimeError::unsupported_call(
                "Closure::__invoke()",
                "closure value has no native descriptor/frame callback",
            )
            .message(),
        );
    };
    let Some(callback) = descriptor.callback else {
        return NativeClosureInvocationResult::diagnostic(
            RuntimeError::unsupported_call(
                "Closure::__invoke()",
                "closure descriptor has no frame callback",
            )
            .message(),
        );
    };
    if arg_count < descriptor.required_arg_count
        || (!descriptor.is_variadic() && arg_count > descriptor.param_count)
    {
        return NativeClosureInvocationResult::diagnostic(
            RuntimeError::unsupported_call(
                "Closure::__invoke()",
                "argument count is outside the native closure frame descriptor range",
            )
            .message(),
        );
    }
    let args_slice = if arg_count == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(args, arg_count) }
    };
    for (index, arg) in args_slice.iter().enumerate() {
        if arg.is_variadic_collection()
            && (!descriptor.is_variadic()
                || index + 1 != descriptor.param_count
                || index + 1 != arg_count)
        {
            return NativeClosureInvocationResult::diagnostic(
                RuntimeError::unsupported_call(
                    "Closure::__invoke()",
                    "finalized variadic closure argument must be the descriptor variadic slot",
                )
                .message(),
            );
        }
        if descriptor.param_is_by_reference(index) && !arg.is_reference() {
            return NativeClosureInvocationResult::diagnostic(
                RuntimeError::unsupported_call(
                    "Closure::__invoke()",
                    format!(
                        "by-reference parameter ${index} requires a supported lvalue argument for descriptor-backed closure invocation"
                    ),
                )
                .message(),
            );
        }
        if !descriptor.param_is_by_reference(index) && arg.value.is_null() {
            return NativeClosureInvocationResult::diagnostic(
                RuntimeError::unsupported_call(
                    "Closure::__invoke()",
                    "native closure frame callback received a null value argument",
                )
                .message(),
            );
        }
    }

    let capture_args = closure
        .captures()
        .iter()
        .map(|capture| {
            let value = NativeValueHandle::from_value(capture.value());
            if capture.by_reference() {
                let reference = NativeReferenceHandle::from_cell(capture.cell());
                NativeClosureArgument::from_reference(value, reference)
            } else {
                NativeClosureArgument::from_value(value)
            }
        })
        .collect::<Vec<_>>();
    let mut callback_args = Vec::with_capacity(arg_count.saturating_add(capture_args.len()));
    if arg_count > 0 {
        callback_args.extend_from_slice(args_slice);
    }
    callback_args.extend(capture_args.iter().copied());

    let mut callback_status = 0;
    let result = unsafe {
        callback(
            call_depth,
            if callback_args.is_empty() {
                ptr::null()
            } else {
                callback_args.as_ptr()
            },
            callback_args.len(),
            &mut callback_status,
        )
    };
    for capture in capture_args {
        unsafe { phpc_native_value_free(capture.value) };
        unsafe { phpc_native_reference_free(capture.reference) };
    }

    if callback_status != 1 {
        unsafe { phpc_native_closure_result_free(result) };
        return NativeClosureInvocationResult::diagnostic(
            RuntimeError::unsupported_call(
                "Closure::__invoke()",
                "native closure frame callback did not complete with an owned result",
            )
            .message(),
        );
    }

    if descriptor.returns_by_reference() {
        if result.status == NATIVE_CLOSURE_RESULT_REFERENCE && !result.reference.is_null() {
            return result;
        }
        unsafe { phpc_native_closure_result_free(result) };
        return NativeClosureInvocationResult::diagnostic(
            RuntimeError::unsupported_call(
                "Closure::__invoke()",
                "native closure frame callback did not return an owned reference",
            )
            .message(),
        );
    }

    if result.status == NATIVE_CLOSURE_RESULT_VALUE && !result.value.is_null() {
        return result;
    }
    if result.status == NATIVE_CLOSURE_RESULT_REFERENCE && !result.reference.is_null() {
        let value = unsafe { phpc_native_reference_value_clone(result.reference) };
        unsafe { phpc_native_closure_result_free(result) };
        if !value.is_null() {
            return NativeClosureInvocationResult::value(value);
        }
    } else {
        unsafe { phpc_native_closure_result_free(result) };
    }

    NativeClosureInvocationResult::diagnostic(
        RuntimeError::unsupported_call(
            "Closure::__invoke()",
            "native closure frame callback did not return an owned value",
        )
        .message(),
    )
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. When `arg_count` is non-zero, `args` must point to an
/// array of `arg_count` native closure arguments that remain valid for the duration
/// of the callback. On return, `diagnostic` owns a diagnostic handle when
/// non-null.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_closure_invoke_value_with_diagnostic(
    handle: NativeValueHandle,
    call_depth: c_int,
    args: *const NativeClosureArgument,
    arg_count: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let mut result =
        unsafe { phpc_native_closure_invoke_result(handle, call_depth, args, arg_count) };
    if !result.diagnostic.is_null() {
        unsafe { *diagnostic = result.diagnostic };
        result.diagnostic = NativeDiagnosticHandle::null();
        unsafe { phpc_native_closure_result_free(result) };
        return NativeValueHandle::null();
    }
    let value = result.take_value();
    let value = if value.is_null() && !result.reference.is_null() {
        unsafe { phpc_native_reference_value_clone(result.reference) }
    } else {
        value
    };
    unsafe { phpc_native_closure_result_free(result) };
    value
}

unsafe fn native_closure_captures_from_handles(
    capture_names: *const NativeStringHandle,
    capture_values: *const NativeValueHandle,
    capture_count: usize,
) -> Option<Vec<PhpClosureCapture>> {
    if capture_count == 0 {
        return Some(Vec::new());
    }
    if capture_names.is_null() || capture_values.is_null() {
        return None;
    }

    let names = unsafe { std::slice::from_raw_parts(capture_names, capture_count) };
    let values = unsafe { std::slice::from_raw_parts(capture_values, capture_count) };
    let mut captures = Vec::with_capacity(capture_count);
    for (name, value) in names.iter().zip(values.iter()) {
        let name = unsafe { name.as_ref() }?;
        let name = String::from_utf8(name.bytes.clone()).ok()?;
        let value = unsafe { value.as_ref() }?.clone();
        captures.push(PhpClosureCapture::new(name, false, value));
    }
    Some(captures)
}

unsafe fn native_closure_captures_from_arguments(
    capture_names: *const NativeStringHandle,
    capture_args: *const NativeClosureArgument,
    capture_count: usize,
) -> Option<Vec<PhpClosureCapture>> {
    if capture_count == 0 {
        return Some(Vec::new());
    }
    if capture_names.is_null() || capture_args.is_null() {
        return None;
    }

    let names = unsafe { std::slice::from_raw_parts(capture_names, capture_count) };
    let args = unsafe { std::slice::from_raw_parts(capture_args, capture_count) };
    let mut captures = Vec::with_capacity(capture_count);
    for (name, arg) in names.iter().zip(args.iter()) {
        let name = unsafe { name.as_ref() }?;
        let name = String::from_utf8(name.bytes.clone()).ok()?;
        if arg.is_reference() {
            let reference = unsafe { arg.reference.as_ref() }?;
            captures.push(PhpClosureCapture::new_reference(
                name,
                true,
                reference.cell.clone(),
            ));
        } else {
            let value = unsafe { arg.value.as_ref() }?.clone();
            captures.push(PhpClosureCapture::new(name, false, value));
        }
    }
    Some(captures)
}

unsafe fn native_closure_capture_handles_free(
    capture_names: *const NativeStringHandle,
    capture_values: *const NativeValueHandle,
    capture_count: usize,
) {
    if capture_count == 0 {
        return;
    }
    if !capture_names.is_null() {
        for handle in unsafe { std::slice::from_raw_parts(capture_names, capture_count) } {
            unsafe { phpc_native_string_free(*handle) };
        }
    }
    if !capture_values.is_null() {
        for handle in unsafe { std::slice::from_raw_parts(capture_values, capture_count) } {
            unsafe { phpc_native_value_free(*handle) };
        }
    }
}

unsafe fn native_closure_capture_arguments_free(
    capture_names: *const NativeStringHandle,
    capture_args: *const NativeClosureArgument,
    capture_count: usize,
) {
    if capture_count == 0 {
        return;
    }
    if !capture_names.is_null() {
        for handle in unsafe { std::slice::from_raw_parts(capture_names, capture_count) } {
            unsafe { phpc_native_string_free(*handle) };
        }
    }
    if !capture_args.is_null() {
        for arg in unsafe { std::slice::from_raw_parts(capture_args, capture_count) } {
            unsafe { phpc_native_value_free(arg.value) };
            unsafe { phpc_native_reference_free(arg.reference) };
        }
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. `name_ptr..name_ptr+name_len` must either be a valid
/// byte slice or be null with a zero length. String callable matching follows
/// PHP's ASCII case-insensitive function-name lookup for generated user
/// function frames.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_dynamic_call_name_matches(
    handle: NativeValueHandle,
    name_ptr: *const u8,
    name_len: usize,
) -> bool {
    let Some(name) = (unsafe { native_abi_bytes(name_ptr, name_len) }) else {
        return false;
    };
    let Some(Value::String(callable)) = (unsafe { handle.as_ref() }) else {
        return false;
    };
    callable.as_bytes().eq_ignore_ascii_case(name)
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. `name_ptr..name_ptr+name_len` must either be a valid
/// byte slice or be null with a zero length. Class-name matching follows PHP's
/// ASCII case-insensitive class lookup and ignores one leading namespace
/// separator on either side.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_dynamic_class_name_matches(
    handle: NativeValueHandle,
    name_ptr: *const u8,
    name_len: usize,
) -> bool {
    let Some(name) = (unsafe { native_abi_bytes(name_ptr, name_len) }) else {
        return false;
    };
    let Some(Value::String(class_name)) = (unsafe { handle.as_ref() }) else {
        return false;
    };
    native_class_metadata_lookup_key(class_name.as_bytes())
        == native_class_metadata_lookup_key(name)
}

/// # Safety
///
/// `handle` must be null or a string handle previously returned by the runtime
/// ABI and not yet freed. `name_ptr..name_ptr+name_len` must either be a valid
/// byte slice or be null with a zero length. Class-name matching follows PHP's
/// ASCII case-insensitive class lookup and ignores one leading namespace
/// separator on either side.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_string_dynamic_class_name_matches(
    handle: NativeStringHandle,
    name_ptr: *const u8,
    name_len: usize,
) -> bool {
    let Some(name) = (unsafe { native_abi_bytes(name_ptr, name_len) }) else {
        return false;
    };
    let Some(class_name) = (unsafe { handle.as_ref() }) else {
        return false;
    };
    native_class_metadata_lookup_key(class_name.bytes.as_slice())
        == native_class_metadata_lookup_key(name)
}

unsafe fn native_include_unit_registry_slice<'a>(
    entries: *const NativeIncludeUnitLookupEntry,
    entry_count: usize,
) -> Option<&'a [NativeIncludeUnitLookupEntry]> {
    if entry_count > 0 && entries.is_null() {
        return None;
    }
    Some(unsafe { std::slice::from_raw_parts(entries, entry_count) })
}

unsafe fn native_include_unit_registry_lookup_bytes(
    path: &[u8],
    registry: &[NativeIncludeUnitLookupEntry],
) -> NativeIncludeUnitLookupResult {
    let mut matched_unit = None;
    for entry in registry {
        let Some(key) = (unsafe { native_abi_bytes(entry.key_ptr, entry.key_len) }) else {
            return NativeIncludeUnitLookupResult {
                status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
                unit_index: 0,
            };
        };
        if key != path {
            continue;
        }
        if let Some(previous) = matched_unit {
            if previous != entry.unit_index {
                return NativeIncludeUnitLookupResult {
                    status: NATIVE_INCLUDE_LOOKUP_STATUS_AMBIGUOUS,
                    unit_index: previous,
                };
            }
        } else {
            matched_unit = Some(entry.unit_index);
        }
    }

    if let Some(unit_index) = matched_unit {
        NativeIncludeUnitLookupResult {
            status: NATIVE_INCLUDE_LOOKUP_STATUS_FOUND,
            unit_index,
        }
    } else {
        NativeIncludeUnitLookupResult {
            status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
            unit_index: 0,
        }
    }
}

fn native_include_path_is_absolute(path: &[u8]) -> bool {
    path.starts_with(b"/")
        || path.starts_with(b"\\")
        || matches!(path, [drive, b':', ..] if drive.is_ascii_alphabetic())
}

fn native_include_path_join(root: &[u8], path: &[u8]) -> Vec<u8> {
    if root.is_empty() {
        return path.to_vec();
    }
    let mut candidate = root.to_vec();
    if !candidate.ends_with(b"/") && !candidate.ends_with(b"\\") {
        candidate.push(b'/');
    }
    candidate.extend_from_slice(path);
    candidate
}

/// # Safety
///
/// `path_ptr..path_ptr+path_len` must either be a valid byte slice or be null
/// with a zero length. `entries..entries+entry_count` must either be a valid
/// include-unit registry slice or be null with a zero length. Registry keys
/// are generated request-path and canonical-path aliases for already compiled
/// include units; this ABI does not parse source or probe the filesystem.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_include_unit_registry_lookup(
    path_ptr: *const u8,
    path_len: usize,
    entries: *const NativeIncludeUnitLookupEntry,
    entry_count: usize,
) -> NativeIncludeUnitLookupResult {
    let Some(path) = (unsafe { native_abi_bytes(path_ptr, path_len) }) else {
        return NativeIncludeUnitLookupResult {
            status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
            unit_index: 0,
        };
    };
    let Some(registry) = (unsafe { native_include_unit_registry_slice(entries, entry_count) })
    else {
        return NativeIncludeUnitLookupResult {
            status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
            unit_index: 0,
        };
    };
    unsafe { native_include_unit_registry_lookup_bytes(path, registry) }
}

/// # Safety
///
/// `path_ptr..path_ptr+path_len`, `include_path_ptr..include_path_ptr+
/// include_path_len`, and `source_dir_ptr..source_dir_ptr+source_dir_len` must
/// either be valid byte slices or be null with a zero length.
/// `entries..entries+entry_count` must either be a valid include-unit registry
/// slice or be null with a zero length. The lookup applies selected PHP
/// include_path ordering to generated registry keys for already compiled units;
/// it performs no filesystem probing and does not parse runtime PHP source.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_include_unit_registry_lookup_include_path(
    path_ptr: *const u8,
    path_len: usize,
    include_path_ptr: *const u8,
    include_path_len: usize,
    source_dir_ptr: *const u8,
    source_dir_len: usize,
    entries: *const NativeIncludeUnitLookupEntry,
    entry_count: usize,
) -> NativeIncludeUnitLookupResult {
    let Some(path) = (unsafe { native_abi_bytes(path_ptr, path_len) }) else {
        return NativeIncludeUnitLookupResult {
            status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
            unit_index: 0,
        };
    };
    let Some(include_path) = (unsafe { native_abi_bytes(include_path_ptr, include_path_len) })
    else {
        return NativeIncludeUnitLookupResult {
            status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
            unit_index: 0,
        };
    };
    let Some(source_dir) = (unsafe { native_abi_bytes(source_dir_ptr, source_dir_len) }) else {
        return NativeIncludeUnitLookupResult {
            status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
            unit_index: 0,
        };
    };
    let Some(registry) = (unsafe { native_include_unit_registry_slice(entries, entry_count) })
    else {
        return NativeIncludeUnitLookupResult {
            status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
            unit_index: 0,
        };
    };

    if native_include_path_is_absolute(path) {
        return unsafe { native_include_unit_registry_lookup_bytes(path, registry) };
    }

    for root in include_path.split(|byte| *byte == NATIVE_INCLUDE_PATH_SEPARATOR_BYTE) {
        let root = if root.is_empty() {
            b".".as_slice()
        } else {
            root
        };
        let candidate = native_include_path_join(root, path);
        let result = unsafe { native_include_unit_registry_lookup_bytes(&candidate, registry) };
        if result.status != NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED {
            return result;
        }
    }

    if !source_dir.is_empty() {
        let candidate = native_include_path_join(source_dir, path);
        let result = unsafe { native_include_unit_registry_lookup_bytes(&candidate, registry) };
        if result.status != NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED {
            return result;
        }
    }

    NativeIncludeUnitLookupResult {
        status: NATIVE_INCLUDE_LOOKUP_STATUS_UNSUPPORTED,
        unit_index: 0,
    }
}

fn native_include_runtime_no_match_result(
    status: u8,
    resolved_path: NativeByteBuffer,
    warning: NativeDiagnosticHandle,
    fatal: NativeDiagnosticHandle,
) -> NativeIncludeRuntimeNoMatchResult {
    NativeIncludeRuntimeNoMatchResult {
        status,
        resolved_path,
        warning,
        fatal,
    }
}

fn native_include_runtime_no_match_unsupported(
    message: impl Into<String>,
) -> NativeIncludeRuntimeNoMatchResult {
    native_include_runtime_no_match_result(
        NATIVE_INCLUDE_RUNTIME_NO_MATCH_UNSUPPORTED,
        NativeByteBuffer::empty(),
        NativeDiagnosticHandle::null(),
        NativeDiagnosticHandle::from_message(message),
    )
}

fn native_include_runtime_resolved_source_path(
    requested_path: &str,
    source_file: &str,
    include_path: &str,
) -> Option<PathBuf> {
    let raw_path = PathBuf::from(requested_path);
    if raw_path.is_absolute() {
        return raw_path.is_file().then_some(raw_path);
    }

    for entry in include_path.split(NATIVE_INCLUDE_PATH_SEPARATOR) {
        let entry = if entry.is_empty() { "." } else { entry };
        let candidate = PathBuf::from(entry).join(&raw_path);
        if candidate.is_file() {
            return Some(candidate);
        }
    }

    let candidate = Path::new(source_file)
        .parent()
        .unwrap_or_else(|| Path::new(""))
        .join(raw_path);
    candidate.is_file().then_some(candidate)
}

fn native_include_missing_warning(
    construct: &str,
    requested_path: &str,
    source_file: &str,
    include_path: &str,
    line: usize,
) -> NativeDiagnosticHandle {
    NativeDiagnosticHandle::from_message_with_severity(
        NativeDiagnosticSeverity::Warning,
        format!(
            "PHP Warning:  {construct}({requested_path}): Failed to open stream: No such file or directory in {source_file} on line {line}\nPHP Warning:  {construct}(): Failed opening '{requested_path}' for inclusion (include_path='{include_path}') in {source_file} on line {line}\n",
        ),
    )
}

fn native_include_missing_fatal(
    construct: &str,
    requested_path: &str,
    source_file: &str,
    include_path: &str,
    line: usize,
) -> NativeDiagnosticHandle {
    NativeDiagnosticHandle::from_message(format!(
        "PHP Fatal error:  {construct}(): Failed opening required '{requested_path}' (include_path='{include_path}') in {source_file} on line {line}\n",
    ))
}

/// # Safety
///
/// All `ptr..ptr+len` pairs must either be valid byte slices or null with a
/// zero length. This ABI handles generated include-unit registry misses only:
/// it distinguishes missing paths from existing runtime filesystem source that
/// still requires a broader native source-loader/parser boundary.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_include_runtime_no_match_diagnostic(
    path_ptr: *const u8,
    path_len: usize,
    include_path_ptr: *const u8,
    include_path_len: usize,
    source_file_ptr: *const u8,
    source_file_len: usize,
    construct_ptr: *const u8,
    construct_len: usize,
    required: bool,
    line: usize,
) -> NativeIncludeRuntimeNoMatchResult {
    let requested_path = match unsafe { native_abi_utf8(path_ptr, path_len, "include path") } {
        Ok(path) => path,
        Err(error) => return native_include_runtime_no_match_unsupported(error.message()),
    };
    let include_path =
        match unsafe { native_abi_utf8(include_path_ptr, include_path_len, "include_path") } {
            Ok(path) => path,
            Err(error) => return native_include_runtime_no_match_unsupported(error.message()),
        };
    let source_file =
        match unsafe { native_abi_utf8(source_file_ptr, source_file_len, "source file") } {
            Ok(file) => file,
            Err(error) => return native_include_runtime_no_match_unsupported(error.message()),
        };
    let construct = match unsafe { native_abi_utf8(construct_ptr, construct_len, "construct") } {
        Ok(construct) => construct,
        Err(error) => return native_include_runtime_no_match_unsupported(error.message()),
    };

    if let Some(resolved_path) =
        native_include_runtime_resolved_source_path(requested_path, source_file, include_path)
    {
        let resolved_path = resolved_path.to_string_lossy().into_owned();
        return native_include_runtime_no_match_result(
            NATIVE_INCLUDE_RUNTIME_NO_MATCH_SOURCE_LOAD_REQUIRED,
            NativeByteBuffer::from_vec(resolved_path.clone().into_bytes()),
            NativeDiagnosticHandle::null(),
            NativeDiagnosticHandle::from_message(format!(
                "unsupported runtime include/require path: resolved '{requested_path}' to '{resolved_path}', an existing filesystem source outside the generated include-unit registry; native source loading/parsing ABI is required before arbitrary runtime include execution",
            )),
        );
    }

    native_include_runtime_no_match_result(
        NATIVE_INCLUDE_RUNTIME_NO_MATCH_MISSING,
        NativeByteBuffer::empty(),
        native_include_missing_warning(construct, requested_path, source_file, include_path, line),
        if required {
            native_include_missing_fatal(construct, requested_path, source_file, include_path, line)
        } else {
            NativeDiagnosticHandle::null()
        },
    )
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. `name_ptr..name_ptr+name_len` must either be a valid
/// byte slice or be null with a zero length. Dynamic method-name matching
/// normalizes PHP scalar operands before generated method lookup.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_dynamic_method_name_matches(
    handle: NativeValueHandle,
    name_ptr: *const u8,
    name_len: usize,
) -> bool {
    let Some(name) = (unsafe { native_abi_bytes(name_ptr, name_len) }) else {
        return false;
    };
    let Some(method_name) = (unsafe { handle.as_ref() })
        .and_then(native_value_dynamic_method_name_string)
        .filter(|method_name| !method_name.is_empty())
    else {
        return false;
    };
    method_name.as_bytes().eq_ignore_ascii_case(name)
}

fn native_value_dynamic_method_name_string(value: &Value) -> Option<String> {
    match value {
        Value::Null
        | Value::Bool(_)
        | Value::Int(_)
        | Value::Float(_)
        | Value::String(_)
        | Value::BinaryString(_) => Some(value.echo_string()),
        Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => None,
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. `reason_ptr..reason_ptr+reason_len` must be valid
/// UTF-8 bytes. On return, `diagnostic` owns a diagnostic handle when non-null.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_dynamic_call_failure_with_diagnostic(
    handle: NativeValueHandle,
    reason_ptr: *const u8,
    reason_len: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let reason = match unsafe { native_abi_utf8(reason_ptr, reason_len, "dynamic call reason") } {
        Ok(reason) => reason,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            return;
        }
    };

    let message = match unsafe { handle.as_ref() } {
        Some(Value::String(callable)) => {
            RuntimeError::unsupported_call(format!("{callable}()"), reason)
                .message()
                .to_string()
        }
        Some(value) => RuntimeError::unsupported_call(
            "dynamic function call",
            format!(
                "callable must be a string for generated-C runtime dispatch, got {}",
                value.type_name()
            ),
        )
        .message()
        .to_string(),
        None => RuntimeError::unsupported_call(
            "dynamic function call",
            "callable value handle is null for generated-C runtime dispatch",
        )
        .message()
        .to_string(),
    };
    unsafe { native_store_diagnostic_message(diagnostic, message) };
}

fn native_value_is_callable_syntax_only(value: &Value) -> bool {
    match value {
        Value::String(_) | Value::BinaryString(_) => true,
        Value::Array(array) => native_array_is_callable_syntax_only(array),
        Value::Closure(_) => true,
        Value::Object(_) => false,
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::Resource(_) => {
            false
        }
    }
}

fn native_array_is_callable_syntax_only(array: &PhpArray) -> bool {
    if array.len() != 2 {
        return false;
    }

    let Some(target) = array.get_cloned(ArrayKey::Int(0)) else {
        return false;
    };
    let Some(Value::String(_) | Value::BinaryString(_)) = array.get_cloned(ArrayKey::Int(1)) else {
        return false;
    };
    match target {
        Value::String(_) | Value::BinaryString(_) => true,
        Value::Object(_) => true,
        Value::Null
        | Value::Bool(_)
        | Value::Int(_)
        | Value::Float(_)
        | Value::Array(_)
        | Value::Closure(_)
        | Value::Resource(_) => false,
    }
}

pub const NATIVE_CALLABLE_ARRAY_PARTS_NONE: u8 = 0;
pub const NATIVE_CALLABLE_ARRAY_PARTS_OK: u8 = 1;

#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct NativeCallableArrayParts {
    target: NativeValueHandle,
    method: NativeValueHandle,
    status: u8,
}

impl NativeCallableArrayParts {
    fn none() -> Self {
        Self {
            target: NativeValueHandle::null(),
            method: NativeValueHandle::null(),
            status: NATIVE_CALLABLE_ARRAY_PARTS_NONE,
        }
    }

    fn ok(target: Value, method: Value) -> Self {
        Self {
            target: NativeValueHandle::from_value(target),
            method: NativeValueHandle::from_value(method),
            status: NATIVE_CALLABLE_ARRAY_PARTS_OK,
        }
    }

    pub fn status(&self) -> u8 {
        self.status
    }
}

fn native_callable_array_parts(value: &Value) -> NativeCallableArrayParts {
    let Value::Array(array) = value else {
        return NativeCallableArrayParts::none();
    };
    if array.len() != 2 {
        return NativeCallableArrayParts::none();
    }

    let Some(target) = array.get_cloned(ArrayKey::Int(0)) else {
        return NativeCallableArrayParts::none();
    };
    let Some(method @ (Value::String(_) | Value::BinaryString(_))) =
        array.get_cloned(ArrayKey::Int(1))
    else {
        return NativeCallableArrayParts::none();
    };
    match target {
        Value::String(_) | Value::BinaryString(_) | Value::Object(_) => {
            NativeCallableArrayParts::ok(target, method)
        }
        Value::Null
        | Value::Bool(_)
        | Value::Int(_)
        | Value::Float(_)
        | Value::Array(_)
        | Value::Closure(_)
        | Value::Resource(_) => NativeCallableArrayParts::none(),
    }
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. Null handles are not callable.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_is_callable_syntax_only(
    handle: NativeArrayHandle,
) -> bool {
    unsafe { handle.as_ref() }
        .map(|array| native_array_is_callable_syntax_only(&array.value))
        .unwrap_or(false)
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Null handles are not callable.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_is_callable_syntax_only(
    handle: NativeValueHandle,
) -> bool {
    unsafe { handle.as_ref() }
        .map(native_value_is_callable_syntax_only)
        .unwrap_or(false)
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The returned target and method handles are owned by
/// the caller when status is `NATIVE_CALLABLE_ARRAY_PARTS_OK` and must be
/// released with `phpc_native_callable_array_parts_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_callable_array_parts(
    handle: NativeValueHandle,
) -> NativeCallableArrayParts {
    unsafe { handle.as_ref() }
        .map(native_callable_array_parts)
        .unwrap_or_else(NativeCallableArrayParts::none)
}

#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_array_parts_free(parts: NativeCallableArrayParts) {
    unsafe {
        phpc_native_value_free(parts.target);
        phpc_native_value_free(parts.method);
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The callable, label, and type byte ranges must be
/// valid UTF-8 byte slices. The returned value handle owns the coerced PHP
/// value; ownership of `handle` remains with the caller. On failure the helper
/// stores a diagnostic handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_coerce_call_type_with_diagnostic(
    handle: NativeValueHandle,
    callable_ptr: *const u8,
    callable_len: usize,
    label_ptr: *const u8,
    label_len: usize,
    type_ptr: *const u8,
    type_len: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    match unsafe {
        native_value_coerce_call_type_result(
            handle,
            callable_ptr,
            callable_len,
            label_ptr,
            label_len,
            type_ptr,
            type_len,
        )
    } {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The callable, label, and type byte ranges must be
/// valid UTF-8 byte slices. The returned value handle owns a new PHP array
/// whose entries preserve the input array order and keys while coercing each
/// entry value through call-parameter type semantics; ownership of `handle`
/// remains with the caller. On failure the helper stores a diagnostic handle
/// that the caller owns and must release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_coerce_variadic_collection_type_with_diagnostic(
    handle: NativeValueHandle,
    callable_ptr: *const u8,
    callable_len: usize,
    label_ptr: *const u8,
    label_len: usize,
    type_ptr: *const u8,
    type_len: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    match unsafe {
        native_value_coerce_variadic_collection_type_result(
            handle,
            callable_ptr,
            callable_len,
            label_ptr,
            label_len,
            type_ptr,
            type_len,
        )
    } {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeValueHandle::null()
        }
    }
}

unsafe fn native_value_coerce_call_type_result(
    handle: NativeValueHandle,
    callable_ptr: *const u8,
    callable_len: usize,
    label_ptr: *const u8,
    label_len: usize,
    type_ptr: *const u8,
    type_len: usize,
) -> RuntimeResult<Value> {
    let callable = unsafe { native_abi_utf8(callable_ptr, callable_len, "callable name") }?;
    let label = unsafe { native_abi_utf8(label_ptr, label_len, "type label") }?;
    let type_decl = unsafe { native_abi_utf8(type_ptr, type_len, "type declaration") }?;
    let Some(value) = (unsafe { handle.as_ref() }).cloned() else {
        return Err(RuntimeError::unsupported_call(
            callable,
            format!("{label} type enforcement failed: value handle is null"),
        ));
    };

    let actual_type = value.type_name();
    coerce_property_value_with_object_type_resolver(
        type_decl,
        value,
        callable,
        label,
        false,
        |object, type_name| object.is_instance_of_class_name(type_name),
    )
    .map_err(|_| {
        RuntimeError::unsupported_call(
            callable,
            format!("{label} expects {type_decl}, got {actual_type}"),
        )
    })
}

unsafe fn native_value_coerce_variadic_collection_type_result(
    handle: NativeValueHandle,
    callable_ptr: *const u8,
    callable_len: usize,
    label_ptr: *const u8,
    label_len: usize,
    type_ptr: *const u8,
    type_len: usize,
) -> RuntimeResult<Value> {
    let callable = unsafe { native_abi_utf8(callable_ptr, callable_len, "callable name") }?;
    let label = unsafe { native_abi_utf8(label_ptr, label_len, "type label") }?;
    let type_decl = unsafe { native_abi_utf8(type_ptr, type_len, "type declaration") }?;
    let Some(Value::Array(array)) = (unsafe { handle.as_ref() }).cloned() else {
        let actual_type = unsafe { handle.as_ref() }
            .map(Value::type_name)
            .unwrap_or("null");
        return Err(RuntimeError::unsupported_call(
            callable,
            format!(
                "{label} type enforcement failed: variadic collection expects array, got {actual_type}"
            ),
        ));
    };

    let mut coerced_array = PhpArray::new();
    for entry in array.entries() {
        let value = entry.value_cloned();
        let actual_type = value.type_name();
        let coerced = coerce_property_value_with_object_type_resolver(
            type_decl,
            value,
            callable,
            label,
            false,
            |object, type_name| object.is_instance_of_class_name(type_name),
        )
        .map_err(|_| {
            RuntimeError::unsupported_call(
                callable,
                format!("{label} expects {type_decl}, got {actual_type}"),
            )
        })?;
        coerced_array.insert(entry.key.clone(), coerced);
    }

    Ok(Value::Array(coerced_array))
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_len(handle: NativeArrayHandle) -> usize {
    unsafe { handle.as_ref() }
        .map(|array| array.value.len())
        .unwrap_or(0)
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_append_scalar(
    mut handle: NativeArrayHandle,
    value: NativeScalarValue,
) -> bool {
    let Some(array) = (unsafe { handle.as_mut() }) else {
        return false;
    };

    array.value.append(value.to_value()).is_ok()
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `value` must be null or a value handle previously
/// returned by the runtime ABI and not yet freed. The appended array slot owns a
/// clone of the value; ownership of `value` remains with the caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_append_value(
    handle: NativeArrayHandle,
    value: NativeValueHandle,
) -> bool {
    unsafe { phpc_native_array_append_value_with_diagnostic(handle, value, ptr::null_mut()) }
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `value` must be null or a value handle previously
/// returned by the runtime ABI and not yet freed. The appended array slot owns a
/// clone of the value; ownership of `value` remains with the caller. On failure
/// the helper stores a diagnostic handle that the caller owns and must release
/// with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_append_value_with_diagnostic(
    mut handle: NativeArrayHandle,
    value: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(array) = (unsafe { handle.as_mut() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_array_access(
                        "native array append failed: array handle is null",
                    )
                    .message(),
                )
            };
        }
        return false;
    };

    let Some(value) = (unsafe { value.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_array_access(
                        "native array append failed: value handle is null",
                    )
                    .message(),
                )
            };
        }
        return false;
    };

    match array.value.append(value.clone()) {
        Ok(_) => true,
        Err(error) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
            }
            false
        }
    }
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `reference` must be null or a live reference handle.
/// The appended array slot shares the reference cell; ownership of `reference`
/// remains with the caller. On failure the helper stores a diagnostic handle
/// that the caller owns and must release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_append_reference_with_diagnostic(
    mut handle: NativeArrayHandle,
    reference: NativeReferenceHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let Some(array) = (unsafe { handle.as_mut() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::invalid_array_access(
                    "native array reference append failed: array handle is null",
                )
                .message(),
            )
        };
        return false;
    };

    let Some(reference) = (unsafe { reference.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::invalid_array_access(
                    "native array reference append failed: reference handle is null",
                )
                .message(),
            )
        };
        return false;
    };

    match array.value.append_reference(reference.cell.clone()) {
        Ok(_) => true,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
///
/// `value` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The returned key materialization result must be
/// released with `phpc_native_array_key_materialization_result_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_to_array_key(
    value: NativeValueHandle,
) -> NativeArrayKeyMaterializationResult {
    let Some(value) = (unsafe { value.as_ref() }) else {
        return NativeArrayKeyMaterializationResult::failure(RuntimeError::invalid_array_key(
            "native array key materialization failed: value handle is null",
        ));
    };

    native_array_key_from_runtime_value(value)
        .map(NativeArrayKeyMaterializationResult::from_array_key)
        .unwrap_or_else(NativeArrayKeyMaterializationResult::failure)
}

/// # Safety
///
/// `value` and `reference` are one logical operand slot. `value` must be null
/// or a value handle previously returned by the runtime ABI and not yet freed;
/// `reference` must be null or a live reference handle. At most one of the two
/// handles may be non-null. The returned result owns either array-key bytes or
/// a diagnostic handle; release owned fields with
/// `phpc_native_array_key_materialization_result_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_to_array_key_with_reference_slot(
    value: NativeValueHandle,
    reference: NativeReferenceHandle,
) -> NativeArrayKeyMaterializationResult {
    if reference.is_null() {
        if value.is_null() {
            return NativeArrayKeyMaterializationResult::failure(RuntimeError::invalid_array_key(
                "native array key materialization failed: value handle is null",
            ));
        }
        return unsafe { phpc_native_value_to_array_key(value) };
    }

    if !value.is_null() {
        return NativeArrayKeyMaterializationResult::failure(RuntimeError::invalid_array_key(
            "native array key materialization failed: key slot received both value and reference handles",
        ));
    }

    let owned_value = unsafe { phpc_native_reference_value_clone(reference) };
    if owned_value.is_null() {
        return NativeArrayKeyMaterializationResult::failure(RuntimeError::invalid_array_key(
            "native array key materialization failed: key reference handle is null",
        ));
    }

    let result = unsafe { phpc_native_value_to_array_key(owned_value) };
    unsafe { phpc_native_value_free(owned_value) };
    result
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `key` must be a result returned by
/// `phpc_native_value_to_array_key`. `value` must be null or a value handle
/// previously returned by the runtime ABI and not yet freed. The inserted array
/// slot owns a clone of the value; ownership of `key` and `value` remains with
/// the caller. On failure the helper stores a diagnostic handle that the caller
/// owns and must release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_insert_key_value_with_diagnostic(
    mut handle: NativeArrayHandle,
    key: NativeArrayKeyMaterializationResult,
    value: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let Some(array) = (unsafe { handle.as_mut() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::invalid_array_access(
                    "native array keyed insert failed: array handle is null",
                )
                .message(),
            )
        };
        return false;
    };

    let Some(value) = (unsafe { value.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::invalid_array_access(
                    "native array keyed insert failed: value handle is null",
                )
                .message(),
            )
        };
        return false;
    };

    match unsafe { native_array_key_materialization_to_array_key(&key) } {
        Ok(key) => {
            array.value.insert(key, value.clone());
            true
        }
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `key` must be a result returned by
