/// # Safety
///
/// `handle` must be null or a reference handle previously returned by the
/// runtime ABI and not yet freed. The returned value handle owns a clone of the
/// current reference-cell value and must be freed independently with
/// `phpc_native_value_free`. Null handles return a null value handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_reference_value_clone(
    handle: NativeReferenceHandle,
) -> NativeValueHandle {
    unsafe { handle.as_ref() }
        .map(|reference| NativeValueHandle::from_value(reference.cell.value_cloned()))
        .unwrap_or_else(NativeValueHandle::null)
}

/// # Safety
///
/// `handle` must be null or a reference handle previously returned by the
/// runtime ABI and not yet freed. `predicate` is one of the native reference
/// predicate tags. On failure the helper stores a diagnostic handle that the
/// caller owns and must release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_reference_predicate(
    handle: NativeReferenceHandle,
    predicate: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let predicate = match NativeReferencePredicate::from_tag(predicate) {
        Ok(predicate) => predicate,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            return false;
        }
    };

    let Some(reference) = (unsafe { handle.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                "native reference predicate failed: reference handle is null",
            )
        };
        return false;
    };

    predicate.evaluate(&reference.cell.value_cloned())
}

/// # Safety
///
/// `handle` must be null or a reference handle previously returned by the
/// runtime ABI and not yet freed. The returned handle points at the same PHP
/// reference cell and must be released independently with
/// `phpc_native_reference_free`. Null handles return a null reference handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_reference_clone(
    handle: NativeReferenceHandle,
) -> NativeReferenceHandle {
    unsafe { handle.as_ref() }
        .map(|reference| NativeReferenceHandle::from_cell(reference.cell.clone()))
        .unwrap_or_else(NativeReferenceHandle::null)
}

/// # Safety
///
/// `value` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The returned handle owns a new PHP reference cell
/// initialized from the current value and must be released independently with
/// `phpc_native_reference_free`. This function always consumes `value`; null
/// handles return a null reference handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_reference_from_value_and_free(
    value: NativeValueHandle,
) -> NativeReferenceHandle {
    let Some(value_ref) = (unsafe { value.as_ref() }) else {
        unsafe { phpc_native_value_free(value) };
        return NativeReferenceHandle::null();
    };
    let stored = value_ref.clone();
    unsafe { phpc_native_value_free(value) };
    native_reference_from_value(stored)
}

unsafe fn native_reference_from_owned_value_handle(
    value: NativeValueHandle,
) -> NativeReferenceHandle {
    unsafe { value.into_value() }
        .map(native_reference_from_value)
        .unwrap_or_else(NativeReferenceHandle::null)
}

/// # Safety
///
/// `handle` must be null or a reference handle previously returned by the
/// runtime ABI and not yet freed. `value` must be null or a value handle
/// previously returned by the runtime ABI and not yet freed. Null handles are
/// rejected and leave the reference unchanged. The reference stores a clone of
/// `value`; ownership of `value` remains with the caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_reference_set_value(
    handle: NativeReferenceHandle,
    value: NativeValueHandle,
) -> bool {
    let (Some(reference), Some(value)) = (unsafe { handle.as_ref() }, unsafe { value.as_ref() })
    else {
        return false;
    };

    reference.cell.set_value(value.clone());
    true
}

/// # Safety
///
/// `handle` must be null or a reference handle previously returned by the
/// runtime ABI and not yet freed. `value` must be null or a value handle
/// previously returned by the runtime ABI and not yet freed. Null handles and
/// type-constraint failures are reported through `diagnostic` and leave the
/// reference unchanged. Ownership of `value` remains with the caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_reference_set_value_with_diagnostic(
    handle: NativeReferenceHandle,
    value: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let (Some(reference), Some(value)) = (unsafe { handle.as_ref() }, unsafe { value.as_ref() })
    else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                "native reference set failed: reference or value handle is null",
            )
        };
        return false;
    };

    match reference.cell.coerce_value_for_write(value.clone()) {
        Ok(value) => {
            reference.cell.set_value(value);
            true
        }
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
