/// # Safety
///
/// `table`, `class_name`, and `diagnostic` must be valid according to the
/// runtime ABI. Returns an owned normalized constructor scope for generated
/// classes when `class_name` is a class string or object whose class is
/// allocatable in the callable table. Class aliases are resolved through the
/// shared generated user-class metadata registry.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_constructor_scope_from_value_with_diagnostic(
    table: NativeCallableTableHandle,
    class_name: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeStringHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| -> Result<NativeStringHandle, String> {
        let Some(table) = (unsafe { table.as_ref() }) else {
            return Err("native constructor allocation failed: table is null".to_string());
        };
        let Some(value) = (unsafe { class_name.as_ref() }) else {
            return Err(
                "native constructor allocation failed: class-name handle is null".to_string(),
            );
        };
        let scope = match value {
            Value::String(class_name) => table.allocatable_scope_for_class_name(class_name),
            Value::Object(object) => table.allocatable_scope_for_class_name(object.class_name()),
            other => {
                return Err(RuntimeError::unsupported_object_instantiation(
                    "dynamic class name",
                    format!(
                        "dynamic class-name expression must be object or class string, got {}",
                        other.type_name()
                    ),
                )
                .message()
                .to_string())
            }
        };
        let Some(scope) = scope else {
            let name = match value {
                Value::String(class_name) => class_name.as_str(),
                Value::Object(object) => object.class_name(),
                _ => "dynamic class name",
            };
            return Err(format!(
                "native constructor allocation failed: unknown or non-allocatable class {name}"
            ));
        };
        Ok(NativeStringHandle::from_vec(scope))
    })();

    match result {
        Ok(scope) => scope,
        Err(message) => {
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            NativeStringHandle::null()
        }
    }
}

/// # Safety
///
/// `table`, `class_name`, `registry`, and `diagnostic` must be valid according
/// to the runtime ABI. Returns an owned normalized constructor scope for
/// generated classes. String class names that do not already resolve against
/// the generated callable/class table invoke the request-local SPL autoload
/// registry before scope lookup is retried.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_constructor_scope_from_value_with_autoload_registry_and_diagnostic(
    table: NativeCallableTableHandle,
    class_name: NativeValueHandle,
    mut registry: NativeSplAutoloadRegistryHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeStringHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| -> Result<NativeStringHandle, String> {
        let Some(table) = (unsafe { table.as_ref() }) else {
            return Err("native constructor allocation failed: table is null".to_string());
        };
        let Some(value) = (unsafe { class_name.as_ref() }) else {
            return Err(
                "native constructor allocation failed: class-name handle is null".to_string(),
            );
        };
        let scope = match value {
            Value::String(class_name) => {
                let mut scope = table.allocatable_scope_for_class_name(class_name);
                if scope.is_none() {
                    if let Some(registry) = unsafe { registry.as_mut() } {
                        if !unsafe {
                            native_spl_autoload_call_bytes(
                                registry,
                                class_name.as_bytes(),
                                Some(NativeClassMetadataOperation::ClassExists as u8),
                                diagnostic,
                            )
                        } {
                            return Ok(NativeStringHandle::null());
                        }
                        if unsafe { native_diagnostic_slot_is_set(diagnostic) } {
                            return Ok(NativeStringHandle::null());
                        }
                        scope = table.allocatable_scope_for_class_name(class_name);
                    }
                }
                scope
            }
            Value::Object(object) => table.allocatable_scope_for_class_name(object.class_name()),
            other => {
                return Err(RuntimeError::unsupported_object_instantiation(
                    "dynamic class name",
                    format!(
                        "dynamic class-name expression must be object or class string, got {}",
                        other.type_name()
                    ),
                )
                .message()
                .to_string())
            }
        };
        let Some(scope) = scope else {
            let name = match value {
                Value::String(class_name) => class_name.as_str(),
                Value::Object(object) => object.class_name(),
                _ => "dynamic class name",
            };
            return Err(format!(
                "native constructor allocation failed: unknown or non-allocatable class {name}"
            ));
        };
        Ok(NativeStringHandle::from_vec(scope))
    })();

    match result {
        Ok(scope) => scope,
        Err(message) => {
            if !unsafe { native_diagnostic_slot_is_set(diagnostic) } {
                unsafe { native_store_diagnostic_message(diagnostic, message) };
            }
            NativeStringHandle::null()
        }
    }
}

/// # Safety
///
/// `handle` must be null or a callable handle previously returned by the
/// runtime ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_free(handle: NativeCallableHandle) {
    if handle.ptr.is_null() {
        return;
    }

    drop(unsafe { Box::from_raw(handle.ptr) });
}

/// # Safety
///
/// `handle` must be null or a callable handle previously returned by the
/// runtime ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_is_static(handle: NativeCallableHandle) -> bool {
    unsafe { handle.as_ref() }
        .map(|callable| callable.descriptor.is_static)
        .unwrap_or(false)
}

fn native_callable_value_name(value: &Value, context: &str) -> Result<String, String> {
    match value {
        Value::String(name) => Ok(name.clone()),
        Value::BinaryString(bytes) => String::from_utf8(bytes.clone())
            .map_err(|_| format!("native callable lookup failed: {context} must be valid UTF-8")),
        _ => Err(format!(
            "native callable lookup failed: {context} must be a string, got {}",
            value.type_name()
        )),
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeCallableClassMethodName {
    class_name: String,
    method_name: String,
}

fn native_callable_value_class_method_name(name: &str) -> Option<NativeCallableClassMethodName> {
    let (class_name, method_name) = name.split_once("::")?;
    if class_name.is_empty() || method_name.is_empty() {
        return None;
    }
    Some(NativeCallableClassMethodName {
        class_name: class_name.to_string(),
        method_name: method_name.to_string(),
    })
}

fn native_callable_builtin_for_function_name(name: &str) -> Option<NativeCallableBuiltin> {
    match name.to_ascii_lowercase().as_str() {
        "strlen" => Some(NativeCallableBuiltin::StringLength),
        "str_contains" => Some(NativeCallableBuiltin::StringPredicate(
            NativeStringPredicate::Contains,
        )),
        "str_starts_with" => Some(NativeCallableBuiltin::StringPredicate(
            NativeStringPredicate::StartsWith,
        )),
        "str_ends_with" => Some(NativeCallableBuiltin::StringPredicate(
            NativeStringPredicate::EndsWith,
        )),
        "strrev" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::Reverse,
        )),
        "bin2hex" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::BinToHex,
        )),
        "str_rot13" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::Rot13,
        )),
        "strtolower" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::AsciiLower,
        )),
        "strtoupper" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::AsciiUpper,
        )),
        "ucfirst" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::AsciiFirstUpper,
        )),
        "lcfirst" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::AsciiFirstLower,
        )),
        "escapeshellarg" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::ShellArgEscape,
        )),
        "escapeshellcmd" => Some(NativeCallableBuiltin::StringResult(
            NativeStringResultOperation::ShellCommandEscape,
        )),
        "strpos" => Some(NativeCallableBuiltin::StringSearch(
            NativeStringSearchOperation::Position,
        )),
        "trim" => Some(NativeCallableBuiltin::StringTrim(NativeTrimMode::Both)),
        "ltrim" => Some(NativeCallableBuiltin::StringTrim(NativeTrimMode::Left)),
        "rtrim" => Some(NativeCallableBuiltin::StringTrim(NativeTrimMode::Right)),
        "sort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Sort,
        )),
        "rsort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Rsort,
        )),
        "asort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Asort,
        )),
        "arsort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Arsort,
        )),
        "ksort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Ksort,
        )),
        "krsort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Krsort,
        )),
        "natsort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Natsort,
        )),
        "natcasesort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Natcasesort,
        )),
        "usort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Usort,
        )),
        "uasort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Uasort,
        )),
        "uksort" => Some(NativeCallableBuiltin::ArraySort(
            NativeArraySortOperation::Uksort,
        )),
        "array_push" => Some(NativeCallableBuiltin::ArrayMutation(
            NativeArrayMutationOperation::Push,
        )),
        "array_pop" => Some(NativeCallableBuiltin::ArrayMutation(
            NativeArrayMutationOperation::Pop,
        )),
        "array_shift" => Some(NativeCallableBuiltin::ArrayMutation(
            NativeArrayMutationOperation::Shift,
        )),
        "array_unshift" => Some(NativeCallableBuiltin::ArrayMutation(
            NativeArrayMutationOperation::Unshift,
        )),
        "strval" => Some(NativeCallableBuiltin::Cast(NATIVE_VALUE_CAST_STRING)),
        "boolval" => Some(NativeCallableBuiltin::Cast(NATIVE_VALUE_CAST_BOOL)),
        "floatval" | "doubleval" => Some(NativeCallableBuiltin::Cast(NATIVE_VALUE_CAST_FLOAT)),
        "gettype" => Some(NativeCallableBuiltin::TypeName(
            NATIVE_VALUE_TYPE_NAME_GETTYPE,
        )),
        "get_debug_type" => Some(NativeCallableBuiltin::TypeName(
            NATIVE_VALUE_TYPE_NAME_DEBUG,
        )),
        "is_null" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_NULL,
        )),
        "is_bool" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_BOOL,
        )),
        "is_int" | "is_integer" | "is_long" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_INT,
        )),
        "is_float" | "is_double" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_FLOAT,
        )),
        "is_string" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_STRING,
        )),
        "is_array" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_ARRAY,
        )),
        "is_scalar" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_SCALAR,
        )),
        "is_numeric" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_NUMERIC,
        )),
        "is_countable" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_COUNTABLE,
        )),
        "is_iterable" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_ITERABLE,
        )),
        "is_object" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_OBJECT,
        )),
        "is_resource" => Some(NativeCallableBuiltin::TypePredicate(
            NATIVE_VALUE_TYPE_IS_RESOURCE,
        )),
        _ => None,
    }
}

const RUNTIME_DYNAMIC_GENERATED_C_UNSUPPORTED_NATIVE_BUILTIN_REASON: &str =
    "runtime dynamic generated-C lookup did not find a registered user-function frame or supported native builtin family";

fn native_callable_unsupported_runtime_builtin_canonical_name(name: &str) -> Option<&'static str> {
    match name.to_ascii_lowercase().as_str() {
        "count" => Some("count"),
        "sizeof" => Some("sizeof"),
        _ => None,
    }
}

fn native_callable_unsupported_runtime_builtin_boundary_message(name: &str) -> Option<String> {
    let canonical_name = native_callable_unsupported_runtime_builtin_canonical_name(name)?;
    Some(
        RuntimeError::unsupported_call(
            format!("{canonical_name}()"),
            RUNTIME_DYNAMIC_GENERATED_C_UNSUPPORTED_NATIVE_BUILTIN_REASON,
        )
        .message()
        .to_string(),
    )
}

fn native_callable_value_lookup(
    table: Option<&NativeCallableTable>,
    callable_value: &Value,
    caller_scope: Option<String>,
) -> Result<NativeCallableValueDispatch, String> {
    match callable_value {
        Value::String(_) | Value::BinaryString(_) => {
            let name = native_callable_value_name(callable_value, "function callable name")?;
            if let Some(class_method) = native_callable_value_class_method_name(&name) {
                let table = table.ok_or_else(|| {
                    "native callable lookup failed: table is null for class-method string callable"
                        .to_string()
                })?;
                let callable = table.lookup(
                    NativeCallableKind::Method,
                    Some(class_method.class_name.clone()),
                    class_method.method_name,
                    caller_scope,
                )?;
                if !callable.descriptor.is_static {
                    let scope = callable
                        .called_scope
                        .as_deref()
                        .or(callable.descriptor.scope.as_deref())
                        .unwrap_or("<unknown>");
                    return Err(format!(
                        "native callable lookup failed: non-static method {}::{} cannot be used as a class-method string callable",
                        scope, callable.descriptor.name
                    ));
                }
                return Ok(NativeCallableValueDispatch::Table {
                    callable,
                    bound_receiver: None,
                });
            }
            if let Some(table) = table {
                match table.lookup(
                    NativeCallableKind::Function,
                    None,
                    name.clone(),
                    caller_scope,
                ) {
                    Ok(callable) => {
                        return Ok(NativeCallableValueDispatch::Table {
                            callable,
                            bound_receiver: None,
                        })
                    }
                    Err(error) => {
                        if let Some(builtin) = native_callable_builtin_for_function_name(&name) {
                            return Ok(NativeCallableValueDispatch::Builtin(builtin));
                        }
                        if let Some(message) =
                            native_callable_unsupported_runtime_builtin_boundary_message(&name)
                        {
                            return Err(message);
                        }
                        return Err(error);
                    }
                }
            }
            if let Some(builtin) = native_callable_builtin_for_function_name(&name) {
                return Ok(NativeCallableValueDispatch::Builtin(builtin));
            }
            if let Some(message) =
                native_callable_unsupported_runtime_builtin_boundary_message(&name)
            {
                return Err(message);
            }
            Err("native callable lookup failed: table is null for string callable".to_string())
        }
        Value::Array(array) => {
            let table = table.ok_or_else(|| {
                "native callable lookup failed: table is null for callable array".to_string()
            })?;
            if array.len() != 2 {
                return Err(format!(
                    "native callable lookup failed: callable array must contain exactly target and method entries, got {} entries",
                    array.len()
                ));
            }
            let Some(target) = array.get_cloned(ArrayKey::Int(0)) else {
                return Err(
                    "native callable lookup failed: callable array target entry 0 is missing"
                        .to_string(),
                );
            };
            let Some(method_value) = array.get_cloned(ArrayKey::Int(1)) else {
                return Err(
                    "native callable lookup failed: callable array method entry 1 is missing"
                        .to_string(),
                );
            };
            let method = native_callable_value_name(&method_value, "callable array method name")?;
            match target {
                Value::String(_) | Value::BinaryString(_) => {
                    let scope = native_callable_value_name(&target, "callable array class name")?;
                    let callable = table.lookup(
                        NativeCallableKind::Method,
                        Some(scope),
                        method,
                        caller_scope,
                    )?;
                    Ok(NativeCallableValueDispatch::Table {
                        callable,
                        bound_receiver: None,
                    })
                }
                Value::Object(object) => {
                    let callable = table.lookup(
                        NativeCallableKind::Method,
                        Some(object.class_name().to_string()),
                        method,
                        caller_scope,
                    )?;
                    Ok(NativeCallableValueDispatch::Table {
                        callable,
                        bound_receiver: Some(Value::Object(object)),
                    })
                }
                other => Err(format!(
                    "native callable lookup failed: callable array target must be a class string or object, got {}",
                    other.type_name()
                )),
            }
        }
        Value::Closure(closure) => {
            let Some(descriptor) = closure.descriptor() else {
                return Err(
                    "native callable lookup failed: closure value has no native descriptor/frame callback"
                        .to_string(),
                );
            };
            if !descriptor.is_invokable() {
                return Err(
                    "native callable lookup failed: closure descriptor is not invokable"
                        .to_string(),
                );
            }
            Ok(NativeCallableValueDispatch::DescriptorClosure(
                closure.clone(),
            ))
        }
        Value::Object(object) => {
            let table = table.ok_or_else(|| {
                "native callable lookup failed: table is null for object callable".to_string()
            })?;
            let callable = table.lookup_with_access_context(
                NativeCallableKind::Method,
                Some(object.class_name().to_string()),
                "__invoke".to_string(),
                caller_scope
                    .map(
                        |caller_scope| NativeCallableAccessContext::ClassContextLookup {
                            caller_scope,
                        },
                    )
                    .unwrap_or(NativeCallableAccessContext::ObjectReceiverLookup),
            )?;
            if callable.descriptor.is_static {
                let scope = callable
                    .called_scope
                    .as_deref()
                    .or(callable.descriptor.scope.as_deref())
                    .unwrap_or("<unknown>");
                return Err(format!(
                    "native callable lookup failed: static method {}::__invoke cannot be used for object callable dispatch",
                    scope
                ));
            }
            if callable.descriptor.visibility != NativeCallableVisibility::Public {
                let scope = callable
                    .called_scope
                    .as_deref()
                    .or(callable.descriptor.scope.as_deref())
                    .unwrap_or("<unknown>");
                return Err(format!(
                    "native callable lookup failed: magic method {scope}::__invoke must be public for object callable dispatch"
                ));
            }
            Ok(NativeCallableValueDispatch::Table {
                callable,
                bound_receiver: Some(Value::Object(object.clone())),
            })
        }
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::Resource(_) => {
            Err(format!(
                "native callable lookup failed: value of type {} is not callable",
                callable_value.type_name()
            ))
        }
    }
}

fn native_callable_value_source_signature(
    dispatch: &NativeCallableValueDispatch,
) -> Result<NativeCallableSourceSignature, String> {
    match dispatch {
        NativeCallableValueDispatch::Builtin(builtin) => {
            builtin.signature().source_signature().ok_or_else(|| {
                format!(
                    "native callable source-call signature lookup failed: runtime builtin {} has no materialized argument signature metadata",
                    builtin.name()
                )
            })
        }
        NativeCallableValueDispatch::Table { callable, .. } => callable
            .descriptor
            .source_signature
            .clone()
            .ok_or_else(|| {
                let scope = callable
                    .called_scope
                    .as_deref()
                    .or(callable.descriptor.scope.as_deref())
                    .unwrap_or("<global>");
                format!(
                    "native callable source-call signature lookup failed: registered callable {}::{} has no runtime materialized argument signature metadata",
                    scope, callable.descriptor.name
                )
            }),
        NativeCallableValueDispatch::DescriptorClosure(closure) => {
            closure.source_signature().ok_or_else(|| {
                "native callable source-call signature lookup failed: descriptor-backed closure value has no runtime parameter names/defaults for materialized argument finalization"
                    .to_string()
            })
        }
    }
}

fn native_callable_scope_key(scope: Option<&str>) -> Option<String> {
    scope.map(normalize_class_lookup_name)
}

fn native_callable_name_key(kind: NativeCallableKind, name: &str) -> String {
    match kind {
        NativeCallableKind::Function | NativeCallableKind::Method => name.to_ascii_lowercase(),
        NativeCallableKind::Constructor => name.to_ascii_lowercase(),
    }
}

fn native_callable_dispatches_match(
    left: &NativeCallableValueDispatch,
    right: &NativeCallableValueDispatch,
) -> bool {
    match (left, right) {
        (
            NativeCallableValueDispatch::Table {
                callable: left,
                bound_receiver: left_receiver,
            },
            NativeCallableValueDispatch::Table {
                callable: right,
                bound_receiver: right_receiver,
            },
        ) => {
            left.descriptor.kind == right.descriptor.kind
                && native_callable_scope_key(left.descriptor.scope.as_deref())
                    == native_callable_scope_key(right.descriptor.scope.as_deref())
                && native_callable_name_key(left.descriptor.kind, &left.descriptor.name)
                    == native_callable_name_key(right.descriptor.kind, &right.descriptor.name)
                && native_callable_scope_key(left.called_scope.as_deref())
                    == native_callable_scope_key(right.called_scope.as_deref())
                && left_receiver == right_receiver
        }
        (
            NativeCallableValueDispatch::Builtin(left),
            NativeCallableValueDispatch::Builtin(right),
        ) => left == right,
        (
            NativeCallableValueDispatch::DescriptorClosure(left),
            NativeCallableValueDispatch::DescriptorClosure(right),
        ) => left == right,
        _ => false,
    }
}

fn native_spl_autoload_static_method_value(class_name: String, method_name: String) -> Value {
    let mut callable = PhpArray::new();
    callable.insert(ArrayKey::Int(0), Value::String(class_name));
    callable.insert(ArrayKey::Int(1), Value::String(method_name));
    Value::Array(callable)
}

fn native_spl_autoload_value_name(value: &Value) -> Option<String> {
    match value {
        Value::String(value) => Some(value.clone()),
        Value::BinaryString(value) => String::from_utf8(value.clone()).ok(),
        _ => None,
    }
}

fn native_spl_autoload_callback_value_from_dispatch(
    dispatch: &NativeCallableValueDispatch,
) -> Result<Value, String> {
    match dispatch {
        NativeCallableValueDispatch::Table {
            callable,
            bound_receiver,
        } => match callable.descriptor.kind {
            NativeCallableKind::Function => Ok(Value::String(callable.descriptor.name.clone())),
            NativeCallableKind::Method | NativeCallableKind::Constructor => {
                if let Some(receiver) = bound_receiver {
                    if callable.descriptor.name.eq_ignore_ascii_case("__invoke") {
                        return Ok(receiver.clone());
                    }
                    let mut value = PhpArray::new();
                    value.insert(ArrayKey::Int(0), receiver.clone());
                    value.insert(
                        ArrayKey::Int(1),
                        Value::String(callable.descriptor.name.clone()),
                    );
                    Ok(Value::Array(value))
                } else {
                    let scope = callable
                        .called_scope
                        .as_ref()
                        .or(callable.descriptor.scope.as_ref())
                        .ok_or_else(|| {
                            "spl_autoload_functions(): registered static method callback has no class scope"
                                .to_string()
                        })?;
                    Ok(native_spl_autoload_static_method_value(
                        scope.clone(),
                        callable.descriptor.name.clone(),
                    ))
                }
            }
        },
        NativeCallableValueDispatch::Builtin(builtin) => {
            Ok(Value::String(builtin.name().to_string()))
        }
        NativeCallableValueDispatch::DescriptorClosure(closure) => {
            Ok(Value::Closure(closure.clone()))
        }
    }
}

fn native_spl_autoload_callback_value_from_registration(
    dispatch: &NativeCallableValueDispatch,
    callback_value: Option<&Value>,
) -> Result<Value, String> {
    let Some(callback_value) = callback_value else {
        return native_spl_autoload_callback_value_from_dispatch(dispatch);
    };

    match callback_value {
        Value::String(_) | Value::BinaryString(_) => {
            let name = native_spl_autoload_value_name(callback_value).ok_or_else(|| {
                "spl_autoload_register(): callback string must be valid UTF-8 in the current native subset"
                    .to_string()
            })?;
            if let Some(class_method) = native_callable_value_class_method_name(&name) {
                return Ok(native_spl_autoload_static_method_value(
                    class_method.class_name,
                    class_method.method_name,
                ));
            }
            Ok(callback_value.clone())
        }
        Value::Array(_) | Value::Object(_) | Value::Closure(_) => Ok(callback_value.clone()),
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::Resource(_) => {
            native_spl_autoload_callback_value_from_dispatch(dispatch)
        }
    }
}

#[derive(Debug)]
enum NativeSplAutoloadCallbackIdentity {
    Function(String),
    StaticMethod {
        class_name: String,
        method_name: String,
    },
    ObjectMethod {
        object: PhpObject,
        method_name: String,
    },
    InvokableObject(PhpObject),
    Closure(PhpClosure),
}

fn native_spl_autoload_callback_identity(
    value: &Value,
) -> Option<NativeSplAutoloadCallbackIdentity> {
    match value {
        Value::String(_) | Value::BinaryString(_) => {
            let name = native_spl_autoload_value_name(value)?;
            if let Some(class_method) = native_callable_value_class_method_name(&name) {
                Some(NativeSplAutoloadCallbackIdentity::StaticMethod {
                    class_name: class_method.class_name,
                    method_name: class_method.method_name,
                })
            } else {
                Some(NativeSplAutoloadCallbackIdentity::Function(name))
            }
        }
        Value::Array(array) => {
            if array.len() != 2 {
                return None;
            }
            let target = array.get_cloned(ArrayKey::Int(0))?;
            let method = array.get_cloned(ArrayKey::Int(1))?;
            let method_name = native_spl_autoload_value_name(&method)?;
            match target {
                Value::String(_) | Value::BinaryString(_) => {
                    let class_name = native_spl_autoload_value_name(&target)?;
                    Some(NativeSplAutoloadCallbackIdentity::StaticMethod {
                        class_name,
                        method_name,
                    })
                }
                Value::Object(object) => Some(NativeSplAutoloadCallbackIdentity::ObjectMethod {
                    object,
                    method_name,
                }),
                _ => None,
            }
        }
        Value::Object(object) => Some(NativeSplAutoloadCallbackIdentity::InvokableObject(
            object.clone(),
        )),
        Value::Closure(closure) => {
            Some(NativeSplAutoloadCallbackIdentity::Closure(closure.clone()))
        }
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::Resource(_) => None,
    }
}

fn native_spl_autoload_callback_identities_match(
    left: NativeSplAutoloadCallbackIdentity,
    right: NativeSplAutoloadCallbackIdentity,
) -> bool {
    match (left, right) {
        (
            NativeSplAutoloadCallbackIdentity::Function(left),
            NativeSplAutoloadCallbackIdentity::Function(right),
        ) => left.eq_ignore_ascii_case(&right),
        (
            NativeSplAutoloadCallbackIdentity::StaticMethod {
                class_name: left_class,
                method_name: left_method,
            },
            NativeSplAutoloadCallbackIdentity::StaticMethod {
                class_name: right_class,
                method_name: right_method,
            },
        ) => {
            left_class.eq_ignore_ascii_case(&right_class)
                && left_method.eq_ignore_ascii_case(&right_method)
        }
        (
            NativeSplAutoloadCallbackIdentity::ObjectMethod {
                object: left_object,
                method_name: left_method,
            },
            NativeSplAutoloadCallbackIdentity::ObjectMethod {
                object: right_object,
                method_name: right_method,
            },
        ) => left_object == right_object && left_method.eq_ignore_ascii_case(&right_method),
        (
            NativeSplAutoloadCallbackIdentity::InvokableObject(left),
            NativeSplAutoloadCallbackIdentity::InvokableObject(right),
        ) => left == right,
        (
            NativeSplAutoloadCallbackIdentity::Closure(left),
            NativeSplAutoloadCallbackIdentity::Closure(right),
        ) => left.id() == right.id(),
        _ => false,
    }
}

fn native_spl_autoload_callbacks_match(
    left: &NativeSplAutoloadCallback,
    right: &NativeSplAutoloadCallback,
) -> bool {
    match (
        native_spl_autoload_callback_identity(&left.value),
        native_spl_autoload_callback_identity(&right.value),
    ) {
        (Some(left), Some(right)) => native_spl_autoload_callback_identities_match(left, right),
        _ => native_callable_dispatches_match(&left.dispatch, &right.dispatch),
    }
}

#[no_mangle]
pub extern "C" fn phpc_native_callable_value_null() -> NativeCallableValueHandle {
    NativeCallableValueHandle::null()
}

#[no_mangle]
pub extern "C" fn phpc_native_callable_value_is_null(handle: NativeCallableValueHandle) -> bool {
    handle.is_null()
}

/// # Safety
///
/// `handle` must be null or a callable-value dispatch handle previously
/// returned by the runtime ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_value_free(handle: NativeCallableValueHandle) {
    if handle.ptr.is_null() {
        return;
    }

    drop(unsafe { Box::from_raw(handle.ptr) });
}

unsafe fn native_callable_value_dispatch_take(
    handle: NativeCallableValueHandle,
) -> Option<NativeCallableValueDispatch> {
    if handle.ptr.is_null() {
        None
    } else {
        Some(*unsafe { Box::from_raw(handle.ptr) })
    }
}

