/// # Safety
///
/// `arguments` must be a materialized call-arguments handle. `value` is
/// consumed exactly once. Array integer keys become positional materialized
/// entries and array string keys become named materialized entries.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_materialized_call_arguments_unpack_array_value_and_free(
    mut arguments: NativeMaterializedCallArgumentsHandle,
    value: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let Some(arguments) = (unsafe { arguments.as_mut() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                "native call argument unpack failed: materialized entries handle is null",
            )
        };
        unsafe { phpc_native_value_free(value) };
        return false;
    };

    let Some(value_ref) = (unsafe { value.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                "native call argument unpack failed: spread value handle is null",
            )
        };
        unsafe { phpc_native_value_free(value) };
        return false;
    };

    let Value::Array(array) = value_ref else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::unsupported_call(
                    "argument unpacking",
                    format!(
                        "spread operand must be array in generated C, got {}",
                        value_ref.type_name()
                    ),
                )
                .message(),
            )
        };
        unsafe { phpc_native_value_free(value) };
        return false;
    };

    for entry in array.entries() {
        let name = match &entry.key {
            ArrayKey::Int(_) => None,
            ArrayKey::String(name) => Some(name.clone()),
        };
        arguments.entries.push(NativeMaterializedCallArgumentEntry {
            name,
            slot: native_materialized_call_argument_slot_from_array_slot(entry.slot()),
        });
    }

    unsafe { phpc_native_value_free(value) };
    true
}

unsafe fn native_parameter_name_slice(
    parameter_names: *const NativeStringHandle,
    fixed_count: usize,
) -> Result<Vec<String>, String> {
    if fixed_count == 0 {
        return Ok(Vec::new());
    }
    if parameter_names.is_null() {
        return Err(
            "native materialized call-argument finalization failed: parameter-name vector is null"
                .to_string(),
        );
    }

    unsafe { std::slice::from_raw_parts(parameter_names, fixed_count) }
        .iter()
        .enumerate()
        .map(|(index, name)| {
            unsafe { native_string_handle_to_string(*name) }.ok_or_else(|| {
                format!(
                    "native materialized call-argument finalization failed: parameter name at slot {index} is null or not UTF-8"
                )
            })
        })
        .collect()
}

unsafe fn native_u8_metadata_slice<'a>(
    pointer: *const u8,
    fixed_count: usize,
    label: &str,
) -> Result<&'a [u8], String> {
    if fixed_count == 0 {
        return Ok(&[]);
    }
    if pointer.is_null() {
        return Err(format!(
            "native materialized call-argument finalization failed: {label} vector is null"
        ));
    }
    Ok(unsafe { std::slice::from_raw_parts(pointer, fixed_count) })
}

unsafe fn native_default_value_slice<'a>(
    pointer: *const NativeValueHandle,
    fixed_count: usize,
) -> Result<&'a [NativeValueHandle], String> {
    if fixed_count == 0 {
        return Ok(&[]);
    }
    if pointer.is_null() {
        return Err(
            "native materialized call-argument finalization failed: default-value vector is null"
                .to_string(),
        );
    }
    Ok(unsafe { std::slice::from_raw_parts(pointer, fixed_count) })
}

unsafe fn native_materialized_slot_for_parameter(
    slot: NativeCallArgumentSlot,
    parameter_name: &str,
    by_reference: bool,
) -> Result<NativeCallArgumentSlot, String> {
    match (slot, by_reference) {
        (NativeCallArgumentSlot::Value(value), false) => {
            let cloned = unsafe { phpc_native_value_clone(value) };
            if cloned.is_null() {
                Err(format!(
                    "native materialized call-argument finalization failed: value for parameter ${parameter_name} is null"
                ))
            } else {
                Ok(NativeCallArgumentSlot::Value(cloned))
            }
        }
        (NativeCallArgumentSlot::Reference(reference), false) => {
            let cloned = unsafe { phpc_native_reference_value_clone(reference) };
            if cloned.is_null() {
                Err(format!(
                    "native materialized call-argument finalization failed: reference value for parameter ${parameter_name} is null"
                ))
            } else {
                Ok(NativeCallArgumentSlot::Value(cloned))
            }
        }
        (NativeCallArgumentSlot::Reference(reference), true) => {
            let cloned = unsafe { phpc_native_reference_clone(reference) };
            if cloned.is_null() {
                Err(format!(
                    "native materialized call-argument finalization failed: reference for parameter ${parameter_name} is null"
                ))
            } else {
                Ok(NativeCallArgumentSlot::Reference(cloned))
            }
        }
        (NativeCallArgumentSlot::Value(_), true) => Err(format!(
            "unsupported call argument unpacking: by-reference parameter ${parameter_name} requires reference materialization before NativeCallArgumentsHandle finalization"
        )),
    }
}

unsafe fn native_materialized_slot_value_clone(
    slot: NativeCallArgumentSlot,
) -> Result<Value, String> {
    match slot {
        NativeCallArgumentSlot::Value(value) => unsafe { value.as_ref() }.cloned().ok_or_else(|| {
            "native materialized call-argument finalization failed: variadic value slot is null"
                .to_string()
        }),
        NativeCallArgumentSlot::Reference(reference) => unsafe { reference.as_ref() }
            .map(|reference| reference.cell.value_cloned())
            .ok_or_else(|| {
                "native materialized call-argument finalization failed: variadic reference slot is null"
                    .to_string()
            }),
    }
}

unsafe fn native_materialized_slot_forward_source_clone(
    slot: NativeCallArgumentSlot,
) -> Result<NativeCallArgumentSlot, String> {
    match slot {
        NativeCallArgumentSlot::Value(value) => {
            let cloned = unsafe { phpc_native_value_clone(value) };
            if cloned.is_null() {
                Err(
                    "native materialized call-argument source forwarding failed: value slot is null"
                        .to_string(),
                )
            } else {
                Ok(NativeCallArgumentSlot::Value(cloned))
            }
        }
        NativeCallArgumentSlot::Reference(reference) => {
            let cloned = unsafe { phpc_native_reference_clone(reference) };
            if cloned.is_null() {
                Err(
                    "native materialized call-argument source forwarding failed: reference slot is null"
                        .to_string(),
                )
            } else {
                Ok(NativeCallArgumentSlot::Reference(cloned))
            }
        }
    }
}

unsafe fn native_materialized_call_arguments_forward_source(
    materialized: &NativeMaterializedCallArguments,
    target: &mut NativeCallArguments,
) -> Result<(), String> {
    for (entry_index, entry) in materialized.entries.iter().enumerate() {
        let slot = unsafe { native_materialized_slot_forward_source_clone(entry.slot) }
            .map_err(|message| format!("{message} at materialized entry {entry_index}"))?;
        target.slots.push(slot);
        target.names.push(entry.name.clone());
    }
    target.finalized_variadic = false;
    Ok(())
}

unsafe fn native_materialized_slot_reference_clone(
    slot: NativeCallArgumentSlot,
    parameter_name: &str,
) -> Result<PhpReferenceCell, String> {
    match slot {
        NativeCallArgumentSlot::Reference(reference) => unsafe { reference.as_ref() }
            .map(|reference| reference.cell.clone())
            .ok_or_else(|| {
                format!(
                    "native materialized call-argument finalization failed: variadic reference slot for parameter ${parameter_name} is null"
                )
            }),
        NativeCallArgumentSlot::Value(_) => Err(format!(
            "unsupported call argument unpacking: by-reference parameter ${parameter_name} requires reference materialization before NativeCallArgumentsHandle finalization"
        )),
    }
}

unsafe fn native_materialized_call_arguments_finalize(
    materialized: &NativeMaterializedCallArguments,
    parameter_names: Vec<String>,
    parameter_required: &[u8],
    parameter_by_reference: &[u8],
    parameter_defaults: &[NativeValueHandle],
    variadic_parameter_name: Option<String>,
    has_variadic: bool,
    variadic_by_reference: bool,
) -> Result<NativeCallArgumentsHandle, String> {
    let fixed_count = parameter_names.len();
    let mut supplied_fixed_entries: Vec<Option<usize>> = vec![None; fixed_count];
    let mut variadic_entries = Vec::new();
    let mut seen_named = false;
    let mut next_positional_index = 0usize;
    let mut named_entries = std::collections::HashMap::<String, usize>::new();
    let fixed_name_to_index = parameter_names
        .iter()
        .enumerate()
        .map(|(index, name)| (name.clone(), index))
        .collect::<std::collections::HashMap<_, _>>();

    for (entry_index, entry) in materialized.entries.iter().enumerate() {
        if let Some(name) = &entry.name {
            seen_named = true;
            if let Some(first_entry_index) = named_entries.get(name).copied() {
                return Err(format!(
                    "duplicate named argument ${name} from materialized entry {entry_index}; first supplied by entry {first_entry_index}"
                ));
            }
            named_entries.insert(name.clone(), entry_index);

            if let Some(parameter_index) = fixed_name_to_index.get(name).copied() {
                if let Some(first_entry_index) = supplied_fixed_entries[parameter_index] {
                    return Err(format!(
                        "duplicate argument for parameter ${name} from materialized entry {entry_index}; first supplied by entry {first_entry_index}"
                    ));
                }
                supplied_fixed_entries[parameter_index] = Some(entry_index);
            } else if has_variadic {
                variadic_entries.push(entry_index);
            } else {
                return Err(format!(
                    "unknown named argument ${name} from materialized entry {entry_index}"
                ));
            }
        } else {
            if seen_named {
                return Err(format!(
                    "positional argument from materialized entry {entry_index} follows a named argument"
                ));
            }
            if next_positional_index < fixed_count {
                supplied_fixed_entries[next_positional_index] = Some(entry_index);
                next_positional_index += 1;
            } else if has_variadic {
                variadic_entries.push(entry_index);
            } else {
                return Err(format!(
                    "too many positional arguments: materialized entry {entry_index} exceeds fixed parameter count {fixed_count}"
                ));
            }
        }
    }

    let mut slots = Vec::new();
    let mut names = Vec::new();
    for parameter_index in 0..fixed_count {
        let parameter_name = &parameter_names[parameter_index];
        if let Some(entry_index) = supplied_fixed_entries[parameter_index] {
            slots.push(unsafe {
                native_materialized_slot_for_parameter(
                    materialized.entries[entry_index].slot,
                    parameter_name,
                    parameter_by_reference[parameter_index] != 0,
                )?
            });
            names.push(None);
        } else if parameter_required[parameter_index] != 0 {
            return Err(format!(
                "missing required argument ${parameter_name} at parameter {parameter_index}"
            ));
        } else {
            if parameter_by_reference[parameter_index] != 0 {
                return Err(format!(
                    "unsupported call argument unpacking: defaulted by-reference parameter ${parameter_name} requires reference materialization before NativeCallArgumentsHandle finalization"
                ));
            }
            let default = parameter_defaults[parameter_index];
            let value = unsafe { phpc_native_value_clone(default) };
            if value.is_null() {
                return Err(format!(
                    "native materialized call-argument finalization failed: default value for parameter ${parameter_name} is null"
                ));
            }
            slots.push(NativeCallArgumentSlot::Value(value));
            names.push(None);
        }
    }

    if has_variadic {
        let parameter_name = variadic_parameter_name.as_deref().unwrap_or("__variadic");
        let mut array = PhpArray::new();
        for entry_index in variadic_entries {
            let entry = &materialized.entries[entry_index];
            if variadic_by_reference {
                let reference =
                    unsafe { native_materialized_slot_reference_clone(entry.slot, parameter_name)? };
                if let Some(name) = &entry.name {
                    array.insert_reference(ArrayKey::string(name.clone()), reference);
                    Ok(ArrayKey::string(name.clone()))
                } else {
                    array.append_reference(reference)
                }
            } else {
                let value = unsafe { native_materialized_slot_value_clone(entry.slot)? };
                if let Some(name) = &entry.name {
                    array.insert_checked(ArrayKey::string(name.clone()), value)
                } else {
                    array.append(value)
                }
            }
            .map_err(|error| {
                format!(
                    "native materialized call-argument finalization failed: variadic collection rejected entry {entry_index}: {}",
                    error.message()
                )
            })?;
        }
        slots.push(NativeCallArgumentSlot::Value(
            NativeValueHandle::from_value(Value::Array(array)),
        ));
        names.push(None);
    }

    Ok(NativeCallArgumentsHandle {
        ptr: Box::into_raw(Box::new(NativeCallArguments {
            slots,
            names,
            finalized_variadic: has_variadic,
        })),
    })
}

/// # Safety
///
/// `entries` is borrowed. Metadata pointers must be null only when
/// `fixed_count` is zero; otherwise they must point to `fixed_count` entries.
/// Default value handles are borrowed and cloned into the finalized call
/// argument handle only when the matching parameter is omitted.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_materialized_call_arguments_finalize_with_diagnostic(
    entries: NativeMaterializedCallArgumentsHandle,
    parameter_names: *const NativeStringHandle,
    parameter_required: *const u8,
    parameter_by_reference: *const u8,
    parameter_defaults: *const NativeValueHandle,
    fixed_count: usize,
    variadic_parameter_name: NativeStringHandle,
    has_variadic: bool,
    variadic_by_reference: bool,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallArgumentsHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let Some(entries) = (unsafe { entries.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                "native materialized call-argument finalization failed: entries handle is null",
            )
        };
        return NativeCallArgumentsHandle::null();
    };

    let result = (|| {
        let names = unsafe { native_parameter_name_slice(parameter_names, fixed_count)? };
        let required =
            unsafe { native_u8_metadata_slice(parameter_required, fixed_count, "required-flag")? };
        let by_reference = unsafe {
            native_u8_metadata_slice(parameter_by_reference, fixed_count, "by-reference-flag")?
        };
        let defaults = unsafe { native_default_value_slice(parameter_defaults, fixed_count)? };
        let variadic_name = if has_variadic {
            Some(unsafe { native_string_handle_to_string(variadic_parameter_name) }.ok_or_else(
                || {
                    "native materialized call-argument finalization failed: variadic parameter name is null or not UTF-8"
                        .to_string()
                },
            )?)
        } else {
            None
        };
        unsafe {
            native_materialized_call_arguments_finalize(
                entries,
                names,
                required,
                by_reference,
                defaults,
                variadic_name,
                has_variadic,
                variadic_by_reference,
            )
        }
    })();

    match result {
        Ok(handle) => handle,
        Err(message) => {
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            NativeCallArgumentsHandle::null()
        }
    }
}

/// # Safety
///
/// `entries` is borrowed. `target` must be a call-arguments handle.
/// Materialized entries are cloned into `target` in source order, preserving
/// named source keys for later magic `$args` packing.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_materialized_call_arguments_forward_source_to_call_arguments_with_diagnostic(
    entries: NativeMaterializedCallArgumentsHandle,
    mut target: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let Some(entries) = (unsafe { entries.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                "native materialized call-argument source forwarding failed: entries handle is null",
            )
        };
        return false;
    };
    let Some(target) = (unsafe { target.as_mut() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                "native materialized call-argument source forwarding failed: target arguments handle is null",
            )
        };
        return false;
    };

    match unsafe { native_materialized_call_arguments_forward_source(entries, target) } {
        Ok(()) => true,
        Err(message) => {
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            false
        }
    }
}

/// # Safety
///
/// `handle` must be null or a materialized call-arguments handle previously
/// returned by the runtime ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_materialized_call_arguments_free(
    handle: NativeMaterializedCallArgumentsHandle,
) {
    if handle.ptr.is_null() {
        return;
    }
    let entries = unsafe { Box::from_raw(handle.ptr) };
    for entry in entries.entries {
        unsafe { entry.slot.free() };
    }
}

/// # Safety
///
/// `arguments` must be null or a call-arguments handle previously returned by
/// the runtime ABI and not yet freed. The returned value is an owned clone.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_arguments_read_value(
    arguments: NativeCallArgumentsHandle,
    index: usize,
) -> NativeValueHandle {
    match unsafe { arguments.as_ref() }.and_then(|arguments| arguments.slots.get(index)) {
        Some(NativeCallArgumentSlot::Value(value)) => unsafe { phpc_native_value_clone(*value) },
        Some(NativeCallArgumentSlot::Reference(reference)) => unsafe {
            phpc_native_reference_value_clone(*reference)
        },
        None => NativeValueHandle::null(),
    }
}

/// # Safety
///
/// `arguments` must be null or a call-arguments handle previously returned by
/// the runtime ABI and not yet freed. The returned reference is an owned clone.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_arguments_read_reference(
    arguments: NativeCallArgumentsHandle,
    index: usize,
) -> NativeReferenceHandle {
    match unsafe { arguments.as_ref() }.and_then(|arguments| arguments.slots.get(index)) {
        Some(NativeCallArgumentSlot::Reference(reference)) => unsafe {
            phpc_native_reference_clone(*reference)
        },
        Some(NativeCallArgumentSlot::Value(_)) | None => NativeReferenceHandle::null(),
    }
}

/// # Safety
///
/// `arguments` must be null or a call-arguments handle previously returned by
/// the runtime ABI. The marker records that the final slot is a packed
/// variadic collection produced by source-call argument binding.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_arguments_mark_finalized_variadic(
    mut arguments: NativeCallArgumentsHandle,
) -> bool {
    let Some(arguments) = (unsafe { arguments.as_mut() }) else {
        return false;
    };
    arguments.finalized_variadic = true;
    true
}

/// # Safety
///
/// `handle` must be null or a call-arguments handle previously returned by the
/// runtime ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_arguments_free(handle: NativeCallArgumentsHandle) {
    #[cfg(test)]
    NATIVE_CALL_ARGUMENTS_FREE_COUNT_FOR_TEST.with(|count| {
        *count.borrow_mut() += 1;
    });

    if handle.ptr.is_null() {
        return;
    }
    let arguments = unsafe { Box::from_raw(handle.ptr) };
    for slot in arguments.slots {
        unsafe { slot.free() };
    }
}

/// # Safety
///
/// `called_scope` may be null or a UTF-8 native string handle. Ownership stays
/// with the caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_new(
    called_scope: NativeStringHandle,
) -> NativeCallFrameHandle {
    NativeCallFrameHandle::from_frame(NativeCallFrame {
        slots: Vec::new(),
        called_scope: unsafe { native_string_handle_to_string(called_scope) },
        receiver: None,
    })
}

/// # Safety
///
/// `frame` and `arguments` must be runtime handles. The frame stores an owned
/// clone of the selected argument slot.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_bind_argument(
    mut frame: NativeCallFrameHandle,
    arguments: NativeCallArgumentsHandle,
    index: usize,
) -> bool {
    let (Some(frame), Some(slot)) = (
        unsafe { frame.as_mut() },
        unsafe { arguments.as_ref() }.and_then(|arguments| arguments.slots.get(index).copied()),
    ) else {
        return false;
    };
    frame.slots.push(unsafe { slot.clone_slot() });
    true
}

/// # Safety
///
/// `frame` must be null or a call-frame handle. The returned value is owned.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_read_value(
    frame: NativeCallFrameHandle,
    index: usize,
) -> NativeValueHandle {
    match unsafe { frame.as_ref() }.and_then(|frame| frame.slots.get(index)) {
        Some(NativeCallArgumentSlot::Value(value)) => unsafe { phpc_native_value_clone(*value) },
        Some(NativeCallArgumentSlot::Reference(reference)) => unsafe {
            phpc_native_reference_value_clone(*reference)
        },
        None => NativeValueHandle::null(),
    }
}

/// # Safety
///
/// `frame` must be null or a call-frame handle. The returned reference is owned.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_read_reference(
    frame: NativeCallFrameHandle,
    index: usize,
) -> NativeReferenceHandle {
    match unsafe { frame.as_ref() }.and_then(|frame| frame.slots.get(index)) {
        Some(NativeCallArgumentSlot::Reference(reference)) => unsafe {
            phpc_native_reference_clone(*reference)
        },
        Some(NativeCallArgumentSlot::Value(_)) | None => NativeReferenceHandle::null(),
    }
}

/// # Safety
///
/// `frame` must be null or a call-frame handle. The returned string is owned.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_called_scope(
    frame: NativeCallFrameHandle,
) -> NativeStringHandle {
    unsafe { frame.as_ref() }
        .and_then(|frame| frame.called_scope.as_ref())
        .map(|scope| NativeStringHandle::from_vec(scope.as_bytes().to_vec()))
        .unwrap_or_else(NativeStringHandle::null)
}

/// # Safety
///
/// `frame` must be null or a call-frame handle. The returned value is an owned
/// clone of the receiver bound by callable-value dispatch, or null when the
/// frame was not created for a bound object callable.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_read_receiver(
    frame: NativeCallFrameHandle,
) -> NativeValueHandle {
    unsafe { frame.as_ref() }
        .and_then(|frame| frame.receiver)
        .map(|receiver| unsafe { phpc_native_value_clone(receiver) })
        .unwrap_or_else(NativeValueHandle::null)
}

/// # Safety
///
/// `handle` must be null or a call-frame handle previously returned by the
/// runtime ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_free(handle: NativeCallFrameHandle) {
    if handle.ptr.is_null() {
        return;
    }
    let frame = unsafe { Box::from_raw(handle.ptr) };
    for slot in frame.slots {
        unsafe { slot.free() };
    }
    if let Some(receiver) = frame.receiver {
        unsafe { phpc_native_value_free(receiver) };
    }
}

