/// # Safety
///
/// `handle` must be null or a call-result handle previously returned by the
/// runtime ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_result_free(handle: NativeCallResultHandle) {
    if handle.ptr.is_null() {
        return;
    }
    let mut result = unsafe { Box::from_raw(handle.ptr) };
    unsafe { result.slot.discard() };
}

unsafe fn native_call_result_diagnostic_consumer<'a>(
    result: &'a mut NativeCallResultHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> Option<&'a mut NativeCallResult> {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    unsafe { result.as_mut() }
}

unsafe fn native_call_result_take_value_with_diagnostic_and_free(
    mut result: NativeCallResultHandle,
    diagnostic: *mut NativeDiagnosticHandle,
    missing_value_message: &'static str,
) -> NativeValueHandle {
    let Some(result_ref) =
        (unsafe { native_call_result_diagnostic_consumer(&mut result, diagnostic) })
    else {
        unsafe { phpc_native_call_result_free(result) };
        return NativeValueHandle::null();
    };

    if result_ref.slot.status() == NativeCallResultStatus::Failure {
        if !diagnostic.is_null() {
            unsafe { *diagnostic = phpc_native_call_result_read_diagnostic(result) };
        }
        unsafe { phpc_native_call_result_free(result) };
        return NativeValueHandle::null();
    }

    let value = unsafe { phpc_native_call_result_take_value_and_free(result) };
    if value.is_null() {
        unsafe { native_store_diagnostic_message(diagnostic, missing_value_message) };
    }
    value
}

unsafe fn native_call_result_take_reference_with_diagnostic_and_free(
    mut result: NativeCallResultHandle,
    diagnostic: *mut NativeDiagnosticHandle,
    missing_reference_message: &'static str,
) -> NativeReferenceHandle {
    let Some(result_ref) =
        (unsafe { native_call_result_diagnostic_consumer(&mut result, diagnostic) })
    else {
        unsafe { phpc_native_call_result_free(result) };
        return NativeReferenceHandle::null();
    };

    if result_ref.slot.status() == NativeCallResultStatus::Failure {
        if !diagnostic.is_null() {
            unsafe { *diagnostic = phpc_native_call_result_read_diagnostic(result) };
        }
        unsafe { phpc_native_call_result_free(result) };
        return NativeReferenceHandle::null();
    }

    let reference = unsafe { phpc_native_call_result_take_reference_and_free(result) };
    if reference.is_null() {
        unsafe { native_store_diagnostic_message(diagnostic, missing_reference_message) };
    }
    reference
}

unsafe fn native_call_result_discard_with_diagnostic_and_free(
    mut result: NativeCallResultHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    let Some(result_ref) =
        (unsafe { native_call_result_diagnostic_consumer(&mut result, diagnostic) })
    else {
        unsafe { phpc_native_call_result_free(result) };
        return false;
    };

    if result_ref.slot.status() == NativeCallResultStatus::Failure {
        if !diagnostic.is_null() {
            unsafe { *diagnostic = phpc_native_call_result_read_diagnostic(result) };
        }
        unsafe { phpc_native_call_result_free(result) };
        return false;
    }

    unsafe { phpc_native_call_result_discard_and_free(result) };
    true
}

/// # Safety
///
/// Same as the native call-result value consumer. `diagnostic` must be null or
/// point to writable diagnostic storage.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_result_take_value_with_diagnostic_and_free(
    result: NativeCallResultHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe {
        native_call_result_take_value_with_diagnostic_and_free(
            result,
            diagnostic,
            "native call result consumption failed: result did not contain a value",
        )
    }
}

/// # Safety
///
/// Same as the native call-result reference consumer. `diagnostic` must be null
/// or point to writable diagnostic storage.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_result_take_reference_with_diagnostic_and_free(
    result: NativeCallResultHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeReferenceHandle {
    unsafe {
        native_call_result_take_reference_with_diagnostic_and_free(
            result,
            diagnostic,
            "native call result consumption failed: result did not contain a reference",
        )
    }
}

unsafe fn native_call_result_conditional_handoff_cleanup_detail(
    result: NativeCallResultHandle,
) -> Option<String> {
    match unsafe { result.as_ref() }.map(|result| result.slot) {
        Some(NativeCallResultSlot::Value(value)) => unsafe {
            value
                .as_ref()
                .and_then(native_call_result_value_cleanup_ordering_detail)
        },
        Some(NativeCallResultSlot::Reference(reference)) => {
            let value_detail = unsafe {
                reference.as_ref().and_then(|reference| {
                    native_call_result_value_cleanup_ordering_detail(&reference.cell.value_cloned())
                })
            };
            Some(
                value_detail
                    .map(|detail| format!("reference result containing {detail}"))
                    .unwrap_or_else(|| "reference result".to_string()),
            )
        }
        Some(NativeCallResultSlot::Failure(_)) | None => None,
    }
}

unsafe fn native_call_result_conditional_handoff_contract_result(
    result: NativeCallResultHandle,
    feature: NativeCallFrameConditionalHandoffFeature,
) -> NativeCallResultHandle {
    if result.is_null() {
        return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
            NativeDiagnosticHandle::from_message(
                "native call frame conditional handoff failed: call result handle is null",
            ),
        ));
    }

    if unsafe { phpc_native_call_result_status(result) } == NativeCallResultStatus::Failure {
        return result;
    }

    let Some(cleanup_detail) =
        (unsafe { native_call_result_conditional_handoff_cleanup_detail(result) })
    else {
        return result;
    };

    unsafe { phpc_native_call_result_free(result) };
    NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
        NativeDiagnosticHandle::from_message(format!(
            "unsupported call {}: {} contains {cleanup_detail} requires object destructors, resource finalizers, reference/COW preservation, conditional result handoff, and {}",
            feature.call_result_label(),
            feature.operand_label(),
            feature.branch_cleanup_label(),
        )),
    ))
}

/// # Safety
///
/// `result` must be null or an owned call-result handle previously returned by
/// the runtime ABI and not yet freed. `conditional_feature` must be a
/// `NativeCallFrameConditionalHandoffFeature` tag. The returned call-result
/// handle owns the original ordinary result, the propagated diagnostic, or the
/// centralized blocker diagnostic for cleanup-sensitive values.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_result_conditional_handoff_contract_result(
    result: NativeCallResultHandle,
    conditional_feature: u8,
) -> NativeCallResultHandle {
    let Some(feature) = NativeCallFrameConditionalHandoffFeature::from_tag(conditional_feature)
    else {
        unsafe { phpc_native_call_result_free(result) };
        return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
            NativeDiagnosticHandle::from_message(
                "native call frame conditional handoff failed: unknown conditional handoff feature tag",
            ),
        ));
    };

    unsafe { native_call_result_conditional_handoff_contract_result(result, feature) }
}

/// # Safety
///
/// Same as `phpc_native_call_frame_result_conditional_handoff_contract_result`
/// with the short-ternary condition feature tag.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_result_short_ternary_condition_contract_result(
    result: NativeCallResultHandle,
) -> NativeCallResultHandle {
    unsafe {
        native_call_result_conditional_handoff_contract_result(
            result,
            NativeCallFrameConditionalHandoffFeature::ShortTernaryCondition,
        )
    }
}

/// # Safety
///
/// Same as `phpc_native_call_frame_result_conditional_handoff_contract_result`
/// with the null-coalescing left-operand feature tag.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_result_null_coalesce_condition_contract_result(
    result: NativeCallResultHandle,
) -> NativeCallResultHandle {
    unsafe {
        native_call_result_conditional_handoff_contract_result(
            result,
            NativeCallFrameConditionalHandoffFeature::NullCoalesceLeftOperand,
        )
    }
}

unsafe fn native_call_result_value_family(result: NativeCallResultHandle) -> &'static str {
    match unsafe { result.as_ref() }.map(|result| result.slot) {
        Some(NativeCallResultSlot::Value(value)) => unsafe { value.as_ref() }
            .map(|value| match value {
                Value::Null => "null",
                Value::Bool(_) => "bool",
                Value::Int(_) => "int",
                Value::Float(_) => "float",
                Value::String(_) => "string",
                Value::BinaryString(_) => "string",
                Value::Array(_) => "array",
                Value::Object(_) => "object",
                Value::Resource(_) => "resource",
                Value::Closure(_) => "closure",
            })
            .unwrap_or("null"),
        Some(NativeCallResultSlot::Reference(reference)) => unsafe { reference.as_ref() }
            .map(|reference| match reference.cell.value_cloned() {
                Value::Null => "null",
                Value::Bool(_) => "bool",
                Value::Int(_) => "int",
                Value::Float(_) => "float",
                Value::String(_) => "string",
                Value::BinaryString(_) => "string",
                Value::Array(_) => "array",
                Value::Object(_) => "object",
                Value::Resource(_) => "resource",
                Value::Closure(_) => "closure",
            })
            .unwrap_or("null"),
        Some(NativeCallResultSlot::Failure(_)) => "diagnostic",
        None => "null",
    }
}

fn native_call_result_value_cleanup_ordering_detail(value: &Value) -> Option<String> {
    match value {
        Value::Array(array) => native_call_result_array_cleanup_ordering_detail(array),
        Value::Object(_) => Some("object value".to_string()),
        Value::Closure(closure) => native_call_result_closure_cleanup_ordering_detail(closure),
        Value::Resource(_) => Some("resource value".to_string()),
        Value::Null
        | Value::Bool(_)
        | Value::Int(_)
        | Value::Float(_)
        | Value::String(_)
        | Value::BinaryString(_) => None,
    }
}

fn native_call_result_array_cleanup_ordering_detail(array: &PhpArray) -> Option<String> {
    for (index, entry) in array.entries().iter().enumerate() {
        let slot = entry.slot();
        if slot.is_reference() {
            return Some("array reference slot".to_string());
        }
        if native_call_result_array_slot_shares_value_cell(slot) {
            return Some("array shared COW slot".to_string());
        }
        if let Some(detail) = native_call_result_value_cleanup_ordering_detail(&slot.value_cloned())
        {
            return Some(format!("array slot {index} contains {detail}"));
        }
    }

    None
}

fn native_call_result_array_slot_shares_value_cell(slot: &ArraySlot) -> bool {
    match &slot.storage {
        ArraySlotStorage::Value(cell) => Rc::strong_count(cell) > 1,
        ArraySlotStorage::Reference(_) => false,
    }
}

fn native_call_result_closure_cleanup_ordering_detail(closure: &PhpClosure) -> Option<String> {
    for capture in closure.captures() {
        let captured = capture.value();
        if let Some(detail) = native_call_result_value_cleanup_ordering_detail(&captured) {
            return Some(match (capture.by_reference(), detail.as_str()) {
                (true, "array reference slot") => {
                    "closure by-reference capture with array reference slot".to_string()
                }
                (true, "array shared COW slot") => {
                    "closure by-reference capture with array shared COW slot".to_string()
                }
                (true, "object value") => {
                    "closure by-reference capture with object value".to_string()
                }
                (true, "closure value") => {
                    "closure by-reference capture with closure value".to_string()
                }
                (true, "resource value") => {
                    "closure by-reference capture with resource value".to_string()
                }
                (true, _) => format!("closure by-reference capture containing {detail}"),
                (false, "array reference slot") => {
                    "closure capture with array reference slot".to_string()
                }
                (false, "array shared COW slot") => {
                    "closure capture with array shared COW slot".to_string()
                }
                (false, "object value") => "closure capture with object value".to_string(),
                (false, "closure value") => "closure capture with closure value".to_string(),
                (false, "resource value") => "closure capture with resource value".to_string(),
                (false, _) => format!("closure capture containing {detail}"),
            });
        }
        if capture.by_reference() {
            return Some("closure by-reference capture slot".to_string());
        }
    }

    Some("closure value".to_string())
}

unsafe fn native_call_result_vector_failure(
    results: *mut NativeCallResultHandle,
    result_count: usize,
) -> Option<NativeDiagnosticHandle> {
    if result_count == 0 {
        return None;
    }
    let results = unsafe { std::slice::from_raw_parts_mut(results, result_count) };
    for result in results.iter_mut() {
        if unsafe { phpc_native_call_result_status(*result) } == NativeCallResultStatus::Failure {
            let diagnostic = unsafe { phpc_native_call_result_take_diagnostic(*result) };
            for owned in results.iter_mut() {
                unsafe { phpc_native_call_result_free(*owned) };
                *owned = NativeCallResultHandle::null();
            }
            return Some(diagnostic);
        }
    }
    None
}

unsafe fn native_call_result_vector_free(
    results: *mut NativeCallResultHandle,
    result_count: usize,
) {
    if result_count == 0 || results.is_null() {
        return;
    }
    for result in unsafe { std::slice::from_raw_parts_mut(results, result_count) } {
        unsafe { phpc_native_call_result_free(*result) };
        *result = NativeCallResultHandle::null();
    }
}

/// # Safety
///
/// `callable` and `missing_semantics` must be borrowed string handles. When
/// `argument_count` is nonzero, `argument_results` must point to
/// `argument_count` owned call-result handles, which this helper consumes and
/// nulls. When `count` is nonzero, `parameter_names`, `parameter_indices`, and
/// `argument_targets` must point to `count` borrowed entries. The helper does
/// not execute alias transfer; it centralizes the produced-result diagnostic
/// boundary while preserving caller-visible target labels and value families.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_call_frame_reference_parameter_alias_transfer_result_from_results_with_diagnostic(
    callable: NativeStringHandle,
    argument_results: *mut NativeCallResultHandle,
    argument_count: usize,
    parameter_names: *const NativeStringHandle,
    parameter_indices: *const usize,
    argument_targets: *const NativeStringHandle,
    count: usize,
    missing_semantics: NativeStringHandle,
) -> NativeCallResultHandle {
    if argument_count > 0 && argument_results.is_null() {
        return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
            NativeDiagnosticHandle::from_message(
                "native call frame by-reference alias-transfer contract failed: argument result vector pointer is null",
            ),
        ));
    }
    if count > 0 {
        if parameter_names.is_null() {
            unsafe { native_call_result_vector_free(argument_results, argument_count) };
            return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
                NativeDiagnosticHandle::from_message(
                    "native call frame by-reference alias-transfer contract failed: parameter-name vector pointer is null",
                ),
            ));
        }
        if parameter_indices.is_null() {
            unsafe { native_call_result_vector_free(argument_results, argument_count) };
            return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
                NativeDiagnosticHandle::from_message(
                    "native call frame by-reference alias-transfer contract failed: parameter-index vector pointer is null",
                ),
            ));
        }
        if argument_targets.is_null() {
            unsafe { native_call_result_vector_free(argument_results, argument_count) };
            return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
                NativeDiagnosticHandle::from_message(
                    "native call frame by-reference alias-transfer contract failed: caller target vector pointer is null",
                ),
            ));
        }
    }

    if let Some(diagnostic) =
        unsafe { native_call_result_vector_failure(argument_results, argument_count) }
    {
        return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(diagnostic));
    }

    let callable = unsafe { native_string_handle_to_string(callable) }
        .unwrap_or_else(|| "<unknown callable>".to_string());
    let missing_semantics = unsafe { native_string_handle_to_string(missing_semantics) }
        .unwrap_or_else(|| "by-reference parameter alias transfer".to_string());
    let parameter_names = if count == 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(parameter_names, count) }
    };
    let parameter_indices = if count == 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(parameter_indices, count) }
    };
    let argument_targets = if count == 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(argument_targets, count) }
    };
    let argument_results_slice = if argument_count == 0 {
        &[][..]
    } else {
        unsafe { std::slice::from_raw_parts(argument_results, argument_count) }
    };

    let mut entries = Vec::with_capacity(count);
    for entry_index in 0..count {
        let parameter_index = parameter_indices[entry_index];
        if parameter_index >= argument_count {
            unsafe { native_call_result_vector_free(argument_results, argument_count) };
            return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
                NativeDiagnosticHandle::from_message(
                    "native call frame by-reference alias-transfer contract failed: parameter index exceeds argument result vector count",
                ),
            ));
        }
        let parameter_name =
            unsafe { native_string_handle_to_string(parameter_names[entry_index]) }
                .unwrap_or_else(|| format!("param{entry_index}"));
        let argument_target =
            unsafe { native_string_handle_to_string(argument_targets[entry_index]) }
                .unwrap_or_else(|| "caller argument".to_string());
        let family =
            unsafe { native_call_result_value_family(argument_results_slice[parameter_index]) };
        entries.push(format!(
            "${parameter_name} at parameter slot {entry_index} from caller argument slot {parameter_index} from {argument_target} carrying caller argument value family {family}"
        ));
    }
    unsafe { native_call_result_vector_free(argument_results, argument_count) };

    let detail = if entries.is_empty() {
        "no by-reference parameters were supplied".to_string()
    } else {
        entries.join("; ")
    };
    NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
        NativeDiagnosticHandle::from_message(format!(
            "unsupported call {callable}: {missing_semantics}; {detail}; caller-visible target slot binding, reference/COW preservation, alias writeback ordering, and owned argument result cleanup via by-reference-parameter alias-transfer boundary"
        )),
    ))
}

unsafe fn native_diagnostic_slot_is_set(diagnostic: *mut NativeDiagnosticHandle) -> bool {
    !diagnostic.is_null() && !unsafe { (*diagnostic).is_null() }
}

/// # Safety
///
/// `callable` and `arguments` must be runtime handles. The returned frame owns
/// clones of each argument slot.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_frame_from_arguments_with_diagnostic(
    callable: NativeCallableHandle,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallFrameHandle {
    let (Some(callable), Some(arguments)) =
        (unsafe { callable.as_ref() }, unsafe { arguments.as_ref() })
    else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    "native call frame creation failed: callable or arguments handle is null",
                )
            };
        }
        return NativeCallFrameHandle::null();
    };
    let mut slots = Vec::with_capacity(arguments.slots.len());
    for slot in &arguments.slots {
        slots.push(unsafe { slot.clone_slot() });
    }
    NativeCallFrameHandle::from_frame(NativeCallFrame {
        slots,
        called_scope: callable.called_scope.clone(),
        receiver: None,
    })
}

/// # Safety
///
/// Same as `phpc_native_callable_frame_from_arguments_with_diagnostic`, and
/// consumes `arguments`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_frame_from_arguments_with_diagnostic_and_free(
    callable: NativeCallableHandle,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallFrameHandle {
    let frame = unsafe {
        phpc_native_callable_frame_from_arguments_with_diagnostic(callable, arguments, diagnostic)
    };
    unsafe { phpc_native_call_arguments_free(arguments) };
    frame
}

/// # Safety
///
/// `callable` and `arguments` must be runtime handles. The returned result owns
/// the callback result handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_invoke_result_with_diagnostic(
    callable: NativeCallableHandle,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallResultHandle {
    let Some(callable_ref) = (unsafe { callable.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    "native callable invocation failed: callable handle is null",
                )
            };
        }
        return NativeCallResultHandle::null();
    };
    let frame = unsafe {
        phpc_native_callable_frame_from_arguments_with_diagnostic(callable, arguments, diagnostic)
    };
    if frame.is_null() {
        return NativeCallResultHandle::null();
    }
    let result = unsafe { (callable_ref.descriptor.callback)(frame) };
    unsafe { phpc_native_call_frame_free(frame) };
    if result.is_null() {
        NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
            NativeDiagnosticHandle::from_message(
                "native callable invocation failed: frame callback returned a null result",
            ),
        ))
    } else {
        result
    }
}

/// # Safety
///
/// Same as `phpc_native_callable_invoke_result_with_diagnostic`, and consumes
/// `arguments`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_invoke_result_with_diagnostic_and_free(
    callable: NativeCallableHandle,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallResultHandle {
    let result = unsafe {
        phpc_native_callable_invoke_result_with_diagnostic(callable, arguments, diagnostic)
    };
    unsafe { phpc_native_call_arguments_free(arguments) };
    result
}

/// # Safety
///
/// Invokes a callable and returns an owned value result, or null with a
/// diagnostic for failures and non-value results.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_callable_invoke_value_with_diagnostic_and_free(
    callable: NativeCallableHandle,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = unsafe {
        phpc_native_callable_invoke_result_with_diagnostic_and_free(callable, arguments, diagnostic)
    };
    if unsafe { native_diagnostic_slot_is_set(diagnostic) } {
        unsafe { phpc_native_call_result_free(result) };
        return NativeValueHandle::null();
    }
    unsafe {
        native_call_result_take_value_with_diagnostic_and_free(
            result,
            diagnostic,
            "native callable invocation failed: result did not contain a value",
        )
    }
}

