unsafe fn native_closure_arguments_from_call_arguments(
    descriptor: NativeClosureDescriptor,
    arguments: NativeCallArgumentsHandle,
) -> Result<Vec<NativeClosureArgument>, String> {
    let Some(arguments) = (unsafe { arguments.as_ref() }) else {
        return Err(
            "native callable-value invocation failed: arguments handle is null".to_string(),
        );
    };

    let mut closure_args = Vec::with_capacity(arguments.slots.len());
    for (index, slot) in arguments.slots.iter().enumerate() {
        let is_finalized_variadic_slot = arguments.finalized_variadic
            && descriptor.is_variadic()
            && arguments.slots.len() == descriptor.param_count
            && index + 1 == descriptor.param_count;
        let argument = match *slot {
            NativeCallArgumentSlot::Value(value) => {
                if descriptor.param_is_by_reference(index) {
                    unsafe { native_closure_arguments_free(closure_args) };
                    return Err(
                        RuntimeError::unsupported_call(
                            "Closure::__invoke()",
                            format!(
                                "by-reference parameter ${index} requires a supported lvalue argument for descriptor-backed closure invocation"
                            ),
                        )
                        .message()
                        .to_string(),
                    );
                }
                let value = unsafe { phpc_native_value_clone(value) };
                if value.is_null() {
                    unsafe { native_closure_arguments_free(closure_args) };
                    return Err(
                        "native callable-value invocation failed: value argument clone is null"
                            .to_string(),
                    );
                }
                if is_finalized_variadic_slot {
                    NativeClosureArgument::from_variadic_value(value)
                } else {
                    NativeClosureArgument::from_value(value)
                }
            }
            NativeCallArgumentSlot::Reference(reference) => {
                let value = unsafe { phpc_native_reference_value_clone(reference) };
                if value.is_null() {
                    unsafe { phpc_native_value_free(value) };
                    unsafe { native_closure_arguments_free(closure_args) };
                    return Err(
                        "native callable-value invocation failed: reference value clone is null"
                            .to_string(),
                    );
                }
                if descriptor.param_is_by_reference(index) {
                    let reference = unsafe { phpc_native_reference_clone(reference) };
                    if reference.is_null() {
                        unsafe { phpc_native_value_free(value) };
                        unsafe { native_closure_arguments_free(closure_args) };
                        return Err(
                            "native callable-value invocation failed: reference argument clone is null"
                                .to_string(),
                        );
                    }
                    NativeClosureArgument::from_reference(value, reference)
                } else {
                    NativeClosureArgument::from_value(value)
                }
            }
        };
        closure_args.push(argument);
    }
    Ok(closure_args)
}

unsafe fn native_closure_arguments_free(arguments: Vec<NativeClosureArgument>) {
    for argument in arguments {
        unsafe { phpc_native_value_free(argument.value) };
        unsafe { phpc_native_reference_free(argument.reference) };
    }
}

unsafe fn native_callable_builtin_argument_values(
    builtin: NativeCallableBuiltin,
    arguments: NativeCallArgumentsHandle,
) -> Result<Vec<NativeValueHandle>, String> {
    let Some(arguments_ref) = (unsafe { arguments.as_ref() }) else {
        return Err(format!(
            "native callable builtin invocation failed: {} arguments handle is null",
            builtin.name()
        ));
    };
    let signature = builtin.signature();
    let actual = arguments_ref.slots.len();
    if !signature.accepts_arg_count(actual) {
        let expected = signature.required_arg_count;
        return Err(format!(
            "native callable builtin invocation failed: {} expected {expected} argument(s), got {actual}",
            builtin.name()
        ));
    }

    let mut values = Vec::with_capacity(actual);
    for index in 0..actual {
        let value = unsafe { phpc_native_call_arguments_read_value(arguments, index) };
        if value.is_null() {
            for value in values {
                unsafe { phpc_native_value_free(value) };
            }
            return Err(format!(
                "native callable builtin invocation failed: {} argument {index} could not be read as a value",
                builtin.name()
            ));
        }
        values.push(value);
    }
    Ok(values)
}

const PHP_DEFAULT_TRIM_MASK: &[u8] = b" \n\r\t\x0b\x0c\0";

fn native_callable_trimmed_bytes(subject: &[u8], mask: &[u8], mode: NativeTrimMode) -> Vec<u8> {
    let mut start = 0;
    let mut end = subject.len();

    if matches!(mode, NativeTrimMode::Both | NativeTrimMode::Left) {
        while start < end && mask.contains(&subject[start]) {
            start += 1;
        }
    }
    if matches!(mode, NativeTrimMode::Both | NativeTrimMode::Right) {
        while end > start && mask.contains(&subject[end - 1]) {
            end -= 1;
        }
    }

    subject[start..end].to_vec()
}

fn native_callable_trim_mask_parse_error(name: &str, reason: &str) -> RuntimeError {
    RuntimeError::unsupported_call(
        name,
        format!("character mask ranges are not fully implemented: {reason}"),
    )
}

fn native_callable_trim_expanded_mask(mask: &[u8], name: &str) -> RuntimeResult<Vec<u8>> {
    let mut expanded = Vec::with_capacity(mask.len());
    let mut index = 0;

    while index < mask.len() {
        if mask[index] == b'.' && mask.get(index + 1) == Some(&b'.') {
            return Err(native_callable_trim_mask_parse_error(
                name,
                "no character to the left of '..'",
            ));
        }

        if mask.get(index + 1) == Some(&b'.') && mask.get(index + 2) == Some(&b'.') {
            let Some(&end) = mask.get(index + 3) else {
                return Err(native_callable_trim_mask_parse_error(
                    name,
                    "no character to the right of '..'",
                ));
            };
            if end == b'.' {
                return Err(native_callable_trim_mask_parse_error(
                    name,
                    "ambiguous dot-runs are blocked until full PHP charlist parsing is implemented",
                ));
            }

            let start = mask[index];
            if start > end {
                return Err(native_callable_trim_mask_parse_error(
                    name,
                    "'..'-ranges must be incrementing",
                ));
            }
            expanded.extend(start..=end);
            index += 4;
        } else {
            expanded.push(mask[index]);
            index += 1;
        }
    }

    Ok(expanded)
}

fn native_callable_trim_mask(
    mode: NativeTrimMode,
    values: &[NativeValueHandle],
) -> RuntimeResult<Vec<u8>> {
    if values.len() == 1 {
        return Ok(PHP_DEFAULT_TRIM_MASK.to_vec());
    }

    let name = match mode {
        NativeTrimMode::Both => "trim()",
        NativeTrimMode::Left => "ltrim()",
        NativeTrimMode::Right => "rtrim()",
    };
    native_callable_trim_expanded_mask(&unsafe { native_value_to_string_bytes(values[1]) }?, name)
}

unsafe fn native_callable_trim_value(
    mode: NativeTrimMode,
    values: &[NativeValueHandle],
) -> RuntimeResult<Value> {
    let subject = unsafe { native_value_to_string_bytes(values[0]) }?;
    let mask = native_callable_trim_mask(mode, values)?;
    value_from_native_string_result_bytes(native_callable_trimmed_bytes(&subject, &mask, mode))
}

unsafe fn native_array_lvalue_result_into_value(
    result: NativeArrayLvalueResult,
    missing_value_message: impl Into<String>,
) -> Result<Value, String> {
    match result.tag {
        NATIVE_ARRAY_LVALUE_OK => {
            let value = unsafe { result.value.into_value() };
            unsafe { phpc_native_diagnostic_free(result.diagnostic) };
            value.ok_or_else(|| missing_value_message.into())
        }
        _ => {
            let message = unsafe { result.diagnostic.as_ref() }
                .map(|diagnostic| diagnostic.message.clone())
                .unwrap_or_else(|| "native array lvalue operation failed".to_string());
            unsafe { phpc_native_value_free(result.value) };
            unsafe { phpc_native_diagnostic_free(result.diagnostic) };
            Err(message)
        }
    }
}

unsafe fn native_callable_builtin_slot_value_cloned(
    builtin_name: &str,
    index: usize,
    slot: NativeCallArgumentSlot,
) -> Result<Value, String> {
    match slot {
        NativeCallArgumentSlot::Value(value) => {
            unsafe { value.as_ref() }.cloned().ok_or_else(|| {
                format!(
                    "native callable builtin invocation failed: {builtin_name} argument {index} value slot is null"
                )
            })
        }
        NativeCallArgumentSlot::Reference(reference) => unsafe { reference.as_ref() }
            .map(|reference| reference.cell.value_cloned())
            .ok_or_else(|| {
                format!(
                    "native callable builtin invocation failed: {builtin_name} argument {index} reference slot is null"
                )
            }),
    }
}

unsafe fn native_callable_array_mutation_operands(
    operation: NativeArrayMutationOperation,
    signature: NativeCallableBuiltinSignature,
    arguments: &NativeCallArguments,
) -> Result<Vec<Value>, String> {
    let fixed_count = signature.fixed_param_count();
    if arguments.finalized_variadic && signature.accepts_variadic_args {
        if arguments.slots.len() != fixed_count + 1 {
            return Err(format!(
                "native callable builtin invocation failed: {} finalized variadic arguments expected {} fixed slot(s) plus one variadic collection, got {} slot(s)",
                operation.label(),
                fixed_count,
                arguments.slots.len()
            ));
        }
        let value = unsafe {
            native_callable_builtin_slot_value_cloned(
                operation.label(),
                fixed_count,
                arguments.slots[fixed_count],
            )?
        };
        let Value::Array(array) = value else {
            return Err(format!(
                "native callable builtin invocation failed: {} finalized variadic slot must be array, got {}",
                operation.label(),
                value.type_name()
            ));
        };
        return Ok(array
            .entries()
            .iter()
            .map(|entry| entry.value_cloned())
            .collect());
    }

    arguments
        .slots
        .iter()
        .copied()
        .enumerate()
        .skip(fixed_count)
        .map(|(index, slot)| unsafe {
            native_callable_builtin_slot_value_cloned(operation.label(), index, slot)
        })
        .collect()
}

unsafe fn native_callable_array_mutation_value(
    operation: NativeArrayMutationOperation,
    arguments: NativeCallArgumentsHandle,
) -> Result<Value, String> {
    let Some(arguments_ref) = (unsafe { arguments.as_ref() }) else {
        return Err(format!(
            "native callable builtin invocation failed: {} arguments handle is null",
            operation.label()
        ));
    };
    let builtin = NativeCallableBuiltin::ArrayMutation(operation);
    let signature = builtin.signature();
    let actual = arguments_ref.slots.len();
    if !signature.accepts_arg_count(actual) {
        let expected = signature.required_arg_count;
        return Err(format!(
            "native callable builtin invocation failed: {} expected {expected} argument(s), got {actual}",
            operation.label()
        ));
    }

    let Some(slot) = arguments_ref.slots.first() else {
        return Err(format!(
            "native callable builtin invocation failed: {} missing array argument slot",
            operation.label()
        ));
    };
    let reference = match slot {
        NativeCallArgumentSlot::Reference(reference) => reference,
        NativeCallArgumentSlot::Value(_) => {
            return Err(format!(
                "unsupported call {}(): by-reference parameter $array requires reference materialization before runtime callable builtin invocation",
                operation.label()
            ))
        }
    };
    let Some(reference) = (unsafe { reference.as_ref() }) else {
        return Err(format!(
            "native callable builtin invocation failed: {} array reference slot is null",
            operation.label()
        ));
    };

    let operands =
        unsafe { native_callable_array_mutation_operands(operation, signature, arguments_ref) }?;
    if !operation.operand_count_is_supported(operands.len()) {
        return Err(format!(
            "native callable builtin invocation failed: {} expected {} variadic operand(s), got {}",
            operation.label(),
            match operation {
                NativeArrayMutationOperation::Push | NativeArrayMutationOperation::Unshift =>
                    "at least 1",
                NativeArrayMutationOperation::Pop | NativeArrayMutationOperation::Shift => "0",
            },
            operands.len()
        ));
    }

    let mut value = reference.cell.value_cloned();
    let result = native_array_mutation_value_path_result(&mut value, &[], operation, &operands);
    let return_value = unsafe {
        native_array_lvalue_result_into_value(
            result,
            format!(
                "native callable builtin invocation failed: {} mutation returned no value",
                operation.label()
            ),
        )?
    };
    let value = reference
        .cell
        .coerce_value_for_write(value)
        .map_err(|error| error.message().to_string())?;
    reference.cell.set_value(value);
    Ok(return_value)
}

unsafe fn native_callable_array_sort_value(
    operation: NativeArraySortOperation,
    arguments: NativeCallArgumentsHandle,
) -> Result<Value, String> {
    if !operation.supports_runtime_callable_writeback() {
        return Err(format!(
            "native callable builtin invocation failed: {} is not supported through the runtime sorting callable family",
            operation.label()
        ));
    }

    let Some(arguments_ref) = (unsafe { arguments.as_ref() }) else {
        return Err(format!(
            "native callable builtin invocation failed: {} arguments handle is null",
            operation.label()
        ));
    };
    let builtin = NativeCallableBuiltin::ArraySort(operation);
    let signature = builtin.signature();
    let actual = arguments_ref.slots.len();
    if !signature.accepts_arg_count(actual) {
        let expected = signature.required_arg_count;
        return Err(format!(
            "native callable builtin invocation failed: {} expected {expected} argument(s), got {actual}",
            operation.label()
        ));
    }

    let Some(slot) = arguments_ref.slots.first() else {
        return Err(format!(
            "native callable builtin invocation failed: {} missing array argument slot",
            operation.label()
        ));
    };
    let reference = match slot {
        NativeCallArgumentSlot::Reference(reference) => reference,
        NativeCallArgumentSlot::Value(_) => {
            return Err(format!(
                "unsupported call {}(): by-reference parameter $array requires reference materialization before runtime callable builtin invocation",
                operation.label()
            ))
        }
    };
    let Some(reference) = (unsafe { reference.as_ref() }) else {
        return Err(format!(
            "native callable builtin invocation failed: {} array reference slot is null",
            operation.label()
        ));
    };

    let mut operands = Vec::with_capacity(actual.saturating_sub(1));
    for index in 1..actual {
        let value = unsafe { phpc_native_call_arguments_read_value(arguments, index) };
        if value.is_null() {
            for value in operands {
                unsafe { phpc_native_value_free(value) };
            }
            return Err(format!(
                "native callable builtin invocation failed: {} argument {index} could not be read as a value",
                operation.label()
            ));
        }
        operands.push(value);
    }

    let result = (|| {
        if !operation.operand_count_is_supported(operands.len()) {
            return Err(format!(
                "native callable builtin invocation failed: {} expected {} sort operand(s), got {}",
                operation.label(),
                match operation {
                    NativeArraySortOperation::Sort
                    | NativeArraySortOperation::Rsort
                    | NativeArraySortOperation::Asort
                    | NativeArraySortOperation::Arsort
                    | NativeArraySortOperation::Ksort
                    | NativeArraySortOperation::Krsort => "0 or 1",
                    NativeArraySortOperation::Natsort | NativeArraySortOperation::Natcasesort =>
                        "0",
                    NativeArraySortOperation::Usort
                    | NativeArraySortOperation::Uasort
                    | NativeArraySortOperation::Uksort => "1",
                },
                operands.len()
            ));
        }

        if operation.uses_comparator_sort() {
            let Some(callback) = operands.first().copied() else {
                return Err(format!(
                    "native callable builtin invocation failed: {} missing comparator callback argument",
                    operation.label()
                ));
            };
            let mut diagnostic = NativeDiagnosticHandle::null();
            let callable = unsafe {
                phpc_native_callable_lookup_value_or_closure_with_context_diagnostic(
                    NativeCallableTableHandle::null(),
                    callback,
                    NativeStringHandle::null(),
                    &mut diagnostic,
                )
            };
            if !diagnostic.is_null() {
                let message = unsafe { diagnostic.as_ref() }
                    .map(|diagnostic| diagnostic.message.clone())
                    .unwrap_or_else(|| "comparator callback lookup failed".to_string());
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                return Err(format!(
                    "native callable builtin invocation failed: {} comparator callback lookup failed: {message}",
                    operation.label()
                ));
            }
            let Some(dispatch) = (unsafe { callable.as_ref() }).cloned() else {
                return Err(format!(
                    "native callable builtin invocation failed: {} comparator callback dispatch handle is null",
                    operation.label()
                ));
            };
            unsafe { phpc_native_callable_value_free(callable) };

            let mut value = reference.cell.value_cloned();
            let result = native_array_sort_value_path_result(
                &mut value,
                &[],
                operation,
                NativeArraySortCriteria::Comparator {
                    dispatch: &dispatch,
                    diagnostic: &mut diagnostic,
                },
            );
            let return_value = unsafe {
                native_array_lvalue_result_into_value(
                    result,
                    format!(
                        "native callable builtin invocation failed: {} sorting returned no value",
                        operation.label()
                    ),
                )?
            };
            let value = reference
                .cell
                .coerce_value_for_write(value)
                .map_err(|error| error.message().to_string())?;
            reference.cell.set_value(value);
            return Ok(return_value);
        }

        let mode = match unsafe {
            native_array_sort_mode_from_operands(
                operation,
                if operands.is_empty() {
                    ptr::null()
                } else {
                    operands.as_ptr()
                },
                operands.len(),
            )
        } {
            Ok(mode) => mode,
            Err(result) => {
                return unsafe {
                    native_array_lvalue_result_into_value(
                        result,
                        format!(
                            "native callable builtin invocation failed: {} sort flag conversion returned no value",
                            operation.label()
                        ),
                    )
                };
            }
        };

        let mut value = reference.cell.value_cloned();
        let result = native_array_sort_value_path_result(
            &mut value,
            &[],
            operation,
            NativeArraySortCriteria::Mode(mode),
        );
        let return_value = unsafe {
            native_array_lvalue_result_into_value(
                result,
                format!(
                    "native callable builtin invocation failed: {} sorting returned no value",
                    operation.label()
                ),
            )?
        };
        let value = reference
            .cell
            .coerce_value_for_write(value)
            .map_err(|error| error.message().to_string())?;
        reference.cell.set_value(value);
        Ok(return_value)
    })();

    for value in operands {
        unsafe { phpc_native_value_free(value) };
    }
    result
}

unsafe fn native_callable_builtin_invoke_value(
    builtin: NativeCallableBuiltin,
    arguments: NativeCallArgumentsHandle,
) -> Result<Value, String> {
    if let NativeCallableBuiltin::ArraySort(operation) = builtin {
        return unsafe { native_callable_array_sort_value(operation, arguments) };
    }
    if let NativeCallableBuiltin::ArrayMutation(operation) = builtin {
        return unsafe { native_callable_array_mutation_value(operation, arguments) };
    }

    let values = unsafe { native_callable_builtin_argument_values(builtin, arguments) }?;
    let result = match builtin {
        NativeCallableBuiltin::StringLength => {
            unsafe { native_value_to_string_bytes(values[0]) }.and_then(|bytes| {
                i64::try_from(bytes.len()).map(Value::Int).map_err(|_| {
                    RuntimeError::invalid_string_conversion(
                        "native callable builtin invocation failed: strlen() result exceeds int range",
                    )
                })
            })
        }
        NativeCallableBuiltin::StringPredicate(predicate) => unsafe {
            native_value_string_predicate(values[0], values[1], predicate as u8).map(Value::Bool)
        },
        NativeCallableBuiltin::StringResult(operation) => unsafe {
            native_value_string_result_operation_value(values[0], 0, operation as u8)
        },
        NativeCallableBuiltin::StringSearch(NativeStringSearchOperation::Position) => {
            let offset_result = if values.len() > 2 {
                unsafe {
                    native_value_to_int64(
                        values[2],
                        NativeIntConversionOperation::StringOffset as u8,
                    )
                }
            } else {
                Ok(0)
            };
            offset_result.and_then(|offset| unsafe {
                native_value_string_search_result(
                    values[0],
                    values[1],
                    offset,
                    0,
                    0,
                    NativeStringSearchOperation::Position as u8,
                )
            })
        }
        NativeCallableBuiltin::StringSearch(NativeStringSearchOperation::Count) => {
            Err(RuntimeError::unsupported_call(
                "substr_count",
                "runtime callable builtin invocation is not implemented",
            ))
        }
        NativeCallableBuiltin::StringTrim(mode) => unsafe { native_callable_trim_value(mode, &values) },
        NativeCallableBuiltin::ArraySort(_) => unreachable!(),
        NativeCallableBuiltin::ArrayMutation(_) => unreachable!(),
        NativeCallableBuiltin::Cast(operation) => unsafe {
            native_value_cast_operation_value(values[0], operation)
        },
        NativeCallableBuiltin::TypeName(kind) => {
            match unsafe { values[0].as_ref() } {
                Some(value) => native_value_type_name(value, kind)
                    .map(Value::String)
                    .map_err(RuntimeError::invalid_string_conversion),
                None => Err(RuntimeError::invalid_string_conversion(
                    "native callable builtin invocation failed: type-name value handle is null",
                )),
            }
        }
        NativeCallableBuiltin::TypePredicate(predicate) => {
            match unsafe { values[0].as_ref() } {
                Some(value) => native_value_type_predicate(value, predicate)
                    .map(Value::Bool)
                    .ok_or_else(|| {
                        RuntimeError::invalid_string_conversion(format!(
                            "native callable builtin invocation failed: unsupported type-predicate tag {predicate}"
                        ))
                    }),
                None => Err(RuntimeError::invalid_string_conversion(
                    "native callable builtin invocation failed: type-predicate value handle is null",
                )),
            }
        }
    };
    for value in values {
        unsafe { phpc_native_value_free(value) };
    }
    result.map_err(|error| error.message().to_string())
}

unsafe fn native_callable_builtin_invoke_result(
    builtin: NativeCallableBuiltin,
    arguments: NativeCallArgumentsHandle,
) -> NativeCallResultHandle {
    match unsafe { native_callable_builtin_invoke_value(builtin, arguments) } {
        Ok(value) => phpc_native_call_result_from_value(NativeValueHandle::from_value(value)),
        Err(message) => NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
            NativeDiagnosticHandle::from_message(message),
        )),
    }
}

unsafe fn native_callable_value_invoke_table_result(
    callable: &NativeCallable,
    bound_receiver: Option<&Value>,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallResultHandle {
    let Some(arguments_ref) = (unsafe { arguments.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                "native callable-value invocation failed: arguments handle is null",
            )
        };
        return NativeCallResultHandle::null();
    };
    let mut slots = Vec::with_capacity(arguments_ref.slots.len());
    for slot in &arguments_ref.slots {
        slots.push(unsafe { slot.clone_slot() });
    }
    let receiver = bound_receiver.cloned().map(NativeValueHandle::from_value);
    let frame = NativeCallFrameHandle::from_frame(NativeCallFrame {
        slots,
        called_scope: callable.called_scope.clone(),
        receiver,
    });
    let result = unsafe { (callable.descriptor.callback)(frame) };
    unsafe { phpc_native_call_frame_free(frame) };
    if result.is_null() {
        NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
            NativeDiagnosticHandle::from_message(
                "native callable-value invocation failed: frame callback returned a null result",
            ),
        ))
    } else {
        result
    }
}

unsafe fn native_callable_value_invoke_closure_result(
    closure: &PhpClosure,
    arguments: NativeCallArgumentsHandle,
) -> NativeCallResultHandle {
    let Some(descriptor) = closure.descriptor() else {
        return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
            NativeDiagnosticHandle::from_message(
                "native callable-value invocation failed: closure value has no native descriptor/frame callback",
            ),
        ));
    };
    let closure_args =
        match unsafe { native_closure_arguments_from_call_arguments(descriptor, arguments) } {
            Ok(arguments) => arguments,
            Err(message) => {
                return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
                    NativeDiagnosticHandle::from_message(message),
                ));
            }
        };
    let closure_handle = NativeValueHandle::from_value(Value::Closure(closure.clone()));
    let mut result = unsafe {
        phpc_native_closure_invoke_result(
            closure_handle,
            0,
            if closure_args.is_empty() {
                ptr::null()
            } else {
                closure_args.as_ptr()
            },
            closure_args.len(),
        )
    };
    unsafe { phpc_native_value_free(closure_handle) };
    unsafe { native_closure_arguments_free(closure_args) };

    if !result.diagnostic.is_null() {
        let diagnostic = result.diagnostic;
        result.diagnostic = NativeDiagnosticHandle::null();
        unsafe { phpc_native_closure_result_free(result) };
        return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(diagnostic));
    }
    match result.status {
        NATIVE_CLOSURE_RESULT_VALUE if !result.value.is_null() => {
            let value = result.take_value();
            unsafe { phpc_native_closure_result_free(result) };
            phpc_native_call_result_from_value(value)
        }
        NATIVE_CLOSURE_RESULT_REFERENCE if !result.reference.is_null() => {
            let reference = result.reference;
            result.reference = NativeReferenceHandle::null();
            unsafe { phpc_native_closure_result_free(result) };
            phpc_native_call_result_from_reference(reference)
        }
        _ => {
            unsafe { phpc_native_closure_result_free(result) };
            NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
                NativeDiagnosticHandle::from_message(
                    "native callable-value invocation failed: descriptor closure returned no result",
                ),
            ))
        }
    }
}

fn native_magic_argument_array_insert_slot(
    array: &mut PhpArray,
    key: Option<ArrayKey>,
    slot: &NativeCallArgumentSlot,
) -> Result<(), String> {
    match slot {
        NativeCallArgumentSlot::Value(value) => {
            let value = unsafe { value.as_ref() }
                .cloned()
                .ok_or_else(|| "value slot is null".to_string())?;
            if let Some(key) = key {
                array.insert_checked(key, value)
            } else {
                array.append(value)
            }
            .map(|_| ())
            .map_err(|error| error.message().to_string())
        }
        NativeCallArgumentSlot::Reference(reference) => {
            let value = unsafe { reference.as_ref() }
                .map(|reference| reference.cell.value_cloned())
                .ok_or_else(|| "reference slot is null".to_string())?;
            if let Some(key) = key {
                array.insert_checked(key, value)
            } else {
                array.append(value)
            }
            .map(|_| ())
            .map_err(|error| error.message().to_string())
        }
    }
}

fn native_magic_call_arguments_from_method_and_arguments(
    method_name: &str,
    arguments: &NativeCallArguments,
) -> Result<NativeCallArgumentsHandle, String> {
    let mut argument_array = PhpArray::new();
    for (index, slot) in arguments.slots.iter().enumerate() {
        let key = if let Some(name) = arguments.names.get(index).and_then(|name| name.as_ref()) {
            Some(ArrayKey::string(name.clone()))
        } else {
            None
        };
        native_magic_argument_array_insert_slot(&mut argument_array, key, slot)
            .map_err(|error| format!("native magic __call argument packing failed: {}", error))?;
    }

    Ok(NativeCallArgumentsHandle {
        ptr: Box::into_raw(Box::new(NativeCallArguments {
            slots: vec![
                NativeCallArgumentSlot::Value(NativeValueHandle::from_value(Value::String(
                    method_name.to_string(),
                ))),
                NativeCallArgumentSlot::Value(NativeValueHandle::from_value(Value::Array(
                    argument_array,
                ))),
            ],
            names: vec![None, None],
            finalized_variadic: false,
        })),
    })
}

unsafe fn native_closure_value_invoke_result_with_diagnostic(
    handle: NativeValueHandle,
    call_depth: c_int,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallResultHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let Some(Value::Closure(closure)) = (unsafe { handle.as_ref() }) else {
        let type_name = unsafe { handle.as_ref() }
            .map(Value::type_name)
            .unwrap_or("null");
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::unsupported_call(
                    "Closure::__invoke()",
                    format!(
                        "direct descriptor-backed closure invocation requires a closure value, got {type_name}"
                    ),
                )
                .message(),
            )
        };
        return NativeCallResultHandle::null();
    };
    let Some(descriptor) = closure.descriptor() else {
        return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
            NativeDiagnosticHandle::from_message(
                RuntimeError::unsupported_call(
                    "Closure::__invoke()",
                    "closure value has no native descriptor/frame callback",
                )
                .message(),
            ),
        ));
    };
    let closure_args =
        match unsafe { native_closure_arguments_from_call_arguments(descriptor, arguments) } {
            Ok(arguments) => arguments,
            Err(message) => {
                return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
                    NativeDiagnosticHandle::from_message(message),
                ));
            }
        };
    let mut result = unsafe {
        phpc_native_closure_invoke_result(
            handle,
            call_depth,
            if closure_args.is_empty() {
                ptr::null()
            } else {
                closure_args.as_ptr()
            },
            closure_args.len(),
        )
    };
    unsafe { native_closure_arguments_free(closure_args) };

    if !result.diagnostic.is_null() {
        let diagnostic = result.diagnostic;
        result.diagnostic = NativeDiagnosticHandle::null();
        unsafe { phpc_native_closure_result_free(result) };
        return NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(diagnostic));
    }
    match result.status {
        NATIVE_CLOSURE_RESULT_VALUE if !result.value.is_null() => {
            let value = result.take_value();
            unsafe { phpc_native_closure_result_free(result) };
            phpc_native_call_result_from_value(value)
        }
        NATIVE_CLOSURE_RESULT_REFERENCE if !result.reference.is_null() => {
            let reference = result.reference;
            result.reference = NativeReferenceHandle::null();
            unsafe { phpc_native_closure_result_free(result) };
            phpc_native_call_result_from_reference(reference)
        }
        _ => {
            unsafe { phpc_native_closure_result_free(result) };
            NativeCallResultHandle::from_slot(NativeCallResultSlot::Failure(
                NativeDiagnosticHandle::from_message(
                    "native descriptor-backed closure invocation failed: closure returned no result",
                ),
            ))
        }
    }
}

