unsafe fn native_method_lookup_invoke_result_with_access_context_and_free_receiver_method_arguments(
    table: NativeCallableTableHandle,
    receiver: NativeValueHandle,
    method: NativeValueHandle,
    access_context: NativeCallableAccessContextTag,
    caller_scope: NativeStringHandle,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallResultHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| -> Result<NativeCallResultHandle, String> {
        let Some(table) = (unsafe { table.as_ref() }) else {
            return Err("native method invocation failed: table is null".to_string());
        };
        let Some(receiver_value) = (unsafe { receiver.as_ref() }) else {
            return Err("native method invocation failed: receiver handle is null".to_string());
        };
        let Some(method_value) = (unsafe { method.as_ref() }) else {
            return Err("native method invocation failed: method handle is null".to_string());
        };
        let method_name = match native_value_dynamic_method_name_string(method_value) {
            Some(method_name) if !method_name.is_empty() => method_name,
            Some(_) => {
                return Err(
                    "native method invocation failed: method name must be a non-empty scalar string"
                        .to_string(),
                );
            }
            None => {
                return Err(format!(
                    "native method invocation failed: method name must be a scalar-convertible string, got {}",
                    method_value.type_name()
                ));
            }
        };
        let access_context =
            unsafe { NativeCallableAccessContext::from_abi(access_context, caller_scope) }
                .map_err(|message| {
                    message.replace(
                        "native callable access context failed",
                        "native method invocation failed",
                    )
                })?;
        let callable =
            match table.lookup_receiver_method(receiver_value, method_name.clone(), access_context)
            {
                Ok(callable) => {
                    return Ok(unsafe {
                        native_callable_value_invoke_table_result(
                            &callable,
                            Some(receiver_value),
                            arguments,
                            diagnostic,
                        )
                    });
                }
                Err(message) => {
                    let original_error = message.replace(
                        "native callable lookup failed",
                        "native method invocation failed",
                    );
                    match table.lookup_receiver_magic_call(receiver_value, &original_error)? {
                        Some(callable) => callable,
                        None => return Err(original_error),
                    }
                }
            };
        let Some(arguments_ref) = (unsafe { arguments.as_ref() }) else {
            return Err(
                "native method invocation failed: arguments handle is null during magic __call dispatch"
                    .to_string(),
            );
        };
        let magic_arguments =
            native_magic_call_arguments_from_method_and_arguments(&method_name, arguments_ref)?;
        let magic_result = unsafe {
            native_callable_value_invoke_table_result(
                &callable,
                Some(receiver_value),
                magic_arguments,
                diagnostic,
            )
        };
        unsafe { phpc_native_call_arguments_free(magic_arguments) };
        Ok(magic_result)
    })();
    unsafe { phpc_native_value_free(receiver) };
    unsafe { phpc_native_value_free(method) };
    unsafe { phpc_native_call_arguments_free(arguments) };

    match result {
        Ok(result) => result,
        Err(message) => {
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            NativeCallResultHandle::null()
        }
    }
}

unsafe fn native_static_method_lookup_invoke_result_with_access_context_and_free_scope_method_arguments(
    table: NativeCallableTableHandle,
    scope: NativeStringHandle,
    method: NativeValueHandle,
    access_context: NativeCallableAccessContextTag,
    caller_scope: NativeStringHandle,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallResultHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| -> Result<NativeCallResultHandle, String> {
        let Some(table) = (unsafe { table.as_ref() }) else {
            return Err("native static method invocation failed: table is null".to_string());
        };
        let Some(scope) = (unsafe { native_string_handle_to_string(scope) }) else {
            return Err("native static method invocation failed: scope is null".to_string());
        };
        let Some(method_value) = (unsafe { method.as_ref() }) else {
            return Err(
                "native static method invocation failed: method handle is null".to_string(),
            );
        };
        let method_name =
            native_callable_value_name(method_value, "static method name").map_err(|message| {
                message.replace(
                    "native callable lookup failed",
                    "native static method invocation failed",
                )
            })?;
        let access_context =
            unsafe { NativeCallableAccessContext::from_abi(access_context, caller_scope) }
                .map_err(|message| {
                    message.replace(
                        "native callable access context failed",
                        "native static method invocation failed",
                    )
                })?;
        let callable = match table.lookup_static_method_for_dispatch(
            scope.clone(),
            method_name.clone(),
            access_context,
        ) {
            Ok(callable) => {
                return Ok(unsafe {
                    native_callable_value_invoke_table_result(
                        &callable, None, arguments, diagnostic,
                    )
                });
            }
            Err(NativeStaticMethodLookupFailure::NonStatic(message)) => {
                return Err(message.replace(
                    "native static method lookup failed",
                    "native static method invocation failed",
                ));
            }
            Err(NativeStaticMethodLookupFailure::Lookup(message)) => {
                let original_error = message.replace(
                    "native callable lookup failed",
                    "native static method invocation failed",
                );
                match table.lookup_static_magic_call(&scope, &original_error)? {
                    Some(callable) => callable,
                    None => return Err(original_error),
                }
            }
        };
        let Some(arguments_ref) = (unsafe { arguments.as_ref() }) else {
            return Err(
                "native static method invocation failed: arguments handle is null during magic __callStatic dispatch"
                    .to_string(),
            );
        };
        let magic_arguments = native_magic_callstatic_arguments_from_method_and_arguments(
            &method_name,
            arguments_ref,
        )?;
        let magic_result = unsafe {
            native_callable_value_invoke_table_result(&callable, None, magic_arguments, diagnostic)
        };
        unsafe { phpc_native_call_arguments_free(magic_arguments) };
        Ok(magic_result)
    })();
    unsafe { phpc_native_value_free(method) };
    unsafe { phpc_native_call_arguments_free(arguments) };

    match result {
        Ok(result) => result,
        Err(message) => {
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            NativeCallResultHandle::null()
        }
    }
}

unsafe fn native_constructor_allocation_invoke_result_with_access_context_and_free_scope_receiver_arguments(
    table: NativeCallableTableHandle,
    scope: NativeStringHandle,
    mut receiver: NativeValueHandle,
    access_context: NativeCallableAccessContextTag,
    caller_scope: NativeStringHandle,
    arguments: NativeCallArgumentsHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeCallResultHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| -> Result<NativeCallResultHandle, String> {
        let Some(table) = (unsafe { table.as_ref() }) else {
            return Err("native constructor invocation failed: table is null".to_string());
        };
        let Some(scope) = (unsafe { native_string_handle_to_string(scope) }) else {
            return Err("native constructor invocation failed: scope is null".to_string());
        };
        let Some(receiver_value) = (unsafe { receiver.as_ref() }) else {
            return Err(
                "native constructor invocation failed: receiver handle is null".to_string(),
            );
        };
        if !matches!(receiver_value, Value::Object(_)) {
            return Err(format!(
                "native constructor invocation failed: receiver must be an object, got {}",
                receiver_value.type_name()
            ));
        }
        let access_context =
            unsafe { NativeCallableAccessContext::from_abi(access_context, caller_scope) }
                .map_err(|message| {
                    message.replace(
                        "native callable access context failed",
                        "native constructor invocation failed",
                    )
                })?;
        if let Some(callable) = table
            .lookup_constructor_for_scope(scope, access_context)
            .map_err(|message| {
                message
                    .replace(
                        "native constructor lookup failed",
                        "native constructor invocation failed",
                    )
                    .replace(
                        "native constructor allocation failed",
                        "native constructor invocation failed",
                    )
            })?
        {
            let constructor_result = unsafe {
                native_callable_value_invoke_table_result(
                    &callable,
                    Some(receiver_value),
                    arguments,
                    diagnostic,
                )
            };
            if unsafe { native_diagnostic_slot_is_set(diagnostic) } {
                unsafe { phpc_native_call_result_free(constructor_result) };
                return Ok(NativeCallResultHandle::null());
            }
            if constructor_result.is_null() {
                return Err(
                    "native constructor invocation failed: frame callback returned a null result"
                        .to_string(),
                );
            }
            let constructor_diagnostic =
                unsafe { phpc_native_call_result_take_diagnostic(constructor_result) };
            unsafe { phpc_native_call_result_free(constructor_result) };
            if !constructor_diagnostic.is_null() {
                unsafe { phpc_native_value_free(receiver) };
                receiver = NativeValueHandle::null();
                return Ok(phpc_native_call_result_from_diagnostic_and_free(
                    constructor_diagnostic,
                ));
            }
        }
        let object = receiver;
        receiver = NativeValueHandle::null();
        Ok(phpc_native_call_result_from_value(object))
    })();
    unsafe { phpc_native_call_arguments_free(arguments) };

    match result {
        Ok(result) => result,
        Err(message) => {
            unsafe { phpc_native_value_free(receiver) };
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            NativeCallResultHandle::null()
        }
    }
}

