unsafe fn native_value_string_offset_operation_value(
    subject: NativeValueHandle,
    offset: NativeValueHandle,
    operation: u8,
) -> RuntimeResult<Value> {
    let operation = NativeStringOffsetOperation::from_tag(operation)?;
    if matches!(operation, NativeStringOffsetOperation::Read) {
        let bytes = unsafe { native_value_string_offset_read_subject_bytes(subject) }?;
        let offset = unsafe { native_string_offset_index_from_value(offset) }?;
        return php_string_offset_read_value(&bytes, offset);
    }

    let bytes = unsafe { native_value_string_offset_subject_bytes(subject) }?;
    let offset = unsafe { native_string_offset_index_from_value(offset) }?;
    Ok(Value::Bool(php_string_offset_bool_operation(
        &bytes, offset, operation,
    )))
}

unsafe fn native_value_string_offset_write_value(
    subject: NativeValueHandle,
    offset: NativeValueHandle,
    replacement: NativeValueHandle,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    let mut bytes = unsafe { native_value_string_offset_subject_bytes(subject) }?;
    let offset = unsafe { native_string_offset_index_from_value(offset) }?;
    let replacement = unsafe { native_string_offset_replacement_bytes_from_value(replacement) }?;

    let warning = php_string_offset_write(&mut bytes, offset, &replacement)?;
    Ok((value_from_php_string_bytes(bytes), warning))
}

unsafe fn native_value_offset_operation_value(
    subject: NativeValueHandle,
    offset: NativeValueHandle,
    operation: u8,
) -> RuntimeResult<(Value, Option<String>)> {
    let Some(value) = (unsafe { subject.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native value offset operation failed: subject handle is null",
        ));
    };

    if let Value::Array(array) = value {
        return unsafe { native_array_value_offset_operation_value(array, offset, operation) };
    }

    unsafe { native_value_string_offset_operation_value(subject, offset, operation) }
        .map(|value| (value, None))
}

unsafe fn native_conversion_source_value(source: NativeConversionSource) -> Result<Value, String> {
    match source.kind {
        PHPC_NATIVE_CONVERSION_SOURCE_SCALAR => Ok(source.scalar.to_value()),
        PHPC_NATIVE_CONVERSION_SOURCE_VALUE => unsafe { source.value.as_ref() }
            .cloned()
            .ok_or_else(|| "native conversion source value handle is null".to_string()),
        PHPC_NATIVE_CONVERSION_SOURCE_STRING => {
            let string = unsafe { source.string.as_ref() }
                .ok_or_else(|| "native conversion source string handle is null".to_string())?;
            String::from_utf8(string.bytes.clone())
                .map(Value::String)
                .map_err(|_| "native conversion source string requires UTF-8 bytes".to_string())
        }
        PHPC_NATIVE_CONVERSION_SOURCE_ARRAY => unsafe { source.array.as_ref() }
            .map(|array| Value::Array(array.value.clone()))
            .ok_or_else(|| "native conversion source array handle is null".to_string()),
        PHPC_NATIVE_CONVERSION_SOURCE_OBJECT => Err(
            "native conversion source object handle materialization awaits the object value boundary"
                .to_string(),
        ),
        PHPC_NATIVE_CONVERSION_SOURCE_RESOURCE => Err(
            "native conversion source resource handle materialization awaits the resource value boundary"
                .to_string(),
        ),
        PHPC_NATIVE_CONVERSION_SOURCE_REFERENCE => unsafe { source.reference.as_ref() }
            .map(|reference| reference.cell.value_cloned())
            .ok_or_else(|| "native conversion source reference handle is null".to_string()),
        kind => Err(format!("native conversion source kind {kind} is not supported")),
    }
}

fn native_string_offset_index_from_runtime_value(value: &Value) -> RuntimeResult<usize> {
    let offset = match value {
        Value::Null => 0,
        Value::Bool(false) => 0,
        Value::Bool(true) => 1,
        Value::Int(value) => *value,
        Value::Float(value)
            if value.is_finite()
                && value.fract() == 0.0
                && *value >= i64::MIN as f64
                && *value <= i64::MAX as f64 =>
        {
            *value as i64
        }
        Value::Float(_) => {
            return Err(RuntimeError::invalid_string_conversion(
                "native string offset operation failed: offset must be an integer",
            ))
        }
        Value::String(value) => php_string_offset_index_from_string(value)?,
        other => {
            return Err(RuntimeError::invalid_string_conversion(format!(
                "native string offset operation failed: {} offsets are not supported; only null, bool, int, integral float, and integer string offsets are implemented",
                other.type_name()
            )))
        }
    };

    usize::try_from(offset).map_err(|_| {
        RuntimeError::invalid_string_conversion(
            "native string offset operation failed: offset must be a non-negative integer",
        )
    })
}

fn native_offset_read_source_result_from_values(
    target: Value,
    key: Value,
) -> NativeConversionResult {
    match target {
        Value::Array(array) => match native_array_key_from_runtime_value(&key) {
            Ok(key) => match array.get_cloned(key.clone()) {
                Some(value) => NativeConversionResult::value(value),
                None => NativeConversionResult::value_with_warning(
                    Value::Null,
                    RuntimeError::undefined_array_key(key.diagnostic_key()).message(),
                ),
            },
            Err(error) => NativeConversionResult::error(error.message()),
        },
        Value::String(value) => match native_string_offset_index_from_runtime_value(&key)
            .and_then(|offset| php_string_offset_read_value(value.as_bytes(), offset))
        {
            Ok(value) => NativeConversionResult::value(value),
            Err(error) => NativeConversionResult::error(error.message()),
        },
        Value::BinaryString(value) => match native_string_offset_index_from_runtime_value(&key)
            .and_then(|offset| php_string_offset_read_value(&value, offset))
        {
            Ok(value) => NativeConversionResult::value(value),
            Err(error) => NativeConversionResult::error(error.message()),
        },
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::Resource(_) => {
            NativeConversionResult::value_with_warning(
                Value::Null,
                format!(
                    "Warning: Trying to access array offset on value of type {}",
                    target.type_name()
                ),
            )
        }
        Value::Object(_) | Value::Closure(_) => NativeConversionResult::error(format!(
            "native offset read source failed: {} subjects require a supported ArrayAccess/object boundary",
            target.type_name()
        )),
    }
}

/// # Safety
///
/// Each source must contain null handles or handles returned by the runtime ABI
/// and not yet freed. The returned value and diagnostic handles are owned by
/// the result consumer.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_offset_read_source(
    target_source: NativeConversionSource,
    key_source: NativeConversionSource,
) -> NativeConversionResult {
    let target = match unsafe { native_conversion_source_value(target_source) } {
        Ok(value) => value,
        Err(message) => return NativeConversionResult::error(message),
    };
    let key = match unsafe { native_conversion_source_value(key_source) } {
        Ok(value) => value,
        Err(message) => return NativeConversionResult::error(message),
    };
    native_offset_read_source_result_from_values(target, key)
}

/// # Safety
///
/// `source` must contain null handles or handles returned by the runtime ABI
/// and not yet freed. The returned value and diagnostic handles are owned by
/// the caller and must be freed with the matching runtime ABI helpers.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_conversion_source_numeric_unary(
    source: NativeConversionSource,
    op: u8,
) -> NativeConversionResult {
    if op != PHPC_NATIVE_NUMERIC_UNARY_OP_NEGATE {
        return NativeConversionResult::error(
            "native numeric unary operation tag is not supported",
        );
    }

    let value = match unsafe { native_conversion_source_value(source) } {
        Ok(value) => value,
        Err(message) => return NativeConversionResult::error(message),
    };

    if let Some(message) = native_value_unary_blocker(&value) {
        return NativeConversionResult::error(message);
    }

    match native_value_unary_value_with_diagnostic(&value, NATIVE_VALUE_UNARY_NEGATE) {
        Ok((value, Some(message))) => NativeConversionResult::value_with_warning(value, message),
        Ok((value, None)) => NativeConversionResult::value(value),
        Err(error) => NativeConversionResult::error(format!(
            "native numeric unary operation rejected by runtime semantics: {}",
            error.message()
        )),
    }
}

fn native_object_property_name_from_value(value: &Value) -> Result<String, String> {
    value
        .try_echo_string()
        .map_err(|error| error.message().to_string())
}

/// # Safety
///
/// Each source must contain null handles or handles returned by the runtime ABI
/// and not yet freed. The returned value and diagnostic handles are owned by
/// the result consumer.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_object_property_offset_read_source(
    target_source: NativeConversionSource,
    property_source: NativeConversionSource,
    key_source: NativeConversionSource,
) -> NativeConversionResult {
    let target = match unsafe { native_conversion_source_value(target_source) } {
        Ok(value) => value,
        Err(message) => return NativeConversionResult::error(message),
    };
    let property = match unsafe { native_conversion_source_value(property_source) } {
        Ok(value) => value,
        Err(message) => return NativeConversionResult::error(message),
    };
    let key = match unsafe { native_conversion_source_value(key_source) } {
        Ok(value) => value,
        Err(message) => return NativeConversionResult::error(message),
    };

    let property_name = match native_object_property_name_from_value(&property) {
        Ok(name) if !name.is_empty() => name,
        Ok(_) => {
            return NativeConversionResult::error(
                "native object property offset read source requires a non-empty property name",
            )
        }
        Err(message) => return NativeConversionResult::error(message),
    };

    let Value::Object(object) = target else {
        return NativeConversionResult::error(
            "native object property offset read source requires an object value",
        );
    };
    match object.read_public_property(&property_name) {
        Ok(value) => native_offset_read_source_result_from_values(value, key),
        Err(error) => NativeConversionResult::error(error.message()),
    }
}

unsafe fn native_value_arrayaccess_offset_write_operation_value(
    table: NativeCallableTableHandle,
    subject: NativeValueHandle,
    offset: NativeValueHandle,
    replacement: NativeValueHandle,
    operation: u8,
    caller_scope: NativeStringHandle,
) -> RuntimeResult<Value> {
    let operation = NativeArrayAccessOffsetWriteOperation::from_tag(operation)?;
    let Some(table) = (unsafe { table.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native ArrayAccess offset write dispatch failed: callable table is null",
        ));
    };
    let Some(subject_value) = (unsafe { subject.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native ArrayAccess offset write dispatch failed: subject handle is null",
        ));
    };
    let Value::Object(object) = subject_value else {
        return Err(RuntimeError::invalid_array_access(format!(
            "native ArrayAccess offset write dispatch requires an object subject, got {}",
            subject_value.type_name()
        )));
    };
    if !object.is_instance_of_class_name("ArrayAccess") {
        return Err(RuntimeError::invalid_array_access(format!(
            "native ArrayAccess offset write dispatch failed: object of class {} does not implement ArrayAccess",
            object.class_name()
        )));
    }

    let callable = table
        .lookup(
            NativeCallableKind::Method,
            Some(object.class_name().to_string()),
            operation.method_name().to_string(),
            unsafe { native_string_handle_to_string(caller_scope) },
        )
        .map_err(RuntimeError::invalid_array_access)?;
    let dispatch = NativeCallableValueHandle::from_dispatch(NativeCallableValueDispatch::Table {
        callable,
        bound_receiver: Some(Value::Object(object.clone())),
    });
    let arguments = match unsafe {
        native_arrayaccess_offset_write_arguments(offset, replacement, operation)
    } {
        Ok(arguments) => arguments,
        Err(error) => {
            unsafe { phpc_native_callable_value_free(dispatch) };
            return Err(error);
        }
    };
    let mut call_diagnostic = NativeDiagnosticHandle::null();
    let result = unsafe {
        phpc_native_callable_value_invoke_result_with_diagnostic_and_free(
            dispatch,
            arguments,
            &mut call_diagnostic,
        )
    };
    unsafe { phpc_native_callable_value_free(dispatch) };

    if !call_diagnostic.is_null() {
        let message = unsafe { call_diagnostic.as_ref() }
            .map(|diagnostic| diagnostic.message.clone())
            .unwrap_or_else(|| {
                "native ArrayAccess offset write dispatch failed: callable dispatch failed"
                    .to_string()
            });
        unsafe { phpc_native_diagnostic_free(call_diagnostic) };
        unsafe { phpc_native_call_result_free(result) };
        return Err(RuntimeError::invalid_array_access(message));
    }

    if unsafe { phpc_native_call_result_status(result) } == NativeCallResultStatus::Failure {
        let diagnostic = unsafe { phpc_native_call_result_take_diagnostic_and_free(result) };
        let message = unsafe { diagnostic.as_ref() }
            .map(|diagnostic| diagnostic.message.clone())
            .unwrap_or_else(|| {
                "native ArrayAccess offset write dispatch failed: callback returned failure"
                    .to_string()
            });
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        return Err(RuntimeError::invalid_array_access(message));
    }

    unsafe { phpc_native_call_result_discard_and_free(result) };
    Ok(Value::Object(object.clone()))
}

unsafe fn native_value_arrayaccess_offset_read_operation_value(
    table: NativeCallableTableHandle,
    subject: NativeValueHandle,
    offset: NativeValueHandle,
    operation: u8,
    caller_scope: NativeStringHandle,
) -> RuntimeResult<Value> {
    let operation = NativeArrayAccessOffsetReadOperation::from_tag(operation)?;
    let Some(table) = (unsafe { table.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native ArrayAccess offset read dispatch failed: callable table is null",
        ));
    };
    let Some(subject_value) = (unsafe { subject.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native ArrayAccess offset read dispatch failed: subject handle is null",
        ));
    };
    let Value::Object(object) = subject_value else {
        return Err(RuntimeError::invalid_array_access(format!(
            "native ArrayAccess offset read dispatch requires an object subject, got {}",
            subject_value.type_name()
        )));
    };
    if !object.is_instance_of_class_name("ArrayAccess") {
        return Err(RuntimeError::invalid_array_access(format!(
            "native ArrayAccess offset read dispatch failed: object of class {} does not implement ArrayAccess",
            object.class_name()
        )));
    }

    let callable = table
        .lookup(
            NativeCallableKind::Method,
            Some(object.class_name().to_string()),
            operation.method_name().to_string(),
            unsafe { native_string_handle_to_string(caller_scope) },
        )
        .map_err(RuntimeError::invalid_array_access)?;
    let dispatch = NativeCallableValueHandle::from_dispatch(NativeCallableValueDispatch::Table {
        callable,
        bound_receiver: Some(Value::Object(object.clone())),
    });
    let arguments = match unsafe { native_arrayaccess_offset_read_arguments(offset, operation) } {
        Ok(arguments) => arguments,
        Err(error) => {
            unsafe { phpc_native_callable_value_free(dispatch) };
            return Err(error);
        }
    };
    let mut call_diagnostic = NativeDiagnosticHandle::null();
    let result = unsafe {
        phpc_native_callable_value_invoke_result_with_diagnostic_and_free(
            dispatch,
            arguments,
            &mut call_diagnostic,
        )
    };
    unsafe { phpc_native_callable_value_free(dispatch) };

    if !call_diagnostic.is_null() {
        let message = unsafe { call_diagnostic.as_ref() }
            .map(|diagnostic| diagnostic.message.clone())
            .unwrap_or_else(|| {
                "native ArrayAccess offset read dispatch failed: callable dispatch failed"
                    .to_string()
            });
        unsafe { phpc_native_diagnostic_free(call_diagnostic) };
        unsafe { phpc_native_call_result_free(result) };
        return Err(RuntimeError::invalid_array_access(message));
    }

    match unsafe { phpc_native_call_result_status(result) } {
        NativeCallResultStatus::Failure => {
            let diagnostic = unsafe { phpc_native_call_result_take_diagnostic_and_free(result) };
            let message = unsafe { diagnostic.as_ref() }
                .map(|diagnostic| diagnostic.message.clone())
                .unwrap_or_else(|| {
                    "native ArrayAccess offset read dispatch failed: callback returned failure"
                        .to_string()
                });
            unsafe { phpc_native_diagnostic_free(diagnostic) };
            Err(RuntimeError::invalid_array_access(message))
        }
        NativeCallResultStatus::Value | NativeCallResultStatus::Reference => {
            let value = unsafe { phpc_native_call_result_take_value_and_free(result) };
            let Some(value_ref) = (unsafe { value.as_ref() }) else {
                return Err(RuntimeError::invalid_array_access(
                    "native ArrayAccess offset read dispatch failed: callback returned no value",
                ));
            };
            if matches!(operation, NativeArrayAccessOffsetReadOperation::Exists) {
                let exists = value_ref.is_truthy();
                unsafe { phpc_native_value_free(value) };
                Ok(Value::Bool(exists))
            } else {
                let result = value_ref.clone();
                unsafe { phpc_native_value_free(value) };
                Ok(result)
            }
        }
        NativeCallResultStatus::Null => {
            unsafe { phpc_native_call_result_free(result) };
            Err(RuntimeError::invalid_array_access(
                "native ArrayAccess offset read dispatch failed: callback returned a null result",
            ))
        }
    }
}

unsafe fn native_value_arrayaccess_offset_get_reference(
    table: NativeCallableTableHandle,
    subject: NativeValueHandle,
    offset: NativeValueHandle,
    caller_scope: NativeStringHandle,
) -> RuntimeResult<PhpReferenceCell> {
    let Some(table) = (unsafe { table.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native ArrayAccess offsetGet reference dispatch failed: callable table is null",
        ));
    };
    let Some(subject_value) = (unsafe { subject.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native ArrayAccess offsetGet reference dispatch failed: subject handle is null",
        ));
    };
    let Value::Object(object) = subject_value else {
        return Err(RuntimeError::invalid_array_access(format!(
            "native ArrayAccess offsetGet reference dispatch requires an object subject, got {}",
            subject_value.type_name()
        )));
    };
    if !object.is_instance_of_class_name("ArrayAccess") {
        return Err(RuntimeError::invalid_array_access(format!(
            "native ArrayAccess offsetGet reference dispatch failed: object of class {} does not implement ArrayAccess",
            object.class_name()
        )));
    }

    let callable = table
        .lookup(
            NativeCallableKind::Method,
            Some(object.class_name().to_string()),
            NativeArrayAccessOffsetReadOperation::Get
                .method_name()
                .to_string(),
            unsafe { native_string_handle_to_string(caller_scope) },
        )
        .map_err(RuntimeError::invalid_array_access)?;
    let dispatch = NativeCallableValueHandle::from_dispatch(NativeCallableValueDispatch::Table {
        callable,
        bound_receiver: Some(Value::Object(object.clone())),
    });
    let arguments = match unsafe {
        native_arrayaccess_offset_read_arguments(offset, NativeArrayAccessOffsetReadOperation::Get)
    } {
        Ok(arguments) => arguments,
        Err(error) => {
            unsafe { phpc_native_callable_value_free(dispatch) };
            return Err(error);
        }
    };
    let mut call_diagnostic = NativeDiagnosticHandle::null();
    let result = unsafe {
        phpc_native_callable_value_invoke_result_with_diagnostic_and_free(
            dispatch,
            arguments,
            &mut call_diagnostic,
        )
    };
    unsafe { phpc_native_callable_value_free(dispatch) };

    if !call_diagnostic.is_null() {
        let message = unsafe { call_diagnostic.as_ref() }
            .map(|diagnostic| diagnostic.message.clone())
            .unwrap_or_else(|| {
                "native ArrayAccess offsetGet reference dispatch failed: callable dispatch failed"
                    .to_string()
            });
        unsafe { phpc_native_diagnostic_free(call_diagnostic) };
        unsafe { phpc_native_call_result_free(result) };
        return Err(RuntimeError::invalid_array_access(message));
    }

    match unsafe { phpc_native_call_result_status(result) } {
        NativeCallResultStatus::Reference => {
            let reference = unsafe { phpc_native_call_result_take_reference_and_free(result) };
            let Some(reference_ref) = (unsafe { reference.as_ref() }) else {
                return Err(RuntimeError::invalid_array_access(
                    "native ArrayAccess offsetGet reference dispatch failed: callback returned no reference",
                ));
            };
            let cell = reference_ref.cell.clone();
            unsafe { phpc_native_reference_free(reference) };
            Ok(cell)
        }
        NativeCallResultStatus::Failure => {
            let diagnostic = unsafe { phpc_native_call_result_take_diagnostic_and_free(result) };
            let message = unsafe { diagnostic.as_ref() }
                .map(|diagnostic| diagnostic.message.clone())
                .unwrap_or_else(|| {
                    "native ArrayAccess offsetGet reference dispatch failed: callback returned failure"
                        .to_string()
                });
            unsafe { phpc_native_diagnostic_free(diagnostic) };
            Err(RuntimeError::invalid_array_access(message))
        }
        NativeCallResultStatus::Value => {
            let value = unsafe { phpc_native_call_result_take_value_and_free(result) };
            unsafe { phpc_native_value_free(value) };
            Err(RuntimeError::invalid_array_access(
                "native ArrayAccess offsetGet reference dispatch failed: callback returned a value",
            ))
        }
        NativeCallResultStatus::Null => {
            unsafe { phpc_native_call_result_free(result) };
            Err(RuntimeError::invalid_array_access(
                "native ArrayAccess offsetGet reference dispatch failed: callback returned a null result",
            ))
        }
    }
}

unsafe fn native_arrayaccess_offset_write_arguments(
    offset: NativeValueHandle,
    replacement: NativeValueHandle,
    operation: NativeArrayAccessOffsetWriteOperation,
) -> RuntimeResult<NativeCallArgumentsHandle> {
    let arguments = phpc_native_call_arguments_new();
    let offset_value = match operation {
        NativeArrayAccessOffsetWriteOperation::Append => Value::Null,
        NativeArrayAccessOffsetWriteOperation::Write
        | NativeArrayAccessOffsetWriteOperation::Unset => {
            match unsafe { offset.as_ref() }.cloned() {
                Some(offset) => offset,
                None => {
                    unsafe { phpc_native_call_arguments_free(arguments) };
                    return Err(RuntimeError::invalid_array_access(format!(
                        "native ArrayAccess offset write dispatch failed: {} offset handle is null",
                        operation.replacement_label()
                    )));
                }
            }
        }
    };

    if !unsafe {
        phpc_native_call_arguments_push_value_and_free(
            arguments,
            NativeValueHandle::from_value(offset_value),
        )
    } {
        unsafe { phpc_native_call_arguments_free(arguments) };
        return Err(RuntimeError::invalid_array_access(
            "native ArrayAccess offset write dispatch failed: offset argument could not be materialized",
        ));
    }

    if !matches!(operation, NativeArrayAccessOffsetWriteOperation::Unset) {
        let Some(replacement) = (unsafe { replacement.as_ref() }) else {
            unsafe { phpc_native_call_arguments_free(arguments) };
            return Err(RuntimeError::invalid_array_access(format!(
                "native ArrayAccess offset write dispatch failed: {} value handle is null",
                operation.replacement_label()
            )));
        };
        if !unsafe {
            phpc_native_call_arguments_push_value_and_free(
                arguments,
                NativeValueHandle::from_value(replacement.clone()),
            )
        } {
            unsafe { phpc_native_call_arguments_free(arguments) };
            return Err(RuntimeError::invalid_array_access(
                "native ArrayAccess offset write dispatch failed: replacement argument could not be materialized",
            ));
        }
    }

    Ok(arguments)
}

unsafe fn native_arrayaccess_offset_read_arguments(
    offset: NativeValueHandle,
    operation: NativeArrayAccessOffsetReadOperation,
) -> RuntimeResult<NativeCallArgumentsHandle> {
    let arguments = phpc_native_call_arguments_new();
    let Some(offset) = (unsafe { offset.as_ref() }) else {
        unsafe { phpc_native_call_arguments_free(arguments) };
        return Err(RuntimeError::invalid_array_access(format!(
            "native ArrayAccess offset read dispatch failed: {} offset handle is null",
            operation.offset_label()
        )));
    };

    if !unsafe {
        phpc_native_call_arguments_push_value_and_free(
            arguments,
            NativeValueHandle::from_value(offset.clone()),
        )
    } {
        unsafe { phpc_native_call_arguments_free(arguments) };
        return Err(RuntimeError::invalid_array_access(
            "native ArrayAccess offset read dispatch failed: offset argument could not be materialized",
        ));
    }

    Ok(arguments)
}

unsafe fn native_value_offset_mutation_operation_value(
    subject: NativeValueHandle,
    offset: NativeValueHandle,
    replacement: NativeValueHandle,
    operation: u8,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    let Some(value) = (unsafe { subject.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native value offset mutation failed: subject handle is null",
        ));
    };

    if let Value::Array(array) = value {
        return unsafe {
            native_array_value_offset_mutation_operation_value(
                array,
                offset,
                replacement,
                operation,
            )
        };
    }

    if operation == NativeValueOffsetMutationOperation::Append as u8 {
        return unsafe { native_value_offset_append_mutation_value(value, replacement) };
    }

    if operation == NativeValueOffsetMutationOperation::Write as u8
        && matches!(value, Value::Null | Value::Bool(false))
    {
        return unsafe {
            native_array_conversion_offset_write_mutation_value(value, offset, replacement)
        };
    }

    if operation == NativeValueOffsetMutationOperation::Write as u8
        && matches!(value, Value::Bool(true) | Value::Int(_) | Value::Float(_))
    {
        return Err(RuntimeError::invalid_array_access(
            "cannot use a scalar value as an array",
        ));
    }

    unsafe {
        native_string_value_offset_mutation_operation_value(subject, offset, replacement, operation)
    }
}

unsafe fn native_array_conversion_offset_write_mutation_value(
    subject: &Value,
    offset: NativeValueHandle,
    replacement: NativeValueHandle,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    let Some(offset) = (unsafe { offset.as_ref() }) else {
        return Err(RuntimeError::invalid_array_key(
            "native value offset mutation failed: write offset handle is null",
        ));
    };
    let value = unsafe { native_value_clone_for_offset_mutation(replacement, "write") }?;
    let mut array = PhpArray::new();
    array.insert(native_array_key_from_runtime_value(offset)?, value);
    let diagnostic =
        matches!(subject, Value::Bool(false)).then_some(PHP_FALSE_TO_ARRAY_DEPRECATION);
    Ok((Value::Array(array), diagnostic))
}

unsafe fn native_array_value_offset_mutation_operation_value(
    array: &PhpArray,
    offset: NativeValueHandle,
    replacement: NativeValueHandle,
    operation: u8,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    let mut array = array.clone();
    match operation {
        tag if tag == NativeValueOffsetMutationOperation::Write as u8 => {
            let Some(offset) = (unsafe { offset.as_ref() }) else {
                return Err(RuntimeError::invalid_array_key(
                    "native value offset mutation failed: write offset handle is null",
                ));
            };
            let value = unsafe { native_value_clone_for_offset_mutation(replacement, "write") }?;
            array.insert(native_array_key_from_runtime_value(offset)?, value);
        }
        tag if tag == NativeValueOffsetMutationOperation::Append as u8 => {
            let value = unsafe { native_value_clone_for_offset_mutation(replacement, "append") }?;
            array.append(value)?;
        }
        tag if tag == NativeValueOffsetMutationOperation::Unset as u8 => {
            let Some(offset) = (unsafe { offset.as_ref() }) else {
                return Err(RuntimeError::invalid_array_key(
                    "native value offset mutation failed: unset offset handle is null",
                ));
            };
            array.remove(native_array_key_from_runtime_value(offset)?);
        }
        _ => {
            return Err(RuntimeError::invalid_array_access(
                "native value offset mutation failed: unsupported operation tag",
            ));
        }
    }

    Ok((Value::Array(array), None))
}

unsafe fn native_value_offset_append_mutation_value(
    subject: &Value,
    replacement: NativeValueHandle,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    if matches!(subject, Value::Null | Value::Bool(false)) {
        let replacement = unsafe { native_value_clone_for_offset_mutation(replacement, "append") }?;
        let mut array = PhpArray::new();
        array.append(replacement)?;
        let diagnostic =
            matches!(subject, Value::Bool(false)).then_some(PHP_FALSE_TO_ARRAY_DEPRECATION);
        return Ok((Value::Array(array), diagnostic));
    }

    if subject.string_byte_view().is_some() {
        return Err(RuntimeError::invalid_array_access(
            "native value offset mutation failed: string offset append awaits the shared mutable string-offset ABI",
        ));
    }

    if matches!(subject, Value::Bool(true) | Value::Int(_) | Value::Float(_)) {
        return Err(RuntimeError::invalid_array_access(
            "cannot use a scalar value as an array",
        ));
    }

    Err(RuntimeError::invalid_array_access(format!(
        "native value offset mutation append blocked for {} subjects pending object/ArrayAccess/resource/reference/COW semantics",
        subject.type_name()
    )))
}

unsafe fn native_value_offset_path_write_value(
    subject: NativeValueHandle,
    offsets: *const NativeValueHandle,
    offsets_len: usize,
    replacement: NativeValueHandle,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    let keys = unsafe {
        native_value_offset_key_path_from_handles(
            offsets,
            offsets_len,
            "native value offset path write",
        )
    }?;
    if keys.is_empty() {
        return Err(RuntimeError::invalid_array_access(
            "native value offset path write failed: offset path requires at least one key",
        ));
    }
    let replacement = unsafe { native_value_clone_for_offset_mutation(replacement, "path write") }?;

    let Some(subject) = (unsafe { subject.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native value offset path write failed: subject handle is null",
        ));
    };

    native_value_offset_path_write_subject_value(subject, &keys, replacement)
}

unsafe fn native_value_offset_path_unset_value(
    subject: NativeValueHandle,
    offsets: *const NativeValueHandle,
    offsets_len: usize,
) -> RuntimeResult<Value> {
    let keys = unsafe {
        native_value_offset_key_path_from_handles(
            offsets,
            offsets_len,
            "native value offset path unset",
        )
    }?;
    if keys.is_empty() {
        return Err(RuntimeError::invalid_array_access(
            "native value offset path unset failed: offset path requires at least one key",
        ));
    }

    let Some(subject) = (unsafe { subject.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native value offset path unset failed: subject handle is null",
        ));
    };

    native_value_offset_path_unset_subject_value(subject, &keys)
}

unsafe fn native_value_offset_path_append_value(
    subject: NativeValueHandle,
    prefix_offsets: *const NativeValueHandle,
    prefix_offsets_len: usize,
    suffix_offsets: *const NativeValueHandle,
    suffix_offsets_len: usize,
    replacement: NativeValueHandle,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    let prefix_keys = unsafe {
        native_value_offset_key_path_from_handles(
            prefix_offsets,
            prefix_offsets_len,
            "native value offset path append prefix",
        )
    }?;
    let suffix_keys = unsafe {
        native_value_offset_key_path_from_handles(
            suffix_offsets,
            suffix_offsets_len,
            "native value offset path append suffix",
        )
    }?;
    let replacement =
        unsafe { native_value_clone_for_offset_mutation(replacement, "path append") }?;
    let replacement = native_value_wrap_offset_path_suffix(&suffix_keys, replacement)?;

    let Some(subject) = (unsafe { subject.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(
            "native value offset path append failed: subject handle is null",
        ));
    };

    native_value_offset_path_append_subject_value(subject, &prefix_keys, replacement)
}

unsafe fn native_value_offset_key_path_from_handles(
    offsets: *const NativeValueHandle,
    offsets_len: usize,
    operation: &'static str,
) -> RuntimeResult<Vec<ArrayKey>> {
    if offsets_len == 0 {
        return Ok(Vec::new());
    }
    if offsets.is_null() {
        return Err(RuntimeError::invalid_array_key(format!(
            "{operation} failed: offset path pointer is null"
        )));
    }

    let offsets = unsafe { std::slice::from_raw_parts(offsets, offsets_len) };
    let mut keys = Vec::with_capacity(offsets.len());
    for (index, offset) in offsets.iter().enumerate() {
        let Some(value) = (unsafe { offset.as_ref() }) else {
            return Err(RuntimeError::invalid_array_key(format!(
                "{operation} failed: offset path handle {index} is null"
            )));
        };
        keys.push(native_array_key_from_runtime_value(value)?);
    }
    Ok(keys)
}

fn native_value_offset_path_write_subject_value(
    subject: &Value,
    keys: &[ArrayKey],
    replacement: Value,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    if let Value::Array(array) = subject {
        let mut array = array.clone();
        native_php_array_write_path(&mut array, keys, replacement)?;
        return Ok((Value::Array(array), None));
    }

    if matches!(subject, Value::Null | Value::Bool(false)) {
        let mut array = PhpArray::new();
        native_php_array_write_path(&mut array, keys, replacement)?;
        let diagnostic =
            matches!(subject, Value::Bool(false)).then_some(PHP_FALSE_TO_ARRAY_DEPRECATION);
        return Ok((Value::Array(array), diagnostic));
    }

    Err(native_value_offset_path_subject_error(
        "write",
        "native value offset path write",
        subject,
    ))
}

fn native_value_offset_path_append_subject_value(
    subject: &Value,
    prefix_keys: &[ArrayKey],
    replacement: Value,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    if let Value::Array(array) = subject {
        let mut array = array.clone();
        array.append_path(prefix_keys, replacement)?;
        return Ok((Value::Array(array), None));
    }

    if matches!(subject, Value::Null | Value::Bool(false)) {
        let mut array = PhpArray::new();
        array.append_path(prefix_keys, replacement)?;
        let diagnostic =
            matches!(subject, Value::Bool(false)).then_some(PHP_FALSE_TO_ARRAY_DEPRECATION);
        return Ok((Value::Array(array), diagnostic));
    }

    Err(native_value_offset_path_subject_error(
        "append",
        "native value offset path append",
        subject,
    ))
}

fn native_value_offset_path_subject_error(
    operation: &'static str,
    surface: &'static str,
    subject: &Value,
) -> RuntimeError {
    if subject.string_byte_view().is_some() {
        return RuntimeError::invalid_array_access(format!(
            "{surface} blocked for string subjects pending mutable string-offset path {operation}, references, and copy-on-write semantics"
        ));
    }

    if matches!(subject, Value::Bool(true) | Value::Int(_) | Value::Float(_)) {
        return RuntimeError::invalid_array_access("cannot use a scalar value as an array");
    }

    RuntimeError::invalid_array_access(format!(
        "{surface} blocked for {} subjects pending object/ArrayAccess/resource/reference/COW semantics",
        subject.type_name()
    ))
}

fn native_value_offset_path_unset_subject_value(
    subject: &Value,
    keys: &[ArrayKey],
) -> RuntimeResult<Value> {
    match subject {
        Value::Array(array) => {
            let mut array = array.clone();
            native_php_array_unset_path(&mut array, keys)?;
            Ok(Value::Array(array))
        }
        Value::Null => Ok(Value::Null),
        other => Err(native_value_offset_path_subject_error(
            "unset",
            "native value offset path unset",
            other,
        )),
    }
}

fn native_value_wrap_offset_path_suffix(
    suffix_keys: &[ArrayKey],
    replacement: Value,
) -> RuntimeResult<Value> {
    if suffix_keys.is_empty() {
        return Ok(replacement);
    }

    let mut array = PhpArray::new();
    native_php_array_write_path(&mut array, suffix_keys, replacement)?;
    Ok(Value::Array(array))
}

fn native_php_array_unset_path(array: &mut PhpArray, keys: &[ArrayKey]) -> RuntimeResult<()> {
    let Some((key, rest)) = keys.split_first() else {
        return Ok(());
    };

    if rest.is_empty() {
        array.remove(key.clone());
        return Ok(());
    }

    let Some(value) = array.get_cloned(key.clone()) else {
        return Ok(());
    };

    let mut child = match value {
        Value::Array(child) => child,
        Value::Null => return Ok(()),
        other => {
            return Err(RuntimeError::invalid_array_access(format!(
                "cannot unset offset on {}",
                other.type_name()
            )));
        }
    };

    native_php_array_unset_path(&mut child, rest)?;
    array.insert_checked(key.clone(), Value::Array(child))?;
    Ok(())
}

fn native_php_array_write_path(
    array: &mut PhpArray,
    keys: &[ArrayKey],
    value: Value,
) -> RuntimeResult<()> {
    let Some((key, rest)) = keys.split_first() else {
        return Err(RuntimeError::invalid_array_access(
            "nested array assignment requires at least one key",
        ));
    };

    if rest.is_empty() {
        array.insert_checked(key.clone(), value)?;
        return Ok(());
    }

    let mut child = match array.get_cloned(key.clone()) {
        Some(Value::Array(child)) => child,
        Some(Value::Null) | Some(Value::Bool(false)) | None => PhpArray::new(),
        Some(other) => {
            return Err(RuntimeError::invalid_array_access(format!(
                "cannot write offset on {}",
                other.type_name()
            )));
        }
    };

    native_php_array_write_path(&mut child, rest, value)?;
    array.insert_checked(key.clone(), Value::Array(child))?;
    Ok(())
}

/// # Safety
///
/// `array` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. The returned owner borrows the array handle; ownership
/// remains with the caller.
#[no_mangle]
pub extern "C" fn phpc_native_array_lvalue_owner_array(
    array: NativeArrayHandle,
) -> NativeArrayLvalueOwner {
    NativeArrayLvalueOwner::array(array)
}

/// # Safety
///
/// `reference` must be null or a reference handle previously returned by the
/// runtime ABI and not yet freed. The returned owner borrows the reference
/// handle; ownership remains with the caller.
#[no_mangle]
pub extern "C" fn phpc_native_array_lvalue_owner_reference_slot(
    reference: NativeReferenceHandle,
) -> NativeArrayLvalueOwner {
    NativeArrayLvalueOwner::reference_slot(reference)
}

/// # Safety
///
/// The owner and each key handle inside `segments` must be null or handles
/// previously returned by the runtime ABI and not yet freed. `segments` must be
/// null when `segment_count` is zero, or point to `segment_count` initialized
/// path segments. Key and append segments are executable for writes; reads,
/// probes, and unsets remain key-only. Increment/decrement updates accept key
/// paths and final append segments; append suffix updates remain centralized
/// blockers. Other families remain centralized blockers.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_value_operation_result(
    mut owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    family: u8,
    _operation: u8,
    _op: u8,
    _position: u8,
    value: NativeValueHandle,
) -> NativeArrayLvalueResult {
    if !matches!(
        family,
        NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE
            | NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET
            | NATIVE_ARRAY_LVALUE_VALUE_OPERATION_READ
            | NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE
            | NATIVE_ARRAY_LVALUE_VALUE_OPERATION_ISSET
    ) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!("array lvalue value-operation family tag {family} is not supported"),
        );
    }

    match owner.tag {
        NATIVE_ARRAY_LVALUE_OWNER_ARRAY => {
            let Some(array) = (unsafe { owner.array.as_mut() }) else {
                return NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_ROOT,
                    "array lvalue root is not a live native array handle",
                );
            };
            unsafe {
                native_array_lvalue_owner_array_value_operation_result(
                    &mut array.value,
                    segments,
                    segment_count,
                    family,
                    _operation,
                    _op,
                    _position,
                    value,
                )
            }
        }
        NATIVE_ARRAY_LVALUE_OWNER_REFERENCE_SLOT => unsafe {
            native_array_lvalue_owner_reference_slot_value_operation_result(
                owner.reference,
                segments,
                segment_count,
                family,
                _operation,
                _op,
                _position,
                value,
            )
        },
        _ => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            format!("array lvalue owner tag {} is not supported", owner.tag),
        ),
    }
}

unsafe fn native_array_lvalue_owner_array_value_operation_result(
    array: &mut PhpArray,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    family: u8,
    operation: u8,
    op: u8,
    position: u8,
    value: NativeValueHandle,
) -> NativeArrayLvalueResult {
    match family {
        NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE => {
            let path =
                match unsafe { native_array_lvalue_path_from_segments(segments, segment_count) } {
                    Ok(path) => path,
                    Err(result) => return result,
                };
            let value = match unsafe { native_array_lvalue_clone_write_value(value) } {
                Ok(value) => value,
                Err(result) => return result,
            };
            match native_array_write_lvalue_path(array, &path, value) {
                Ok(()) => NativeArrayLvalueResult::ok(),
                Err(result) => result,
            }
        }
        NATIVE_ARRAY_LVALUE_VALUE_OPERATION_READ => {
            let keys = match unsafe {
                native_array_lvalue_key_path_from_segments(segments, segment_count, "read")
            } {
                Ok(keys) => keys,
                Err(result) => return result,
            };
            match native_array_read_key_path(array, &keys) {
                Ok(value) => NativeArrayLvalueResult::value(value),
                Err(result) => result,
            }
        }
        NATIVE_ARRAY_LVALUE_VALUE_OPERATION_ISSET => {
            let keys = match unsafe {
                native_array_lvalue_key_path_from_segments(segments, segment_count, "isset")
            } {
                Ok(keys) => keys,
                Err(result) => return result,
            };
            match native_array_lvalue_isset_key_path(array, &keys) {
                Ok(present) => NativeArrayLvalueResult::value(Value::Bool(present)),
                Err(result) => result,
            }
        }
        NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET => {
            let keys = match unsafe {
                native_array_lvalue_key_path_from_segments(segments, segment_count, "unset")
            } {
                Ok(keys) => keys,
                Err(result) => return result,
            };
            native_array_unset_key_path(array, &keys);
            NativeArrayLvalueResult::ok()
        }
        NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE => {
            if operation != NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT {
                return NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                    format!("array lvalue update operation tag {operation} is not supported"),
                );
            }
            let path =
                match unsafe { native_array_lvalue_path_from_segments(segments, segment_count) } {
                    Ok(path) => path,
                    Err(result) => return result,
                };
            match native_array_increment_decrement_lvalue_path(array, &path, op, position) {
                Ok(value) => NativeArrayLvalueResult::value(value),
                Err(result) => return result,
            }
        }
        _ => unreachable!("array lvalue value-operation family was validated above"),
    }
}

unsafe fn native_array_lvalue_owner_reference_slot_value_operation_result(
    reference: NativeReferenceHandle,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    family: u8,
    operation: u8,
    op: u8,
    position: u8,
    value: NativeValueHandle,
) -> NativeArrayLvalueResult {
    let Some(reference) = (unsafe { reference.as_ref() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue reference owner is not a live native reference handle",
        );
    };

    let current = reference.cell.value_cloned();
    let mut array = match current {
        Value::Array(array) => array,
        Value::Null | Value::Bool(false)
            if matches!(
                family,
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE
                    | NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE
            ) =>
        {
            PhpArray::new()
        }
        Value::Null | Value::Bool(false) if family == NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET => {
            let keys = match unsafe {
                native_array_lvalue_key_path_from_segments(segments, segment_count, "unset")
            } {
                Ok(keys) => keys,
                Err(result) => return result,
            };
            let _ = keys;
            return NativeArrayLvalueResult::ok();
        }
        Value::Null | Value::Bool(false) if family == NATIVE_ARRAY_LVALUE_VALUE_OPERATION_ISSET => {
            let keys = match unsafe {
                native_array_lvalue_key_path_from_segments(segments, segment_count, "isset")
            } {
                Ok(keys) => keys,
                Err(result) => return result,
            };
            let _ = keys;
            return NativeArrayLvalueResult::value(Value::Bool(false));
        }
        other => {
            return NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_ROOT,
                format!(
                    "array lvalue reference owner contains {} and requires the shared scalar-to-array owner boundary",
                    other.type_name()
                ),
            )
        }
    };

    let result = unsafe {
        native_array_lvalue_owner_array_value_operation_result(
            &mut array,
            segments,
            segment_count,
            family,
            operation,
            op,
            position,
            value,
        )
    };

    if matches!(
        family,
        NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE
            | NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET
            | NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE
    ) && result.tag == NATIVE_ARRAY_LVALUE_OK
    {
        reference.cell.set_value(Value::Array(array));
    }

    result
}

/// # Safety
///
/// The owner and each key handle inside `segments` must be null or handles
/// previously returned by the runtime ABI and not yet freed. `segments` must be
/// null when `segment_count` is zero, or point to `segment_count` initialized
/// key-only path segments. The returned result owns any value/diagnostic
/// handles it carries.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_pointer_result(
    mut owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    operation: u8,
) -> NativeArrayLvalueResult {
    let operation = match NativeArrayPointerOperation::from_tag(operation) {
        Ok(operation) => operation,
        Err(result) => return result,
    };

    if owner.tag != NATIVE_ARRAY_LVALUE_OWNER_ARRAY {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue pointer owner is not a native array handle",
        );
    }

    let Some(array) = (unsafe { owner.array.as_mut() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue pointer root is not a live native array handle",
        );
    };
    let path = if segment_count == 0 {
        Vec::new()
    } else {
        match unsafe {
            native_array_lvalue_key_path_from_segments(segments, segment_count, operation.label())
        } {
            Ok(path) => path,
            Err(result) => return result,
        }
    };

    native_array_pointer_array_path_result(&mut array.value, &path, operation)
}

/// # Safety
///
/// The owner, operand handles, and each key handle inside `segments` must be
/// null or handles previously returned by the runtime ABI and not yet freed.
/// `segments` must be null when `segment_count` is zero, or point to
/// `segment_count` initialized key-only path segments. Operand handles are
/// borrowed; the returned result owns any value/diagnostic handles it carries.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_sort_result(
    mut owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    operation: u8,
    operands: *const NativeValueHandle,
    operand_count: usize,
) -> NativeArrayLvalueResult {
    let operation = match NativeArraySortOperation::from_tag(operation) {
        Ok(operation) => operation,
        Err(result) => return result,
    };

    if operand_count > 0 && operands.is_null() {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native array {}() sort operand array is null for {operand_count} operands",
                operation.label()
            ),
        );
    }

    if !operation.operand_count_is_supported(operand_count) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native array {}() sort blocker received unsupported operand count {operand_count}",
                operation.label()
            ),
        );
    }

    let mode =
        match unsafe { native_array_sort_mode_from_operands(operation, operands, operand_count) } {
            Ok(mode) => mode,
            Err(result) => return result,
        };

    if owner.tag != NATIVE_ARRAY_LVALUE_OWNER_ARRAY {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue sort owner is not a native array handle",
        );
    }

    let Some(array) = (unsafe { owner.array.as_mut() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue sort root is not a live native array handle",
        );
    };

    let path =
        match unsafe { native_array_lvalue_optional_path_from_segments(segments, segment_count) } {
            Ok(path) => path,
            Err(result) => return result,
        };

    native_array_sort_array_path_result(
        &mut array.value,
        &path,
        operation,
        NativeArraySortCriteria::Mode(mode),
    )
}

/// # Safety
///
/// The owner, callable handle, and each key handle inside `segments` must be
/// null or handles previously returned by the runtime ABI and not yet freed.
/// `segments` must be null when `segment_count` is zero, or point to
/// `segment_count` initialized key-only path segments. The callable handle is
/// borrowed; the returned result owns any value/diagnostic handles it carries.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_callable_sort_result(
    mut owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    operation: u8,
    callable: NativeCallableValueHandle,
) -> NativeArrayLvalueResult {
    let operation = match NativeArraySortOperation::from_tag(operation) {
        Ok(operation) => operation,
        Err(result) => return result,
    };

    if !operation.uses_comparator_sort() {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native array {}() callable sort ABI received a non-comparator operation",
                operation.label()
            ),
        );
    }

    let Some(dispatch) = (unsafe { callable.as_ref() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native array {}() comparator callback dispatch handle is null",
                operation.label()
            ),
        );
    };

    if owner.tag != NATIVE_ARRAY_LVALUE_OWNER_ARRAY {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue sort owner is not a native array handle",
        );
    }

    let Some(array) = (unsafe { owner.array.as_mut() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue sort root is not a live native array handle",
        );
    };

    let path =
        match unsafe { native_array_lvalue_optional_path_from_segments(segments, segment_count) } {
            Ok(path) => path,
            Err(result) => return result,
        };

    let mut diagnostic = NativeDiagnosticHandle::null();
    native_array_sort_array_path_result(
        &mut array.value,
        &path,
        operation,
        NativeArraySortCriteria::Comparator {
            dispatch,
            diagnostic: &mut diagnostic,
        },
    )
}

/// # Safety
///
/// The owner, operand handles, and each key handle inside `segments` must be
/// null or handles previously returned by the runtime ABI and not yet freed.
/// `segments` must be null when `segment_count` is zero, or point to
/// `segment_count` initialized key-only path segments. Operand handles are
/// borrowed; the returned result owns any value/diagnostic handles it carries.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_array_mutation_result(
    mut owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    operation: u8,
    operands: *const NativeValueHandle,
    operand_count: usize,
) -> NativeArrayLvalueResult {
    let operation = match NativeArrayMutationOperation::from_tag(operation) {
        Ok(operation) => operation,
        Err(result) => return result,
    };

    if operand_count > 0 && operands.is_null() {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native array {}() mutation operand array is null for {operand_count} operands",
                operation.label()
            ),
        );
    }

    if !operation.operand_count_is_supported(operand_count) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native array {}() mutation ABI received unsupported operand count {operand_count}",
                operation.label()
            ),
        );
    }

    let operands = match unsafe { native_array_mutation_operands(operands, operand_count) } {
        Ok(operands) => operands,
        Err(result) => return result,
    };

    if owner.tag != NATIVE_ARRAY_LVALUE_OWNER_ARRAY {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue mutation owner is not a native array handle",
        );
    }

    let Some(array) = (unsafe { owner.array.as_mut() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue mutation root is not a live native array handle",
        );
    };

    let path =
        match unsafe { native_array_lvalue_optional_path_from_segments(segments, segment_count) } {
            Ok(path) => path,
            Err(result) => return result,
        };

    native_array_mutation_array_path_result(&mut array.value, &path, operation, &operands)
}

/// # Safety
///
/// `handle` and `operand` must be null or value handles previously returned by
/// the runtime ABI and not yet freed. The returned value handle owns the PHP
/// value produced by the selected query operation. On failure the helper stores
/// a diagnostic handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_query_operation_with_diagnostic(
    handle: NativeValueHandle,
    operand: NativeValueHandle,
    flags: u8,
    operation: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let result =
        unsafe { native_value_array_query_operation_value(handle, operand, flags, operation) };
    match result {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
            }
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `handle` and each entry in `operands` must be null or value handles
/// previously returned by the runtime ABI and not yet freed. `operands` must
/// point to `operand_count` initialized handles when `operand_count` is
/// nonzero. The returned value handle owns the PHP value produced by the
/// selected query operation. On failure the helper stores a diagnostic handle
/// that the caller owns and must release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_query_operation_with_operands_and_diagnostic(
    handle: NativeValueHandle,
    operands: *const NativeValueHandle,
    operand_count: usize,
    flags: u8,
    operation: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    if operand_count > 0 && operands.is_null() {
        let error = RuntimeError::invalid_array_access(format!(
            "native value array query operation failed: operand array is null for {operand_count} operands"
        ));
        if !diagnostic.is_null() {
            unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
        }
        return NativeValueHandle::null();
    }

    let operands = if operand_count == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(operands, operand_count) }
    };

    let result = unsafe {
        native_value_array_query_operands_operation_value(handle, operands, flags, operation)
    };
    match result {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
            }
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `key` and `handle` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. On failure the helper stores a diagnostic
/// handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_key_exists_value_with_diagnostic(
    key: NativeValueHandle,
    handle: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let result = unsafe { native_value_array_key_exists_value_with_diagnostic(key, handle) };
    match result {
        Ok(value) => value,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
///
/// `key` must be null or a value handle previously returned by the runtime ABI
/// and not yet freed. `reference` must be null or a reference handle
/// previously returned by the runtime ABI and not yet freed. On failure the
/// helper stores a diagnostic handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_reference_array_key_exists_value_with_diagnostic(
    key: NativeValueHandle,
    reference: NativeReferenceHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let result = unsafe { native_reference_array_key_exists_value_with_diagnostic(key, reference) };
    match result {
        Ok(value) => value,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
///
/// `values` must be null when `value_count` is zero, or point to
/// `value_count` initialized handles previously returned by the runtime ABI
/// and not yet freed. Operand handles are borrowed; the returned result owns
/// any value/diagnostic handles it carries.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_callback_result(
    operation: u8,
    values: *const NativeValueHandle,
    value_count: usize,
) -> NativeArrayLvalueResult {
    let operation = match NativeValueArrayCallbackOperation::from_tag(operation) {
        Ok(operation) => operation,
        Err(result) => return result,
    };

    if value_count > 0 && values.is_null() {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native value {}() callback operand array is null for {value_count} operands",
                operation.label()
            ),
        );
    }

    if !operation.operand_count_is_supported(value_count) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native value {}() callback blocker received unsupported operand count {value_count}",
                operation.label()
            ),
        );
    }

    let values = unsafe { std::slice::from_raw_parts(values, value_count) };
    match operation {
        NativeValueArrayCallbackOperation::Filter => native_value_array_filter_result(values),
        NativeValueArrayCallbackOperation::Map => native_value_array_map_result(values),
        NativeValueArrayCallbackOperation::Reduce => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            native_value_array_callback_blocker("array_reduce()"),
        ),
    }
}

unsafe fn native_value_array_query_operation_value(
    handle: NativeValueHandle,
    operand: NativeValueHandle,
    flags: u8,
    operation: u8,
) -> RuntimeResult<Value> {
    if operand.is_null() {
        unsafe { native_value_array_query_operands_operation_value(handle, &[], flags, operation) }
    } else {
        unsafe {
            native_value_array_query_operands_operation_value(
                handle,
                std::slice::from_ref(&operand),
                flags,
                operation,
            )
        }
    }
}

unsafe fn native_value_array_key_exists_value_with_diagnostic(
    key: NativeValueHandle,
    handle: NativeValueHandle,
) -> RuntimeResult<bool> {
    let key = unsafe { key.as_ref() }.ok_or_else(|| {
        RuntimeError::invalid_array_access(
            "native array_key_exists() failed: key value handle is null",
        )
    })?;
    let key = ArrayKey::from_array_key_exists_value(key)?;
    let owner = unsafe { handle.as_ref() }.ok_or_else(|| {
        RuntimeError::invalid_array_access(
            "native array_key_exists() failed: array value handle is null",
        )
    })?;
    native_value_array_key_exists_value_ref_with_diagnostic(&key, owner)
}

unsafe fn native_reference_array_key_exists_value_with_diagnostic(
    key: NativeValueHandle,
    reference: NativeReferenceHandle,
) -> RuntimeResult<bool> {
    let key = unsafe { key.as_ref() }.ok_or_else(|| {
        RuntimeError::invalid_array_access(
            "native array_key_exists() failed: key value handle is null",
        )
    })?;
    let key = ArrayKey::from_array_key_exists_value(key)?;
    let reference = unsafe { reference.as_ref() }.ok_or_else(|| {
        RuntimeError::invalid_array_access(
            "native array_key_exists() failed: array reference handle is null",
        )
    })?;
    let owner = reference.cell.value_cloned();
    native_value_array_key_exists_value_ref_with_diagnostic(&key, &owner)
}

fn native_value_array_key_exists_value_ref_with_diagnostic(
    key: &ArrayKey,
    owner: &Value,
) -> RuntimeResult<bool> {
    match owner {
        Value::Array(array) => Ok(array.contains_key(key.clone())),
        other => Err(RuntimeError::unsupported_call(
            "array_key_exists()",
            format!("second argument must be array, got {}", other.type_name()),
        )),
    }
}

unsafe fn native_value_array_query_operands_operation_value(
    handle: NativeValueHandle,
    operands: &[NativeValueHandle],
    flags: u8,
    operation: u8,
) -> RuntimeResult<Value> {
    if flags & !NATIVE_ARRAY_QUERY_STRICT != 0 {
        return Err(RuntimeError::invalid_array_access(
            "native value array query operation failed: unsupported operation flags",
        ));
    }

    let operation = NativeValueArrayQueryOperation::from_tag(operation)?;
    if !operation.accepts_flags() && flags != 0 {
        return Err(RuntimeError::invalid_array_access(format!(
            "native value array query operation failed: {} does not accept operation flags",
            operation.callable()
        )));
    }

    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(format!(
            "native value array query operation failed: {} array value handle is null",
            operation.callable()
        )));
    };
    let Value::Array(array) = value else {
        return Err(RuntimeError::unsupported_call(
            operation.callable(),
            format!(
                "{} must be array, got {}",
                operation.array_argument_label(),
                value.type_name()
            ),
        ));
    };

    let strict = flags & NATIVE_ARRAY_QUERY_STRICT != 0;
    if operands.len() < operation.min_operand_count() {
        return Err(RuntimeError::invalid_array_access(format!(
            "native value array query operation failed: {} operand value handle is null",
            operation.callable()
        )));
    }
    if operands.len() > operation.max_operand_count() {
        return Err(RuntimeError::invalid_array_access(format!(
            "native value array query operation failed: {} received unsupported operand count {}",
            operation.callable(),
            operands.len()
        )));
    }

    match operation {
        NativeValueArrayQueryOperation::Count => Ok(Value::Int(array.len() as i64)),
        NativeValueArrayQueryOperation::KeysMatching => {
            let search = unsafe { native_value_array_query_operand(operation, operands, 0)? };
            let keys = if strict {
                array.keys_matching_strict_scalar(search)?
            } else {
                array.keys_matching_loose_scalar(search)?
            };
            Ok(Value::Array(keys))
        }
        NativeValueArrayQueryOperation::Contains => {
            let needle = unsafe { native_value_array_query_operand(operation, operands, 0)? };
            let contains = if strict {
                array.contains_value_strict_scalar(needle)?
            } else {
                array.contains_value_loose_scalar(needle)?
            };
            Ok(Value::Bool(contains))
        }
        NativeValueArrayQueryOperation::Search => {
            let needle = unsafe { native_value_array_query_operand(operation, operands, 0)? };
            let key = if strict {
                array.search_value_strict_scalar(needle)?
            } else {
                array.search_value_loose_scalar(needle)?
            };
            Ok(key
                .as_ref()
                .map(array_key_to_value)
                .unwrap_or(Value::Bool(false)))
        }
        NativeValueArrayQueryOperation::Flip => Ok(Value::Array(array.flipped()?)),
        NativeValueArrayQueryOperation::CountValues => Ok(Value::Array(array.count_values()?)),
        NativeValueArrayQueryOperation::Sum => array.sum_values(),
        NativeValueArrayQueryOperation::Product => array.product_values(),
        NativeValueArrayQueryOperation::FillKeys => {
            let fill = unsafe { native_value_array_query_operand(operation, operands, 0)? };
            Ok(Value::Array(array.filled_keys(fill.clone())?))
        }
        NativeValueArrayQueryOperation::Combine => {
            let values = unsafe { native_value_array_query_operand(operation, operands, 0)? };
            let Value::Array(values) = values else {
                return Err(RuntimeError::unsupported_call(
                    "array_combine()",
                    format!("second argument must be array, got {}", values.type_name()),
                ));
            };
            Ok(Value::Array(array.combined_with(values)?))
        }
        NativeValueArrayQueryOperation::ChangeKeyCase => {
            let case = match operands.first() {
                Some(handle) => match unsafe { handle.as_ref() } {
                    Some(Value::Int(case)) => ArrayKeyCase::from_flag(*case),
                    Some(other) => {
                        return Err(RuntimeError::unsupported_call(
                            "array_change_key_case()",
                            format!(
                                "case flag must be int in the current subset, got {}",
                                other.type_name()
                            ),
                        ))
                    }
                    None => {
                        return Err(RuntimeError::invalid_array_access(
                            "native value array query operation failed: array_change_key_case() operand value handle is null",
                        ))
                    }
                },
                None => ArrayKeyCase::Lower,
            };
            Ok(Value::Array(array.keys_with_ascii_case(case)))
        }
        NativeValueArrayQueryOperation::Column => {
            let column_key = ArrayColumnKey::from_value(unsafe {
                native_value_array_query_operand(operation, operands, 0)?
            })?;
            let index_key = if operands.len() > 1 {
                ArrayColumnKey::index_from_value(unsafe {
                    native_value_array_query_operand(operation, operands, 1)?
                })?
            } else {
                None
            };
            Ok(Value::Array(array.column_values(column_key, index_key)?))
        }
    }
}

unsafe fn native_value_array_query_operand<'a>(
    operation: NativeValueArrayQueryOperation,
    operands: &'a [NativeValueHandle],
    index: usize,
) -> RuntimeResult<&'a Value> {
    let Some(handle) = operands.get(index) else {
        return Err(RuntimeError::invalid_array_access(format!(
            "native value array query operation failed: {} operand value handle is null",
            operation.callable()
        )));
    };
    unsafe { handle.as_ref() }.ok_or_else(|| {
        RuntimeError::invalid_array_access(format!(
            "native value array query operation failed: {} operand value handle is null",
            operation.callable()
        ))
    })
}

fn native_value_array_filter_result(values: &[NativeValueHandle]) -> NativeArrayLvalueResult {
    let null_value = Value::Null;
    let array_value = unsafe { values[0].as_ref() }.unwrap_or(&null_value);
    let Value::Array(array) = array_value else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "unsupported call array_filter(): first argument must be array, got {}",
                array_value.type_name()
            ),
        );
    };

    let callback = unsafe { values[1].as_ref() }.unwrap_or(&null_value);
    if !matches!(callback, Value::Null) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            native_value_array_callback_blocker("array_filter()"),
        );
    }

    if let Some(mode) = values.get(2) {
        let mode = unsafe { mode.as_ref() }.unwrap_or(&null_value);
        if let Err(message) =
            native_value_array_callback_integer_parameter("array_filter()", "mode parameter", mode)
        {
            return NativeArrayLvalueResult::diagnostic(NATIVE_ARRAY_LVALUE_UNSUPPORTED, message);
        }
    }

    NativeArrayLvalueResult::value(Value::Array(array.filtered_without_callback()))
}

fn native_value_array_map_result(values: &[NativeValueHandle]) -> NativeArrayLvalueResult {
    let null_value = Value::Null;
    let callback = unsafe { values[0].as_ref() }.unwrap_or(&null_value);
    if !matches!(callback, Value::Null) {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            native_value_array_callback_blocker("array_map()"),
        );
    }

    let mut arrays = Vec::with_capacity(values.len().saturating_sub(1));
    for (index, handle) in values.iter().enumerate().skip(1) {
        let value = unsafe { handle.as_ref() }.unwrap_or(&null_value);
        let Value::Array(array) = value else {
            return NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                format!(
                    "unsupported call array_map(): {} must be array, got {}",
                    native_value_array_variadic_argument_label(index),
                    value.type_name()
                ),
            );
        };
        arrays.push(array);
    }

    NativeArrayLvalueResult::value(Value::Array(PhpArray::map_null_callback(&arrays)))
}

fn native_value_array_callback_integer_parameter(
    callable: &'static str,
    parameter: &'static str,
    value: &Value,
) -> Result<i64, String> {
    match value {
        Value::Null => Ok(0),
        Value::Bool(value) => Ok(i64::from(*value)),
        Value::Int(value) => Ok(*value),
        Value::Float(value) => native_value_float_to_int(*value, callable)
            .map_err(|error| error.message().to_string()),
        Value::String(value) => {
            let Some(number) = parse_numeric_string(value) else {
                return Err(format!("native value {callable} {parameter} string is not numeric"));
            };
            match number {
                Number::Int(value) => Ok(value),
                Number::Float(value) => native_value_float_to_int(value, callable)
                    .map_err(|error| error.message().to_string()),
            }
        }
        Value::BinaryString(value) => {
            let Some(number) = parse_numeric_string_bytes(value) else {
                return Err(format!("native value {callable} {parameter} string is not numeric"));
            };
            match number {
                Number::Int(value) => Ok(value),
                Number::Float(value) => native_value_float_to_int(value, callable)
                    .map_err(|error| error.message().to_string()),
            }
        }
        Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => Err(
            format!(
                "native value {callable} {parameter} rejects {} until shared internal-parameter integer coercion can model arrays, objects, resources, references/copy-on-write, cleanup ownership, and exact diagnostics",
                value.type_name()
            ),
        ),
    }
}

fn native_value_array_callback_blocker(callable: &'static str) -> String {
    format!(
        "native value {callable} callback/mode forms need one callback ABI covering callable materialization, value/key mode routing, by-reference effects, cleanup ownership, and exact PHP diagnostics"
    )
}

fn native_value_array_variadic_argument_label(index: usize) -> String {
    match index {
        0 => "first argument".to_string(),
        1 => "second argument".to_string(),
        2 => "third argument".to_string(),
        _ => format!("argument {}", index + 1),
    }
}

/// # Safety
///
/// The owner and each key handle inside `segments` must be null or handles
/// previously returned by the runtime ABI and not yet freed. `segments` must be
/// null when `segment_count` is zero, or point to `segment_count` initialized
/// path segments. The returned value is an owned by-value array snapshot for
/// foreach iteration.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_foreach_iterable_result(
    owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
) -> NativeArrayLvalueResult {
    let path =
        match unsafe { native_array_lvalue_optional_path_from_segments(segments, segment_count) } {
            Ok(path) => path,
            Err(result) => return result,
        };

    match owner.tag {
        NATIVE_ARRAY_LVALUE_OWNER_ARRAY => {
            let Some(array) = (unsafe { owner.array.as_ref() }) else {
                return NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_ROOT,
                    "array foreach iterable root is not a live native array handle",
                );
            };

            native_array_foreach_iterable_path_result(&array.value, &path)
        }
        NATIVE_ARRAY_LVALUE_OWNER_REFERENCE_SLOT => {
            let Some(reference) = (unsafe { owner.reference.as_ref() }) else {
                return NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_ROOT,
                    "array foreach iterable reference owner is not a live native reference handle",
                );
            };

            match reference.cell.value_cloned() {
                Value::Array(array) => native_array_foreach_iterable_path_result(&array, &path),
                value => native_value_foreach_iterable_value_result(value),
            }
        }
        _ => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            format!(
                "array foreach iterable owner tag {} is not supported",
                owner.tag
            ),
        ),
    }
}

/// # Safety
///
/// `iterable` must be null or a value handle returned by the runtime ABI and
/// not yet freed. Non-array and null handles have length zero so generated C can
/// route diagnostics through the iterable result boundary before looping.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_foreach_iterable_len(
    iterable: NativeValueHandle,
) -> usize {
    match unsafe { iterable.as_ref() } {
        Some(Value::Array(array)) => array.len(),
        _ => 0,
    }
}

/// # Safety
///
/// `iterable` must be a live value handle carrying an array snapshot returned by
/// `phpc_native_array_lvalue_owner_foreach_iterable_result`. The returned result
/// owns a clone of the PHP key for `index`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_foreach_iterable_key_result(
    iterable: NativeValueHandle,
    index: usize,
) -> NativeArrayLvalueResult {
    let Some(Value::Array(array)) = (unsafe { iterable.as_ref() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array foreach key read received a non-array iterable handle",
        );
    };
    let Some(entry) = array.entries().get(index) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            format!("array foreach key index {index} is out of range"),
        );
    };

    NativeArrayLvalueResult::value(array_key_to_value(&entry.key))
}

/// # Safety
///
/// `iterable` must be a live value handle carrying an array snapshot returned by
/// `phpc_native_array_lvalue_owner_foreach_iterable_result`. The returned result
/// owns a clone of the PHP value for `index`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_foreach_iterable_value_result(
    iterable: NativeValueHandle,
    index: usize,
) -> NativeArrayLvalueResult {
    let Some(Value::Array(array)) = (unsafe { iterable.as_ref() }) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array foreach value read received a non-array iterable handle",
        );
    };
    let Some(entry) = array.entries().get(index) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            format!("array foreach value index {index} is out of range"),
        );
    };

    NativeArrayLvalueResult::value(entry.value_cloned())
}

/// # Safety
///
/// `owner`, every value in `segments`, and `key` must be null or handles
/// returned by the runtime ABI and not yet freed. `segments` must be null when
/// `segment_count` is zero, or point to `segment_count` initialized key-only
/// path segments. The returned reference aliases the live array slot selected
/// by the foreach iterable path plus the current snapshot key.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_owner_foreach_value_reference_result(
    mut owner: NativeArrayLvalueOwner,
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    key: NativeValueHandle,
) -> NativeArrayLvalueReferenceResult {
    let mut keys = if segment_count == 0 {
        Vec::new()
    } else {
        match unsafe {
            native_array_lvalue_key_path_from_segments(segments, segment_count, "foreach reference")
        } {
            Ok(keys) => keys,
            Err(result) => return NativeArrayLvalueReferenceResult::from_lvalue_result(result),
        }
    };
    let Some(key_value) = (unsafe { key.as_ref() }) else {
        return NativeArrayLvalueReferenceResult::diagnostic(
            "array foreach reference key handle is null",
        );
    };
    let key = match native_array_key_from_runtime_value(key_value) {
        Ok(key) => key,
        Err(error) => return NativeArrayLvalueReferenceResult::diagnostic(error.message()),
    };
    keys.push(key);

    match owner.tag {
        NATIVE_ARRAY_LVALUE_OWNER_ARRAY => {
            let Some(array) = (unsafe { owner.array.as_mut() }) else {
                return NativeArrayLvalueReferenceResult::diagnostic(
                    "array foreach reference root is not a live native array handle",
                );
            };
            match array.value.reference_path(&keys) {
                Ok(reference) => NativeArrayLvalueReferenceResult::reference(reference),
                Err(error) => NativeArrayLvalueReferenceResult::diagnostic(error.message()),
            }
        }
        NATIVE_ARRAY_LVALUE_OWNER_REFERENCE_SLOT => {
            let Some(reference) = (unsafe { owner.reference.as_ref() }) else {
                return NativeArrayLvalueReferenceResult::diagnostic(
                    "array foreach reference owner is not a live native reference handle",
                );
            };
            let mut array = match reference.cell.value_cloned() {
                Value::Array(array) => array,
                other => {
                    return NativeArrayLvalueReferenceResult::diagnostic(format!(
                        "array foreach reference owner contains {}",
                        other.type_name()
                    ))
                }
            };
            match array.reference_path(&keys) {
                Ok(slot_reference) => {
                    reference.cell.set_value(Value::Array(array));
                    NativeArrayLvalueReferenceResult::reference(slot_reference)
                }
                Err(error) => NativeArrayLvalueReferenceResult::diagnostic(error.message()),
            }
        }
        _ => NativeArrayLvalueReferenceResult::diagnostic(format!(
            "array foreach reference owner tag {} is not supported",
            owner.tag
        )),
    }
}

#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_result_free(result: NativeArrayLvalueResult) {
    unsafe { phpc_native_value_free(result.value) };
    unsafe { phpc_native_diagnostic_free(result.diagnostic) };
}

#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_lvalue_reference_result_free(
    result: NativeArrayLvalueReferenceResult,
) {
    unsafe { phpc_native_reference_free(result.reference) };
    unsafe { phpc_native_diagnostic_free(result.diagnostic) };
}

unsafe fn native_array_lvalue_optional_path_from_segments(
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
) -> Result<Vec<NativeArrayLvaluePathElement>, NativeArrayLvalueResult> {
    if segment_count == 0 {
        return Ok(Vec::new());
    }

    unsafe { native_array_lvalue_path_from_segments(segments, segment_count) }
}

unsafe fn native_array_lvalue_key_path_from_segments(
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
    operation: &str,
) -> Result<Vec<ArrayKey>, NativeArrayLvalueResult> {
    let path = unsafe { native_array_lvalue_path_from_segments(segments, segment_count) }?;
    path.into_iter()
        .map(|segment| match segment {
            NativeArrayLvaluePathElement::Key(key) => Ok(key),
            NativeArrayLvaluePathElement::Append => Err(NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_KEY,
                format!("array lvalue {operation} path cannot contain an append segment"),
            )),
        })
        .collect()
}

unsafe fn native_array_lvalue_path_from_segments(
    segments: *const NativeArrayPathSegment,
    segment_count: usize,
) -> Result<Vec<NativeArrayLvaluePathElement>, NativeArrayLvalueResult> {
    if segment_count == 0 {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue path must contain at least one key segment",
        ));
    }
    if segments.is_null() {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue path pointer is null with nonzero length",
        ));
    }

    let segments = unsafe { std::slice::from_raw_parts(segments, segment_count) };
    let mut path = Vec::with_capacity(segment_count);
    for segment in segments {
        match segment.tag {
            NATIVE_ARRAY_PATH_KEY => {
                let Some(value) = (unsafe { segment.key.as_ref() }) else {
                    return Err(NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_INVALID_KEY,
                        "array lvalue key segment has a null value handle",
                    ));
                };
                let key = native_array_key_from_runtime_value(value).map_err(|error| {
                    NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_INVALID_KEY,
                        error.message(),
                    )
                })?;
                path.push(NativeArrayLvaluePathElement::Key(key));
            }
            NATIVE_ARRAY_PATH_APPEND => path.push(NativeArrayLvaluePathElement::Append),
            _ => {
                return Err(NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_KEY,
                    format!(
                        "array lvalue path segment tag {} is not supported",
                        segment.tag
                    ),
                ))
            }
        }
    }
    Ok(path)
}

unsafe fn native_array_lvalue_clone_write_value(
    handle: NativeValueHandle,
) -> Result<Value, NativeArrayLvalueResult> {
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue write failed: value handle is null",
        ));
    };

    Ok(value.clone())
}

fn native_array_write_lvalue_path(
    array: &mut PhpArray,
    path: &[NativeArrayLvaluePathElement],
    value: Value,
) -> Result<(), NativeArrayLvalueResult> {
    let Some((segment, rest)) = path.split_first() else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue write path must contain at least one path segment",
        ));
    };

    match segment {
        NativeArrayLvaluePathElement::Key(key) => {
            if rest.is_empty() {
                array.insert(key.clone(), value);
                return Ok(());
            }

            let mut child = match array.get_cloned(key.clone()) {
                Some(Value::Array(child)) => child,
                Some(Value::Null) | None => PhpArray::new(),
                Some(other) => {
                    return Err(NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_INVALID_ROOT,
                        format!(
                            "array lvalue nested write failed: {} intermediate at key {} requires the shared scalar-to-array warning/recovery boundary",
                            other.type_name(),
                            key.diagnostic_key()
                        ),
                    ));
                }
            };

            native_array_write_lvalue_path(&mut child, rest, value)?;
            array.insert(key.clone(), Value::Array(child));
            Ok(())
        }
        NativeArrayLvaluePathElement::Append => {
            if rest.is_empty() {
                return array.append(value).map(|_| ()).map_err(|error| {
                    NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_INVALID_KEY,
                        error.message(),
                    )
                });
            }

            let mut child = PhpArray::new();
            native_array_write_lvalue_path(&mut child, rest, value)?;
            array
                .append(Value::Array(child))
                .map(|_| ())
                .map_err(|error| {
                    NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_INVALID_KEY,
                        error.message(),
                    )
                })
        }
    }
}

fn native_array_unset_key_path(array: &mut PhpArray, keys: &[ArrayKey]) -> bool {
    let Some((key, rest)) = keys.split_first() else {
        return false;
    };

    if rest.is_empty() {
        array.remove(key.clone());
        return true;
    }

    let Some(Value::Array(mut child)) = array.get_cloned(key.clone()) else {
        return true;
    };
    let removed = native_array_unset_key_path(&mut child, rest);
    array.insert(key.clone(), Value::Array(child));
    removed
}

fn native_array_lvalue_null_increment_decrement_value(
    op: u8,
) -> Result<Value, NativeArrayLvalueResult> {
    match op {
        NATIVE_ARRAY_LVALUE_INCREMENT => Ok(Value::Int(1)),
        NATIVE_ARRAY_LVALUE_DECREMENT => Ok(Value::Null),
        other => Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!("array lvalue increment/decrement operation tag {other} is not supported"),
        )),
    }
}

fn native_array_increment_decrement_lvalue_path(
    array: &mut PhpArray,
    path: &[NativeArrayLvaluePathElement],
    op: u8,
    position: u8,
) -> Result<Value, NativeArrayLvalueResult> {
    let Some((segment, rest)) = path.split_first() else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue increment/decrement path must contain at least one key segment",
        ));
    };

    if !matches!(
        op,
        NATIVE_ARRAY_LVALUE_INCREMENT | NATIVE_ARRAY_LVALUE_DECREMENT
    ) {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!("array lvalue increment/decrement operation tag {op} is not supported"),
        ));
    }
    if !matches!(
        position,
        NATIVE_ARRAY_LVALUE_POSITION_PRE | NATIVE_ARRAY_LVALUE_POSITION_POST
    ) {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!("array lvalue increment/decrement position tag {position} is not supported"),
        ));
    }

    match segment {
        NativeArrayLvaluePathElement::Key(key) if rest.is_empty() => {
            let Some(slot) = array.get_slot_mut(key.clone()) else {
                let previous = Value::Null;
                let updated = native_array_lvalue_null_increment_decrement_value(op)?;
                let expression_value = if position == NATIVE_ARRAY_LVALUE_POSITION_PRE {
                    updated.clone()
                } else {
                    previous
                };
                array.insert(key.clone(), updated);
                return Err(NativeArrayLvalueResult::value_with_diagnostic(
                    expression_value,
                    RuntimeError::undefined_array_key(key.diagnostic_key()).message(),
                ));
            };

            let previous = slot.value_cloned();
            let updated = native_array_lvalue_increment_decrement_value(&previous, op)?;
            let expression_value = if position == NATIVE_ARRAY_LVALUE_POSITION_PRE {
                updated.clone()
            } else {
                previous
            };
            slot.set_value(updated);
            Ok(expression_value)
        }
        NativeArrayLvaluePathElement::Key(key) => {
            let Some(Value::Array(mut child)) = array.get_cloned(key.clone()) else {
                return Err(NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_ROOT,
                    format!(
                        "array lvalue nested increment/decrement failed: missing or non-array intermediate at key {} requires the shared read-modify-write recovery boundary",
                        key.diagnostic_key()
                    ),
                ));
            };

            match native_array_increment_decrement_lvalue_path(&mut child, rest, op, position) {
                Ok(value) => {
                    array.insert(key.clone(), Value::Array(child));
                    Ok(value)
                }
                Err(result) if result.tag == NATIVE_ARRAY_LVALUE_OK => {
                    array.insert(key.clone(), Value::Array(child));
                    Err(result)
                }
                Err(result) => Err(result),
            }
        }
        NativeArrayLvaluePathElement::Append if rest.is_empty() => {
            let previous = Value::Null;
            let updated = native_array_lvalue_increment_decrement_value(&previous, op)?;
            let expression_value = if position == NATIVE_ARRAY_LVALUE_POSITION_PRE {
                updated.clone()
            } else {
                previous
            };
            array.append(updated).map_err(|error| {
                NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_INVALID_KEY,
                    error.message(),
                )
            })?;
            Ok(expression_value)
        }
        NativeArrayLvaluePathElement::Append => Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            "array lvalue nested append increment/decrement suffix awaits the shared missing-slot read-modify-write recovery boundary",
        )),
    }
}

fn native_array_lvalue_increment_decrement_value(
    current: &Value,
    op: u8,
) -> Result<Value, NativeArrayLvalueResult> {
    match (current, op) {
        (Value::Null, op) => native_array_lvalue_null_increment_decrement_value(op),
        (Value::Int(value), NATIVE_ARRAY_LVALUE_INCREMENT) => Ok(Value::Int(value.wrapping_add(1))),
        (Value::Int(value), NATIVE_ARRAY_LVALUE_DECREMENT) => Ok(Value::Int(value.wrapping_sub(1))),
        (Value::Float(value), NATIVE_ARRAY_LVALUE_INCREMENT) => Ok(Value::Float(value + 1.0)),
        (Value::Float(value), NATIVE_ARRAY_LVALUE_DECREMENT) => Ok(Value::Float(value - 1.0)),
        (_, other)
            if other != NATIVE_ARRAY_LVALUE_INCREMENT && other != NATIVE_ARRAY_LVALUE_DECREMENT =>
        {
            Err(NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                format!("array lvalue increment/decrement operation tag {other} is not supported"),
            ))
        }
        (other, _) => Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "array lvalue increment/decrement supports int and float slots in the current native boundary, got {}",
                other.type_name()
            ),
        )),
    }
}

fn native_value_increment_decrement_value(current: &Value, op: u8) -> Result<Value, String> {
    match (current, op) {
        (Value::Null, NATIVE_VALUE_INCREMENT) => Ok(Value::Int(1)),
        (Value::Null, NATIVE_VALUE_DECREMENT) => Ok(Value::Null),
        (Value::Int(value), NATIVE_VALUE_INCREMENT) => Ok(Value::Int(value.wrapping_add(1))),
        (Value::Int(value), NATIVE_VALUE_DECREMENT) => Ok(Value::Int(value.wrapping_sub(1))),
        (Value::Float(value), NATIVE_VALUE_INCREMENT) => Ok(Value::Float(value + 1.0)),
        (Value::Float(value), NATIVE_VALUE_DECREMENT) => Ok(Value::Float(value - 1.0)),
        (_, other) if other != NATIVE_VALUE_INCREMENT && other != NATIVE_VALUE_DECREMENT => {
            Err(format!(
                "native value increment/decrement operation tag {other} is not supported"
            ))
        }
        (other, _) => Err(format!(
            "native value increment/decrement supports int, float, and null values in the current native boundary, got {}",
            other.type_name()
        )),
    }
}

/// # Safety
///
/// `value` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Null handles are treated as PHP null. The result
/// carries the updated value or a diagnostic explaining the unsupported
/// semantic family.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_increment_decrement_result(
    value: NativeValueHandle,
    op: u8,
) -> NativeValueOperationResult {
    let null_value = Value::Null;
    let value = unsafe { value.as_ref() }.unwrap_or(&null_value);

    match native_value_increment_decrement_value(value, op) {
        Ok(value) => NativeValueOperationResult::value(value),
        Err(message) => NativeValueOperationResult::diagnostic(message),
    }
}

fn native_array_read_key_path(
    array: &PhpArray,
    keys: &[ArrayKey],
) -> Result<Value, NativeArrayLvalueResult> {
    let Some((key, rest)) = keys.split_first() else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue read path must contain at least one key segment",
        ));
    };

    let Some(value) = array.get_cloned(key.clone()) else {
        return Err(native_array_lvalue_missing_key_read_result(key, rest));
    };

    if rest.is_empty() {
        return Ok(value);
    }

    match value {
        Value::Array(child) => native_array_read_key_path(&child, rest),
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => Err(
            native_array_lvalue_scalar_read_recovery_result(&value, rest),
        ),
        other => Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            format!(
                "array lvalue nested read failed: {} intermediate at key {} requires the shared scalar read recovery boundary",
                other.type_name(),
                key.diagnostic_key()
            ),
        )),
    }
}

fn native_array_lvalue_isset_key_path(
    array: &PhpArray,
    keys: &[ArrayKey],
) -> Result<bool, NativeArrayLvalueResult> {
    let Some((key, rest)) = keys.split_first() else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array lvalue isset path must contain at least one key segment",
        ));
    };

    let Some(value) = array.get_cloned(key.clone()) else {
        return Ok(false);
    };

    if rest.is_empty() {
        return Ok(!matches!(value, Value::Null));
    }

    match value {
        Value::Array(child) => native_array_lvalue_isset_key_path(&child, rest),
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => Ok(false),
        Value::String(_) => Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "array lvalue nested isset failed: string intermediate at key {} requires the shared string-offset presence boundary",
                key.diagnostic_key()
            ),
        )),
        other => Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            format!(
                "array lvalue nested isset failed: {} intermediate at key {} requires a generalized offset presence boundary",
                other.type_name(),
                key.diagnostic_key()
            ),
        )),
    }
}

fn native_array_pointer_array_path_result(
    array: &mut PhpArray,
    path: &[ArrayKey],
    operation: NativeArrayPointerOperation,
) -> NativeArrayLvalueResult {
    let Some((key, rest)) = path.split_first() else {
        return native_array_pointer_array_result(array, operation);
    };

    let Some(mut value) = array.get_cloned(key.clone()) else {
        return NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            RuntimeError::undefined_array_key(key.diagnostic_key()).message(),
        );
    };
    let result = native_array_pointer_value_path_result(&mut value, rest, operation);
    if result.tag == NATIVE_ARRAY_LVALUE_OK && operation.mutates_owner() {
        array.insert(key.clone(), value);
    }
    result
}

fn native_array_pointer_value_path_result(
    value: &mut Value,
    path: &[ArrayKey],
    operation: NativeArrayPointerOperation,
) -> NativeArrayLvalueResult {
    if path.is_empty() {
        return match value {
            Value::Array(array) => native_array_pointer_array_result(array, operation),
            other => native_array_pointer_non_array_result(operation, other),
        };
    }

    match value {
        Value::Array(array) => native_array_pointer_array_path_result(array, path, operation),
        other => native_array_pointer_non_array_result(operation, other),
    }
}

fn native_array_pointer_array_result(
    array: &mut PhpArray,
    operation: NativeArrayPointerOperation,
) -> NativeArrayLvalueResult {
    match operation {
        NativeArrayPointerOperation::Current => {
            NativeArrayLvalueResult::value(array.current_value())
        }
        NativeArrayPointerOperation::Key => NativeArrayLvalueResult::value(array.key_value()),
        NativeArrayPointerOperation::Next => NativeArrayLvalueResult::value(array.next_value()),
        NativeArrayPointerOperation::Prev => NativeArrayLvalueResult::value(array.prev_value()),
        NativeArrayPointerOperation::Reset => NativeArrayLvalueResult::value(array.reset_value()),
        NativeArrayPointerOperation::End => NativeArrayLvalueResult::value(array.end_value()),
    }
}

fn native_array_pointer_non_array_result(
    operation: NativeArrayPointerOperation,
    value: &Value,
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_UNSUPPORTED,
        format!(
            "unsupported call {}(): argument must be array, got {}",
            operation.label(),
            value.type_name()
        ),
    )
}

unsafe fn native_array_sort_mode_from_operands(
    operation: NativeArraySortOperation,
    operands: *const NativeValueHandle,
    operand_count: usize,
) -> Result<Option<NativeArraySortMode>, NativeArrayLvalueResult> {
    if !operation.uses_mode_sort() {
        return Ok(None);
    }

    let Some(operand) = (operand_count > 0).then(|| unsafe { operands.add(0) }) else {
        return Ok(Some(NativeArraySortMode::Regular));
    };
    let Some(handle) = (unsafe { operand.as_ref() }) else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native array {}() sort flag parameter operand is unavailable",
                operation.label()
            ),
        ));
    };
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            format!(
                "native array {}() sort flag parameter materialization produced a null value handle",
                operation.label()
            ),
        ));
    };

    native_array_sort_mode_from_value(operation, value)
}

fn native_array_sort_mode_from_value(
    operation: NativeArraySortOperation,
    value: &Value,
) -> Result<Option<NativeArraySortMode>, NativeArrayLvalueResult> {
    let mode = native_array_sort_flag_integer(operation, value).map_err(|message| {
        NativeArrayLvalueResult::diagnostic(NATIVE_ARRAY_LVALUE_UNSUPPORTED, message)
    })?;
    let mode = match mode {
        0 => NativeArraySortMode::Regular,
        1 => NativeArraySortMode::Numeric,
        2 => NativeArraySortMode::String,
        other => {
            return Err(NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                format!(
                    "native array {}() sort flag parameter {other} is not supported; only SORT_REGULAR (0), SORT_NUMERIC (1), and SORT_STRING (2) are implemented",
                    operation.label()
                ),
            ));
        }
    };
    Ok(Some(mode))
}

fn native_array_sort_flag_integer(
    operation: NativeArraySortOperation,
    value: &Value,
) -> Result<i64, String> {
    match value {
        Value::Null => Ok(0),
        Value::Bool(value) => Ok(i64::from(*value)),
        Value::Int(value) => Ok(*value),
        Value::Float(value) => native_value_float_to_int(*value, operation.callable())
            .map_err(|error| error.message().to_string()),
        Value::String(value) => {
            let Some(number) = parse_numeric_string(value) else {
                return Err(format!(
                    "native array {}() sort flag parameter string is not numeric",
                    operation.label()
                ));
            };
            match number {
                Number::Int(value) => Ok(value),
                Number::Float(value) => native_value_float_to_int(value, operation.callable())
                    .map_err(|error| error.message().to_string()),
            }
        }
        Value::BinaryString(value) => {
            let Some(number) = parse_numeric_string_bytes(value) else {
                return Err(format!(
                    "native array {}() sort flag parameter string is not numeric",
                    operation.label()
                ));
            };
            match number {
                Number::Int(value) => Ok(value),
                Number::Float(value) => native_value_float_to_int(value, operation.callable())
                    .map_err(|error| error.message().to_string()),
            }
        }
        Value::Array(_) | Value::Object(_) | Value::Closure(_) | Value::Resource(_) => Err(
            format!(
                "native array {}() sort flag parameter rejects {} until shared internal-parameter integer coercion can model arrays, objects, resources, references/copy-on-write, cleanup ownership, and exact diagnostics",
                operation.label(),
                value.type_name()
            ),
        ),
    }
}

fn native_array_sort_array_path_result(
    array: &mut PhpArray,
    path: &[NativeArrayLvaluePathElement],
    operation: NativeArraySortOperation,
    criteria: NativeArraySortCriteria<'_>,
) -> NativeArrayLvalueResult {
    let Some((segment, rest)) = path.split_first() else {
        return native_array_sort_array_result(array, operation, criteria);
    };

    match segment {
        NativeArrayLvaluePathElement::Key(key) => {
            let Some(mut value) = array.get_cloned(key.clone()) else {
                return NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                    RuntimeError::undefined_array_key(key.diagnostic_key()).message(),
                );
            };
            let result = native_array_sort_value_path_result(&mut value, rest, operation, criteria);
            if result.tag == NATIVE_ARRAY_LVALUE_OK
                && (operation.uses_comparator_free_sort() || operation.uses_comparator_sort())
            {
                array.insert(key.clone(), value);
            }
            result
        }
        NativeArrayLvaluePathElement::Append => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            format!(
                "unsupported call {}(): sorting paths cannot contain append segments",
                operation.label()
            ),
        ),
    }
}

fn native_array_sort_value_path_result(
    value: &mut Value,
    path: &[NativeArrayLvaluePathElement],
    operation: NativeArraySortOperation,
    criteria: NativeArraySortCriteria<'_>,
) -> NativeArrayLvalueResult {
    if path.is_empty() {
        return match value {
            Value::Array(array) => native_array_sort_array_result(array, operation, criteria),
            Value::Object(_) | Value::Closure(_) => {
                native_array_sort_object_array_access_blocker_result(operation)
            }
            Value::Resource(_) => native_array_sort_resource_blocker_result(operation),
            other => native_array_sort_non_array_result(operation, other),
        };
    }

    match value {
        Value::Array(array) => {
            native_array_sort_array_path_result(array, path, operation, criteria)
        }
        Value::Object(_) | Value::Closure(_) => {
            native_array_sort_object_array_access_blocker_result(operation)
        }
        Value::Resource(_) => native_array_sort_resource_blocker_result(operation),
        other => native_array_sort_non_array_result(operation, other),
    }
}

fn native_array_sort_array_result(
    array: &mut PhpArray,
    operation: NativeArraySortOperation,
    criteria: NativeArraySortCriteria<'_>,
) -> NativeArrayLvalueResult {
    let callable = operation.callable();
    if operation.uses_natural_sort() {
        let result = array.sort_values_natural_for_native(
            callable,
            matches!(operation, NativeArraySortOperation::Natcasesort),
        );
        return match result {
            Ok(()) => NativeArrayLvalueResult::value(Value::Bool(true)),
            Err(error) => NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                error.message().to_string(),
            ),
        };
    }

    let result = match criteria {
        NativeArraySortCriteria::Mode(Some(mode)) if operation.uses_mode_sort() => {
            if operation.sorts_keys() {
                array.sort_keys_for_native(callable, mode, operation.reverses_order())
            } else {
                array.sort_values_for_native(
                    callable,
                    mode,
                    operation.preserves_keys(),
                    operation.reverses_order(),
                )
            }
        }
        NativeArraySortCriteria::Comparator {
            dispatch,
            diagnostic,
        } if operation.uses_comparator_sort() => {
            if operation.sorts_keys() {
                array.sort_keys_with_comparator_for_native(callable, dispatch, diagnostic)
            } else {
                array.sort_values_with_comparator_for_native(
                    callable,
                    dispatch,
                    operation.preserves_keys(),
                    diagnostic,
                )
            }
        }
        _ => return native_array_sort_blocker_result(operation),
    };

    match result {
        Ok(()) => NativeArrayLvalueResult::value(Value::Bool(true)),
        Err(error) => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_UNSUPPORTED,
            error.message().to_string(),
        ),
    }
}

fn native_array_sort_blocker_result(
    operation: NativeArraySortOperation,
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_UNSUPPORTED,
        format!(
            "native array {}() sorting mutation needs one sorting/comparator ABI with mode flag coercion, comparator callback frames, by-reference owner mutation, copy-on-write/reference separation, cleanup ownership, and exact PHP diagnostics",
            operation.label()
        ),
    )
}

fn native_array_sort_object_array_access_blocker_result(
    operation: NativeArraySortOperation,
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_UNSUPPORTED,
        format!(
            "native array {}() sorting mutation through an object/ArrayAccess owner needs ArrayAccess/object offset dispatch, Traversable/object behavior, references/copy-on-write, cleanup ownership, and exact PHP diagnostics",
            operation.label()
        ),
    )
}

fn native_array_sort_resource_blocker_result(
    operation: NativeArraySortOperation,
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_UNSUPPORTED,
        format!(
            "native array {}() sorting mutation through a resource owner needs resource root classification, by-reference diagnostics, cleanup ownership, and exact PHP diagnostics",
            operation.label()
        ),
    )
}

fn native_array_sort_non_array_result(
    operation: NativeArraySortOperation,
    value: &Value,
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_UNSUPPORTED,
        format!(
            "unsupported call {}(): sorting argument must be array, got {}",
            operation.label(),
            value.type_name()
        ),
    )
}

unsafe fn native_array_mutation_operands(
    operands: *const NativeValueHandle,
    operand_count: usize,
) -> Result<Vec<Value>, NativeArrayLvalueResult> {
    if operand_count == 0 {
        return Ok(Vec::new());
    }

    let handles = unsafe { std::slice::from_raw_parts(operands, operand_count) };
    handles
        .iter()
        .map(|handle| {
            let Some(value) = (unsafe { handle.as_ref() }) else {
                return Err(NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                    "native array mutation operand materialization produced a null value handle",
                ));
            };
            Ok(value.clone())
        })
        .collect()
}

fn native_array_mutation_array_path_result(
    array: &mut PhpArray,
    path: &[NativeArrayLvaluePathElement],
    operation: NativeArrayMutationOperation,
    operands: &[Value],
) -> NativeArrayLvalueResult {
    let Some((segment, rest)) = path.split_first() else {
        return native_array_mutation_array_result(array, operation, operands);
    };

    match segment {
        NativeArrayLvaluePathElement::Key(key) => {
            let Some(mut value) = array.get_cloned(key.clone()) else {
                return NativeArrayLvalueResult::diagnostic(
                    NATIVE_ARRAY_LVALUE_UNSUPPORTED,
                    RuntimeError::undefined_array_key(key.diagnostic_key()).message(),
                );
            };
            let result =
                native_array_mutation_value_path_result(&mut value, rest, operation, operands);
            if result.tag == NATIVE_ARRAY_LVALUE_OK {
                array.insert(key.clone(), value);
            }
            result
        }
        NativeArrayLvaluePathElement::Append => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            format!(
                "unsupported call {}(): mutation paths cannot contain append segments",
                operation.label()
            ),
        ),
    }
}

fn native_array_mutation_value_path_result(
    value: &mut Value,
    path: &[NativeArrayLvaluePathElement],
    operation: NativeArrayMutationOperation,
    operands: &[Value],
) -> NativeArrayLvalueResult {
    if path.is_empty() {
        return match value {
            Value::Array(array) => native_array_mutation_array_result(array, operation, operands),
            Value::Object(_) | Value::Closure(_) => {
                native_array_mutation_object_array_access_blocker_result(operation)
            }
            Value::Resource(_) => native_array_mutation_resource_blocker_result(operation),
            other => native_array_mutation_non_array_result(operation, other),
        };
    }

    match value {
        Value::Array(array) => {
            native_array_mutation_array_path_result(array, path, operation, operands)
        }
        Value::Object(_) | Value::Closure(_) => {
            native_array_mutation_object_array_access_blocker_result(operation)
        }
        Value::Resource(_) => native_array_mutation_resource_blocker_result(operation),
        other => native_array_mutation_non_array_result(operation, other),
    }
}

fn native_array_mutation_array_result(
    array: &mut PhpArray,
    operation: NativeArrayMutationOperation,
    operands: &[Value],
) -> NativeArrayLvalueResult {
    match operation {
        NativeArrayMutationOperation::Push => {
            for operand in operands {
                if let Err(error) = array.append(operand.clone()) {
                    return NativeArrayLvalueResult::diagnostic(
                        NATIVE_ARRAY_LVALUE_INVALID_KEY,
                        error.message().to_string(),
                    );
                }
            }
            NativeArrayLvalueResult::value(Value::Int(
                i64::try_from(array.len()).expect("array length fits in i64"),
            ))
        }
        NativeArrayMutationOperation::Pop => NativeArrayLvalueResult::value(array.pop_value()),
        NativeArrayMutationOperation::Shift => NativeArrayLvalueResult::value(array.shift_value()),
        NativeArrayMutationOperation::Unshift => match array.unshift_values(operands) {
            Ok(len) => NativeArrayLvalueResult::value(Value::Int(len)),
            Err(error) => NativeArrayLvalueResult::diagnostic(
                NATIVE_ARRAY_LVALUE_INVALID_KEY,
                error.message().to_string(),
            ),
        },
    }
}

fn native_array_mutation_object_array_access_blocker_result(
    operation: NativeArrayMutationOperation,
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_UNSUPPORTED,
        format!(
            "native array {}() mutation needs object/ArrayAccess dispatch, reference/copy-on-write separation, cleanup ownership, and exact diagnostics",
            operation.label()
        ),
    )
}

fn native_array_mutation_resource_blocker_result(
    operation: NativeArrayMutationOperation,
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_UNSUPPORTED,
        format!(
            "native array {}() mutation needs resource diagnostics, reference/copy-on-write separation, cleanup ownership, and exact diagnostics",
            operation.label()
        ),
    )
}

fn native_array_mutation_non_array_result(
    operation: NativeArrayMutationOperation,
    value: &Value,
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::diagnostic(
        NATIVE_ARRAY_LVALUE_UNSUPPORTED,
        format!(
            "unsupported call {}(): mutation argument must be array, got {}",
            operation.label(),
            value.type_name()
        ),
    )
}

fn native_array_foreach_iterable_path_result(
    array: &PhpArray,
    path: &[NativeArrayLvaluePathElement],
) -> NativeArrayLvalueResult {
    if path.is_empty() {
        return NativeArrayLvalueResult::value(Value::Array(array.clone()));
    }

    match native_array_foreach_iterable_path_value(array, path) {
        Ok(Some(value)) => native_value_foreach_iterable_value_result(value),
        Ok(None) => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            RuntimeError::invalid_foreach("missing array lvalue iterable").message(),
        ),
        Err(result) => result,
    }
}

fn native_value_foreach_iterable_value_result(value: Value) -> NativeArrayLvalueResult {
    match value {
        Value::Array(_) => NativeArrayLvalueResult::value(value),
        other => NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            RuntimeError::invalid_foreach(format!(
                "cannot iterate {} array lvalue iterable",
                other.type_name()
            ))
            .message(),
        ),
    }
}

fn native_array_foreach_iterable_path_value(
    array: &PhpArray,
    path: &[NativeArrayLvaluePathElement],
) -> Result<Option<Value>, NativeArrayLvalueResult> {
    let Some((segment, rest)) = path.split_first() else {
        return Ok(Some(Value::Array(array.clone())));
    };

    let NativeArrayLvaluePathElement::Key(key) = segment else {
        return Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_KEY,
            "array foreach iterable path cannot contain append segments",
        ));
    };

    let Some(value) = array.get_cloned(key.clone()) else {
        return Ok(None);
    };
    if rest.is_empty() {
        return Ok(Some(value));
    }

    match value {
        Value::Array(child) => native_array_foreach_iterable_path_value(&child, rest),
        other => Err(NativeArrayLvalueResult::diagnostic(
            NATIVE_ARRAY_LVALUE_INVALID_ROOT,
            format!(
                "cannot iterate nested foreach offset on {}",
                other.type_name()
            ),
        )),
    }
}

fn native_array_lvalue_missing_key_read_result(
    key: &ArrayKey,
    rest: &[ArrayKey],
) -> NativeArrayLvalueResult {
    let mut diagnostics = vec![RuntimeError::undefined_array_key(key.diagnostic_key())
        .message()
        .to_string()];
    diagnostics.extend(native_array_lvalue_scalar_read_recovery_diagnostics(
        &Value::Null,
        rest,
    ));
    NativeArrayLvalueResult::value_with_diagnostic(Value::Null, diagnostics.join("\n"))
}

fn native_array_lvalue_scalar_read_recovery_result(
    root: &Value,
    rest: &[ArrayKey],
) -> NativeArrayLvalueResult {
    NativeArrayLvalueResult::value_with_diagnostic(
        Value::Null,
        native_array_lvalue_scalar_read_recovery_diagnostics(root, rest).join("\n"),
    )
}

fn native_array_lvalue_scalar_read_recovery_diagnostics(
    root: &Value,
    rest: &[ArrayKey],
) -> Vec<String> {
    let mut value_type = root.type_name();
    let mut diagnostics = Vec::with_capacity(rest.len());
    for _ in rest {
        diagnostics.push(format!(
            "Warning: Trying to access array offset on value of type {value_type}"
        ));
        value_type = Value::Null.type_name();
    }
    diagnostics
}

unsafe fn native_string_value_offset_mutation_operation_value(
    subject: NativeValueHandle,
    offset: NativeValueHandle,
    replacement: NativeValueHandle,
    operation: u8,
) -> RuntimeResult<(Value, Option<&'static str>)> {
    match operation {
        tag if tag == NativeValueOffsetMutationOperation::Write as u8 => {
            unsafe { native_value_string_offset_write_value(subject, offset, replacement) }
        }
        tag if tag == NativeValueOffsetMutationOperation::Append as u8 => {
            Err(RuntimeError::invalid_array_access(
                "native value offset mutation failed: string offset append awaits the shared mutable string-offset ABI",
            ))
        }
        tag if tag == NativeValueOffsetMutationOperation::Unset as u8 => {
            Err(RuntimeError::invalid_array_access(
                "native value offset mutation failed: string offset unset awaits the shared mutable string-offset ABI",
            ))
        }
        _ => Err(RuntimeError::invalid_array_access(
            "native value offset mutation failed: unsupported operation tag",
        )),
    }
}

unsafe fn native_value_clone_for_offset_mutation(
    handle: NativeValueHandle,
    operation: &'static str,
) -> RuntimeResult<Value> {
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(RuntimeError::invalid_array_access(format!(
            "native value offset mutation failed: {operation} value handle is null"
        )));
    };

    Ok(value.clone())
}

unsafe fn native_array_value_offset_operation_value(
    array: &PhpArray,
    offset: NativeValueHandle,
    operation: u8,
) -> RuntimeResult<(Value, Option<String>)> {
    let Some(offset) = (unsafe { offset.as_ref() }) else {
        return Err(RuntimeError::invalid_array_key(
            "native value offset operation failed: offset handle is null",
        ));
    };
    let key = native_array_key_from_runtime_value(offset)?;

    match NativeStringOffsetOperation::from_tag(operation)? {
        NativeStringOffsetOperation::Read => match array.get_cloned(key.clone()) {
            Some(value) => Ok((value, None)),
            None => Ok((
                Value::Null,
                Some(
                    RuntimeError::undefined_array_key(key.diagnostic_key())
                        .message()
                        .to_string(),
                ),
            )),
        },
        NativeStringOffsetOperation::Isset => Ok((
            Value::Bool(!matches!(array.get(key), None | Some(Value::Null))),
            None,
        )),
        NativeStringOffsetOperation::Empty => Ok((
            Value::Bool(
                array
                    .get(key)
                    .map(|value| !value.is_truthy())
                    .unwrap_or(true),
            ),
            None,
        )),
    }
}

unsafe fn native_value_string_offset_read_subject_bytes(
    handle: NativeValueHandle,
) -> RuntimeResult<Vec<u8>> {
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(RuntimeError::invalid_string_conversion(
            "native string offset read failed: subject handle is null",
        ));
    };

    match value {
        Value::String(value) => Ok(value.as_bytes().to_vec()),
        Value::BinaryString(value) => Ok(value.clone()),
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) => {
            Err(RuntimeError::unsupported_call(
                "native string offset read",
                format!(
                    "{} subjects require PHP value-offset warning semantics before generated native reads",
                    value.type_name()
                ),
            ))
        }
        Value::Array(_)
        | Value::Object(_)
        | Value::Closure(_)
        | Value::Resource(_) => Err(RuntimeError::invalid_string_conversion(format!(
            "native string offset read failed: {} subjects are not supported; only string byte subjects are implemented",
            value.type_name()
        ))),
    }
}

unsafe fn native_value_string_offset_subject_bytes(
    handle: NativeValueHandle,
) -> RuntimeResult<Vec<u8>> {
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(RuntimeError::invalid_string_conversion(
            "native string offset operation failed: subject handle is null",
        ));
    };

    match value {
        Value::BinaryString(value) => Ok(value.clone()),
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::String(_) => {
            Ok(analyze_php_value_string_semantics(value).into_bytes())
        }
        Value::Array(_)
        | Value::Object(_)
        | Value::Closure(_)
        | Value::Resource(_) => Err(RuntimeError::invalid_string_conversion(format!(
            "native string offset operation failed: {} subjects are not supported; only null, bool, int, float, and string subjects are implemented",
            value.type_name()
        ))),
    }
}

unsafe fn native_string_offset_replacement_bytes_from_value(
    handle: NativeValueHandle,
) -> RuntimeResult<Vec<u8>> {
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(RuntimeError::invalid_string_conversion(
            "native string offset write failed: replacement handle is null",
        ));
    };

    match value {
        Value::BinaryString(value) => Ok(value.clone()),
        Value::Null | Value::Bool(_) | Value::Int(_) | Value::Float(_) | Value::String(_) => {
            Ok(analyze_php_value_string_semantics(value).into_bytes())
        }
        Value::Array(_)
        | Value::Object(_)
        | Value::Closure(_)
        | Value::Resource(_) => Err(RuntimeError::invalid_string_conversion(format!(
            "native string offset write failed: {} replacements are not supported; only null, bool, int, float, and string replacements are implemented",
            value.type_name()
        ))),
    }
}

unsafe fn native_string_offset_index_from_value(handle: NativeValueHandle) -> RuntimeResult<usize> {
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(RuntimeError::invalid_string_conversion(
            "native string offset operation failed: offset handle is null",
        ));
    };

    let offset = match value {
        Value::Null => 0,
        Value::Bool(false) => 0,
        Value::Bool(true) => 1,
        Value::Int(value) => *value,
        Value::Float(value)
            if value.is_finite()
                && value.fract() == 0.0
                && *value >= i64::MIN as f64
                && *value <= i64::MAX as f64 =>
        {
            *value as i64
        }
        Value::Float(_) => {
            return Err(RuntimeError::invalid_string_conversion(
                "native string offset operation failed: offset must be an integer",
            ))
        }
        Value::String(value) => php_string_offset_index_from_string(value)?,
        Value::BinaryString(value) => php_string_offset_index_from_bytes(value)?,
        other => {
            return Err(RuntimeError::invalid_string_conversion(format!(
                "native string offset operation failed: {} offsets are not supported; only null, bool, int, integral float, and integer string offsets are implemented",
                other.type_name()
            )))
        }
    };

    usize::try_from(offset).map_err(|_| {
        RuntimeError::invalid_string_conversion(
            "native string offset operation failed: offset must be a non-negative integer",
        )
    })
}

fn php_string_offset_index_from_string(value: &str) -> RuntimeResult<i64> {
    php_string_offset_index_from_bytes(value.as_bytes())
}

fn php_string_offset_index_from_bytes(bytes: &[u8]) -> RuntimeResult<i64> {
    if bytes.is_empty() {
        return Err(RuntimeError::invalid_string_conversion(
            "native string offset operation failed: offset must be an integer string",
        ));
    }

    let digits = match bytes[0] {
        b'+' | b'-' if bytes.len() > 1 => &bytes[1..],
        b'+' | b'-' => &[][..],
        _ => bytes,
    };

    if digits.is_empty() || !digits.iter().all(u8::is_ascii_digit) {
        return Err(RuntimeError::invalid_string_conversion(
            "native string offset operation failed: offset must be an integer string",
        ));
    }

    let value = std::str::from_utf8(bytes).map_err(|_| {
        RuntimeError::invalid_string_conversion(
            "native string offset operation failed: offset must be an integer string",
        )
    })?;

    value.parse::<i64>().map_err(|_| {
        RuntimeError::invalid_string_conversion(
            "native string offset operation failed: offset integer string is out of range",
        )
    })
}

fn php_string_offset_bool_operation(
    bytes: &[u8],
    offset: usize,
    operation: NativeStringOffsetOperation,
) -> bool {
    match operation {
        NativeStringOffsetOperation::Read => {
            unreachable!("string offset read is handled by php_string_offset_read_value")
        }
        NativeStringOffsetOperation::Isset => bytes.get(offset).is_some(),
        NativeStringOffsetOperation::Empty => match bytes.get(offset) {
            Some(b'0') | None => true,
            Some(_) => false,
        },
    }
}

fn php_string_offset_read_value(bytes: &[u8], offset: usize) -> RuntimeResult<Value> {
    let Some(byte) = bytes.get(offset) else {
        return Err(RuntimeError::invalid_string_conversion(format!(
            "native string offset read failed: offset {offset} is outside string length {}",
            bytes.len()
        )));
    };

    Ok(value_from_php_string_bytes(vec![*byte]))
}

pub fn php_string_offset_write(
    bytes: &mut Vec<u8>,
    offset: usize,
    replacement: &[u8],
) -> RuntimeResult<Option<&'static str>> {
    if replacement.is_empty() {
        return Err(RuntimeError::invalid_array_access(
            "cannot assign an empty string to a string offset",
        ));
    }

    let warning = if replacement.len() > 1 {
        Some(PHP_STRING_OFFSET_TRUNCATED_REPLACEMENT_WARNING)
    } else {
        None
    };
    let replacement = replacement[0];
    if offset > bytes.len() {
        bytes.resize(offset, b' ');
        bytes.push(replacement);
    } else if offset == bytes.len() {
        bytes.push(replacement);
    } else {
        bytes[offset] = replacement;
    }

    Ok(warning)
}

unsafe fn native_value_string_result_operation_value(
    subject: NativeValueHandle,
    flags: u8,
    operation: u8,
) -> RuntimeResult<Value> {
    if flags != 0 {
        return Err(RuntimeError::invalid_string_conversion(
            "native string result operation failed: unary operation does not accept operation flags",
        ));
    }

    let subject = unsafe { native_value_to_string_bytes(subject) }?;
    let bytes = match operation {
        value if value == NativeStringResultOperation::Reverse as u8 => php_strrev_bytes(&subject),
        value if value == NativeStringResultOperation::BinToHex as u8 => {
            php_bin2hex_bytes(&subject)
        }
        value if value == NativeStringResultOperation::Rot13 as u8 => php_str_rot13_bytes(&subject),
        value if value == NativeStringResultOperation::AsciiLower as u8 => {
            php_ascii_lower_bytes(&subject)
        }
        value if value == NativeStringResultOperation::AsciiUpper as u8 => {
            php_ascii_upper_bytes(&subject)
        }
        value if value == NativeStringResultOperation::AsciiFirstUpper as u8 => {
            php_ascii_first_upper_bytes(&subject)
        }
        value if value == NativeStringResultOperation::AsciiFirstLower as u8 => {
            php_ascii_first_lower_bytes(&subject)
        }
        value
            if value == NativeStringResultOperation::ShellArgEscape as u8
                || value == NativeStringResultOperation::ShellCommandEscape as u8 =>
        {
            if value == NativeStringResultOperation::ShellArgEscape as u8 {
                php_shell_arg_escape_bytes(&subject)?
            } else {
                php_shell_command_escape_bytes(&subject)?
            }
        }
        _ => {
            return Err(RuntimeError::invalid_string_conversion(
                "native string result operation failed: unsupported operation tag",
            ))
        }
    };

    value_from_native_string_result_bytes(bytes)
}

unsafe fn native_value_string_array_operation_value(
    subject: NativeValueHandle,
    operand: NativeValueHandle,
    limit_or_length: i64,
    flags: u8,
    operation: u8,
) -> RuntimeResult<Value> {
    match operation {
        value if value == NativeStringArrayOperation::Explode as u8 => {
            if flags & !NATIVE_STRING_ARRAY_HAS_LIMIT != 0 {
                return Err(RuntimeError::invalid_string_conversion(
                    "native string array operation failed: explode received unsupported flags",
                ));
            }
            let subject = unsafe { native_value_to_string_bytes(subject) }?;
            let separator = unsafe { native_value_to_string_bytes(operand) }?;
            let limit = (flags & NATIVE_STRING_ARRAY_HAS_LIMIT != 0).then_some(limit_or_length);
            Ok(Value::Array(php_explode_bytes(
                &separator, &subject, limit,
            )?))
        }
        value if value == NativeStringArrayOperation::Split as u8 => {
            if flags != 0 {
                return Err(RuntimeError::invalid_string_conversion(
                    "native string array operation failed: str_split received unsupported flags",
                ));
            }
            let subject = unsafe { native_value_to_string_bytes(subject) }?;
            Ok(Value::Array(php_str_split_bytes(
                &subject,
                limit_or_length,
            )?))
        }
        _ => Err(RuntimeError::invalid_string_conversion(
            "native string array operation failed: unsupported operation tag",
        )),
    }
}

fn php_explode_bytes(
    separator: &[u8],
    subject: &[u8],
    limit: Option<i64>,
) -> RuntimeResult<PhpArray> {
    if separator.is_empty() {
        return Err(RuntimeError::invalid_string_conversion(
            "native string array operation failed: explode separator must not be empty",
        ));
    }

    let limit = limit.unwrap_or(i64::MAX);
    if limit < 0 {
        let mut segments = split_all_bytes(subject, separator);
        let remove = limit
            .checked_neg()
            .and_then(|value| usize::try_from(value).ok())
            .unwrap_or(usize::MAX);
        segments.truncate(segments.len().saturating_sub(remove));
        return Ok(php_array_from_byte_segments(segments));
    }

    let max_parts = if limit == 0 {
        1
    } else {
        usize::try_from(limit).unwrap_or(usize::MAX)
    };
    let mut segments = Vec::new();
    let mut cursor = 0;
    while segments.len().saturating_add(1) < max_parts {
        let Some(position) = find_subslice(&subject[cursor..], separator) else {
            break;
        };
        let end = cursor + position;
        segments.push(subject[cursor..end].to_vec());
        cursor = end + separator.len();
    }
    segments.push(subject[cursor..].to_vec());
    Ok(php_array_from_byte_segments(segments))
}

fn php_str_split_bytes(subject: &[u8], length: i64) -> RuntimeResult<PhpArray> {
    if length < 1 {
        return Err(RuntimeError::invalid_string_conversion(
            "native string array operation failed: str_split length must be greater than or equal to 1",
        ));
    }

    let length = usize::try_from(length).unwrap_or(usize::MAX);
    let mut segments = Vec::new();
    let mut cursor = 0;
    while cursor < subject.len() {
        let end = cursor.saturating_add(length).min(subject.len());
        segments.push(subject[cursor..end].to_vec());
        cursor = end;
    }
    Ok(php_array_from_byte_segments(segments))
}

fn split_all_bytes(subject: &[u8], separator: &[u8]) -> Vec<Vec<u8>> {
    let mut segments = Vec::new();
    let mut cursor = 0;
    while let Some(position) = find_subslice(&subject[cursor..], separator) {
        let end = cursor + position;
        segments.push(subject[cursor..end].to_vec());
        cursor = end + separator.len();
    }
    segments.push(subject[cursor..].to_vec());
    segments
}

fn find_subslice(subject: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    subject
        .windows(needle.len())
        .position(|window| window == needle)
}

fn php_array_from_byte_segments(segments: Vec<Vec<u8>>) -> PhpArray {
    let mut array = PhpArray::new();
    for segment in segments {
        array
            .append(value_from_php_string_bytes(segment))
            .expect("append into a fresh array should not fail");
    }
    array
}

fn value_from_native_string_result_bytes(bytes: Vec<u8>) -> RuntimeResult<Value> {
    String::from_utf8(bytes).map(Value::String).map_err(|_| {
        RuntimeError::invalid_string_conversion(
            "native string result operation failed: result bytes are not valid UTF-8",
        )
    })
}

unsafe fn native_value_string_distance_operation(
    subject: NativeValueHandle,
    operand: NativeValueHandle,
    insertion_cost: i64,
    replacement_cost: i64,
    deletion_cost: i64,
    operation: u8,
) -> RuntimeResult<i64> {
    let left = unsafe { native_value_to_string_bytes(subject) }?;
    let right = unsafe { native_value_to_string_bytes(operand) }?;

    match operation {
        value if value == NativeStringDistanceOperation::Levenshtein as u8 => {
            php_levenshtein_bytes(
                &left,
                &right,
                insertion_cost,
                replacement_cost,
                deletion_cost,
            )
        }
        value if value == NativeStringDistanceOperation::SimilarText as u8 => {
            php_similar_text_bytes(&left, &right)
        }
        _ => Err(RuntimeError::invalid_string_conversion(
            "native string distance operation failed: unsupported operation tag",
        )),
    }
}

fn php_levenshtein_bytes(
    left: &[u8],
    right: &[u8],
    insertion_cost: i64,
    replacement_cost: i64,
    deletion_cost: i64,
) -> RuntimeResult<i64> {
    let insertion_cost = i128::from(insertion_cost);
    let replacement_cost = i128::from(replacement_cost);
    let deletion_cost = i128::from(deletion_cost);

    let mut previous = Vec::with_capacity(right.len() + 1);
    let mut current = Vec::with_capacity(right.len() + 1);
    previous.push(0_i128);
    for index in 1..=right.len() {
        previous.push(checked_distance_add(
            previous[index - 1],
            insertion_cost,
            "levenshtein",
        )?);
    }

    for (left_index, left_byte) in left.iter().enumerate() {
        current.clear();
        current.push(checked_distance_mul(
            i128::try_from(left_index + 1).unwrap_or(i128::MAX),
            deletion_cost,
            "levenshtein",
        )?);

        for (right_index, right_byte) in right.iter().enumerate() {
            let insert = checked_distance_add(current[right_index], insertion_cost, "levenshtein")?;
            let delete =
                checked_distance_add(previous[right_index + 1], deletion_cost, "levenshtein")?;
            let replace = checked_distance_add(
                previous[right_index],
                if left_byte == right_byte {
                    0
                } else {
                    replacement_cost
                },
                "levenshtein",
            )?;
            current.push(insert.min(delete).min(replace));
        }

        std::mem::swap(&mut previous, &mut current);
    }

    distance_to_i64(previous[right.len()], "levenshtein")
}

fn checked_distance_add(left: i128, right: i128, operation: &str) -> RuntimeResult<i128> {
    left.checked_add(right).ok_or_else(|| {
        RuntimeError::invalid_string_conversion(format!(
            "native string distance operation failed: {operation} distance overflowed"
        ))
    })
}

fn checked_distance_mul(left: i128, right: i128, operation: &str) -> RuntimeResult<i128> {
    left.checked_mul(right).ok_or_else(|| {
        RuntimeError::invalid_string_conversion(format!(
            "native string distance operation failed: {operation} distance overflowed"
        ))
    })
}

fn distance_to_i64(value: i128, operation: &str) -> RuntimeResult<i64> {
    i64::try_from(value).map_err(|_| {
        RuntimeError::invalid_string_conversion(format!(
            "native string distance operation failed: {operation} distance overflowed"
        ))
    })
}

fn php_similar_text_bytes(left: &[u8], right: &[u8]) -> RuntimeResult<i64> {
    i64::try_from(similar_text_score_bytes(left, right)).map_err(|_| {
        RuntimeError::invalid_string_conversion(
            "native string distance operation failed: similar_text score overflowed",
        )
    })
}

fn similar_text_score_bytes(left: &[u8], right: &[u8]) -> usize {
    let mut max_len = 0;
    let mut left_pos = 0;
    let mut right_pos = 0;

    for left_index in 0..left.len() {
        for right_index in 0..right.len() {
            let mut len = 0;
            while left_index + len < left.len()
                && right_index + len < right.len()
                && left[left_index + len] == right[right_index + len]
            {
                len += 1;
            }
            if len > max_len {
                max_len = len;
                left_pos = left_index;
                right_pos = right_index;
            }
        }
    }

    if max_len == 0 {
        return 0;
    }

    max_len
        + similar_text_score_bytes(&left[..left_pos], &right[..right_pos])
        + similar_text_score_bytes(&left[left_pos + max_len..], &right[right_pos + max_len..])
}

unsafe fn native_output_buffer_args(
    first: NativeValueHandle,
    second: NativeValueHandle,
    third: NativeValueHandle,
    argc: u8,
) -> RuntimeResult<Vec<Value>> {
    if argc > 3 {
        return Err(RuntimeError::arity_mismatch(
            "native output-buffer operation",
            ArityExpectation::Between { min: 0, max: 3 },
            argc as usize,
        ));
    }

    let mut args = Vec::new();
    for handle in [first, second, third].into_iter().take(argc as usize) {
        let Some(value) = (unsafe { handle.as_ref() }) else {
            return Err(RuntimeError::unsupported_call(
                "native output-buffer operation",
                "argument value handle is null",
            ));
        };
        args.push(value.clone());
    }
    Ok(args)
}

fn native_output_buffer_operation_value(
    table: NativeCallableTableHandle,
    operation: NativeOutputBufferOperation,
    args: &[Value],
) -> RuntimeResult<Value> {
    if !operation.accepts_arity(args.len()) {
        return Err(RuntimeError::arity_mismatch(
            operation.callable(),
            operation.expected_arity(),
            args.len(),
        ));
    }

    match operation {
        NativeOutputBufferOperation::Start => {
            let handler = if let Some(callback) = args.first() {
                if matches!(callback, Value::Null) {
                    None
                } else {
                    Some(
                        native_callable_value_lookup(unsafe { table.as_ref() }, callback, None)
                            .map_err(|message| {
                                RuntimeError::unsupported_call(operation.callable(), message)
                            })?,
                    )
                }
            } else {
                None
            };
            let chunk_size = if let Some(chunk_size) = args.get(1) {
                value_to_native_int64(chunk_size, NativeIntConversionOperation::StringLength)?
                    .try_into()
                    .unwrap_or(0)
            } else {
                0
            };
            let requested_flags = if let Some(flags) = args.get(2) {
                value_to_native_int64(flags, NativeIntConversionOperation::StringLength)?
            } else {
                NATIVE_OUTPUT_HANDLER_STDFLAGS
            };
            let handler_status =
                NativeOutputBufferHandlerStatus::new(handler.is_some(), requested_flags);
            NATIVE_OUTPUT_BUFFERS.with(|buffers| {
                buffers.borrow_mut().push(NativeOutputBuffer {
                    bytes: Vec::new(),
                    chunk_size,
                    handler,
                    handler_status,
                })
            });
            Ok(Value::Bool(true))
        }
        NativeOutputBufferOperation::GetLevel => {
            let level = NATIVE_OUTPUT_BUFFERS.with(|buffers| buffers.borrow().len());
            Ok(Value::Int(i64::try_from(level).unwrap_or(i64::MAX)))
        }
        NativeOutputBufferOperation::GetContents => NATIVE_OUTPUT_BUFFERS.with(|buffers| {
            buffers
                .borrow()
                .last()
                .map(|buffer| value_from_output_buffer_bytes(buffer.bytes.clone(), operation))
                .unwrap_or(Ok(Value::Bool(false)))
        }),
        NativeOutputBufferOperation::GetLength => Ok(NATIVE_OUTPUT_BUFFERS.with(|buffers| {
            buffers
                .borrow()
                .last()
                .map(|buffer| Value::Int(i64::try_from(buffer.bytes.len()).unwrap_or(i64::MAX)))
                .unwrap_or(Value::Bool(false))
        })),
        NativeOutputBufferOperation::ListHandlers => Ok(NATIVE_OUTPUT_BUFFERS.with(|buffers| {
            let mut handlers = PhpArray::new();
            for buffer in buffers.borrow().iter() {
                handlers
                    .append(Value::String(native_output_buffer_handler_name(buffer)))
                    .expect("output buffer handler list append should use integer keys");
            }
            Value::Array(handlers)
        })),
        NativeOutputBufferOperation::GetStatus => {
            let full_status = args.first().is_some_and(Value::is_truthy);
            Ok(NATIVE_OUTPUT_BUFFERS.with(|buffers| {
                let buffers = buffers.borrow();
                if full_status {
                    let mut statuses = PhpArray::new();
                    for (index, buffer) in buffers.iter().enumerate() {
                        statuses
                            .append(native_output_buffer_status_value(index + 1, buffer))
                            .expect("output buffer full status append should use integer keys");
                    }
                    Value::Array(statuses)
                } else {
                    buffers
                        .last()
                        .map(|buffer| native_output_buffer_status_value(buffers.len(), buffer))
                        .unwrap_or_else(|| Value::Array(PhpArray::new()))
                }
            }))
        }
        NativeOutputBufferOperation::GetClean => native_output_buffer_pop_value(false),
        NativeOutputBufferOperation::GetFlush => native_output_buffer_pop_value(true),
        NativeOutputBufferOperation::Clean => Ok(NATIVE_OUTPUT_BUFFERS.with(|buffers| {
            let mut buffers = buffers.borrow_mut();
            if let Some(buffer) = buffers.last_mut() {
                buffer.bytes.clear();
                buffer.handler_status.mark_processed();
                Value::Bool(true)
            } else {
                Value::Bool(false)
            }
        })),
        NativeOutputBufferOperation::Flush => native_output_buffer_flush_active(),
        NativeOutputBufferOperation::EndClean => native_output_buffer_pop_bool(false),
        NativeOutputBufferOperation::EndFlush => native_output_buffer_pop_bool(true),
    }
}

const NATIVE_OUTPUT_HANDLER_WRITE: i64 = 0;
const NATIVE_OUTPUT_HANDLER_START: i64 = 1;
const NATIVE_OUTPUT_HANDLER_TYPE_MASK: i64 = 0x000f;
const NATIVE_OUTPUT_HANDLER_INTERNAL: i64 = 0x0000;
const NATIVE_OUTPUT_HANDLER_USER: i64 = 0x0001;
const NATIVE_OUTPUT_HANDLER_FLUSH: i64 = 4;
const NATIVE_OUTPUT_HANDLER_FINAL: i64 = 8;
const NATIVE_OUTPUT_HANDLER_STDFLAGS: i64 = 0x0070;
const NATIVE_OUTPUT_HANDLER_STARTED: i64 = 0x1000;
const NATIVE_OUTPUT_HANDLER_PROCESSED: i64 = 0x4000;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct NativeOutputBufferHandlerStatus {
    handler_type: i64,
    flags: i64,
}

impl NativeOutputBufferHandlerStatus {
    fn new(user_handler: bool, requested_flags: i64) -> Self {
        let handler_type = if user_handler {
            NATIVE_OUTPUT_HANDLER_USER
        } else {
            NATIVE_OUTPUT_HANDLER_INTERNAL
        };
        Self {
            handler_type,
            flags: (requested_flags & !NATIVE_OUTPUT_HANDLER_TYPE_MASK) | handler_type,
        }
    }

    fn internal_default() -> Self {
        Self::new(false, NATIVE_OUTPUT_HANDLER_STDFLAGS)
    }

    fn handler_type(self) -> i64 {
        self.handler_type
    }

    fn flags(self) -> i64 {
        self.flags
    }

    fn started(self) -> bool {
        self.flags & NATIVE_OUTPUT_HANDLER_STARTED != 0
    }

    fn mark_processed(&mut self) {
        self.flags |= NATIVE_OUTPUT_HANDLER_STARTED | NATIVE_OUTPUT_HANDLER_PROCESSED;
    }
}

fn native_output_buffer_handler_phase(started: bool, terminal_flag: i64) -> i64 {
    if started {
        terminal_flag
    } else {
        NATIVE_OUTPUT_HANDLER_START | terminal_flag
    }
}

unsafe fn native_output_buffer_handler_result_bytes(
    handler: &NativeCallableValueDispatch,
    bytes: &[u8],
    phase: i64,
    operation: NativeOutputBufferOperation,
) -> RuntimeResult<Vec<u8>> {
    let callable = NativeCallableValueHandle::from_dispatch(handler.clone());
    let arguments = NativeCallArgumentsHandle::new();
    let buffer = NativeValueHandle::from_value(Value::BinaryString(bytes.to_vec()));
    if !unsafe { phpc_native_call_arguments_push_value_and_free(arguments, buffer) } {
        unsafe { phpc_native_callable_value_free(callable) };
        return Err(RuntimeError::unsupported_call(
            operation.callable(),
            "callback output handler argument materialization failed for buffer bytes",
        ));
    }
    let phase = NativeValueHandle::from_value(Value::Int(phase));
    if !unsafe { phpc_native_call_arguments_push_value_and_free(arguments, phase) } {
        unsafe { phpc_native_call_arguments_free(arguments) };
        unsafe { phpc_native_callable_value_free(callable) };
        return Err(RuntimeError::unsupported_call(
            operation.callable(),
            "callback output handler argument materialization failed for phase flags",
        ));
    }

    let mut diagnostic = NativeDiagnosticHandle::null();
    let result = unsafe {
        phpc_native_callable_value_invoke_value_with_diagnostic_and_free(
            callable,
            arguments,
            &mut diagnostic,
        )
    };
    unsafe { phpc_native_callable_value_free(callable) };
    if !diagnostic.is_null() {
        let message = unsafe { diagnostic.as_ref() }
            .map(|diagnostic| diagnostic.message.clone())
            .unwrap_or_else(|| "callback output handler invocation failed".to_string());
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        return Err(RuntimeError::unsupported_call(
            operation.callable(),
            message,
        ));
    }

    let handled = match unsafe { result.as_ref() } {
        Some(Value::Bool(false)) => Ok(bytes.to_vec()),
        Some(_) => unsafe { native_value_to_string_bytes(result) },
        None => Err(RuntimeError::unsupported_call(
            operation.callable(),
            "callback output handler returned a null value handle",
        )),
    };
    unsafe { phpc_native_value_free(result) };
    handled
}

fn native_output_buffer_flush_bytes_to_target(
    bytes: &[u8],
    handler: Option<&NativeCallableValueDispatch>,
    phase: i64,
    operation: NativeOutputBufferOperation,
    target: Option<usize>,
) -> RuntimeResult<usize> {
    let output = if let Some(handler) = handler {
        let handled =
            unsafe { native_output_buffer_handler_result_bytes(handler, bytes, phase, operation) }?;
        handled
    } else {
        bytes.to_vec()
    };
    native_output_write_bytes_to_buffer_index(&output, target)
}

fn native_output_buffer_flush_active() -> RuntimeResult<Value> {
    NATIVE_OUTPUT_BUFFERS.with(|buffers| {
        let mut buffers = buffers.borrow_mut();
        let target = buffers.len().checked_sub(2);
        let Some(buffer) = buffers.last_mut() else {
            return Ok(Value::Bool(false));
        };
        let bytes = std::mem::take(&mut buffer.bytes);
        let handler = buffer.handler.clone();
        let phase = native_output_buffer_handler_phase(
            buffer.handler_status.started(),
            NATIVE_OUTPUT_HANDLER_FLUSH,
        );
        buffer.handler_status.mark_processed();
        drop(buffers);
        native_output_buffer_flush_bytes_to_target(
            &bytes,
            handler.as_ref(),
            phase,
            NativeOutputBufferOperation::Flush,
            target,
        )
        .map(|_| Value::Bool(true))
    })
}

fn native_output_buffer_handler_name(buffer: &NativeOutputBuffer) -> String {
    match buffer.handler.as_ref() {
        Some(handler) => native_callable_dispatch_handler_name(handler),
        None => "default output handler".to_string(),
    }
}

fn native_callable_dispatch_handler_name(handler: &NativeCallableValueDispatch) -> String {
    match handler {
        NativeCallableValueDispatch::Builtin(builtin) => builtin.name().to_string(),
        NativeCallableValueDispatch::Table { callable, .. } => match callable.descriptor.kind {
            NativeCallableKind::Function => callable.descriptor.name.clone(),
            NativeCallableKind::Method | NativeCallableKind::Constructor => {
                let scope = callable
                    .called_scope
                    .as_deref()
                    .or(callable.descriptor.scope.as_deref())
                    .unwrap_or("<unknown>");
                format!("{scope}::{}", callable.descriptor.name)
            }
        },
        NativeCallableValueDispatch::DescriptorClosure(_) => "Closure::__invoke".to_string(),
    }
}

fn native_output_buffer_status_value(level: usize, buffer: &NativeOutputBuffer) -> Value {
    let mut status = PhpArray::new();
    status.insert(
        "name",
        Value::String(native_output_buffer_handler_name(buffer)),
    );
    status.insert("type", Value::Int(buffer.handler_status.handler_type()));
    status.insert("flags", Value::Int(buffer.handler_status.flags()));
    status.insert(
        "level",
        Value::Int(i64::try_from(level).unwrap_or(i64::MAX)),
    );
    status.insert(
        "chunk_size",
        Value::Int(i64::try_from(buffer.chunk_size).unwrap_or(i64::MAX)),
    );
    status.insert(
        "buffer_used",
        Value::Int(i64::try_from(buffer.bytes.len()).unwrap_or(i64::MAX)),
    );
    Value::Array(status)
}

fn native_output_buffer_pop_value(flush: bool) -> RuntimeResult<Value> {
    NATIVE_OUTPUT_BUFFERS.with(|buffers| {
        let (buffer, target) = {
            let mut buffers = buffers.borrow_mut();
            let target = buffers.len().checked_sub(2);
            let Some(buffer) = buffers.pop() else {
                return Ok(Value::Bool(false));
            };
            (buffer, target)
        };
        let bytes = buffer.bytes;
        if flush {
            let phase = native_output_buffer_handler_phase(
                buffer.handler_status.started(),
                NATIVE_OUTPUT_HANDLER_FINAL,
            );
            native_output_buffer_flush_bytes_to_target(
                &bytes,
                buffer.handler.as_ref(),
                phase,
                NativeOutputBufferOperation::GetFlush,
                target,
            )?;
        }
        value_from_output_buffer_bytes(
            bytes,
            if flush {
                NativeOutputBufferOperation::GetFlush
            } else {
                NativeOutputBufferOperation::GetClean
            },
        )
    })
}

fn native_output_buffer_pop_bool(flush: bool) -> RuntimeResult<Value> {
    NATIVE_OUTPUT_BUFFERS.with(|buffers| {
        let (buffer, target) = {
            let mut buffers = buffers.borrow_mut();
            let target = buffers.len().checked_sub(2);
            let Some(buffer) = buffers.pop() else {
                return Ok(Value::Bool(false));
            };
            (buffer, target)
        };
        if flush {
            let phase = native_output_buffer_handler_phase(
                buffer.handler_status.started(),
                NATIVE_OUTPUT_HANDLER_FINAL,
            );
            native_output_buffer_flush_bytes_to_target(
                &buffer.bytes,
                buffer.handler.as_ref(),
                phase,
                NativeOutputBufferOperation::EndFlush,
                target,
            )?;
        }
        Ok(Value::Bool(true))
    })
}

fn native_output_buffer_unwind_stack() -> RuntimeResult<usize> {
    let mut written = 0;
    loop {
        let next = NATIVE_OUTPUT_BUFFERS.with(|buffers| {
            let mut buffers = buffers.borrow_mut();
            let target = buffers.len().checked_sub(2);
            let buffer = buffers.pop()?;
            let phase = native_output_buffer_handler_phase(
                buffer.handler_status.started(),
                NATIVE_OUTPUT_HANDLER_FINAL,
            );
            Some((buffer.bytes, buffer.handler, phase, target))
        });
        let Some((bytes, handler, phase, target)) = next else {
            break;
        };
        written += native_output_buffer_flush_bytes_to_target(
            &bytes,
            handler.as_ref(),
            phase,
            NativeOutputBufferOperation::EndFlush,
            target,
        )?;
    }
    Ok(written)
}

fn native_output_write_bytes(bytes: &[u8]) -> RuntimeResult<usize> {
    native_output_write_bytes_to_buffer(bytes, false)
}

fn native_output_write_bytes_to_buffer(bytes: &[u8], skip_active: bool) -> RuntimeResult<usize> {
    let target = NATIVE_OUTPUT_BUFFERS.with(|buffers| {
        let buffers = buffers.borrow();
        if skip_active {
            buffers.len().checked_sub(2)
        } else {
            buffers.len().checked_sub(1)
        }
    });
    native_output_write_bytes_to_buffer_index(bytes, target)
}

fn native_output_write_bytes_to_buffer_index(
    bytes: &[u8],
    target: Option<usize>,
) -> RuntimeResult<usize> {
    let Some(target) = target else {
        let mut stdout = io::stdout();
        stdout
            .write_all(bytes)
            .and_then(|()| stdout.flush())
            .map_err(|_| {
                RuntimeError::unsupported_call("native output buffer", "native output write failed")
            })?;
        return Ok(bytes.len());
    };

    let pending_flush = NATIVE_OUTPUT_BUFFERS.with(|buffers| {
        let mut buffers = buffers.borrow_mut();
        let Some(buffer) = buffers.get_mut(target) else {
            return None;
        };
        buffer.bytes.extend_from_slice(bytes);
        if buffer.chunk_size > 0 && buffer.bytes.len() >= buffer.chunk_size {
            let bytes = std::mem::take(&mut buffer.bytes);
            let handler = buffer.handler.clone();
            let phase = native_output_buffer_handler_phase(
                buffer.handler_status.started(),
                NATIVE_OUTPUT_HANDLER_WRITE,
            );
            buffer.handler_status.mark_processed();
            Some((bytes, handler, phase))
        } else {
            None
        }
    });

    if let Some((flush_bytes, handler, phase)) = pending_flush {
        let output = if let Some(handler) = handler.as_ref() {
            unsafe {
                native_output_buffer_handler_result_bytes(
                    handler,
                    &flush_bytes,
                    phase,
                    NativeOutputBufferOperation::Flush,
                )
            }?
        } else {
            flush_bytes
        };
        native_output_write_bytes_to_buffer_index(&output, target.checked_sub(1))?;
    }

    Ok(bytes.len())
}

fn value_from_output_buffer_bytes(
    bytes: Vec<u8>,
    operation: NativeOutputBufferOperation,
) -> RuntimeResult<Value> {
    String::from_utf8(bytes).map(Value::String).map_err(|_| {
        RuntimeError::unsupported_call(
            operation.callable(),
            "captured output contains non-UTF-8 bytes; binary PHP string values need a native byte-string value representation",
        )
    })
}

#[cfg(test)]
fn native_clear_output_buffers() {
    NATIVE_OUTPUT_BUFFERS.with(|buffers| buffers.borrow_mut().clear());
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. `formatter` must be one of the
/// `NativeValueFormatterTag` discriminants. `diagnostic` may be null; when
/// non-null, it must point to writable storage for one
/// `NativeDiagnosticHandle`. On formatter-tag, null-handle, or output-write
/// failure the helper stores a diagnostic handle that the caller owns and must
/// release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_format_stdout_with_diagnostic(
    handle: NativeValueHandle,
    formatter: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> usize {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    match unsafe { native_value_format_stdout_bytes(handle, formatter) }
        .and_then(|bytes| native_output_write_bytes(&bytes))
    {
        Ok(written) => written,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            0
        }
    }
}

unsafe fn native_value_format_stdout_bytes(
    handle: NativeValueHandle,
    formatter: u8,
) -> RuntimeResult<Vec<u8>> {
    let formatter = NativeValueFormatterTag::from_tag(formatter)?;
    unsafe { native_value_format_bytes(handle, formatter) }
}

unsafe fn native_value_format_bytes(
    handle: NativeValueHandle,
    formatter: NativeValueFormatterTag,
) -> RuntimeResult<Vec<u8>> {
    let Some(value) = (unsafe { handle.as_ref() }) else {
        return Err(RuntimeError::unsupported_call(
            formatter.surface_name(),
            "native value formatting failed: value handle is null",
        ));
    };
    match formatter {
        NativeValueFormatterTag::Echo => value.try_echo_bytes(),
        NativeValueFormatterTag::PrintR => native_value_print_r_bytes(value),
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. `formatter` must be one of the
/// `NativeValueFormatterTag` discriminants. `diagnostic` may be null; when
/// non-null, it must point to writable storage for one
/// `NativeDiagnosticHandle`. On formatter-tag or null-handle failure the helper
/// stores a diagnostic handle that the caller owns and must release with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_format_string_with_diagnostic(
    handle: NativeValueHandle,
    formatter: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = NativeValueFormatterTag::from_tag(formatter).and_then(|formatter| {
        unsafe { native_value_format_bytes(handle, formatter) }.map(value_from_php_string_bytes)
    });
    match result {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `handle` and `return_mode` must be null or value handles previously
/// returned by the runtime ABI and not yet freed. `formatter` must be one of
/// the `NativeValueFormatterTag` discriminants. `diagnostic` may be null; when
/// non-null, it must point to writable storage for one `NativeDiagnosticHandle`.
/// The input handles are borrowed. The returned value handle is owned by the
/// caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_format_return_mode_with_diagnostic(
    handle: NativeValueHandle,
    formatter: u8,
    return_mode: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let should_return =
        unsafe { phpc_native_value_truthy_with_diagnostic(return_mode, diagnostic) };
    if unsafe { native_diagnostic_slot_is_set(diagnostic) } {
        return NativeValueHandle::null();
    }

    if should_return {
        return unsafe {
            phpc_native_value_format_string_with_diagnostic(handle, formatter, diagnostic)
        };
    }

    unsafe { phpc_native_value_format_stdout_with_diagnostic(handle, formatter, diagnostic) };
    if unsafe { native_diagnostic_slot_is_set(diagnostic) } {
        return NativeValueHandle::null();
    }
    NativeValueHandle::from_value(Value::Bool(true))
}

#[cfg(test)]
unsafe fn native_value_format_stdout_result<W: Write>(
    handle: NativeValueHandle,
    formatter: u8,
    writer: &mut W,
) -> RuntimeResult<usize> {
    let formatter_tag = NativeValueFormatterTag::from_tag(formatter)?;
    let output = unsafe { native_value_format_stdout_bytes(handle, formatter) }?;
    writer
        .write_all(&output)
        .and_then(|()| writer.flush())
        .map_err(|_| {
            RuntimeError::unsupported_call(
                formatter_tag.surface_name(),
                "native value formatter stdout write failed",
            )
        })?;
    Ok(output.len())
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The helper writes the current PHP echo bytes for the
/// value to stdout and returns the number of bytes written. Null handles and
/// host write failures return zero; generated code should prefer
/// `phpc_native_value_format_stdout_with_diagnostic`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_echo_stdout(handle: NativeValueHandle) -> usize {
    unsafe {
        native_value_format_stdout_bytes(handle, NativeValueFormatterTag::Echo as u8)
            .and_then(|bytes| native_output_write_bytes(&bytes))
    }
    .unwrap_or(0)
}

/// # Safety
///
/// Argument handles up to `argc` must be non-null value handles previously
/// returned by the runtime ABI and not yet freed. Missing argument handles are
/// ignored. `diagnostic` may be null; when non-null, it must point to writable
/// storage for one `NativeDiagnosticHandle`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_output_buffer_operation_with_diagnostic(
    first: NativeValueHandle,
    second: NativeValueHandle,
    third: NativeValueHandle,
    argc: u8,
    operation: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe {
        phpc_native_output_buffer_operation_with_callable_table_diagnostic(
            NativeCallableTableHandle::null(),
            first,
            second,
            third,
            argc,
            operation,
            diagnostic,
        )
    }
}

/// # Safety
///
/// `table` may be null unless `ob_start()` receives a non-null callback
/// argument naming a generated user function, method, callable array, or
/// invokable object. Argument handles up to `argc` must be non-null value
/// handles previously returned by the runtime ABI and not yet freed.
/// `diagnostic` may be null; when non-null, it must point to writable storage
/// for one `NativeDiagnosticHandle`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_output_buffer_operation_with_callable_table_diagnostic(
    table: NativeCallableTableHandle,
    first: NativeValueHandle,
    second: NativeValueHandle,
    third: NativeValueHandle,
    argc: u8,
    operation: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result: RuntimeResult<Value> = (|| {
        let operation = NativeOutputBufferOperation::from_tag(operation).ok_or_else(|| {
            RuntimeError::unsupported_call(
                "native output-buffer operation",
                "unsupported operation tag",
            )
        })?;
        let args = unsafe { native_output_buffer_args(first, second, third, argc) }?;
        native_output_buffer_operation_value(table, operation, &args)
    })();
    match result {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `diagnostic` may be null; when non-null, it must point to writable storage
/// for one `NativeDiagnosticHandle`. On handler invocation or output-write
/// failure the helper stores a diagnostic handle that the caller owns and must
/// release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_output_buffer_unwind_stack_with_diagnostic(
    diagnostic: *mut NativeDiagnosticHandle,
) -> usize {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    match native_output_buffer_unwind_stack() {
        Ok(written) => written,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            0
        }
    }
}

#[no_mangle]
pub extern "C" fn phpc_native_scalar_compare(
    left: NativeScalarValue,
    op: u8,
    right: NativeScalarValue,
) -> NativeComparisonResult {
    let operation = NativeComparisonOperation::from_opcode(op);
    let op = match operation.php_operation() {
        Ok(op) => op,
        Err(outcome) => return outcome.into_native_result(),
    };
    let left = left.to_value();
    let right = right.to_value();

    NativeComparisonOutcome::from_evaluation(evaluate_php_comparison(&left, &right, op))
        .into_native_result()
}

/// # Safety
///
/// `left` and `right` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. The returned diagnostic handle is null on
/// success; blocked comparison results own their diagnostic and callers should
/// release it with `phpc_native_comparison_result_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_compare(
    left: NativeValueHandle,
    op: u8,
    right: NativeValueHandle,
) -> NativeComparisonResult {
    unsafe { native_value_compare_outcome(left, op, right) }.into_native_result()
}

/// # Safety
///
/// `left` and `right` must be value handles previously returned by the runtime
/// ABI and not yet freed. `diagnostic` may be null; when non-null, it must
/// point to writable storage for one `NativeDiagnosticHandle`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_comparison_with_diagnostic(
    left: NativeValueHandle,
    right: NativeValueHandle,
    operation: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    match unsafe { native_value_compare_outcome(left, operation, right) } {
        NativeComparisonOutcome::Value(value) => value,
        NativeComparisonOutcome::Blocked(message) => {
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            false
        }
    }
}

/// # Safety
///
/// `left`, `right`, `left_reference`, and `right_reference` must be null or
/// handles previously returned by the runtime ABI and not yet freed. For each
/// comparison operand slot, pass either a value handle or a reference handle.
/// Reference operands are dereferenced at the comparison boundary so generated
/// backends can preserve reference ownership instead of cloning values before
/// PHP comparison semantics run.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_comparison_with_reference_slots_with_diagnostic(
    left: NativeValueHandle,
    left_reference: NativeReferenceHandle,
    right: NativeValueHandle,
    right_reference: NativeReferenceHandle,
    operation: u8,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let (left, left_owned) = match unsafe {
        native_value_reference_slot_owned_value(
            left,
            left_reference,
            "native value comparison",
            "left",
        )
    } {
        Ok(slot) => slot,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            return false;
        }
    };
    let (right, right_owned) = match unsafe {
        native_value_reference_slot_owned_value(
            right,
            right_reference,
            "native value comparison",
            "right",
        )
    } {
        Ok(slot) => slot,
        Err(error) => {
            if left_owned {
                unsafe { phpc_native_value_free(left) };
            }
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            return false;
        }
    };

    let outcome = unsafe { native_value_compare_outcome(left, operation, right) };

    if right_owned {
        unsafe { phpc_native_value_free(right) };
    }
    if left_owned {
        unsafe { phpc_native_value_free(left) };
    }

    match outcome {
        NativeComparisonOutcome::Value(value) => value,
        NativeComparisonOutcome::Blocked(message) => {
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            false
        }
    }
}

#[test]
fn native_value_comparison_reference_slots_dereference_binary_strings_and_arrays() {
    fn diagnostic_message_for_test(handle: NativeDiagnosticHandle) -> String {
        let buffer = unsafe { phpc_native_diagnostic_message_clone_bytes(handle) };
        let bytes = if buffer.ptr().is_null() {
            Vec::new()
        } else {
            unsafe { std::slice::from_raw_parts(buffer.ptr(), buffer.len()) }.to_vec()
        };
        unsafe { phpc_native_byte_buffer_free(buffer) };
        String::from_utf8(bytes).expect("runtime diagnostics should be valid UTF-8")
    }

    let left = NativeValueHandle::from_value(Value::String("A\0B".to_string()));
    let right = NativeValueHandle::from_value(Value::String("A\0B".to_string()));
    let left_reference = unsafe { phpc_native_reference_from_value_and_free(left) };
    let right_reference = unsafe { phpc_native_reference_from_value_and_free(right) };
    let mut diagnostic = NativeDiagnosticHandle::null();

    let equal = unsafe {
        phpc_native_value_comparison_with_reference_slots_with_diagnostic(
            NativeValueHandle::null(),
            left_reference,
            NativeValueHandle::null(),
            right_reference,
            NATIVE_VALUE_COMPARISON_EQ,
            &mut diagnostic,
        )
    };
    assert!(diagnostic.is_null());
    assert!(equal);

    let lower = NativeValueHandle::from_value(Value::String("A\0C".to_string()));
    let lower_reference = unsafe { phpc_native_reference_from_value_and_free(lower) };
    let less_than = unsafe {
        phpc_native_value_comparison_with_reference_slots_with_diagnostic(
            NativeValueHandle::null(),
            left_reference,
            NativeValueHandle::null(),
            lower_reference,
            NATIVE_VALUE_COMPARISON_LT,
            &mut diagnostic,
        )
    };
    assert!(diagnostic.is_null());
    assert!(less_than);

    let mut left_array = PhpArray::new();
    left_array.insert("payload", Value::String("A\0B".to_string()));
    left_array.insert("byte", Value::String("C".to_string()));
    let mut right_array = PhpArray::new();
    right_array.insert("payload", Value::String("A\0B".to_string()));
    right_array.insert("byte", Value::String("C".to_string()));
    let left_array = NativeValueHandle::from_value(Value::Array(left_array));
    let right_array = NativeValueHandle::from_value(Value::Array(right_array));
    let left_array_reference = unsafe { phpc_native_reference_from_value_and_free(left_array) };
    let strict_equal = unsafe {
        phpc_native_value_comparison_with_reference_slots_with_diagnostic(
            NativeValueHandle::null(),
            left_array_reference,
            right_array,
            NativeReferenceHandle::null(),
            NATIVE_VALUE_COMPARISON_STRICT_EQ,
            &mut diagnostic,
        )
    };
    assert!(diagnostic.is_null());
    assert!(strict_equal);

    let invalid_value = NativeValueHandle::from_value(Value::String("invalid".to_string()));
    let invalid = unsafe {
        phpc_native_value_comparison_with_reference_slots_with_diagnostic(
            invalid_value,
            left_reference,
            NativeValueHandle::null(),
            right_reference,
            NATIVE_VALUE_COMPARISON_EQ,
            &mut diagnostic,
        )
    };
    assert!(!invalid);
    assert!(diagnostic_message_for_test(diagnostic)
        .contains("left slot received both value and reference handles"));
    unsafe { phpc_native_diagnostic_free(diagnostic) };

    unsafe { phpc_native_value_free(invalid_value) };
    unsafe { phpc_native_value_free(right_array) };
    unsafe { phpc_native_reference_free(left_array_reference) };
    unsafe { phpc_native_reference_free(lower_reference) };
    unsafe { phpc_native_reference_free(right_reference) };
    unsafe { phpc_native_reference_free(left_reference) };
}

unsafe fn native_value_compare_outcome(
    left: NativeValueHandle,
    op: u8,
    right: NativeValueHandle,
) -> NativeComparisonOutcome {
    let operation = NativeComparisonOperation::from_opcode(op);
    native_value_compare_operation_outcome(left, operation, right)
}

unsafe fn native_value_compare_operation_outcome(
    left: NativeValueHandle,
    operation: NativeComparisonOperation,
    right: NativeValueHandle,
) -> NativeComparisonOutcome {
    let op = match operation.php_operation() {
        Ok(op) => op,
        Err(outcome) => return outcome,
    };
    let Some(left) = (unsafe { left.as_ref() }) else {
        return NativeComparisonOutcome::blocked_null_handle("left", "value");
    };
    let Some(right) = (unsafe { right.as_ref() }) else {
        return NativeComparisonOutcome::blocked_null_handle("right", "value");
    };

    NativeComparisonOutcome::from_evaluation(evaluate_php_comparison(left, right, op))
}

/// # Safety
///
/// `left` and `right` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. The helper consumes each unique non-null value
/// handle after producing the comparison result. The returned diagnostic handle
/// follows the same ownership contract as `phpc_native_value_compare`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_compare_and_free(
    left: NativeValueHandle,
    op: u8,
    right: NativeValueHandle,
) -> NativeComparisonResult {
    let outcome = unsafe { native_value_compare_outcome(left, op, right) };
    unsafe { phpc_native_value_free(left) };
    if left.ptr != right.ptr {
        unsafe { phpc_native_value_free(right) };
    }
    outcome.into_native_result()
}

/// # Safety
///
/// `left` and `right` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. The helper consumes each unique non-null value
/// handle, reports and frees blocked comparison diagnostics, and returns the
/// canonical branch status/value pair.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_compare_branch_and_free(
    left: NativeValueHandle,
    op: u8,
    right: NativeValueHandle,
) -> NativeComparisonBranchResult {
    let outcome = unsafe { native_value_compare_outcome(left, op, right) };
    unsafe { phpc_native_value_free(left) };
    if left.ptr != right.ptr {
        unsafe { phpc_native_value_free(right) };
    }
    outcome.into_branch_result()
}

/// # Safety
///
/// `left` and `right` must be null or value handles previously returned by the
/// runtime ABI and not yet freed. `left_diagnostic` and `right_diagnostic` must
/// be null or diagnostic handles produced while materializing those operands
/// and not yet freed. The helper consumes each diagnostic handle and each
/// unique non-null value handle. The returned diagnostic handle follows the
/// same ownership contract as `phpc_native_value_compare`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_compare_with_materialization_and_free(
    left: NativeValueHandle,
    left_diagnostic: NativeDiagnosticHandle,
    op: u8,
    right: NativeValueHandle,
    right_diagnostic: NativeDiagnosticHandle,
) -> NativeComparisonResult {
    unsafe {
        phpc_native_value_compare_operation_with_materialization_and_free(
            left,
            left_diagnostic,
            NativeComparisonOperation::from_opcode(op),
            right,
            right_diagnostic,
        )
    }
}

/// # Safety
///
/// The value and diagnostic handles follow the same ownership contract as
/// `phpc_native_value_compare_with_materialization_and_free`. `operation`
/// should be produced by `phpc_native_comparison_operation_from_opcode`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_compare_operation_with_materialization_and_free(
    left: NativeValueHandle,
    left_diagnostic: NativeDiagnosticHandle,
    operation: NativeComparisonOperation,
    right: NativeValueHandle,
    right_diagnostic: NativeDiagnosticHandle,
) -> NativeComparisonResult {
    unsafe {
        phpc_native_comparison_operand_compare_operation_and_free(
            NativeComparisonOperand::from_parts(left, left_diagnostic),
            operation,
            NativeComparisonOperand::from_parts(right, right_diagnostic),
        )
    }
}

/// # Safety
///
/// The value and diagnostic handles follow the same ownership contract as
/// `phpc_native_value_compare_with_materialization_and_free`. The helper
/// reports blocked diagnostics to stderr and returns the canonical branch
