#[derive(Debug, Clone, Default, PartialEq)]
pub struct PhpStaticPropertyDefaults {
    defaults: HashMap<(ClassId, String), Value>,
}

impl PhpStaticPropertyDefaults {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn len(&self) -> usize {
        self.defaults.len()
    }

    pub fn is_empty(&self) -> bool {
        self.defaults.is_empty()
    }

    pub fn add(
        &mut self,
        classes: &PhpClassTable,
        class_id: ClassId,
        property_name: impl Into<String>,
        value: Value,
    ) -> RuntimeResult<()> {
        let property_name = property_name.into();
        let (class, property) =
            declared_static_property_metadata(classes, class_id, &property_name)?;
        if !property.is_static() {
            return Err(RuntimeError::invalid_property_access(format!(
                "static property default {}::${} targets a non-static property",
                class.name(),
                property_name
            )));
        }

        let key = (class_id, property_name.clone());
        if self.defaults.contains_key(&key) {
            return Err(RuntimeError::invalid_property_access(format!(
                "static property default for {}::${} is already registered",
                class.name(),
                property_name
            )));
        }

        self.defaults.insert(key, value);
        Ok(())
    }

    fn default_value(&self, declaring_class_id: ClassId, property_name: &str) -> Option<Value> {
        self.defaults
            .get(&(declaring_class_id, property_name.to_string()))
            .cloned()
    }
}

#[derive(Debug, Clone, Default, PartialEq)]
pub struct PhpStaticPropertyStorage {
    cells: HashMap<(ClassId, String), PhpStaticPropertyCell>,
}

impl PhpStaticPropertyStorage {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn from_class_table(
        classes: &PhpClassTable,
        defaults: &PhpStaticPropertyDefaults,
    ) -> RuntimeResult<Self> {
        let mut storage = Self::new();
        storage.reset_from_class_table(classes, defaults)?;
        Ok(storage)
    }

    pub fn len(&self) -> usize {
        self.cells.len()
    }

    pub fn is_empty(&self) -> bool {
        self.cells.is_empty()
    }

    pub fn clear(&mut self) {
        self.cells.clear();
    }

    pub fn reset_from_class_table(
        &mut self,
        classes: &PhpClassTable,
        defaults: &PhpStaticPropertyDefaults,
    ) -> RuntimeResult<()> {
        self.cells.clear();

        for class in classes.classes() {
            for property in class
                .properties()
                .iter()
                .filter(|property| property.is_static())
            {
                let default = defaults.default_value(class.id(), property.name());
                let cell = PhpStaticPropertyCell::from_metadata(
                    class.id(),
                    class.name(),
                    property,
                    default,
                )?;
                self.cells
                    .insert((class.id(), property.name().to_string()), cell);
            }
        }

        Ok(())
    }

    pub fn read(
        &self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<Value> {
        let cell = self.resolved_cell(classes, receiver, property_name, context)?;
        cell.initialized_value_cloned()
    }

    pub fn read_for_isset(
        &self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<Option<Value>> {
        let (receiver_class_id, _) =
            resolve_static_property_receiver(classes, receiver, property_name, context)?;
        let Some((declaring_class_id, declaring_class_name, property)) =
            resolve_static_property_metadata(classes, receiver_class_id, property_name)
        else {
            return Ok(None);
        };

        ensure_static_property_visible(
            classes,
            declaring_class_id,
            &declaring_class_name,
            property.name(),
            property.visibility(),
            context,
        )?;

        let Some(cell) = self
            .cells
            .get(&(declaring_class_id, property.name().to_string()))
        else {
            return Ok(None);
        };
        if !cell.is_initialized() {
            return Ok(None);
        }

        let value = cell.value_cloned();
        Ok((!matches!(value, Value::Null)).then_some(value))
    }

    pub fn write(
        &mut self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        value: Value,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<Value> {
        self.write_with_object_type_resolver(
            classes,
            receiver,
            property_name,
            value,
            context,
            |object, type_name| object.is_instance_of_class_name(type_name),
        )
    }

    pub fn write_with_object_type_resolver<F>(
        &mut self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        value: Value,
        context: PhpStaticPropertyAccessContext,
        object_type_resolver: F,
    ) -> RuntimeResult<Value>
    where
        F: Fn(&PhpObject, &str) -> bool,
    {
        let cell = self.resolved_cell_mut(classes, receiver, property_name, context)?;
        cell.set_value_with_object_type_resolver(value, &object_type_resolver)
    }

    pub fn unset(
        &mut self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<()> {
        let cell = self.resolved_cell_mut(classes, receiver, property_name, context)?;
        cell.unset_value();
        Ok(())
    }

    pub fn reference_cell(
        &mut self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<PhpReferenceCell> {
        let cell = self.resolved_cell_mut(classes, receiver, property_name, context)?;
        cell.reference_cell()
    }

    pub fn bind_reference_cell(
        &mut self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        reference: PhpReferenceCell,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<()> {
        self.bind_reference_cell_with_object_type_resolver(
            classes,
            receiver,
            property_name,
            reference,
            context,
            |object, type_name| object.is_instance_of_class_name(type_name),
        )
    }

    pub fn bind_reference_cell_with_object_type_resolver<F>(
        &mut self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        reference: PhpReferenceCell,
        context: PhpStaticPropertyAccessContext,
        object_type_resolver: F,
    ) -> RuntimeResult<()>
    where
        F: Fn(&PhpObject, &str) -> bool,
    {
        let cell = self.resolved_cell_mut(classes, receiver, property_name, context)?;
        cell.set_reference_cell_with_object_type_resolver(reference, &object_type_resolver)
    }

    pub fn existing_reference_cell(
        &mut self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<Option<PhpReferenceCell>> {
        let cell = self.resolved_cell_mut(classes, receiver, property_name, context)?;
        cell.existing_reference_cell()
    }

    fn resolved_cell(
        &self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<&PhpStaticPropertyCell> {
        let (declaring_class_id, declaring_class_name, property_name) =
            resolve_static_property_storage_key(classes, receiver, property_name, context)?;
        self.cells
            .get(&(declaring_class_id, property_name.clone()))
            .ok_or_else(|| {
                uninitialized_static_storage_error(&declaring_class_name, &property_name)
            })
    }

    fn resolved_cell_mut(
        &mut self,
        classes: &PhpClassTable,
        receiver: PhpStaticPropertyReceiver,
        property_name: &str,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<&mut PhpStaticPropertyCell> {
        let (declaring_class_id, declaring_class_name, property_name) =
            resolve_static_property_storage_key(classes, receiver, property_name, context)?;
        self.cells
            .get_mut(&(declaring_class_id, property_name.clone()))
            .ok_or_else(|| {
                uninitialized_static_storage_error(&declaring_class_name, &property_name)
            })
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct PhpStaticPropertyCell {
    declaring_class_id: ClassId,
    declaring_class_name: String,
    name: String,
    visibility: Visibility,
    type_decl: Option<String>,
    storage: PhpStaticPropertyCellStorage,
    initialized: bool,
}

impl PhpStaticPropertyCell {
    fn from_metadata(
        declaring_class_id: ClassId,
        declaring_class_name: &str,
        property: &PhpPropertyMetadata,
        default: Option<Value>,
    ) -> RuntimeResult<Self> {
        let initialized = default.is_some() || property.type_decl().is_none();
        let mut value = default.unwrap_or(Value::Null);
        if initialized {
            value = coerce_static_property_value(
                property.type_decl(),
                value,
                declaring_class_name,
                property.name(),
            )?;
        }

        Ok(Self {
            declaring_class_id,
            declaring_class_name: declaring_class_name.to_string(),
            name: property.name().to_string(),
            visibility: property.visibility(),
            type_decl: property.type_decl().map(str::to_string),
            storage: PhpStaticPropertyCellStorage::Value(PhpValueCell::new(value)),
            initialized,
        })
    }

    pub fn declaring_class_id(&self) -> ClassId {
        self.declaring_class_id
    }

    pub fn declaring_class_name(&self) -> &str {
        &self.declaring_class_name
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn visibility(&self) -> Visibility {
        self.visibility
    }

    pub fn is_initialized(&self) -> bool {
        self.initialized
    }

    pub fn is_reference(&self) -> bool {
        matches!(self.storage, PhpStaticPropertyCellStorage::Reference(_))
    }

    pub fn reference_cell_id(&self) -> Option<PhpReferenceCellId> {
        match &self.storage {
            PhpStaticPropertyCellStorage::Value(_) => None,
            PhpStaticPropertyCellStorage::Reference(reference) => Some(reference.id()),
        }
    }

    pub fn shares_reference_with(&self, other: &Self) -> bool {
        match (&self.storage, &other.storage) {
            (
                PhpStaticPropertyCellStorage::Reference(left),
                PhpStaticPropertyCellStorage::Reference(right),
            ) => left.shares_reference_with(right),
            _ => false,
        }
    }

    fn value_cloned(&self) -> Value {
        match &self.storage {
            PhpStaticPropertyCellStorage::Value(cell) => cell.value_cloned(),
            PhpStaticPropertyCellStorage::Reference(reference) => reference.value_cloned(),
        }
    }

    fn initialized_value_cloned(&self) -> RuntimeResult<Value> {
        if self.initialized {
            Ok(self.value_cloned())
        } else {
            Err(RuntimeError::uninitialized_typed_property(
                self.declaring_class_name.clone(),
                self.name.clone(),
            ))
        }
    }

    fn set_value_with_object_type_resolver<F>(
        &mut self,
        value: Value,
        object_type_resolver: &F,
    ) -> RuntimeResult<Value>
    where
        F: Fn(&PhpObject, &str) -> bool,
    {
        let value = match &mut self.storage {
            PhpStaticPropertyCellStorage::Value(cell) => {
                let value = coerce_static_property_value_with_object_type_resolver(
                    self.type_decl.as_deref(),
                    value,
                    &self.declaring_class_name,
                    &self.name,
                    object_type_resolver,
                )?;
                cell.set_value(value.clone());
                value
            }
            PhpStaticPropertyCellStorage::Reference(reference) => {
                let value = reference.coerce_value_for_write_with_object_type_resolver(
                    value,
                    object_type_resolver,
                )?;
                reference.set_value(value.clone());
                value
            }
        };
        self.initialized = true;
        Ok(value)
    }

    fn set_reference_cell_with_object_type_resolver<F>(
        &mut self,
        reference: PhpReferenceCell,
        object_type_resolver: &F,
    ) -> RuntimeResult<()>
    where
        F: Fn(&PhpObject, &str) -> bool,
    {
        let value = coerce_static_property_value_with_object_type_resolver(
            self.type_decl.as_deref(),
            reference.value_cloned(),
            &self.declaring_class_name,
            &self.name,
            object_type_resolver,
        )?;
        if let PhpStaticPropertyCellStorage::Reference(old_reference) = &self.storage {
            old_reference.remove_property_type_constraint(
                self.type_decl.as_deref(),
                &self.declaring_class_name,
                &self.name,
            );
        }
        reference.set_value(value);
        reference.add_property_type_constraint(
            self.type_decl.as_deref(),
            &self.declaring_class_name,
            &self.name,
        );
        self.storage = PhpStaticPropertyCellStorage::Reference(reference);
        self.initialized = true;
        Ok(())
    }

    fn unset_value(&mut self) {
        if let PhpStaticPropertyCellStorage::Reference(reference) = &self.storage {
            reference.remove_property_type_constraint(
                self.type_decl.as_deref(),
                &self.declaring_class_name,
                &self.name,
            );
        }
        self.storage = PhpStaticPropertyCellStorage::Value(PhpValueCell::new(Value::Null));
        self.initialized = self.type_decl.is_none();
    }

    fn reference_cell(&mut self) -> RuntimeResult<PhpReferenceCell> {
        if !self.initialized {
            return Err(RuntimeError::uninitialized_typed_property(
                self.declaring_class_name.clone(),
                self.name.clone(),
            ));
        }

        match &self.storage {
            PhpStaticPropertyCellStorage::Reference(reference) => {
                reference.add_property_type_constraint(
                    self.type_decl.as_deref(),
                    &self.declaring_class_name,
                    &self.name,
                );
                Ok(reference.clone())
            }
            PhpStaticPropertyCellStorage::Value(cell) => {
                let reference = PhpReferenceCell::new(cell.value_cloned());
                reference.add_property_type_constraint(
                    self.type_decl.as_deref(),
                    &self.declaring_class_name,
                    &self.name,
                );
                self.storage = PhpStaticPropertyCellStorage::Reference(reference.clone());
                Ok(reference)
            }
        }
    }

    fn existing_reference_cell(&self) -> RuntimeResult<Option<PhpReferenceCell>> {
        if !self.initialized {
            return Err(RuntimeError::uninitialized_typed_property(
                self.declaring_class_name.clone(),
                self.name.clone(),
            ));
        }

        match &self.storage {
            PhpStaticPropertyCellStorage::Value(_) => Ok(None),
            PhpStaticPropertyCellStorage::Reference(reference) => Ok(Some(reference.clone())),
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
enum PhpStaticPropertyCellStorage {
    Value(PhpValueCell),
    Reference(PhpReferenceCell),
}

fn declared_static_property_metadata<'a>(
    classes: &'a PhpClassTable,
    class_id: ClassId,
    property_name: &str,
) -> RuntimeResult<(&'a PhpClassMetadata, &'a PhpPropertyMetadata)> {
    let class = classes.get(class_id).ok_or_else(|| {
        RuntimeError::invalid_property_access(format!(
            "static property class id #{} does not resolve",
            class_id.index()
        ))
    })?;
    let property = class
        .property(property_name)
        .ok_or_else(|| RuntimeError::undefined_property(class.name(), property_name))?;
    Ok((class, property))
}

fn resolve_static_property_receiver(
    classes: &PhpClassTable,
    receiver: PhpStaticPropertyReceiver,
    property_name: &str,
    context: PhpStaticPropertyAccessContext,
) -> RuntimeResult<(ClassId, String)> {
    match receiver {
        PhpStaticPropertyReceiver::Class(class_id) => classes
            .get(class_id)
            .map(|class| (class_id, class.name().to_string()))
            .ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "static property receiver class id #{} does not resolve",
                    class_id.index()
                ))
            }),
        PhpStaticPropertyReceiver::SelfClass => {
            let Some(class_id) = context.current_class_id() else {
                return Err(RuntimeError::unsupported_call(
                    format!("self::${property_name}"),
                    "self static property access requires class context",
                ));
            };
            let class = classes.get(class_id).ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "self static property class id #{} does not resolve",
                    class_id.index()
                ))
            })?;
            Ok((class_id, class.name().to_string()))
        }
        PhpStaticPropertyReceiver::ParentClass => {
            let Some(class_id) = context.current_class_id() else {
                return Err(RuntimeError::unsupported_call(
                    format!("parent::${property_name}"),
                    "parent static property access requires class context",
                ));
            };
            let class = classes.get(class_id).ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "parent static property class id #{} does not resolve",
                    class_id.index()
                ))
            })?;
            let Some(parent_id) = class.parent_id() else {
                return Err(RuntimeError::unsupported_call(
                    format!("parent::${property_name}"),
                    "parent static property access requires a parent class",
                ));
            };
            let parent = classes.get(parent_id).ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "parent static property class id #{} does not resolve",
                    parent_id.index()
                ))
            })?;
            Ok((parent_id, parent.name().to_string()))
        }
        PhpStaticPropertyReceiver::LateStaticClass => {
            let Some(class_id) = context.called_class_id() else {
                return Err(RuntimeError::unsupported_call(
                    format!("static::${property_name}"),
                    "static property access requires called class context",
                ));
            };
            let class = classes.get(class_id).ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "late static property class id #{} does not resolve",
                    class_id.index()
                ))
            })?;
            Ok((class_id, class.name().to_string()))
        }
    }
}

fn resolve_static_property_storage_key(
    classes: &PhpClassTable,
    receiver: PhpStaticPropertyReceiver,
    property_name: &str,
    context: PhpStaticPropertyAccessContext,
) -> RuntimeResult<(ClassId, String, String)> {
    let (receiver_class_id, receiver_class_name) =
        resolve_static_property_receiver(classes, receiver, property_name, context)?;
    let (declaring_class_id, declaring_class_name, property) =
        resolve_static_property_metadata(classes, receiver_class_id, property_name)
            .ok_or_else(|| RuntimeError::undefined_property(receiver_class_name, property_name))?;

    ensure_static_property_visible(
        classes,
        declaring_class_id,
        &declaring_class_name,
        property.name(),
        property.visibility(),
        context,
    )?;

    Ok((
        declaring_class_id,
        declaring_class_name,
        property.name().to_string(),
    ))
}

fn resolve_static_property_metadata<'a>(
    classes: &'a PhpClassTable,
    class_id: ClassId,
    property_name: &str,
) -> Option<(ClassId, String, &'a PhpPropertyMetadata)> {
    let mut current = Some(class_id);
    while let Some(current_id) = current {
        let class = classes.get(current_id)?;
        if let Some(property) = class.property(property_name) {
            if property.is_static() {
                return Some((current_id, class.name().to_string(), property));
            }
            return None;
        }
        current = class.parent_id();
    }

    None
}

fn ensure_static_property_visible(
    classes: &PhpClassTable,
    declaring_class_id: ClassId,
    declaring_class_name: &str,
    property_name: &str,
    visibility: Visibility,
    context: PhpStaticPropertyAccessContext,
) -> RuntimeResult<()> {
    match visibility {
        Visibility::Public => Ok(()),
        Visibility::Private if context.current_class_id() == Some(declaring_class_id) => Ok(()),
        Visibility::Protected
            if context.current_class_id().is_some_and(|current_id| {
                current_id == declaring_class_id
                    || classes.is_subclass_of(current_id, declaring_class_id)
            }) =>
        {
            Ok(())
        }
        Visibility::Private => Err(RuntimeError::unsupported_call(
            format!("{declaring_class_name}::${property_name}"),
            "private static property is not visible from the current class context",
        )),
        Visibility::Protected => Err(RuntimeError::unsupported_call(
            format!("{declaring_class_name}::${property_name}"),
            "protected static property is not visible from the current class context",
        )),
    }
}

fn coerce_static_property_value(
    type_decl: Option<&str>,
    value: Value,
    class_name: &str,
    property_name: &str,
) -> RuntimeResult<Value> {
    coerce_static_property_value_with_object_type_resolver(
        type_decl,
        value,
        class_name,
        property_name,
        &|object: &PhpObject, type_name: &str| object.is_instance_of_class_name(type_name),
    )
}

fn coerce_static_property_value_with_object_type_resolver<F>(
    type_decl: Option<&str>,
    value: Value,
    class_name: &str,
    property_name: &str,
    object_type_resolver: &F,
) -> RuntimeResult<Value>
where
    F: Fn(&PhpObject, &str) -> bool,
{
    let Some(type_decl) = type_decl else {
        return Ok(value);
    };
    coerce_property_value_with_object_type_resolver(
        type_decl,
        value,
        class_name,
        property_name,
        false,
        object_type_resolver,
    )
}

fn uninitialized_static_storage_error(
    declaring_class_name: &str,
    property_name: &str,
) -> RuntimeError {
    RuntimeError::invalid_property_access(format!(
        "static property storage for {declaring_class_name}::${property_name} has not been initialized for this request"
    ))
}

unsafe fn native_static_property_utf8_argument(
    ptr: *const u8,
    len: usize,
    label: &str,
) -> RuntimeResult<String> {
    let bytes = unsafe { native_abi_bytes(ptr, len) }.ok_or_else(|| {
        RuntimeError::invalid_property_access(format!(
            "native static-property storage received invalid {label} ABI"
        ))
    })?;
    std::str::from_utf8(bytes).map(str::to_string).map_err(|_| {
        RuntimeError::invalid_property_access(format!(
            "native static-property storage requires UTF-8 {label}"
        ))
    })
}

unsafe fn native_static_property_optional_type_decl(
    ptr: *const u8,
    len: usize,
) -> RuntimeResult<Option<String>> {
    if len == 0 {
        return Ok(None);
    }
    unsafe { native_static_property_utf8_argument(ptr, len, "property type declaration") }.map(Some)
}

unsafe fn native_static_property_take_value_and_free(
    value: NativeValueHandle,
    label: &str,
) -> RuntimeResult<Value> {
    let handle = value;
    let Some(value_ref) = (unsafe { handle.as_ref() }) else {
        unsafe { phpc_native_value_free(handle) };
        return Err(RuntimeError::invalid_property_access(format!(
            "native static-property storage received missing {label} value handle"
        )));
    };
    let value = value_ref.clone();
    unsafe { phpc_native_value_free(handle) };
    Ok(value)
}

impl NativeStaticPropertyStorage {
    fn declare_class(&mut self, class_name: String) -> RuntimeResult<()> {
        self.classes.declare_class(class_name).map(|_| ())
    }

    fn declare_parent(&mut self, class_name: &str, parent_name: &str) -> RuntimeResult<()> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        let parent_id = self
            .classes
            .lookup_class_id(parent_name)
            .ok_or_else(|| RuntimeError::undefined_class(parent_name))?;
        self.classes.set_parent(class_id, parent_id)
    }

    fn declare_property(
        &mut self,
        class_name: &str,
        property_name: String,
        visibility: Visibility,
        is_static: bool,
        type_decl: Option<String>,
    ) -> RuntimeResult<()> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        let class = self.classes.get_mut(class_id).ok_or_else(|| {
            RuntimeError::invalid_property_access(format!(
                "native static-property storage class {class_name} does not resolve"
            ))
        })?;
        let property = if is_static {
            PhpPropertyMetadata::static_property(property_name, visibility)
        } else {
            PhpPropertyMetadata::instance(property_name, visibility)
        }
        .with_type_decl(type_decl);
        class.add_property(property)
    }

    fn register_default(
        &mut self,
        class_name: &str,
        property_name: String,
        value: Value,
    ) -> RuntimeResult<()> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        self.defaults
            .add(&self.classes, class_id, property_name, value)
    }

    fn reset(&mut self) -> RuntimeResult<()> {
        self.storage
            .reset_from_class_table(&self.classes, &self.defaults)
    }

    fn read_class(&self, class_name: &str, property_name: &str) -> RuntimeResult<Value> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        self.storage.read(
            &self.classes,
            PhpStaticPropertyReceiver::Class(class_id),
            property_name,
            PhpStaticPropertyAccessContext::external(),
        )
    }

    fn read_class_for_isset(
        &self,
        class_name: &str,
        property_name: &str,
    ) -> RuntimeResult<Option<Value>> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        self.storage.read_for_isset(
            &self.classes,
            PhpStaticPropertyReceiver::Class(class_id),
            property_name,
            PhpStaticPropertyAccessContext::external(),
        )
    }

    fn write_class(
        &mut self,
        class_name: &str,
        property_name: &str,
        value: Value,
    ) -> RuntimeResult<Value> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        self.storage.write(
            &self.classes,
            PhpStaticPropertyReceiver::Class(class_id),
            property_name,
            value,
            PhpStaticPropertyAccessContext::external(),
        )
    }

    fn unset_class(&mut self, class_name: &str, property_name: &str) -> RuntimeResult<()> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        self.storage.unset(
            &self.classes,
            PhpStaticPropertyReceiver::Class(class_id),
            property_name,
            PhpStaticPropertyAccessContext::external(),
        )
    }

    fn reference_class(
        &mut self,
        class_name: &str,
        property_name: &str,
    ) -> RuntimeResult<PhpReferenceCell> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        self.storage.reference_cell(
            &self.classes,
            PhpStaticPropertyReceiver::Class(class_id),
            property_name,
            PhpStaticPropertyAccessContext::external(),
        )
    }

    fn bind_reference_class(
        &mut self,
        class_name: &str,
        property_name: &str,
        reference: PhpReferenceCell,
    ) -> RuntimeResult<()> {
        let class_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        self.storage.bind_reference_cell(
            &self.classes,
            PhpStaticPropertyReceiver::Class(class_id),
            property_name,
            reference,
            PhpStaticPropertyAccessContext::external(),
        )
    }

    fn array_path_reference_class(
        &mut self,
        class_name: &str,
        property_name: &str,
        keys: &[ArrayKey],
    ) -> RuntimeResult<PhpReferenceCell> {
        let reference = self.reference_class(class_name, property_name)?;
        reference_array_path_cell_with_root_write(&reference, keys, false, true)
    }

    fn scope_from_receiver(&self, receiver: &Value) -> RuntimeResult<String> {
        match receiver {
            Value::Object(object) => Ok(object.class_name().to_string()),
            Value::String(class_name) => {
                if self.classes.lookup_class_id(class_name).is_some() {
                    return Ok(class_name.clone());
                }

                let lookup_key = native_class_metadata_lookup_key(class_name.as_bytes());
                if let Some(target_lookup_key) =
                    native_user_class_alias_target_lookup_key(&lookup_key)
                {
                    let target = String::from_utf8(target_lookup_key).map_err(|_| {
                        RuntimeError::invalid_property_access(
                            "native static-property receiver alias target is not UTF-8".to_string(),
                        )
                    })?;
                    if self.classes.lookup_class_id(&target).is_some() {
                        return Ok(target);
                    }
                }

                Err(RuntimeError::undefined_class(class_name))
            }
            other => Err(RuntimeError::unsupported_call(
                "dynamic static property receiver",
                format!(
                    "dynamic static property receiver must be object or class string, got {}",
                    other.type_name()
                ),
            )),
        }
    }

    fn relative_receiver_and_context(
        &self,
        receiver: NativeStaticPropertyReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
    ) -> RuntimeResult<(PhpStaticPropertyReceiver, PhpStaticPropertyAccessContext)> {
        let current_class_id = self
            .classes
            .lookup_class_id(current_class_name)
            .ok_or_else(|| RuntimeError::undefined_class(current_class_name))?;
        let mut context = PhpStaticPropertyAccessContext::class_context(current_class_id);
        if let Some(called_class_name) = called_class_name {
            let called_class_id = self
                .classes
                .lookup_class_id(called_class_name)
                .ok_or_else(|| RuntimeError::undefined_class(called_class_name))?;
            context = context.with_called_class(called_class_id);
        }
        let receiver = match receiver {
            NativeStaticPropertyReceiverTag::SelfClass => PhpStaticPropertyReceiver::SelfClass,
            NativeStaticPropertyReceiverTag::ParentClass => PhpStaticPropertyReceiver::ParentClass,
            NativeStaticPropertyReceiverTag::LateStaticClass => {
                PhpStaticPropertyReceiver::LateStaticClass
            }
        };
        Ok((receiver, context))
    }

    fn read_relative(
        &self,
        receiver: NativeStaticPropertyReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
        property_name: &str,
    ) -> RuntimeResult<Value> {
        let (receiver, context) =
            self.relative_receiver_and_context(receiver, current_class_name, called_class_name)?;
        self.storage
            .read(&self.classes, receiver, property_name, context)
    }

    fn read_relative_for_isset(
        &self,
        receiver: NativeStaticPropertyReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
        property_name: &str,
    ) -> RuntimeResult<Option<Value>> {
        let (receiver, context) =
            self.relative_receiver_and_context(receiver, current_class_name, called_class_name)?;
        self.storage
            .read_for_isset(&self.classes, receiver, property_name, context)
    }

    fn write_relative(
        &mut self,
        receiver: NativeStaticPropertyReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
        property_name: &str,
        value: Value,
    ) -> RuntimeResult<Value> {
        let (receiver, context) =
            self.relative_receiver_and_context(receiver, current_class_name, called_class_name)?;
        self.storage
            .write(&self.classes, receiver, property_name, value, context)
    }

    fn unset_relative(
        &mut self,
        receiver: NativeStaticPropertyReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
        property_name: &str,
    ) -> RuntimeResult<()> {
        let (receiver, context) =
            self.relative_receiver_and_context(receiver, current_class_name, called_class_name)?;
        self.storage
            .unset(&self.classes, receiver, property_name, context)
    }

    fn reference_relative(
        &mut self,
        receiver: NativeStaticPropertyReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
        property_name: &str,
    ) -> RuntimeResult<PhpReferenceCell> {
        let (receiver, context) =
            self.relative_receiver_and_context(receiver, current_class_name, called_class_name)?;
        self.storage
            .reference_cell(&self.classes, receiver, property_name, context)
    }

    fn array_path_reference_relative(
        &mut self,
        receiver: NativeStaticPropertyReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
        property_name: &str,
        keys: &[ArrayKey],
    ) -> RuntimeResult<PhpReferenceCell> {
        let reference = self.reference_relative(
            receiver,
            current_class_name,
            called_class_name,
            property_name,
        )?;
        reference_array_path_cell_with_root_write(&reference, keys, false, true)
    }
}

impl NativeClassConstantTable {
    fn declare_class(&mut self, class_name: String) -> RuntimeResult<()> {
        self.classes.declare_class(class_name).map(|_| ())
    }

    fn declare_parent(&mut self, class_name: &str, parent_name: &str) -> RuntimeResult<()> {
        let child_id = self
            .classes
            .lookup_class_id(class_name)
            .ok_or_else(|| RuntimeError::undefined_class(class_name))?;
        let parent_id = self
            .classes
            .lookup_class_id(parent_name)
            .ok_or_else(|| RuntimeError::undefined_class(parent_name))?;
        self.classes.set_parent(child_id, parent_id)
    }

    fn class_id_for_name(&self, class_name: &str) -> RuntimeResult<ClassId> {
        if let Some(id) = self.classes.lookup_class_id(class_name) {
            return Ok(id);
        }

        let lookup_key = native_class_metadata_lookup_key(class_name.as_bytes());
        if let Some(target_lookup_key) = native_user_class_alias_target_lookup_key(&lookup_key) {
            let target = String::from_utf8(target_lookup_key).map_err(|_| {
                RuntimeError::invalid_property_access(
                    "native class-constant receiver alias target is not UTF-8".to_string(),
                )
            })?;
            if let Some(id) = self.classes.lookup_class_id(&target) {
                return Ok(id);
            }
        }

        Err(RuntimeError::undefined_class(class_name))
    }

    fn declare_constant(
        &mut self,
        class_name: &str,
        constant_name: String,
        visibility: Visibility,
        value: Value,
    ) -> RuntimeResult<()> {
        let class_id = self.class_id_for_name(class_name)?;
        let class = self.classes.get_mut(class_id).ok_or_else(|| {
            RuntimeError::invalid_property_access(format!(
                "native class-constant class {class_name} does not resolve"
            ))
        })?;
        class.add_constant(PhpClassConstantMetadata::new(&constant_name, visibility))?;
        self.values.insert((class_id, constant_name), value);
        Ok(())
    }

    fn relative_receiver_and_context(
        &self,
        receiver: NativeClassConstantReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
        constant_name: &str,
    ) -> RuntimeResult<(ClassId, PhpStaticPropertyAccessContext)> {
        let current_class_id = self.class_id_for_name(current_class_name)?;
        let mut context = PhpStaticPropertyAccessContext::class_context(current_class_id);
        if let Some(called_class_name) = called_class_name {
            let called_class_id = self.class_id_for_name(called_class_name)?;
            context = context.with_called_class(called_class_id);
        }
        let receiver_class_id = match receiver {
            NativeClassConstantReceiverTag::SelfClass => current_class_id,
            NativeClassConstantReceiverTag::ParentClass => {
                let class = self.classes.get(current_class_id).ok_or_else(|| {
                    RuntimeError::invalid_property_access(format!(
                        "parent class constant class id #{} does not resolve",
                        current_class_id.index()
                    ))
                })?;
                class.parent_id().ok_or_else(|| {
                    RuntimeError::unsupported_call(
                        format!("parent::{constant_name}"),
                        "parent class constant access requires a parent class",
                    )
                })?
            }
            NativeClassConstantReceiverTag::LateStaticClass => {
                context.called_class_id().ok_or_else(|| {
                    RuntimeError::unsupported_call(
                        format!("static::{constant_name}"),
                        "static class constant access requires called class context",
                    )
                })?
            }
        };
        Ok((receiver_class_id, context))
    }

    fn read_class(&self, class_name: &str, constant_name: &str) -> RuntimeResult<Value> {
        let class_id = self.class_id_for_name(class_name)?;
        self.read_resolved(
            class_id,
            class_name,
            constant_name,
            PhpStaticPropertyAccessContext::external(),
        )
    }

    fn scope_from_receiver(&self, receiver: &Value) -> RuntimeResult<String> {
        match receiver {
            Value::Object(object) => Ok(object.class_name().to_string()),
            Value::String(class_name) => {
                let class_id = self.class_id_for_name(class_name)?;
                self.classes
                    .get(class_id)
                    .map(|class| class.name().to_string())
                    .ok_or_else(|| {
                        RuntimeError::invalid_property_access(format!(
                            "native class-constant receiver class id #{} does not resolve",
                            class_id.index()
                        ))
                    })
            }
            other => Err(RuntimeError::unsupported_call(
                "dynamic class constant receiver",
                format!(
                    "dynamic class constant receiver must be object or class string, got {}",
                    other.type_name()
                ),
            )),
        }
    }

    fn read_relative(
        &self,
        receiver: NativeClassConstantReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
        constant_name: &str,
    ) -> RuntimeResult<Value> {
        let (class_id, context) = self.relative_receiver_and_context(
            receiver,
            current_class_name,
            called_class_name,
            constant_name,
        )?;
        let receiver_name = self
            .classes
            .get(class_id)
            .map(|class| class.name().to_string())
            .unwrap_or_else(|| current_class_name.to_string());
        self.read_resolved(class_id, &receiver_name, constant_name, context)
    }

    fn class_name_relative(
        &self,
        receiver: NativeClassConstantReceiverTag,
        current_class_name: &str,
        called_class_name: Option<&str>,
    ) -> RuntimeResult<String> {
        let (class_id, _) = self.relative_receiver_and_context(
            receiver,
            current_class_name,
            called_class_name,
            "class",
        )?;
        self.classes
            .get(class_id)
            .map(|class| class.name().to_string())
            .ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "class-name constant class id #{} does not resolve",
                    class_id.index()
                ))
            })
    }

    fn read_resolved(
        &self,
        class_id: ClassId,
        class_name: &str,
        constant_name: &str,
        context: PhpStaticPropertyAccessContext,
    ) -> RuntimeResult<Value> {
        let (declaring_class_id, declaring_class_name, metadata) = self
            .resolve_constant_metadata(class_id, constant_name)
            .ok_or_else(|| {
                RuntimeError::undefined_constant(format!("{class_name}::{constant_name}"))
            })?;
        ensure_class_constant_visible(
            &self.classes,
            declaring_class_id,
            &declaring_class_name,
            metadata.name(),
            metadata.visibility(),
            context,
        )?;
        self.values
            .get(&(declaring_class_id, metadata.name().to_string()))
            .cloned()
            .ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "native class constant {}::{} has metadata but no value",
                    declaring_class_name,
                    metadata.name()
                ))
            })
    }

    fn resolve_constant_metadata<'a>(
        &'a self,
        class_id: ClassId,
        constant_name: &str,
    ) -> Option<(ClassId, String, &'a PhpClassConstantMetadata)> {
        let origin_class_id = class_id;
        let mut current = Some(class_id);
        while let Some(current_id) = current {
            let class = self.classes.get(current_id)?;
            if let Some(metadata) = class.constant(constant_name) {
                if current_id != origin_class_id && metadata.visibility() == Visibility::Private {
                    current = class.parent_id();
                    continue;
                }
                return Some((current_id, class.name().to_string(), metadata));
            }
            current = class.parent_id();
        }
        None
    }
}

fn ensure_class_constant_visible(
    classes: &PhpClassTable,
    declaring_class_id: ClassId,
    declaring_class_name: &str,
    constant_name: &str,
    visibility: Visibility,
    context: PhpStaticPropertyAccessContext,
) -> RuntimeResult<()> {
    match visibility {
        Visibility::Public => Ok(()),
        Visibility::Private if context.current_class_id() == Some(declaring_class_id) => Ok(()),
        Visibility::Protected
            if context.current_class_id().is_some_and(|current_id| {
                current_id == declaring_class_id
                    || classes.is_subclass_of(current_id, declaring_class_id)
            }) =>
        {
            Ok(())
        }
        Visibility::Private | Visibility::Protected => {
            Err(RuntimeError::class_constant_visibility(
                declaring_class_name,
                constant_name,
                visibility,
            ))
        }
    }
}

#[no_mangle]
pub extern "C" fn phpc_native_class_constant_table_new() -> NativeClassConstantTableHandle {
    NativeClassConstantTableHandle::new()
}

/// # Safety
///
/// `handle` must be null or a class-constant table handle previously returned
/// by the runtime ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_constant_table_free(
    handle: NativeClassConstantTableHandle,
) {
    if handle.ptr.is_null() {
        return;
    }
    drop(unsafe { Box::from_raw(handle.ptr) });
}

/// # Safety
///
/// `handle` must be a table handle. Class bytes must be null only when their
/// length is zero. The diagnostic slot is overwritten on failure.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_constant_declare_class_bytes(
    mut handle: NativeClassConstantTableHandle,
    class_ptr: *const u8,
    class_len: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| {
        let table = unsafe { handle.as_mut() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "native class-constant table handle is null".to_string(),
            )
        })?;
        let class_name =
            unsafe { native_static_property_utf8_argument(class_ptr, class_len, "class name") }?;
        table.declare_class(class_name)
    })();
    match result {
        Ok(()) => true,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
///
/// `handle` must be a table handle. Class and parent bytes follow the same
/// pointer/length rules as class declaration.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_constant_declare_class_parent_bytes(
    mut handle: NativeClassConstantTableHandle,
    class_ptr: *const u8,
    class_len: usize,
    parent_ptr: *const u8,
    parent_len: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| {
        let table = unsafe { handle.as_mut() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "native class-constant table handle is null".to_string(),
            )
        })?;
        let class_name =
            unsafe { native_static_property_utf8_argument(class_ptr, class_len, "class name") }?;
        let parent_name = unsafe {
            native_static_property_utf8_argument(parent_ptr, parent_len, "parent class name")
        }?;
        table.declare_parent(&class_name, &parent_name)
    })();
    match result {
        Ok(()) => true,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
///
/// `handle` must be a table handle. Class/constant bytes follow the same
/// pointer/length rules as class declaration. `value` is always consumed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_constant_declare_constant_bytes_and_free(
    mut handle: NativeClassConstantTableHandle,
    class_ptr: *const u8,
    class_len: usize,
    constant_ptr: *const u8,
    constant_len: usize,
    visibility: u8,
    value: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| {
        let value = unsafe { native_static_property_take_value_and_free(value, "class constant") }?;
        let table = unsafe { handle.as_mut() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "native class-constant table handle is null".to_string(),
            )
        })?;
        let class_name =
            unsafe { native_static_property_utf8_argument(class_ptr, class_len, "class name") }?;
        let constant_name = unsafe {
            native_static_property_utf8_argument(constant_ptr, constant_len, "constant name")
        }?;
        let visibility = native_declared_class_property_visibility(visibility).ok_or_else(|| {
            RuntimeError::invalid_property_access(format!(
                "native class-constant table received unsupported constant visibility tag {visibility}"
            ))
        })?;
        table.declare_constant(&class_name, constant_name, visibility, value)
    })();
    match result {
        Ok(()) => true,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
///
/// `handle` must be a table handle. Class and constant bytes follow the same
/// pointer/length rules as class declaration. Returned values are owned by the
/// caller and must be freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_constant_read_class_with_diagnostic(
    handle: NativeClassConstantTableHandle,
    class_ptr: *const u8,
    class_len: usize,
    constant_ptr: *const u8,
    constant_len: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| {
        let table = unsafe { handle.as_ref() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "native class-constant table handle is null".to_string(),
            )
        })?;
        let class_name =
            unsafe { native_static_property_utf8_argument(class_ptr, class_len, "class name") }?;
        let constant_name = unsafe {
            native_static_property_utf8_argument(constant_ptr, constant_len, "constant name")
        }?;
        table.read_class(&class_name, &constant_name)
    })();
    match result {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `handle`, `receiver`, and `diagnostic` must be valid according to the
/// runtime ABI. The receiver is always consumed. Returns an owned class-scope
/// string for dynamic class-constant access when the receiver is an object or
/// declared class string.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_constant_scope_from_receiver_with_diagnostic_and_free(
    handle: NativeClassConstantTableHandle,
    receiver: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeStringHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| -> RuntimeResult<NativeStringHandle> {
        let table = unsafe { handle.as_ref() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "native class-constant table handle is null".to_string(),
            )
        })?;
        let receiver_value = unsafe { receiver.as_ref() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "dynamic class constant receiver handle is null".to_string(),
            )
        })?;
        table
            .scope_from_receiver(receiver_value)
            .map(|scope| NativeStringHandle::from_vec(scope.into_bytes()))
    })();
    unsafe { phpc_native_value_free(receiver) };

    match result {
        Ok(scope) => scope,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeStringHandle::null()
        }
    }
}

/// # Safety
///
/// `handle` must be a table handle. Current/called class and constant bytes
/// follow the same pointer/length rules as class declaration. Returned values
/// are owned by the caller and must be freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_constant_read_relative_with_diagnostic(
    handle: NativeClassConstantTableHandle,
    receiver_tag: u8,
    current_class_ptr: *const u8,
    current_class_len: usize,
    called_class_ptr: *const u8,
    called_class_len: usize,
    constant_ptr: *const u8,
    constant_len: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| {
        let table = unsafe { handle.as_ref() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "native class-constant table handle is null".to_string(),
            )
        })?;
        let receiver =
            NativeClassConstantReceiverTag::from_abi_tag(receiver_tag).ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "native class-constant table received unsupported relative receiver tag {receiver_tag}"
                ))
            })?;
        let current_class_name = unsafe {
            native_static_property_utf8_argument(
                current_class_ptr,
                current_class_len,
                "current class name",
            )
        }?;
        let called_class_name = unsafe {
            native_static_property_optional_utf8_argument(
                called_class_ptr,
                called_class_len,
                "called class name",
            )
        }?;
        let constant_name = unsafe {
            native_static_property_utf8_argument(constant_ptr, constant_len, "constant name")
        }?;
        table.read_relative(
            receiver,
            &current_class_name,
            called_class_name.as_deref(),
            &constant_name,
        )
    })();
    match result {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `handle` must be a table handle. Current/called class bytes follow the
/// same pointer/length rules as class declaration.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_class_constant_class_name_relative_with_diagnostic(
    handle: NativeClassConstantTableHandle,
    receiver_tag: u8,
    current_class_ptr: *const u8,
    current_class_len: usize,
    called_class_ptr: *const u8,
    called_class_len: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeStringHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| {
        let table = unsafe { handle.as_ref() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "native class-constant table handle is null".to_string(),
            )
        })?;
        let receiver =
            NativeClassConstantReceiverTag::from_abi_tag(receiver_tag).ok_or_else(|| {
                RuntimeError::invalid_property_access(format!(
                    "native class-constant table received unsupported class-name receiver tag {receiver_tag}"
                ))
            })?;
        let current_class_name = unsafe {
            native_static_property_utf8_argument(
                current_class_ptr,
                current_class_len,
                "current class name",
            )
        }?;
        let called_class_name = unsafe {
            native_static_property_optional_utf8_argument(
                called_class_ptr,
                called_class_len,
                "called class name",
            )
        }?;
        table.class_name_relative(receiver, &current_class_name, called_class_name.as_deref())
    })();
    match result {
        Ok(class_name) => NativeStringHandle::from_vec(class_name.into_bytes()),
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeStringHandle::null()
        }
    }
}

/// # Safety
///
/// `storage`, `receiver`, and `diagnostic` must be valid according to the
/// runtime ABI. The receiver is always consumed. Returns an owned class-scope
/// string for dynamic static-property access when the receiver is an object or
/// declared class string.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_static_property_scope_from_receiver_with_diagnostic_and_free(
    storage: NativeStaticPropertyStorageHandle,
    receiver: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeStringHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| -> RuntimeResult<NativeStringHandle> {
        let storage = unsafe { storage.as_ref() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "native static-property storage handle is null".to_string(),
            )
        })?;
        let receiver_value = unsafe { receiver.as_ref() }.ok_or_else(|| {
            RuntimeError::invalid_property_access(
                "dynamic static property receiver handle is null".to_string(),
            )
        })?;
        storage
            .scope_from_receiver(receiver_value)
            .map(|scope| NativeStringHandle::from_vec(scope.into_bytes()))
    })();
    unsafe { phpc_native_value_free(receiver) };

    match result {
        Ok(scope) => scope,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeStringHandle::null()
        }
    }
}

/// # Safety
///
/// `value` and `diagnostic` must be valid according to the runtime ABI. The
/// value is always consumed. Returns an owned UTF-8 property-name string for
/// computed static-property access.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_static_property_name_from_value_with_diagnostic_and_free(
    value: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeStringHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };
    let result = (|| -> RuntimeResult<NativeStringHandle> {
        let bytes = unsafe { native_value_to_string_bytes(value) }?;
        if bytes.is_empty() {
            return Err(RuntimeError::invalid_property_access(
                "dynamic static property name cannot be empty".to_string(),
            ));
        }
        String::from_utf8(bytes.clone()).map_err(|_| {
            RuntimeError::invalid_property_access(
                "dynamic static property name must be valid UTF-8".to_string(),
            )
        })?;
        Ok(NativeStringHandle::from_vec(bytes))
    })();
    unsafe { phpc_native_value_free(value) };

    match result {
        Ok(name) => name,
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeStringHandle::null()
        }
    }
}

