/// corresponding count. Type-declaration entries may be null only when the
/// matching length is zero. Default value handles are borrowed and cloned into
/// object storage; callers retain ownership of every handle and must free them
/// after this call.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_new_declared_class_with_relationships_and_property_metadata_and_diagnostic(
    class_id: usize,
    class_name: *const u8,
    class_name_len: usize,
    property_declaring_class_ids: *const usize,
    property_declaring_class_names: *const *const u8,
    property_declaring_class_name_lens: *const usize,
    property_names: *const *const u8,
    property_name_lens: *const usize,
    property_visibilities: *const u8,
    property_type_decls: *const *const u8,
    property_type_decl_lens: *const usize,
    property_default_values: *const NativeValueHandle,
    property_default_flags: *const u8,
    property_count: usize,
    ancestor_class_names: *const *const u8,
    ancestor_class_name_lens: *const usize,
    ancestor_class_count: usize,
    interface_names: *const *const u8,
    interface_name_lens: *const usize,
    interface_count: usize,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    match unsafe {
        native_value_new_declared_class_with_ancestors(
            class_id,
            class_name,
            class_name_len,
            property_declaring_class_ids,
            property_declaring_class_names,
            property_declaring_class_name_lens,
            property_names,
            property_name_lens,
            property_visibilities,
            property_type_decls,
            property_type_decl_lens,
            property_default_values,
            property_default_flags,
            property_count,
            ancestor_class_names,
            ancestor_class_name_lens,
            ancestor_class_count,
            interface_names,
            interface_name_lens,
            interface_count,
        )
    } {
        Ok(value) => NativeValueHandle::from_value(value),
        Err(message) => {
            unsafe { native_store_diagnostic_message(diagnostic, message) };
            NativeValueHandle::null()
        }
    }
}

unsafe fn native_value_new_declared_class(
    class_id: usize,
    class_name: *const u8,
    class_name_len: usize,
    property_names: *const *const u8,
    property_name_lens: *const usize,
    property_visibilities: *const u8,
    property_count: usize,
) -> Result<Value, String> {
    let class_name_bytes =
        unsafe { native_abi_bytes(class_name, class_name_len) }.ok_or_else(|| {
            "native declared class allocation received invalid class-name ABI".to_string()
        })?;
    let class_name = std::str::from_utf8(class_name_bytes)
        .map_err(|_| "native declared class allocation requires UTF-8 class names".to_string())?;
    if class_name.is_empty() {
        return Err("native declared class allocation requires a non-empty class name".to_string());
    }

    let property_names =
        unsafe { native_abi_slice(property_names, property_count) }.ok_or_else(|| {
            "native declared class allocation received invalid property-name ABI".to_string()
        })?;
    let property_name_lens = unsafe { native_abi_slice(property_name_lens, property_count) }
        .ok_or_else(|| {
            "native declared class allocation received invalid property-name length ABI".to_string()
        })?;
    let property_visibilities = unsafe { native_abi_slice(property_visibilities, property_count) }
        .ok_or_else(|| {
            "native declared class allocation received invalid property-visibility ABI".to_string()
        })?;

    let mut class = PhpClassMetadata::new(ClassId(class_id), class_name.to_string());
    for index in 0..property_count {
        let name_bytes =
            unsafe { native_abi_bytes(property_names[index], property_name_lens[index]) }
                .ok_or_else(|| {
                    "native declared class allocation received invalid property-name bytes"
                        .to_string()
                })?;
        let property_name = std::str::from_utf8(name_bytes).map_err(|_| {
            "native declared class allocation requires UTF-8 property names".to_string()
        })?;
        if property_name.is_empty() {
            return Err(
                "native declared class allocation requires non-empty property names".to_string(),
            );
        }

        let visibility = match property_visibilities[index] {
            NATIVE_DECLARED_CLASS_PROPERTY_PUBLIC => Visibility::Public,
            NATIVE_DECLARED_CLASS_PROPERTY_PROTECTED => Visibility::Protected,
            NATIVE_DECLARED_CLASS_PROPERTY_PRIVATE => Visibility::Private,
            tag => {
                return Err(format!(
                    "native declared class allocation received unsupported property visibility tag {tag}"
                ))
            }
        };

        class
            .add_property(PhpPropertyMetadata::instance(property_name, visibility))
            .map_err(|error| error.message().to_string())?;
    }

    Ok(Value::Object(PhpObject::from_class(&class)))
}

unsafe fn native_value_new_declared_class_with_ancestors(
    class_id: usize,
    class_name: *const u8,
    class_name_len: usize,
    property_declaring_class_ids: *const usize,
    property_declaring_class_names: *const *const u8,
    property_declaring_class_name_lens: *const usize,
    property_names: *const *const u8,
    property_name_lens: *const usize,
    property_visibilities: *const u8,
    property_type_decls: *const *const u8,
    property_type_decl_lens: *const usize,
    property_default_values: *const NativeValueHandle,
    property_default_flags: *const u8,
    property_count: usize,
    ancestor_class_names: *const *const u8,
    ancestor_class_name_lens: *const usize,
    ancestor_class_count: usize,
    interface_names: *const *const u8,
    interface_name_lens: *const usize,
    interface_count: usize,
) -> Result<Value, String> {
    let class_name = unsafe {
        native_declared_class_utf8_name(
            class_name,
            class_name_len,
            "class-name",
            "native declared class inheritance allocation",
        )
    }?;
    if class_name.is_empty() {
        return Err(
            "native declared class inheritance allocation requires a non-empty class name"
                .to_string(),
        );
    }

    let property_declaring_class_ids =
        unsafe { native_abi_slice(property_declaring_class_ids, property_count) }.ok_or_else(
            || {
                "native declared class inheritance allocation received invalid property declaring-class id ABI"
                    .to_string()
            },
        )?;
    let property_declaring_class_names =
        unsafe { native_abi_slice(property_declaring_class_names, property_count) }.ok_or_else(
            || {
                "native declared class inheritance allocation received invalid property declaring-class name ABI"
                    .to_string()
            },
        )?;
    let property_declaring_class_name_lens =
        unsafe { native_abi_slice(property_declaring_class_name_lens, property_count) }
            .ok_or_else(|| {
                "native declared class inheritance allocation received invalid property declaring-class name length ABI"
                    .to_string()
            })?;
    let property_names =
        unsafe { native_abi_slice(property_names, property_count) }.ok_or_else(|| {
            "native declared class inheritance allocation received invalid property-name ABI"
                .to_string()
        })?;
    let property_name_lens = unsafe { native_abi_slice(property_name_lens, property_count) }
        .ok_or_else(|| {
            "native declared class inheritance allocation received invalid property-name length ABI"
                .to_string()
        })?;
    let property_visibilities = unsafe { native_abi_slice(property_visibilities, property_count) }
        .ok_or_else(|| {
            "native declared class inheritance allocation received invalid property-visibility ABI"
                .to_string()
        })?;
    let property_type_decls = if property_type_decls.is_null() && property_type_decl_lens.is_null()
    {
        None
    } else if property_type_decls.is_null() || property_type_decl_lens.is_null() {
        return Err(
            "native declared class inheritance allocation received partial property-type ABI"
                .to_string(),
        );
    } else {
        let decls =
            unsafe { native_abi_slice(property_type_decls, property_count) }.ok_or_else(|| {
                "native declared class inheritance allocation received invalid property-type ABI"
                    .to_string()
            })?;
        let lens = unsafe { native_abi_slice(property_type_decl_lens, property_count) }
            .ok_or_else(|| {
                "native declared class inheritance allocation received invalid property-type length ABI"
                    .to_string()
            })?;
        Some((decls, lens))
    };
    let property_defaults = if property_default_values.is_null() && property_default_flags.is_null()
    {
        None
    } else if property_default_values.is_null() || property_default_flags.is_null() {
        return Err(
            "native declared class inheritance allocation received partial property-default ABI"
                .to_string(),
        );
    } else {
        let values = unsafe { native_abi_slice(property_default_values, property_count) }
            .ok_or_else(|| {
                "native declared class inheritance allocation received invalid property-default value ABI"
                    .to_string()
            })?;
        let flags = unsafe { native_abi_slice(property_default_flags, property_count) }
            .ok_or_else(|| {
                "native declared class inheritance allocation received invalid property-default flag ABI"
                    .to_string()
            })?;
        Some((values, flags))
    };
    let ancestor_class_names =
        unsafe { native_abi_slice(ancestor_class_names, ancestor_class_count) }.ok_or_else(
            || {
                "native declared class inheritance allocation received invalid ancestor-name ABI"
                    .to_string()
            },
        )?;
    let ancestor_class_name_lens = unsafe {
        native_abi_slice(ancestor_class_name_lens, ancestor_class_count)
    }
    .ok_or_else(|| {
        "native declared class inheritance allocation received invalid ancestor-name length ABI"
            .to_string()
    })?;
    let interface_names = unsafe { native_abi_slice(interface_names, interface_count) }
        .ok_or_else(|| {
            "native declared class inheritance allocation received invalid interface-name ABI"
                .to_string()
        })?;
    let interface_name_lens = unsafe { native_abi_slice(interface_name_lens, interface_count) }
        .ok_or_else(|| {
            "native declared class inheritance allocation received invalid interface-name length ABI"
                .to_string()
        })?;

    let mut class = PhpClassMetadata::new(ClassId(class_id), class_name.clone());
    let mut inherited_properties = Vec::new();
    let mut default_assignments = Vec::new();
    for index in 0..property_count {
        let declaring_class_name = unsafe {
            native_declared_class_utf8_name(
                property_declaring_class_names[index],
                property_declaring_class_name_lens[index],
                "property declaring-class name",
                "native declared class inheritance allocation",
            )
        }?;
        if declaring_class_name.is_empty() {
            return Err(
                "native declared class inheritance allocation requires non-empty property declaring-class names"
                    .to_string(),
            );
        }
        let property_name = unsafe {
            native_declared_class_utf8_name(
                property_names[index],
                property_name_lens[index],
                "property-name",
                "native declared class inheritance allocation",
            )
        }?;
        if property_name.is_empty() {
            return Err(
                "native declared class inheritance allocation requires non-empty property names"
                    .to_string(),
            );
        }

        let visibility = native_declared_class_property_visibility(property_visibilities[index])
            .ok_or_else(|| {
                format!(
                    "native declared class inheritance allocation received unsupported property visibility tag {}",
                    property_visibilities[index]
                )
            })?;
        let type_decl = if let Some((type_decls, type_lens)) = property_type_decls {
            let type_len = type_lens[index];
            if type_len == 0 {
                None
            } else {
                let type_bytes =
                    unsafe { native_abi_bytes(type_decls[index], type_len) }.ok_or_else(|| {
                        "native declared class inheritance allocation received invalid property-type bytes"
                            .to_string()
                    })?;
                let type_decl = std::str::from_utf8(type_bytes).map_err(|_| {
                    "native declared class inheritance allocation requires UTF-8 property type declarations"
                        .to_string()
                })?;
                if type_decl.is_empty() {
                    return Err(
                        "native declared class inheritance allocation requires non-empty property type declarations"
                            .to_string(),
                    );
                }
                Some(type_decl.to_string())
            }
        } else {
            None
        };
        let property = PhpPropertyMetadata::instance(property_name.clone(), visibility)
            .with_type_decl(type_decl);
        let declaring_class_id = ClassId(property_declaring_class_ids[index]);
        if let Some((default_values, default_flags)) = property_defaults {
            match default_flags[index] {
                0 => {}
                1 => {
                    let Some(default) = (unsafe { default_values[index].as_ref() }) else {
                        return Err(
                            "native declared class inheritance allocation received null property-default value handle"
                                .to_string(),
                        );
                    };
                    default_assignments.push((
                        declaring_class_id,
                        property_name.to_string(),
                        default.clone(),
                    ));
                }
                tag => {
                    return Err(format!(
                        "native declared class inheritance allocation received unsupported property-default flag {tag}"
                    ));
                }
            }
        }
        if declaring_class_id == ClassId(class_id)
            && declaring_class_name.eq_ignore_ascii_case(&class_name)
        {
            class
                .add_property(property)
                .map_err(|error| error.message().to_string())?;
        } else {
            inherited_properties.push(PhpObjectPropertyInitializer::new(
                declaring_class_id,
                declaring_class_name,
                property,
            ));
        }
    }

    let mut ancestors = Vec::with_capacity(ancestor_class_count);
    for index in 0..ancestor_class_count {
        let ancestor = unsafe {
            native_declared_class_utf8_name(
                ancestor_class_names[index],
                ancestor_class_name_lens[index],
                "ancestor class name",
                "native declared class inheritance allocation",
            )
        }?;
        if ancestor.is_empty() {
            return Err(
                "native declared class inheritance allocation requires non-empty ancestor names"
                    .to_string(),
            );
        }
        ancestors.push(ancestor);
    }

    let mut interfaces = Vec::with_capacity(interface_count);
    for index in 0..interface_count {
        let interface = unsafe {
            native_declared_class_utf8_name(
                interface_names[index],
                interface_name_lens[index],
                "interface name",
                "native declared class inheritance allocation",
            )
        }?;
        if interface.is_empty() {
            return Err(
                "native declared class inheritance allocation requires non-empty interface names"
                    .to_string(),
            );
        }
        interfaces.push(interface);
    }

    let object = PhpObject::from_class_with_relationship_metadata_with_id(
        &class,
        &inherited_properties,
        ancestors,
        interfaces,
        NEXT_OBJECT_ID.fetch_add(1, AtomicOrdering::Relaxed),
    );
    for (declaring_class_id, property_name, default) in default_assignments {
        object
            .write_property_from_context(
                &property_name,
                default,
                Some(declaring_class_id),
                &[declaring_class_id],
            )
            .map_err(|error| error.message().to_string())?;
    }

    Ok(Value::Object(object))
}

unsafe fn native_declared_class_utf8_name(
    name: *const u8,
    name_len: usize,
    label: &str,
    context: &str,
) -> Result<String, String> {
    let bytes = unsafe { native_abi_bytes(name, name_len) }
        .ok_or_else(|| format!("{context} received invalid {label} ABI"))?;
    std::str::from_utf8(bytes)
        .map(str::to_string)
        .map_err(|_| format!("{context} requires UTF-8 {label}s"))
}

fn native_declared_class_property_visibility(tag: u8) -> Option<Visibility> {
    match tag {
        NATIVE_DECLARED_CLASS_PROPERTY_PUBLIC => Some(Visibility::Public),
        NATIVE_DECLARED_CLASS_PROPERTY_PROTECTED => Some(Visibility::Protected),
        NATIVE_DECLARED_CLASS_PROPERTY_PRIVATE => Some(Visibility::Private),
        _ => None,
    }
}

fn native_class_metadata_lookup_key(bytes: &[u8]) -> Vec<u8> {
    bytes
        .strip_prefix(b"\\")
        .unwrap_or(bytes)
        .iter()
        .map(|byte| byte.to_ascii_lowercase())
        .collect()
}

fn native_core_class_canonical_name_for_lookup_key(
    classes: &PhpClassTable,
    lookup_key: &[u8],
) -> Option<Vec<u8>> {
    classes
        .classes()
        .iter()
        .find(|class| native_class_metadata_lookup_key(class.name().as_bytes()) == lookup_key)
        .map(|class| class.name().as_bytes().to_vec())
}

fn native_user_class_canonical_name_for_lookup_key(lookup_key: &[u8]) -> Option<Vec<u8>> {
    NATIVE_USER_CLASSES.with(|classes| {
        classes
            .borrow()
            .iter()
            .find(|class| class.lookup_key == lookup_key)
            .map(|class| class.name.clone())
    })
}

fn native_class_lookup_key_exists_without_alias(
    classes: &PhpClassTable,
    lookup_key: &[u8],
) -> bool {
    native_core_class_canonical_name_for_lookup_key(classes, lookup_key).is_some()
        || native_user_class_canonical_name_for_lookup_key(lookup_key).is_some()
}

fn native_user_class_alias_target_lookup_key(alias_lookup_key: &[u8]) -> Option<Vec<u8>> {
    NATIVE_USER_CLASS_ALIASES.with(|aliases| {
        let aliases = aliases.borrow();
        let mut current = alias_lookup_key.to_vec();
        let mut visited = HashSet::new();
        loop {
            if !visited.insert(current.clone()) {
                return None;
            }
            let Some(alias) = aliases.iter().find(|alias| alias.lookup_key == current) else {
                return (current != alias_lookup_key).then_some(current);
            };
            current = alias.target_lookup_key.clone();
        }
    })
}

fn native_class_lookup_key_for_name(classes: &PhpClassTable, name: &[u8]) -> Option<Vec<u8>> {
    let lookup_key = native_class_metadata_lookup_key(name);
    if native_class_lookup_key_exists_without_alias(classes, &lookup_key) {
        return Some(lookup_key);
    }

    let target_lookup_key = native_user_class_alias_target_lookup_key(&lookup_key)?;
    native_class_lookup_key_exists_without_alias(classes, &target_lookup_key)
        .then_some(target_lookup_key)
}

fn native_user_trait_canonical_name_for_lookup_key(lookup_key: &[u8]) -> Option<Vec<u8>> {
    NATIVE_USER_TRAITS.with(|traits| {
        traits
            .borrow()
            .iter()
            .find(|trait_decl| trait_decl.lookup_key == lookup_key)
            .map(|trait_decl| trait_decl.name.clone())
    })
}

fn native_user_trait_canonical_name_bytes(name: &[u8]) -> Option<Vec<u8>> {
    let lookup_key = native_class_metadata_lookup_key(name);
    native_user_trait_canonical_name_for_lookup_key(&lookup_key)
}

fn native_user_interface_canonical_name_for_lookup_key(lookup_key: &[u8]) -> Option<Vec<u8>> {
    NATIVE_USER_INTERFACES.with(|interfaces| {
        interfaces
            .borrow()
            .iter()
            .find(|interface| interface.lookup_key == lookup_key)
            .map(|interface| interface.name.clone())
    })
}

fn native_user_interface_canonical_name_bytes(name: &[u8]) -> Option<Vec<u8>> {
    let lookup_key = native_class_metadata_lookup_key(name);
    native_user_interface_canonical_name_for_lookup_key(&lookup_key)
}

fn native_core_interface_canonical_name_bytes(name: &[u8]) -> Option<Vec<u8>> {
    const CORE_INTERFACES: &[&[u8]] = &[
        b"Traversable",
        b"IteratorAggregate",
        b"Iterator",
        b"Serializable",
        b"ArrayAccess",
        b"Countable",
        b"Stringable",
        b"SplObserver",
        b"SplSubject",
        b"DateTimeInterface",
    ];

    let lookup_key = native_class_metadata_lookup_key(name);
    CORE_INTERFACES
        .iter()
        .find(|interface| native_class_metadata_lookup_key(interface) == lookup_key)
        .map(|interface| interface.to_vec())
}

fn native_interface_canonical_name_bytes(name: &[u8]) -> Option<Vec<u8>> {
    native_user_interface_canonical_name_bytes(name)
        .or_else(|| native_core_interface_canonical_name_bytes(name))
}

fn native_user_trait_names_bytes() -> Vec<Vec<u8>> {
    NATIVE_USER_TRAITS.with(|traits| {
        traits
            .borrow()
            .iter()
            .map(|trait_decl| trait_decl.name.clone())
            .collect()
    })
}

fn native_declare_user_trait_bytes_result(bytes: &[u8]) -> bool {
    let lookup_key = native_class_metadata_lookup_key(bytes);
    let core_classes = PhpClassTable::with_core_classes();
    if native_class_lookup_key_exists_without_alias(&core_classes, &lookup_key)
        || native_user_class_alias_target_lookup_key(&lookup_key).is_some()
        || native_user_trait_canonical_name_for_lookup_key(&lookup_key).is_some()
    {
        return false;
    }

    NATIVE_USER_TRAITS.with(|traits| {
        traits.borrow_mut().push(NativeUserTraitMetadata {
            name: bytes.to_vec(),
            lookup_key,
        });
        true
    })
}

fn native_declare_user_class_bytes_result(bytes: &[u8]) -> bool {
    let lookup_key = native_class_metadata_lookup_key(bytes);
    let core_classes = PhpClassTable::with_core_classes();
    if native_class_lookup_key_exists_without_alias(&core_classes, &lookup_key)
        || native_user_class_alias_target_lookup_key(&lookup_key).is_some()
    {
        return false;
    }

    NATIVE_USER_CLASSES.with(|classes| {
        let mut classes = classes.borrow_mut();
        classes.push(NativeUserClassMetadata {
            name: bytes.to_vec(),
            lookup_key,
            parent: None,
            interfaces: Vec::new(),
            methods: Vec::new(),
            properties: Vec::new(),
            traits: Vec::new(),
        });
        true
    })
}

fn native_declare_user_interface_bytes_result(bytes: &[u8]) -> bool {
    let lookup_key = native_class_metadata_lookup_key(bytes);
    NATIVE_USER_INTERFACES.with(|interfaces| {
        let mut interfaces = interfaces.borrow_mut();
        if interfaces
            .iter()
            .any(|interface| interface.lookup_key == lookup_key)
        {
            return false;
        }
        interfaces.push(NativeUserInterfaceMetadata {
            name: bytes.to_vec(),
            lookup_key,
        });
        true
    })
}

fn native_declare_user_class_interface_bytes_result(class: &[u8], interface: &[u8]) -> bool {
    let class_key = native_class_metadata_lookup_key(class);
    let interface_key = native_class_metadata_lookup_key(interface);
    NATIVE_USER_CLASSES.with(|classes| {
        let mut classes = classes.borrow_mut();
        let Some(class) = classes
            .iter_mut()
            .find(|class| class.lookup_key == class_key)
        else {
            return false;
        };
        if class
            .interfaces
            .iter()
            .any(|candidate| native_class_metadata_lookup_key(candidate) == interface_key)
        {
            return false;
        }
        class.interfaces.push(interface.to_vec());
        true
    })
}

fn native_declare_user_class_trait_bytes_result(class: &[u8], trait_name: &[u8]) -> bool {
    let class_key = native_class_metadata_lookup_key(class);
    let trait_key = native_class_metadata_lookup_key(trait_name);
    NATIVE_USER_CLASSES.with(|classes| {
        let mut classes = classes.borrow_mut();
        let Some(class) = classes
            .iter_mut()
            .find(|class| class.lookup_key == class_key)
        else {
            return false;
        };
        if class
            .traits
            .iter()
            .any(|candidate| native_class_metadata_lookup_key(candidate) == trait_key)
        {
            return true;
        }
        class.traits.push(trait_name.to_vec());
        true
    })
}

/// # Safety
///
/// `ptr` must be null only when `len == 0`, or point to at least `len`
/// readable bytes. The declared name is stored as PHP class-name bytes for the
/// generated userland metadata registry.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_declare_user_class_bytes(ptr: *const u8, len: usize) -> bool {
    let result: Result<bool, ()> = (|| unsafe {
        let bytes = native_abi_bytes(ptr, len).ok_or(())?;
        Ok(native_declare_user_class_bytes_result(bytes))
    })();
    result.unwrap_or(false)
}

/// # Safety
///
/// `ptr` follows the same pointer/length rules as
/// `phpc_native_declare_user_class_bytes`. The declared name is stored in the
/// generated userland interface metadata registry.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_declare_user_interface_bytes(
    ptr: *const u8,
    len: usize,
) -> bool {
    let result: Result<bool, ()> = (|| unsafe {
        let bytes = native_abi_bytes(ptr, len).ok_or(())?;
        Ok(native_declare_user_interface_bytes_result(bytes))
    })();
    result.unwrap_or(false)
}

/// # Safety
///
/// `ptr` follows the same pointer/length rules as
/// `phpc_native_declare_user_class_bytes`. The declared name is stored as PHP
/// trait-name bytes for the generated userland metadata registry.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_declare_user_trait_bytes(ptr: *const u8, len: usize) -> bool {
    let result: Result<bool, ()> = (|| unsafe {
        let bytes = native_abi_bytes(ptr, len).ok_or(())?;
        Ok(native_declare_user_trait_bytes_result(bytes))
    })();
    result.unwrap_or(false)
}

