        assert_eq!(php_strnatcmp_bytes(b" 00", b" 0", false), 1);
        assert_eq!(php_strnatcmp_bytes(b" 0", b" 00", false), -1);
        assert_eq!(php_strnatcmp_bytes(b"a0002", b"a002", false), -1);
        assert_eq!(php_strnatcmp_bytes(b"a2", b"a02", false), 1);
