    #[test]
    fn native_materialized_call_arguments_preserve_reference_slots_in_byref_variadic_collection() {
        let materialized = phpc_native_materialized_call_arguments_new();
        let first = PhpReferenceCell::new(Value::String("first".to_string()));
        let named = PhpReferenceCell::new(Value::String("named".to_string()));
        let mut unpacked = PhpArray::new();
        unpacked.append_reference(first.clone()).unwrap();
        unpacked.insert_reference("name", named.clone());
        let unpacked_value = NativeValueHandle::from_value(Value::Array(unpacked));
        let mut diagnostic = NativeDiagnosticHandle::null();

        assert!(unsafe {
            phpc_native_materialized_call_arguments_unpack_array_value_and_free(
                materialized,
                unpacked_value,
                &mut diagnostic,
            )
        });
        assert!(diagnostic.is_null());

        let rest = native_string_for_test("values");
        let finalized = unsafe {
            phpc_native_materialized_call_arguments_finalize_with_diagnostic(
                materialized,
                ptr::null(),
                ptr::null(),
                ptr::null(),
                ptr::null(),
                0,
                rest,
                true,
                true,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert!(!finalized.is_null());
        assert_eq!(unsafe { phpc_native_call_arguments_len(finalized) }, 1);

        let variadic = unsafe { call_argument_array_for_test(finalized, 0) };
        let first_slot = variadic.get_slot(0).expect("positional variadic reference");
        let named_slot = variadic.get_slot("name").expect("named variadic reference");
        assert!(first_slot
            .reference_cell()
            .is_some_and(|slot| slot.shares_reference_with(&first)));
        assert!(named_slot
            .reference_cell()
            .is_some_and(|slot| slot.shares_reference_with(&named)));

        first.set_value(Value::String("changed".to_string()));
        named.set_value(Value::String("renamed".to_string()));
        assert_eq!(
            variadic.get_cloned(0),
            Some(Value::String("changed".to_string()))
        );
        assert_eq!(
            variadic.get_cloned("name"),
            Some(Value::String("renamed".to_string()))
        );

        unsafe { phpc_native_call_arguments_free(finalized) };
        unsafe { phpc_native_materialized_call_arguments_free(materialized) };
        unsafe { phpc_native_string_free(rest) };
    }

    #[test]
    fn native_materialized_call_arguments_forward_source_slots_for_magic_packing() {
        let materialized = phpc_native_materialized_call_arguments_new();
        let reference = PhpReferenceCell::new(Value::String("N".to_string()));
        let mut spread = PhpArray::new();
        spread.append(Value::String("A".to_string())).unwrap();
        spread.insert_reference("name", reference.clone());
        let mut diagnostic = NativeDiagnosticHandle::null();
        assert!(unsafe {
            phpc_native_materialized_call_arguments_unpack_array_value_and_free(
                materialized,
                NativeValueHandle::from_value(Value::Array(spread)),
                &mut diagnostic,
            )
        });
        assert!(diagnostic.is_null());

        let forwarded = phpc_native_call_arguments_new();
        assert!(unsafe {
            phpc_native_materialized_call_arguments_forward_source_to_call_arguments_with_diagnostic(
                materialized,
                forwarded,
                &mut diagnostic,
            )
        });
        assert!(diagnostic.is_null());
        let forwarded_ref = unsafe { forwarded.as_ref() }.expect("forwarded arguments");
        assert!(
            !forwarded_ref.finalized_variadic,
            "forward-source magic carrier must not mark a packed variadic slot"
        );
        assert_eq!(forwarded_ref.slots.len(), 2);

        let forwarded_reference =
            unsafe { phpc_native_call_arguments_read_reference(forwarded, 1) };
        assert!(!forwarded_reference.is_null());
        let changed = NativeValueHandle::from_value(Value::String("changed".to_string()));
        assert!(unsafe { phpc_native_reference_set_value(forwarded_reference, changed) });
        assert_eq!(
            reference.value_cloned(),
            Value::String("changed".to_string())
        );

        let magic_arguments =
            native_magic_call_arguments_from_method_and_arguments("missing", forwarded_ref)
                .expect("magic packing should preserve forwarded source slots");
        let magic_args = unsafe { phpc_native_call_arguments_read_value(magic_arguments, 1) };
        let Some(Value::Array(array)) = (unsafe { magic_args.as_ref() }) else {
            panic!("expected magic $args array");
        };
        assert_eq!(array.get_cloned(0), Some(Value::String("A".to_string())));
        assert_eq!(
            array.get_cloned("name"),
            Some(Value::String("changed".to_string()))
        );
        assert!(
            array
                .get_slot("name")
                .is_some_and(|slot| slot.reference_cell().is_none()),
            "magic $args should receive a COW value entry, not the caller reference slot"
        );
        let mut magic_array = array.clone();
        magic_array
            .get_slot_mut("name")
            .expect("packed named magic argument")
            .set_value(Value::String("magic-changed".to_string()));
        assert_eq!(
            reference.value_cloned(),
            Value::String("changed".to_string()),
            "mutating magic $args must not write through to the forwarded caller reference"
        );

        unsafe { phpc_native_value_free(magic_args) };
        unsafe { phpc_native_call_arguments_free(magic_arguments) };
        unsafe { phpc_native_value_free(changed) };
        unsafe { phpc_native_reference_free(forwarded_reference) };
        unsafe { phpc_native_call_arguments_free(forwarded) };
        unsafe { phpc_native_materialized_call_arguments_free(materialized) };
    }

    #[test]
    fn native_magic_call_arguments_pack_reference_slots_as_cow_args_array_values() {
        let arguments = phpc_native_call_arguments_new();
        let positional = PhpReferenceCell::new(Value::String("pos".to_string()));
        assert!(unsafe {
            phpc_native_call_arguments_push_reference_and_free(
                arguments,
                NativeReferenceHandle::from_cell(positional.clone()),
            )
        });

        let named = PhpReferenceCell::new(Value::String("named".to_string()));
        let name = native_string_for_test("name");
        assert!(unsafe {
            phpc_native_call_arguments_push_named_reference_and_free(
                arguments,
                name,
                NativeReferenceHandle::from_cell(named.clone()),
            )
        });
        unsafe { phpc_native_string_free(name) };

        let (magic_arguments, magic_static_arguments) = {
            let arguments_ref = unsafe { arguments.as_ref() }.expect("call arguments");
            (
                native_magic_call_arguments_from_method_and_arguments("missing", arguments_ref)
                    .expect("magic arguments should pack"),
                native_magic_callstatic_arguments_from_method_and_arguments(
                    "absent",
                    arguments_ref,
                )
                .expect("magic static arguments should pack"),
            )
        };

        for (label, handle) in [
            ("__call", magic_arguments),
            ("__callStatic", magic_static_arguments),
        ] {
            let args = unsafe { phpc_native_call_arguments_read_value(handle, 1) };
            let Some(Value::Array(array)) = (unsafe { args.as_ref() }) else {
                panic!("expected packed {label} argument array");
            };

            assert_eq!(array.get_cloned(0), Some(Value::String("pos".to_string())));
            assert_eq!(
                array.get_cloned("name"),
                Some(Value::String("named".to_string()))
            );
            assert!(
                array
                    .get_slot(0)
                    .is_some_and(|slot| slot.reference_cell().is_none()),
                "{label} positional magic arg should be a COW value slot"
            );
            assert!(
                array
                    .get_slot("name")
                    .is_some_and(|slot| slot.reference_cell().is_none()),
                "{label} named magic arg should be a COW value slot"
            );

            let mut local_args = array.clone();
            local_args
                .get_slot_mut(0)
                .expect("positional magic arg")
                .set_value(Value::String(format!("{label}:changed")));
            local_args
                .get_slot_mut("name")
                .expect("named magic arg")
                .set_value(Value::String(format!("{label}:renamed")));
            assert_eq!(positional.value_cloned(), Value::String("pos".to_string()));
            assert_eq!(named.value_cloned(), Value::String("named".to_string()));

            unsafe { phpc_native_value_free(args) };
            unsafe { phpc_native_call_arguments_free(handle) };
        }

        unsafe { phpc_native_call_arguments_free(arguments) };
    }

    #[test]
    fn native_magic_call_arguments_preserve_nested_references_inside_cow_value_entries() {
        let leaf = PhpReferenceCell::new(Value::String("leaf".to_string()));
        let mut nested = PhpArray::new();
        nested.append_reference(leaf.clone()).unwrap();
        let source = PhpReferenceCell::new(Value::Array(nested));

        let arguments = phpc_native_call_arguments_new();
        assert!(unsafe {
            phpc_native_call_arguments_push_reference_and_free(
                arguments,
                NativeReferenceHandle::from_cell(source.clone()),
            )
        });

        let magic_arguments = {
            let arguments_ref = unsafe { arguments.as_ref() }.expect("call arguments");
            native_magic_call_arguments_from_method_and_arguments("missing", arguments_ref)
                .expect("magic arguments should pack")
        };
        let args = unsafe { phpc_native_call_arguments_read_value(magic_arguments, 1) };
        let Some(Value::Array(array)) = (unsafe { args.as_ref() }) else {
            panic!("expected packed magic argument array");
        };
        assert!(
            array
                .get_slot(0)
                .is_some_and(|slot| slot.reference_cell().is_none()),
            "top-level referenced argument should be packed as a COW value"
        );

        let mut top_level_mutation = array.clone();
        top_level_mutation
            .get_slot_mut(0)
            .expect("top-level magic arg")
            .set_value(Value::String("replaced".to_string()));
        assert!(
            matches!(source.value_cloned(), Value::Array(_)),
            "replacing magic $args[0] should not replace the caller reference value"
        );

        let Some(Value::Array(mut nested_from_magic)) = array.get_cloned(0) else {
            panic!("expected nested array value in magic arg");
        };
        nested_from_magic
            .get_slot_mut(0)
            .expect("nested magic arg reference")
            .set_value(Value::String("nested-changed".to_string()));
        assert_eq!(
            leaf.value_cloned(),
            Value::String("nested-changed".to_string()),
            "nested reference cells inside the copied value must remain shared"
        );

        unsafe { phpc_native_value_free(args) };
        unsafe { phpc_native_call_arguments_free(magic_arguments) };
        unsafe { phpc_native_call_arguments_free(arguments) };
    }

    #[test]
    fn native_materialized_call_argument_finalizer_reports_runtime_shape_diagnostics() {
        let first = native_string_for_test("first");
        let required = [1];
        let by_reference = [0];
        let defaults = [NativeValueHandle::null()];

        let duplicate = phpc_native_materialized_call_arguments_new();
        assert!(unsafe {
            phpc_native_materialized_call_arguments_push_named_value_and_free(
                duplicate,
                first,
                NativeValueHandle::from_value(Value::String("a".to_string())),
            )
        });
        assert!(unsafe {
            phpc_native_materialized_call_arguments_push_named_value_and_free(
                duplicate,
                first,
                NativeValueHandle::from_value(Value::String("b".to_string())),
            )
        });
        let mut diagnostic = NativeDiagnosticHandle::null();
        let finalized = unsafe {
            phpc_native_materialized_call_arguments_finalize_with_diagnostic(
                duplicate,
                &first,
                required.as_ptr(),
                by_reference.as_ptr(),
                defaults.as_ptr(),
                1,
                NativeStringHandle::null(),
                false,
                false,
                &mut diagnostic,
            )
        };
        assert!(finalized.is_null());
        let message = unsafe { diagnostic.as_ref() }
            .expect("duplicate diagnostic should be set")
            .message
            .clone();
        assert!(message.contains("duplicate"), "{message}");
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        unsafe { phpc_native_materialized_call_arguments_free(duplicate) };

        for (label, array, expected) in [
            (
                "unknown",
                {
                    let mut array = PhpArray::new();
                    array.insert("missing", Value::String("x".to_string()));
                    array
                },
                "unknown named argument $missing",
            ),
            (
                "positional-after-named",
                {
                    let mut array = PhpArray::new();
                    array.insert("first", Value::String("a".to_string()));
                    array.append(Value::String("b".to_string())).unwrap();
                    array
                },
                "follows a named argument",
            ),
        ] {
            let materialized = phpc_native_materialized_call_arguments_new();
            let mut diagnostic = NativeDiagnosticHandle::null();
            assert!(
                unsafe {
                    phpc_native_materialized_call_arguments_unpack_array_value_and_free(
                        materialized,
                        NativeValueHandle::from_value(Value::Array(array)),
                        &mut diagnostic,
                    )
                },
                "{label} unpack should classify array entries"
            );
            assert!(diagnostic.is_null());

            let finalized = unsafe {
                phpc_native_materialized_call_arguments_finalize_with_diagnostic(
                    materialized,
                    &first,
                    required.as_ptr(),
                    by_reference.as_ptr(),
                    defaults.as_ptr(),
                    1,
                    NativeStringHandle::null(),
                    false,
                    false,
                    &mut diagnostic,
                )
            };
            assert!(finalized.is_null(), "{label} should not finalize");
            let message = unsafe { diagnostic.as_ref() }
                .expect("diagnostic should be set")
                .message
                .clone();
            assert!(
                message.contains(expected),
                "{label} diagnostic should contain {expected:?}, got {message:?}"
            );
            unsafe { phpc_native_diagnostic_free(diagnostic) };
            unsafe { phpc_native_materialized_call_arguments_free(materialized) };
        }

        unsafe { phpc_native_string_free(first) };
    }

