    #[test]
    fn native_call_arguments_and_results_preserve_value_reference_failure_and_ownership() {
        let arguments = phpc_native_call_arguments_new();
        let original_value = NativeValueHandle::from_value(Value::Int(7));
        assert!(unsafe { phpc_native_call_arguments_push_value(arguments, original_value) });

        let cell = PhpReferenceCell::new(Value::String("before".to_string()));
        let original_reference = NativeReferenceHandle::from_cell(cell.clone());
        assert!(unsafe {
            phpc_native_call_arguments_push_reference(arguments, original_reference)
        });
        assert_eq!(unsafe { phpc_native_call_arguments_len(arguments) }, 2);

        let read_value = unsafe { phpc_native_call_arguments_read_value(arguments, 0) };
        assert_eq!(unsafe { read_value.as_ref() }, Some(&Value::Int(7)));
        unsafe { phpc_native_value_free(read_value) };

        let read_reference_value = unsafe { phpc_native_call_arguments_read_value(arguments, 1) };
        assert_eq!(
            unsafe { read_reference_value.as_ref() },
            Some(&Value::String("before".to_string()))
        );
        unsafe { phpc_native_value_free(read_reference_value) };

        let read_reference = unsafe { phpc_native_call_arguments_read_reference(arguments, 1) };
        let replacement = NativeValueHandle::from_value(Value::String("after".to_string()));
        assert!(unsafe { phpc_native_reference_set_value(read_reference, replacement) });
        unsafe { phpc_native_value_free(replacement) };
        unsafe { phpc_native_reference_free(read_reference) };
        assert_eq!(cell.value_cloned(), Value::String("after".to_string()));

        let value_result =
            phpc_native_call_result_from_value(NativeValueHandle::from_value(Value::Int(11)));
        assert_eq!(
            unsafe { phpc_native_call_result_status(value_result) },
            NativeCallResultStatus::Value
        );
        let value_read = unsafe { phpc_native_call_result_read_value(value_result) };
        assert_eq!(unsafe { value_read.as_ref() }, Some(&Value::Int(11)));
        unsafe { phpc_native_value_free(value_read) };
        let value_taken = unsafe { phpc_native_call_result_take_value_and_free(value_result) };
        assert_eq!(unsafe { value_taken.as_ref() }, Some(&Value::Int(11)));
        unsafe { phpc_native_value_free(value_taken) };

        let reference_result = phpc_native_call_result_from_reference(unsafe {
            phpc_native_reference_clone(original_reference)
        });
        assert_eq!(
            unsafe { phpc_native_call_result_status(reference_result) },
            NativeCallResultStatus::Reference
        );
        let reference_read = unsafe { phpc_native_call_result_read_reference(reference_result) };
        assert!(!reference_read.is_null());
        unsafe { phpc_native_reference_free(reference_read) };
        let reference_taken =
            unsafe { phpc_native_call_result_take_reference_and_free(reference_result) };
        let final_value = NativeValueHandle::from_value(Value::String("taken".to_string()));
        assert!(unsafe { phpc_native_reference_set_value(reference_taken, final_value) });
        unsafe { phpc_native_value_free(final_value) };
        unsafe { phpc_native_reference_free(reference_taken) };
        assert_eq!(cell.value_cloned(), Value::String("taken".to_string()));

        let diagnostic = NativeDiagnosticHandle::from_message("call failed generically");
        let failure_result = phpc_native_call_result_from_diagnostic_and_free(diagnostic);
        assert_eq!(
            unsafe { phpc_native_call_result_status(failure_result) },
            NativeCallResultStatus::Failure
        );
        let failure_read = unsafe { phpc_native_call_result_read_diagnostic(failure_result) };
        assert_eq!(
            unsafe { failure_read.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some("call failed generically")
        );
        unsafe { phpc_native_diagnostic_free(failure_read) };
        let failure_taken =
            unsafe { phpc_native_call_result_take_diagnostic_and_free(failure_result) };
        assert_eq!(
            unsafe { failure_taken.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some("call failed generically")
        );
        unsafe { phpc_native_diagnostic_free(failure_taken) };

        unsafe { phpc_native_value_free(original_value) };
        unsafe { phpc_native_reference_free(original_reference) };
        unsafe { phpc_native_call_arguments_free(arguments) };
    }

    #[test]
    fn native_magic_call_arguments_preserve_source_named_keys() {
        let arguments = phpc_native_call_arguments_new();
        assert!(unsafe {
            phpc_native_call_arguments_push_value_and_free(
                arguments,
                NativeValueHandle::from_value(Value::String("pos".to_string())),
            )
        });

        let first_name = native_string_for_test("first");
        assert!(unsafe {
            phpc_native_call_arguments_push_named_value_and_free(
                arguments,
                first_name,
                NativeValueHandle::from_value(Value::String("A".to_string())),
            )
        });
        unsafe { phpc_native_string_free(first_name) };

        let second_name = native_string_for_test("second");
        assert!(unsafe {
            phpc_native_call_arguments_push_named_value_and_free(
                arguments,
                second_name,
                NativeValueHandle::from_value(Value::String("B".to_string())),
            )
        });
        unsafe { phpc_native_string_free(second_name) };

        let magic_arguments = {
            let arguments_ref = unsafe { arguments.as_ref() }.expect("call arguments");
            native_magic_call_arguments_from_method_and_arguments("missing", arguments_ref)
                .expect("magic arguments should pack")
        };
        let method = unsafe { phpc_native_call_arguments_read_value(magic_arguments, 0) };
        assert_eq!(
            unsafe { method.as_ref() },
            Some(&Value::String("missing".to_string()))
        );
        unsafe { phpc_native_value_free(method) };

        let args = unsafe { phpc_native_call_arguments_read_value(magic_arguments, 1) };
        let Some(Value::Array(array)) = (unsafe { args.as_ref() }) else {
            panic!("expected packed magic argument array");
        };
        assert_eq!(
            array.get_cloned(ArrayKey::Int(0)),
            Some(Value::String("pos".to_string()))
        );
        assert_eq!(
            array.get_cloned(ArrayKey::String("first".to_string())),
            Some(Value::String("A".to_string()))
        );
        assert_eq!(
            array.get_cloned(ArrayKey::String("second".to_string())),
            Some(Value::String("B".to_string()))
        );
        unsafe { phpc_native_value_free(args) };
        unsafe { phpc_native_call_arguments_free(magic_arguments) };
        unsafe { phpc_native_call_arguments_free(arguments) };
    }

    #[test]
    fn native_call_result_null_consumers_clear_stale_diagnostics_across_result_modes() {
        let mut value_diagnostic =
            NativeDiagnosticHandle::from_message("stale value result diagnostic");
        let value = unsafe {
            native_call_result_take_value_with_diagnostic_and_free(
                NativeCallResultHandle::null(),
                &mut value_diagnostic,
                "native call result test value missing",
            )
        };
        assert!(value.is_null());
        assert!(value_diagnostic.is_null());
        unsafe { phpc_native_value_free(value) };

        let mut reference_diagnostic =
            NativeDiagnosticHandle::from_message("stale reference result diagnostic");
        let reference = unsafe {
            native_call_result_take_reference_with_diagnostic_and_free(
                NativeCallResultHandle::null(),
                &mut reference_diagnostic,
                "native call result test reference missing",
            )
        };
        assert!(reference.is_null());
        assert!(reference_diagnostic.is_null());
        unsafe { phpc_native_reference_free(reference) };

        let mut discard_diagnostic =
            NativeDiagnosticHandle::from_message("stale discard result diagnostic");
        assert!(!unsafe {
            native_call_result_discard_with_diagnostic_and_free(
                NativeCallResultHandle::null(),
                &mut discard_diagnostic,
            )
        });
        assert!(discard_diagnostic.is_null());
    }

    #[test]
    fn native_diagnostic_result_from_call_result_consumes_value_reference_failure_and_null() {
        let value_result =
            phpc_native_call_result_from_value(NativeValueHandle::from_value(Value::Int(41)));
        let value_diagnostic =
            unsafe { phpc_native_diagnostic_result_from_call_result_and_free(value_result) };
        assert!(unsafe { phpc_native_diagnostic_result_has_value(value_diagnostic) });
        assert_eq!(
            unsafe { phpc_native_diagnostic_result_diagnostic_count(value_diagnostic) },
            0
        );
        unsafe { phpc_native_diagnostic_result_free(value_diagnostic) };

        let cell = PhpReferenceCell::new(Value::String("reference value".to_string()));
        let reference_result =
            phpc_native_call_result_from_reference(NativeReferenceHandle::from_cell(cell.clone()));
        let reference_diagnostic =
            unsafe { phpc_native_diagnostic_result_from_call_result_and_free(reference_result) };
        assert!(unsafe { phpc_native_diagnostic_result_has_value(reference_diagnostic) });
        assert_eq!(
            cell.value_cloned(),
            Value::String("reference value".to_string())
        );
        unsafe { phpc_native_diagnostic_result_free(reference_diagnostic) };

        let failure_result = phpc_native_call_result_from_diagnostic_and_free(
            NativeDiagnosticHandle::from_message("call source failed"),
        );
        let failure_diagnostic =
            unsafe { phpc_native_diagnostic_result_from_call_result_and_free(failure_result) };
        assert!(!unsafe { phpc_native_diagnostic_result_has_value(failure_diagnostic) });
        assert_eq!(
            unsafe { phpc_native_diagnostic_result_diagnostic_count(failure_diagnostic) },
            1
        );
        let message = unsafe {
            phpc_native_diagnostic_result_diagnostic_message_clone_bytes_at(failure_diagnostic, 0)
        };
        let message = String::from_utf8(native_byte_buffer_to_vec_for_test(message)).unwrap();
        assert_eq!(message, "call source failed");
        unsafe { phpc_native_diagnostic_result_free(failure_diagnostic) };

        let null_diagnostic = unsafe {
            phpc_native_diagnostic_result_from_call_result_and_free(NativeCallResultHandle::null())
        };
        assert!(null_diagnostic.is_null());
    }

    #[test]
    fn native_call_frame_result_conditional_handoff_contract_preserves_success_and_diagnostics() {
        for (feature, value, expected) in [
            (
                NativeCallFrameConditionalHandoffFeature::ShortTernaryCondition,
                Value::Int(17),
                Value::Int(17),
            ),
            (
                NativeCallFrameConditionalHandoffFeature::NullCoalesceLeftOperand,
                Value::Null,
                Value::Null,
            ),
            (
                NativeCallFrameConditionalHandoffFeature::ShortTernaryCondition,
                Value::String("truthy".to_string()),
                Value::String("truthy".to_string()),
            ),
        ] {
            let passed = unsafe {
                phpc_native_call_frame_result_conditional_handoff_contract_result(
                    phpc_native_call_result_from_value(NativeValueHandle::from_value(value)),
                    feature as u8,
                )
            };
            assert_eq!(
                unsafe { phpc_native_call_result_status(passed) },
                NativeCallResultStatus::Value
            );
            let selected = unsafe { phpc_native_call_result_take_value_and_free(passed) };
            assert_eq!(unsafe { selected.as_ref() }, Some(&expected));
            unsafe { phpc_native_value_free(selected) };
        }

        let mut plain_array = PhpArray::new();
        plain_array
            .append(Value::Int(1))
            .expect("plain array append should succeed");
        let passed_array = unsafe {
            phpc_native_call_frame_result_null_coalesce_condition_contract_result(
                phpc_native_call_result_from_value(NativeValueHandle::from_value(Value::Array(
                    plain_array,
                ))),
            )
        };
        assert_eq!(
            unsafe { phpc_native_call_result_status(passed_array) },
            NativeCallResultStatus::Value
        );
        let selected_array = unsafe { phpc_native_call_result_take_value_and_free(passed_array) };
        assert!(matches!(
            unsafe { selected_array.as_ref() },
            Some(Value::Array(array)) if array.get_cloned(ArrayKey::Int(0)) == Some(Value::Int(1))
        ));
        unsafe { phpc_native_value_free(selected_array) };

        let diagnostic = unsafe {
            phpc_native_call_frame_result_short_ternary_condition_contract_result(
                phpc_native_call_result_from_diagnostic_and_free(
                    NativeDiagnosticHandle::from_message("conditional source diagnostic"),
                ),
            )
        };
        assert_eq!(
            unsafe { phpc_native_call_result_status(diagnostic) },
            NativeCallResultStatus::Failure
        );
        let diagnostic = unsafe { phpc_native_call_result_take_diagnostic_and_free(diagnostic) };
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some("conditional source diagnostic")
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };
    }

    #[test]
    fn native_call_frame_result_conditional_handoff_contract_centralizes_cleanup_blockers() {
        let mut reference_array = PhpArray::new();
        reference_array
            .append_reference(PhpReferenceCell::new(Value::String("ref".to_string())))
            .expect("reference array append should succeed");

        let shared_slot = ArraySlot::new(Value::String("shared".to_string()));
        let mut cow_array = PhpArray::new();
        cow_array
            .append_slot(shared_slot.clone())
            .expect("shared array append should succeed");
        cow_array
            .append_slot(ArraySlot::share_cell_from(&shared_slot))
            .expect("second shared array append should succeed");

        let object_class =
            PhpClassMetadata::new(ClassId(9901), "ConditionalHandoffBox".to_string());
        let object_value = Value::Object(PhpObject::from_class(&object_class));

        for (feature, result, expected_detail, expected_branch_detail) in [
            (
                NativeCallFrameConditionalHandoffFeature::ShortTernaryCondition,
                phpc_native_call_result_from_value(NativeValueHandle::from_value(Value::Resource(
                    801,
                ))),
                "resource value",
                "false-branch discard cleanup ordering",
            ),
            (
                NativeCallFrameConditionalHandoffFeature::NullCoalesceLeftOperand,
                phpc_native_call_result_from_reference(NativeReferenceHandle::from_cell(
                    PhpReferenceCell::new(Value::Int(3)),
                )),
                "reference result",
                "null-branch discard cleanup ordering",
            ),
            (
                NativeCallFrameConditionalHandoffFeature::ShortTernaryCondition,
                phpc_native_call_result_from_value(NativeValueHandle::from_value(Value::Array(
                    reference_array.clone(),
                ))),
                "array reference slot",
                "false-branch discard cleanup ordering",
            ),
            (
                NativeCallFrameConditionalHandoffFeature::NullCoalesceLeftOperand,
                phpc_native_call_result_from_value(NativeValueHandle::from_value(Value::Array(
                    cow_array.clone(),
                ))),
                "array shared COW slot",
                "null-branch discard cleanup ordering",
            ),
            (
                NativeCallFrameConditionalHandoffFeature::ShortTernaryCondition,
                phpc_native_call_result_from_value(NativeValueHandle::from_value(
                    object_value.clone(),
                )),
                "object value",
                "false-branch discard cleanup ordering",
            ),
        ] {
            let blocked = unsafe {
                phpc_native_call_frame_result_conditional_handoff_contract_result(
                    result,
                    feature as u8,
                )
            };
            assert_eq!(
                unsafe { phpc_native_call_result_status(blocked) },
                NativeCallResultStatus::Failure
            );
            let diagnostic = unsafe { phpc_native_call_result_take_diagnostic_and_free(blocked) };
            let message = unsafe { diagnostic.as_ref() }
                .map(|diagnostic| diagnostic.message.clone())
                .unwrap_or_default();
            for fragment in [
                "unsupported call call-result",
                expected_detail,
                "conditional result handoff",
                expected_branch_detail,
                "reference/COW preservation",
            ] {
                assert!(message.contains(fragment), "{message}");
            }
            unsafe { phpc_native_diagnostic_free(diagnostic) };
        }

        let invalid = unsafe {
            phpc_native_call_frame_result_conditional_handoff_contract_result(
                phpc_native_call_result_from_value(NativeValueHandle::from_value(Value::Int(19))),
                u8::MAX,
            )
        };
        assert_eq!(
            unsafe { phpc_native_call_result_status(invalid) },
            NativeCallResultStatus::Failure
        );
        let diagnostic = unsafe { phpc_native_call_result_take_diagnostic_and_free(invalid) };
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native call frame conditional handoff failed: unknown conditional handoff feature tag"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };
    }

