    #[test]
    fn native_callable_table_context_enforces_public_protected_private_method_lookup() {
        let table = phpc_native_callable_table_new();
        unsafe {
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "open",
                NativeCallableVisibility::Public,
                native_scoped_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "guarded",
                NativeCallableVisibility::Protected,
                native_scoped_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Child"),
                "child_guarded",
                NativeCallableVisibility::Protected,
                native_scoped_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Child"),
                "child_secret",
                NativeCallableVisibility::Private,
                native_scoped_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "secret",
                NativeCallableVisibility::Private,
                native_scoped_method_callback,
            );
            assert!(phpc_native_callable_table_register_class_parent_and_free(
                table,
                native_string_for_test("Child"),
                native_string_for_test("Base"),
            ));
        }

        let (public_external, diagnostic) = unsafe {
            lookup_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "open",
                None,
            )
        };
        assert!(diagnostic.is_null());
        assert!(!public_external.is_null());
        unsafe { phpc_native_callable_free(public_external) };

        let (protected_external, diagnostic) = unsafe {
            lookup_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "guarded",
                None,
            )
        };
        assert!(protected_external.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native callable lookup failed: Protected method Base::guarded is not visible from <global>"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        let (protected_same_class, diagnostic) = unsafe {
            lookup_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "guarded",
                Some("Base"),
            )
        };
        assert!(diagnostic.is_null());
        assert!(!protected_same_class.is_null());
        unsafe { phpc_native_callable_free(protected_same_class) };

        let (protected_child, diagnostic) = unsafe {
            lookup_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "guarded",
                Some("Child"),
            )
        };
        assert!(diagnostic.is_null());
        assert!(!protected_child.is_null());
        unsafe { phpc_native_callable_free(protected_child) };

        let (protected_parent_to_child, diagnostic) = unsafe {
            lookup_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Child"),
                "child_guarded",
                Some("Base"),
            )
        };
        assert!(diagnostic.is_null());
        assert!(!protected_parent_to_child.is_null());
        unsafe { phpc_native_callable_free(protected_parent_to_child) };

        let (private_same_class, diagnostic) = unsafe {
            lookup_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "secret",
                Some("Base"),
            )
        };
        assert!(diagnostic.is_null());
        assert!(!private_same_class.is_null());
        unsafe { phpc_native_callable_free(private_same_class) };

        let (private_child, diagnostic) = unsafe {
            lookup_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Base"),
                "secret",
                Some("Child"),
            )
        };
        assert!(private_child.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native callable lookup failed: Private method Base::secret is not visible from Child"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        let (private_parent_to_child, diagnostic) = unsafe {
            lookup_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Child"),
                "child_secret",
                Some("Base"),
            )
        };
        assert!(private_parent_to_child.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some("native callable lookup failed: Private method Child::child_secret is not visible from Base")
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        unsafe { phpc_native_callable_table_free(table) };
    }

    #[test]
    fn native_callable_access_context_preflights_receiver_and_static_method_lookup() {
        let table = phpc_native_callable_table_new();
        unsafe {
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("BaseDispatch"),
                "guarded",
                NativeCallableVisibility::Protected,
                native_scoped_method_callback,
            );
            register_static_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("BaseDispatch"),
                "stat",
                NativeCallableVisibility::Protected,
                native_scoped_method_callback,
            );
            register_static_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("BaseDispatch"),
                "pubstat",
                NativeCallableVisibility::Public,
                native_scoped_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("BaseDispatch"),
                "plain",
                NativeCallableVisibility::Public,
                native_scoped_method_callback,
            );
            assert!(phpc_native_callable_table_register_class_parent_and_free(
                table,
                native_string_for_test("ChildDispatch"),
                native_string_for_test("BaseDispatch"),
            ));
        }

        let mut classes = PhpClassTable::new();
        let child_id = classes.declare_class("ChildDispatch").unwrap();
        let receiver = NativeValueHandle::from_value(Value::Object(PhpObject::from_class(
            classes.get(child_id).unwrap(),
        )));
        let guarded = NativeValueHandle::from_value(Value::String("guarded".to_string()));
        let plain = NativeValueHandle::from_value(Value::String("plain".to_string()));
        let stat = NativeValueHandle::from_value(Value::String("stat".to_string()));
        let pubstat = NativeValueHandle::from_value(Value::String("pubstat".to_string()));
        let mut diagnostic = NativeDiagnosticHandle::null();

        let public_receiver = unsafe {
            phpc_native_method_lookup_with_access_context_diagnostic(
                table,
                receiver,
                plain,
                NativeCallableAccessContextTag::ObjectReceiver,
                NativeStringHandle::null(),
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert!(!public_receiver.is_null());
        unsafe { phpc_native_callable_free(public_receiver) };

        let blocked_receiver = unsafe {
            phpc_native_method_lookup_with_access_context_diagnostic(
                table,
                receiver,
                guarded,
                NativeCallableAccessContextTag::ObjectReceiver,
                NativeStringHandle::null(),
                &mut diagnostic,
            )
        };
        assert!(blocked_receiver.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native callable lookup failed: Protected method BaseDispatch::guarded is not visible from <global>"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        let class_context_receiver = unsafe {
            phpc_native_method_lookup_with_access_context_diagnostic(
                table,
                receiver,
                guarded,
                NativeCallableAccessContextTag::ClassContext,
                native_string_for_test("ChildDispatch"),
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert!(!class_context_receiver.is_null());
        unsafe { phpc_native_callable_free(class_context_receiver) };

        let blocked_static_through_receiver = unsafe {
            phpc_native_method_lookup_with_access_context_diagnostic(
                table,
                receiver,
                pubstat,
                NativeCallableAccessContextTag::ObjectReceiver,
                NativeStringHandle::null(),
                &mut diagnostic,
            )
        };
        assert!(blocked_static_through_receiver.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native method lookup failed: static method ChildDispatch::pubstat cannot be used for object dispatch"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        let blocked_static = unsafe {
            phpc_native_static_method_lookup_with_access_context_diagnostic(
                table,
                native_string_for_test("ChildDispatch"),
                stat,
                NativeCallableAccessContextTag::Static,
                NativeStringHandle::null(),
                &mut diagnostic,
            )
        };
        assert!(blocked_static.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native callable lookup failed: Protected method BaseDispatch::stat is not visible from <global>"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        let class_context_static = unsafe {
            phpc_native_static_method_lookup_with_access_context_diagnostic(
                table,
                native_string_for_test("ChildDispatch"),
                stat,
                NativeCallableAccessContextTag::ClassContext,
                native_string_for_test("ChildDispatch"),
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert!(!class_context_static.is_null());
        unsafe { phpc_native_callable_free(class_context_static) };

        unsafe { phpc_native_value_free(stat) };
        unsafe { phpc_native_value_free(pubstat) };
        unsafe { phpc_native_value_free(plain) };
        unsafe { phpc_native_value_free(guarded) };
        unsafe { phpc_native_value_free(receiver) };
        unsafe { phpc_native_callable_table_free(table) };
    }

