    #[test]
    fn native_callable_value_dispatch_preflights_strings_arrays_objects_and_descriptor_closures() {
        let table = phpc_native_callable_table_new();
        unsafe {
            register_callable_for_test(
                table,
                NativeCallableKind::Function,
                None,
                "alpha",
                NativeCallableVisibility::Public,
                native_sum_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Function,
                None,
                "beta",
                NativeCallableVisibility::Public,
                native_sum_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("BaseCallable"),
                "run",
                NativeCallableVisibility::Public,
                native_scoped_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("InvokableBox"),
                "__invoke",
                NativeCallableVisibility::Public,
                native_receiver_method_callback,
            );
            assert!(phpc_native_callable_table_register_class_parent_and_free(
                table,
                native_string_for_test("ChildCallable"),
                native_string_for_test("BaseCallable"),
            ));
        }

        let mut classes = PhpClassTable::new();
        let invokable_id = classes.declare_class("InvokableBox").unwrap();
        let child_id = classes.declare_class("ChildCallable").unwrap();
        let invokable = Value::Object(PhpObject::from_class(classes.get(invokable_id).unwrap()));
        let child = Value::Object(PhpObject::from_class(classes.get(child_id).unwrap()));
        let descriptor = NativeClosureDescriptor::new(native_descriptor_sum_closure_callback, 2, 2);

        let callable_values = [
            NativeValueHandle::from_value(Value::String("ALPHA".to_string())),
            NativeValueHandle::from_value(Value::BinaryString(b"beta".to_vec())),
            NativeValueHandle::from_value(Value::Array(callable_pair(
                Value::String("ChildCallable".to_string()),
                Value::String("RUN".to_string()),
            ))),
            NativeValueHandle::from_value(Value::Array(callable_pair(
                child,
                Value::String("run".to_string()),
            ))),
            NativeValueHandle::from_value(invokable),
            phpc_native_value_from_closure_descriptor(descriptor),
        ];

        for value in callable_values {
            let (callable, diagnostic) =
                unsafe { lookup_callable_value_for_test(table, value, None) };
            assert!(diagnostic.is_null());
            assert!(!callable.is_null());
            unsafe { phpc_native_callable_value_free(callable) };
            unsafe { phpc_native_value_free(value) };
        }

        let plain_closure =
            NativeValueHandle::from_value(Value::Closure(PhpClosure::new(7001, false, Vec::new())));
        let (callable, diagnostic) =
            unsafe { lookup_callable_value_for_test(table, plain_closure, None) };
        assert!(callable.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native callable lookup failed: closure value has no native descriptor/frame callback"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        unsafe { phpc_native_value_free(plain_closure) };

        let scalar = NativeValueHandle::from_value(Value::Int(42));
        let (callable, diagnostic) = unsafe { lookup_callable_value_for_test(table, scalar, None) };
        assert!(callable.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some("native callable lookup failed: value of type int is not callable")
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        unsafe { phpc_native_value_free(scalar) };

        unsafe {
            register_static_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("StaticInvokable"),
                "__invoke",
                NativeCallableVisibility::Public,
                native_receiver_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("PrivateInvokable"),
                "__invoke",
                NativeCallableVisibility::Private,
                native_receiver_method_callback,
            );
        }
        let static_id = classes.declare_class("StaticInvokable").unwrap();
        let static_invokable = NativeValueHandle::from_value(Value::Object(PhpObject::from_class(
            classes.get(static_id).unwrap(),
        )));
        let (callable, diagnostic) =
            unsafe { lookup_callable_value_for_test(table, static_invokable, None) };
        assert!(callable.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native callable lookup failed: static method StaticInvokable::__invoke cannot be used for object callable dispatch"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        unsafe { phpc_native_value_free(static_invokable) };

        let private_id = classes.declare_class("PrivateInvokable").unwrap();
        let private_invokable = NativeValueHandle::from_value(Value::Object(
            PhpObject::from_class(classes.get(private_id).unwrap()),
        ));
        let (callable, diagnostic) = unsafe {
            lookup_callable_value_for_test(table, private_invokable, Some("PrivateInvokable"))
        };
        assert!(callable.is_null());
        assert_eq!(
            unsafe { diagnostic.as_ref() }.map(|diagnostic| diagnostic.message.as_str()),
            Some(
                "native callable lookup failed: magic method PrivateInvokable::__invoke must be public for object callable dispatch"
            )
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        unsafe { phpc_native_value_free(private_invokable) };

        unsafe { phpc_native_callable_table_free(table) };
    }

    #[test]
    fn native_callable_value_dispatch_invokes_across_callable_value_shapes_with_shared_arguments() {
        let table = phpc_native_callable_table_new();
        unsafe {
            register_callable_for_test(
                table,
                NativeCallableKind::Function,
                None,
                "sum",
                NativeCallableVisibility::Public,
                native_sum_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("Counter"),
                "add",
                NativeCallableVisibility::Public,
                native_scoped_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("InvokeCounter"),
                "__invoke",
                NativeCallableVisibility::Public,
                native_receiver_method_callback,
            );
        }

        let mut classes = PhpClassTable::new();
        let invoke_id = classes.declare_class("InvokeCounter").unwrap();
        let invoke_object = Value::Object(PhpObject::from_class(classes.get(invoke_id).unwrap()));
        let descriptor = NativeClosureDescriptor::new(native_descriptor_sum_closure_callback, 2, 2);

        let cases = [
            (
                NativeValueHandle::from_value(Value::String("SUM".to_string())),
                vec![4, 8],
                Value::Int(12),
            ),
            (
                NativeValueHandle::from_value(Value::Array(callable_pair(
                    Value::String("Counter".to_string()),
                    Value::String("ADD".to_string()),
                ))),
                vec![9],
                Value::String("Counter:9".to_string()),
            ),
            (
                NativeValueHandle::from_value(invoke_object),
                vec![5],
                Value::String("InvokeCounter:5".to_string()),
            ),
            (
                phpc_native_value_from_closure_descriptor(descriptor),
                vec![6, 7],
                Value::Int(13),
            ),
        ];

        for (callable_value, args, expected) in cases {
            let (callable, diagnostic) =
                unsafe { lookup_callable_value_for_test(table, callable_value, None) };
            assert!(diagnostic.is_null());
            assert!(!callable.is_null());
            let (value, diagnostic) =
                unsafe { invoke_callable_value_ints_for_test(callable, &args) };
            assert!(diagnostic.is_null());
            assert_eq!(unsafe { value.as_ref() }, Some(&expected));
            unsafe { phpc_native_value_free(value) };
            unsafe { phpc_native_callable_value_free(callable) };
            unsafe { phpc_native_value_free(callable_value) };
        }

        unsafe { phpc_native_callable_table_free(table) };
    }

    #[test]
    fn native_spl_autoload_registry_preserves_order_prepend_and_unregister_across_callable_shapes()
    {
        spl_autoload_events_reset_for_test();
        let registry = phpc_native_spl_autoload_registry_new();
        let table = phpc_native_callable_table_new();
        unsafe {
            register_callable_for_test(
                table,
                NativeCallableKind::Function,
                None,
                "autoload_function",
                NativeCallableVisibility::Public,
                native_autoload_record_function_callback,
            );
            register_static_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("StaticLoader"),
                "load",
                NativeCallableVisibility::Public,
                native_autoload_static_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("ObjectLoader"),
                "__invoke",
                NativeCallableVisibility::Public,
                native_autoload_object_callback,
            );
        }

        let mut classes = PhpClassTable::new();
        let object_id = classes.declare_class("ObjectLoader").unwrap();
        let object_loader = Value::Object(PhpObject::from_class(classes.get(object_id).unwrap()));
        unsafe {
            register_spl_autoload_callable_for_test(
                registry,
                table,
                Value::String("AUTOLOAD_FUNCTION".to_string()),
                false,
            );
            register_spl_autoload_callable_for_test(
                registry,
                table,
                Value::Array(callable_pair(
                    Value::String("StaticLoader".to_string()),
                    Value::String("LOAD".to_string()),
                )),
                false,
            );
            register_spl_autoload_callable_for_test(registry, table, object_loader, false);
            let descriptor =
                NativeClosureDescriptor::new(native_autoload_descriptor_callback, 1, 1);
            let descriptor_value = phpc_native_value_from_closure_descriptor(descriptor);
            let descriptor_callable = phpc_native_callable_lookup_value_or_closure_with_diagnostic(
                NativeCallableTableHandle::null(),
                descriptor_value,
                std::ptr::null_mut(),
            );
            assert!(phpc_native_spl_autoload_register_callable_value_and_free(
                registry,
                descriptor_callable,
                true,
                std::ptr::null_mut(),
            ));
            phpc_native_value_free(descriptor_value);
        }

        let diagnostic = unsafe { spl_autoload_call_for_test(registry, table, b"Package\\Thing") };
        assert!(diagnostic.is_null());
        assert_eq!(
            spl_autoload_events_for_test(),
            vec![
                "descriptor:Package\\Thing",
                "function:Package\\Thing",
                "StaticLoader::load:Package\\Thing",
                "ObjectLoader::__invoke:Package\\Thing",
            ]
        );

        let unregister = unsafe {
            normalized_callable_for_test(
                table,
                Value::Array(callable_pair(
                    Value::String("staticloader".to_string()),
                    Value::String("load".to_string()),
                )),
            )
        };
        let mut diagnostic = NativeDiagnosticHandle::null();
        assert!(unsafe {
            phpc_native_spl_autoload_unregister_callable_value_and_free(
                registry,
                unregister,
                &mut diagnostic,
            )
        });
        assert!(diagnostic.is_null());

        spl_autoload_events_reset_for_test();
        let diagnostic = unsafe { spl_autoload_call_for_test(registry, table, b"Other\\Thing") };
        assert!(diagnostic.is_null());
        assert_eq!(
            spl_autoload_events_for_test(),
            vec![
                "descriptor:Other\\Thing",
                "function:Other\\Thing",
                "ObjectLoader::__invoke:Other\\Thing",
            ]
        );

        unsafe {
            phpc_native_spl_autoload_registry_free(registry);
            phpc_native_callable_table_free(table);
        }
        spl_autoload_events_reset_for_test();
    }

    #[test]
    fn native_spl_autoload_functions_materializes_order_and_callback_form_equality() {
        spl_autoload_events_reset_for_test();
        let registry = phpc_native_spl_autoload_registry_new();
        let table = phpc_native_callable_table_new();
        unsafe {
            register_callable_for_test(
                table,
                NativeCallableKind::Function,
                None,
                "first_loader",
                NativeCallableVisibility::Public,
                native_autoload_record_function_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Function,
                None,
                "second_loader",
                NativeCallableVisibility::Public,
                native_autoload_record_function_callback,
            );
            register_static_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("StaticLoader"),
                "load",
                NativeCallableVisibility::Public,
                native_autoload_static_method_callback,
            );
            register_callable_for_test(
                table,
                NativeCallableKind::Method,
                Some("ObjectLoader"),
                "__invoke",
                NativeCallableVisibility::Public,
                native_autoload_object_callback,
            );
        }

        let mut classes = PhpClassTable::new();
        let object_id = classes.declare_class("ObjectLoader").unwrap();
        let object_loader = Value::Object(PhpObject::from_class(classes.get(object_id).unwrap()));

        unsafe {
            register_spl_autoload_callable_for_test(
                registry,
                table,
                Value::String("FIRST_LOADER".to_string()),
                false,
            );
            register_spl_autoload_callable_for_test(
                registry,
                table,
                Value::String("StaticLoader::LOAD".to_string()),
                false,
            );
            register_spl_autoload_callable_for_test(
                registry,
                table,
                Value::String("second_loader".to_string()),
                true,
            );
            register_spl_autoload_callable_for_test(registry, table, object_loader.clone(), false);
        }

        let mut diagnostic = NativeDiagnosticHandle::null();
        let callbacks = unsafe {
            phpc_native_spl_autoload_functions_value_with_diagnostic(registry, &mut diagnostic)
        };
        assert!(diagnostic.is_null());
        let callbacks = match unsafe { callbacks.into_value() } {
            Some(Value::Array(callbacks)) => callbacks,
            other => panic!("expected callback list array, got {other:?}"),
        };
        assert_eq!(callbacks.len(), 4);
        assert_eq!(
            callbacks.get_cloned(ArrayKey::Int(0)),
            Some(Value::String("second_loader".to_string()))
        );
        assert_eq!(
            callbacks.get_cloned(ArrayKey::Int(1)),
            Some(Value::String("FIRST_LOADER".to_string()))
        );
        assert_eq!(
            callbacks.get_cloned(ArrayKey::Int(2)),
            Some(Value::Array(callable_pair(
                Value::String("StaticLoader".to_string()),
                Value::String("LOAD".to_string()),
            )))
        );
        assert_eq!(
            callbacks.get_cloned(ArrayKey::Int(3)),
            Some(object_loader.clone())
        );

        assert!(!unsafe {
            unregister_spl_autoload_callable_for_test(
                registry,
                table,
                Value::Array(callable_pair(
                    object_loader.clone(),
                    Value::String("__invoke".to_string()),
                )),
            )
        });
        assert!(unsafe {
            unregister_spl_autoload_callable_for_test(
                registry,
                table,
                Value::Array(callable_pair(
                    Value::String("staticloader".to_string()),
                    Value::String("load".to_string()),
                )),
            )
        });
        assert!(unsafe {
            unregister_spl_autoload_callable_for_test(registry, table, object_loader)
        });

        let callbacks = unsafe {
            phpc_native_spl_autoload_functions_value_with_diagnostic(registry, &mut diagnostic)
        };
        assert!(diagnostic.is_null());
        let callbacks = match unsafe { callbacks.into_value() } {
            Some(Value::Array(callbacks)) => callbacks,
            other => panic!("expected callback list array after unregister, got {other:?}"),
        };
        assert_eq!(callbacks.len(), 2);
        assert_eq!(
            callbacks.get_cloned(ArrayKey::Int(0)),
            Some(Value::String("second_loader".to_string()))
        );
        assert_eq!(
            callbacks.get_cloned(ArrayKey::Int(1)),
            Some(Value::String("FIRST_LOADER".to_string()))
        );

        unsafe {
            phpc_native_spl_autoload_registry_free(registry);
            phpc_native_callable_table_free(table);
        }
        spl_autoload_events_reset_for_test();
    }

