    #[test]
    fn native_container_handle_shapes_are_pointer_sized_with_nullable_array_storage() {
        assert_eq!(
            std::mem::size_of::<NativeArrayHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeArrayEntrySnapshotHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeObjectHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeResourceHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeReferenceHandle>(),
            std::mem::size_of::<*mut ()>()
        );
        assert_eq!(
            std::mem::size_of::<NativeRequestStateHandle>(),
            std::mem::size_of::<*mut ()>()
        );

        let array = phpc_native_array_null();
        let snapshot = NativeArrayEntrySnapshotHandle::null();
        let object = phpc_native_object_null();
        let resource = phpc_native_resource_null();
        let reference = phpc_native_reference_null();
        let request_state = phpc_native_request_state_null();

        assert!(array.is_null());
        assert!(snapshot.is_null());
        assert!(object.is_null());
        assert!(resource.is_null());
        assert!(reference.is_null());
        assert!(request_state.is_null());
        assert!(phpc_native_array_is_null(array));
        assert!(phpc_native_array_entry_snapshot_is_null(snapshot));
        assert!(phpc_native_object_is_null(object));
        assert!(phpc_native_resource_is_null(resource));
        assert!(phpc_native_reference_is_null(reference));
        assert!(phpc_native_request_state_is_null(request_state));

        let array = phpc_native_array_empty();
        assert!(!array.is_null());
        assert!(!phpc_native_array_is_null(array));
        assert_eq!(unsafe { phpc_native_array_len(array) }, 0);
        unsafe { phpc_native_array_free(array) };

        assert_eq!(
            unsafe { phpc_native_array_len(NativeArrayHandle::null()) },
            0
        );
        unsafe { phpc_native_array_free(NativeArrayHandle::null()) };
    }

    #[test]
    fn native_reference_clone_handles_share_cells_with_independent_ownership() {
        unsafe {
            let original = NativeReferenceHandle::from_cell(PhpReferenceCell::new(Value::String(
                "start".to_string(),
            )));
            let alias = phpc_native_reference_clone(original);

            assert!(!phpc_native_reference_is_null(alias));
            let replacement = NativeValueHandle::from_value(Value::String("changed".to_string()));
            assert!(phpc_native_reference_set_value(alias, replacement));
            phpc_native_value_free(replacement);

            let observed = phpc_native_reference_value_clone(original);
            assert_eq!(
                observed.as_ref(),
                Some(&Value::String("changed".to_string()))
            );

            phpc_native_value_free(observed);
            phpc_native_reference_free(alias);
            phpc_native_reference_free(original);
            phpc_native_reference_free(phpc_native_reference_clone(phpc_native_reference_null()));
        }
    }

    #[test]
    fn native_reference_from_value_and_free_promotes_owned_values_to_reference_cells() {
        unsafe {
            let value = NativeValueHandle::from_value(Value::String("seed".to_string()));
            let reference = phpc_native_reference_from_value_and_free(value);
            assert!(!phpc_native_reference_is_null(reference));

            let alias = phpc_native_reference_clone(reference);
            assert!(!phpc_native_reference_is_null(alias));
            let replacement = NativeValueHandle::from_value(Value::String("changed".to_string()));
            assert!(phpc_native_reference_set_value(alias, replacement));
            phpc_native_value_free(replacement);

            let observed = phpc_native_reference_value_clone(reference);
            assert_eq!(
                observed.as_ref(),
                Some(&Value::String("changed".to_string()))
            );

            phpc_native_value_free(observed);
            phpc_native_reference_free(alias);
            phpc_native_reference_free(reference);
            assert!(phpc_native_reference_from_value_and_free(NativeValueHandle::null()).is_null());
        }
    }

