    #[test]
    fn native_request_state_operation_kind_maps_shared_abi_contract() {
        for (
            tag,
            expected,
            expected_address_family,
            uses_keyed_scalar_snapshot,
            owns_value,
            owns_array,
        ) in [
            (
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                NativeRequestStateOperationKind::Value,
                NativeRequestStateOperationAddressFamily::KeyedScalarSnapshot,
                true,
                true,
                false,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                NativeRequestStateOperationKind::Array,
                NativeRequestStateOperationAddressFamily::BagSnapshot,
                false,
                false,
                true,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                NativeRequestStateOperationKind::Presence,
                NativeRequestStateOperationAddressFamily::KeyedScalarSnapshot,
                true,
                false,
                false,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                NativeRequestStateOperationKind::BagPresence,
                NativeRequestStateOperationAddressFamily::BagSnapshot,
                false,
                false,
                false,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_ROOT_VALUE,
                NativeRequestStateOperationKind::RootValue,
                NativeRequestStateOperationAddressFamily::BagSnapshot,
                false,
                true,
                false,
            ),
        ] {
            let operation_kind = NativeRequestStateOperationKind::from_abi_tag(tag)
                .expect("request-state operation tag is supported");

            assert_eq!(operation_kind, expected);
            assert_eq!(operation_kind.address_family(), expected_address_family);
            assert_eq!(
                operation_kind.uses_keyed_scalar_snapshot(),
                uses_keyed_scalar_snapshot
            );
            assert_eq!(
                operation_kind.uses_bag_snapshot(),
                !uses_keyed_scalar_snapshot
            );
            assert_eq!(operation_kind.owns_value_handle(), owns_value);
            assert_eq!(operation_kind.owns_array_handle(), owns_array);
            assert_eq!(
                operation_kind.owns_runtime_handle(),
                owns_value || owns_array
            );
        }

        assert_eq!(NativeRequestStateOperationKind::from_abi_tag(0), None);
        assert_eq!(NativeRequestStateOperationKind::from_abi_tag(99), None);
    }

    #[test]
    fn native_request_state_key_abi_coerces_scalar_and_value_key_families_through_accessors() {
        for (value, expected) in [
            (NativeScalarValue::null(), b"".as_slice()),
            (NativeScalarValue::bool(false), b"0".as_slice()),
            (NativeScalarValue::bool(true), b"1".as_slice()),
            (NativeScalarValue::int(-42), b"-42".as_slice()),
            (NativeScalarValue::float(42.0), b"42".as_slice()),
            (NativeScalarValue::float(-0.0), b"0".as_slice()),
        ] {
            let key = phpc_native_request_state_key_from_scalar(value);
            let (status, bytes) = native_request_state_key_result_for_test(key);

            assert_eq!(status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(bytes, expected);
        }

        for value in [
            NativeScalarValue::float(1.5),
            NativeScalarValue::float(f64::INFINITY),
            NativeScalarValue::float(f64::NAN),
        ] {
            let key = phpc_native_request_state_key_from_scalar(value);
            let (status, bytes) = native_request_state_key_result_for_test(key);

            assert_eq!(
                status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION
            );
            assert_eq!(bytes, b"");
        }

        for (value, expected) in [
            (Value::Null, b"".as_slice()),
            (Value::Bool(false), b"0".as_slice()),
            (Value::Bool(true), b"1".as_slice()),
            (Value::Int(-42), b"-42".as_slice()),
            (Value::Float(42.0), b"42".as_slice()),
            (
                Value::String("text-key".to_string()),
                b"text-key".as_slice(),
            ),
        ] {
            let handle = NativeValueHandle::from_value(value);
            let key = unsafe { phpc_native_request_state_key_from_value(handle) };
            let (status, bytes) = native_request_state_key_result_for_test(key);

            assert_eq!(status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(bytes, expected);
            unsafe { phpc_native_value_free(handle) };
        }

        for value in [
            Value::Float(1.5),
            Value::Float(f64::INFINITY),
            Value::Array(PhpArray::new()),
        ] {
            let handle = NativeValueHandle::from_value(value);
            let key = unsafe { phpc_native_request_state_key_from_value(handle) };
            let (status, bytes) = native_request_state_key_result_for_test(key);

            assert_eq!(
                status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION
            );
            assert_eq!(bytes, b"");
            unsafe { phpc_native_value_free(handle) };
        }

        let null_key =
            unsafe { phpc_native_request_state_key_from_value(NativeValueHandle::null()) };
        let (status, bytes) = native_request_state_key_result_for_test(null_key);
        assert_eq!(status, PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI);
        assert_eq!(bytes, b"");
    }

    #[test]
    fn native_request_state_key_matches_superglobal_names_after_php_key_coercion() {
        for (value, expected_bag) in [
            (Value::String("_GET".to_string()), b"_GET".as_slice()),
            (Value::String("_POST".to_string()), b"_POST".as_slice()),
            (Value::String("_COOKIE".to_string()), b"_COOKIE".as_slice()),
        ] {
            let handle = NativeValueHandle::from_value(value);
            let key = unsafe { phpc_native_request_state_key_from_value(handle) };

            assert!(unsafe {
                phpc_native_request_state_key_matches_superglobal(
                    key,
                    expected_bag.as_ptr(),
                    expected_bag.len(),
                )
            });
            assert!(!unsafe {
                phpc_native_request_state_key_matches_superglobal(
                    key,
                    b"_SERVER".as_ptr(),
                    b"_SERVER".len(),
                )
            });

            let buffer = phpc_native_request_state_key_result_buffer(key);
            unsafe { phpc_native_byte_buffer_free(buffer) };
            unsafe { phpc_native_value_free(handle) };
        }

        let ordinary = NativeValueHandle::from_value(Value::String("plain".to_string()));
        let ordinary_key = unsafe { phpc_native_request_state_key_from_value(ordinary) };
        assert!(!unsafe {
            phpc_native_request_state_key_matches_superglobal(
                ordinary_key,
                b"_GET".as_ptr(),
                b"_GET".len(),
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_key_matches_superglobal(
                ordinary_key,
                b"plain".as_ptr(),
                b"plain".len(),
            )
        });
        let ordinary_buffer = phpc_native_request_state_key_result_buffer(ordinary_key);
        unsafe { phpc_native_byte_buffer_free(ordinary_buffer) };
        unsafe { phpc_native_value_free(ordinary) };

        let unsupported = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let unsupported_key = unsafe { phpc_native_request_state_key_from_value(unsupported) };
        assert!(!unsafe {
            phpc_native_request_state_key_matches_superglobal(
                unsupported_key,
                b"_GET".as_ptr(),
                b"_GET".len(),
            )
        });
        let unsupported_buffer = phpc_native_request_state_key_result_buffer(unsupported_key);
        unsafe { phpc_native_byte_buffer_free(unsupported_buffer) };
        unsafe { phpc_native_value_free(unsupported) };
    }

    #[test]
    fn native_request_state_operations_preserve_php_value_snapshots_and_isset_semantics() {
        let request_state = phpc_native_request_state_empty();
        let bag = b"_GET";

        let null_key = b"null-value";
        let null_value = NativeValueHandle::from_value(Value::Null);
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                null_key.as_ptr(),
                null_key.len(),
                null_value,
            )
        });

        let text_key = b"text";
        let text_value = NativeValueHandle::from_value(Value::String("A\0B".to_string()));
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                text_key.as_ptr(),
                text_key.len(),
                text_value,
            )
        });

        let mut nested = PhpArray::new();
        nested.insert(
            ArrayKey::string("child"),
            Value::String("nested".to_string()),
        );
        let array_key = b"array-value";
        let array_value = NativeValueHandle::from_value(Value::Array(nested.clone()));
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                array_key.as_ptr(),
                array_key.len(),
                array_value,
            )
        });

        let null_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                bag,
                Some(null_key),
            )
        };
        assert_eq!(
            null_presence.result_kind,
            PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE
        );
        assert_eq!(null_presence.exists, 1);
        assert_eq!(null_presence.is_set, 0);
        assert_eq!(null_presence.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);

        let null_result = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(null_key),
            )
        };
        assert_eq!(null_result.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(null_result.exists, 1);
        assert_eq!(null_result.is_set, 0);
        assert_eq!(unsafe { null_result.value.as_ref() }, Some(&Value::Null));
        unsafe { phpc_native_request_state_operation_result_free(null_result) };

        let text_result = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(text_key),
            )
        };
        assert_eq!(text_result.exists, 1);
        assert_eq!(text_result.is_set, 1);
        assert_eq!(
            unsafe { text_result.value.as_ref() },
            Some(&Value::String("A\0B".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(text_result) };

        let array_result = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(array_key),
            )
        };
        assert_eq!(array_result.exists, 1);
        assert_eq!(array_result.is_set, 1);
        assert_eq!(
            unsafe { array_result.value.as_ref() },
            Some(&Value::Array(nested))
        );
        unsafe { phpc_native_request_state_operation_result_free(array_result) };

        let missing = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(b"missing"),
            )
        };
        assert_eq!(missing.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(missing.exists, 0);
        assert_eq!(missing.is_set, 0);
        assert_eq!(missing.status, PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY);
        assert_eq!(unsafe { missing.value.as_ref() }, Some(&Value::Null));
        unsafe { phpc_native_request_state_operation_result_free(missing) };

        let snapshot = unsafe {
            phpc_native_request_state_superglobal_array(request_state, bag.as_ptr(), bag.len())
        };
        let snapshot_array = unsafe { snapshot.as_ref() }.expect("snapshot array handle is valid");
        assert_eq!(snapshot_array.value.len(), 3);
        assert_eq!(
            snapshot_array.value.get(ArrayKey::string("null-value")),
            Some(&Value::Null)
        );
        assert_eq!(
            snapshot_array.value.get(ArrayKey::string("text")),
            Some(&Value::String("A\0B".to_string()))
        );

        assert!(!unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                b"_UNKNOWN".as_ptr(),
                b"_UNKNOWN".len(),
                null_key.as_ptr(),
                null_key.len(),
                null_value,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                null_key.as_ptr(),
                null_key.len(),
                NativeValueHandle::null(),
            )
        });

        unsafe { phpc_native_array_free(snapshot) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(text_value) };
        unsafe { phpc_native_value_free(null_value) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_root_replacements_store_direct_values_and_reenter_slot_tables() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn snapshot_value(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
        ) -> Value {
            let snapshot = unsafe {
                phpc_native_request_state_superglobal_snapshot_value(request_state, root)
            };
            let value = unsafe { snapshot.as_ref() }
                .expect("request root snapshots should return a value")
                .clone();
            unsafe { phpc_native_value_free(snapshot) };
            value
        }

        unsafe fn replace_root(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
            value: Value,
        ) {
            let value = NativeValueHandle::from_value(value);
            let mut diagnostic = NativeDiagnosticHandle::null();
            let replaced = unsafe {
                phpc_native_request_state_superglobal_replace_value_with_diagnostic(
                    request_state,
                    root,
                    value,
                    &mut diagnostic,
                )
            };
            unsafe { phpc_native_value_free(value) };
            if !diagnostic.is_null() {
                let message = native_diagnostic_message_for_test(diagnostic);
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                panic!("{message}");
            }
            assert!(replaced);
        }

        fn assert_array_slot(value: &Value, key: &str, expected: Value) {
            let Value::Array(array) = value else {
                panic!("request root should be array-backed");
            };
            assert_eq!(array.get_cloned(ArrayKey::string(key)), Some(expected));
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let post_root = unsafe { string_handle(b"_POST") };
        let request_root = unsafe { string_handle(b"_REQUEST") };

        let stale_value = NativeValueHandle::from_value(Value::String("stale".to_string()));
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                b"_GET".as_ptr(),
                b"_GET".len(),
                b"stale".as_ptr(),
                b"stale".len(),
                stale_value,
            )
        });
        unsafe { phpc_native_value_free(stale_value) };
        assert_array_slot(
            &unsafe { snapshot_value(request_state, get_root) },
            "stale",
            Value::String("stale".to_string()),
        );

        unsafe {
            replace_root(
                request_state,
                get_root,
                Value::String("direct-root".to_string()),
            )
        };
        assert_eq!(
            unsafe { snapshot_value(request_state, get_root) },
            Value::String("direct-root".to_string())
        );

        let stale_read = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                Some(b"stale"),
            )
        };
        assert_eq!(
            stale_read.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );
        assert_eq!(unsafe { stale_read.value.as_ref() }, Some(&Value::Null));
        unsafe { phpc_native_request_state_operation_result_free(stale_read) };

        let blocked_value = NativeValueHandle::from_value(Value::Int(8));
        let blocked_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"blocked",
                blocked_value,
            )
        };
        unsafe { phpc_native_value_free(blocked_value) };
        assert_eq!(
            blocked_write.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );
        assert_eq!(blocked_write.result_kind, 0);
        assert_eq!(blocked_write.is_set, 0);
        assert_eq!(blocked_write.exists, 0);
        assert!(blocked_write.value.is_null());
        assert!(blocked_write.array.is_null());
        assert_eq!(
            unsafe { snapshot_value(request_state, get_root) },
            Value::String("direct-root".to_string())
        );

        unsafe { replace_root(request_state, get_root, Value::Null) };
        let fresh_value = NativeValueHandle::from_value(Value::Int(7));
        let fresh_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"fresh",
                fresh_value,
            )
        };
        unsafe { phpc_native_value_free(fresh_value) };
        assert_request_state_presence_result_for_test(
            fresh_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let get_snapshot = unsafe { snapshot_value(request_state, get_root) };
        assert_array_slot(&get_snapshot, "fresh", Value::Int(7));
        let Value::Array(get_array) = get_snapshot else {
            panic!("indexed writes should re-enter array-backed request storage");
        };
        assert_eq!(get_array.get_cloned(ArrayKey::string("stale")), None);

        unsafe { replace_root(request_state, post_root, Value::Null) };
        let nested_value = NativeValueHandle::from_value(Value::Bool(true));
        let nested_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_POST",
                &[b"root", b"leaf"],
                nested_value,
            )
        };
        unsafe { phpc_native_value_free(nested_value) };
        assert_request_state_presence_result_for_test(
            nested_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let post_snapshot = unsafe { snapshot_value(request_state, post_root) };
        let Value::Array(post_array) = post_snapshot else {
            panic!("path writes should re-enter array-backed request storage");
        };
        let Some(Value::Array(root_array)) = post_array.get_cloned(ArrayKey::string("root")) else {
            panic!("path writes should materialize nested request arrays");
        };
        assert_eq!(
            root_array.get_cloned(ArrayKey::string("leaf")),
            Some(Value::Bool(true))
        );

        let mut request_array = PhpArray::new();
        request_array.insert(
            ArrayKey::string("id"),
            Value::String("array-root".to_string()),
        );
        unsafe { replace_root(request_state, request_root, Value::Array(request_array)) };
        assert_array_slot(
            &unsafe { snapshot_value(request_state, request_root) },
            "id",
            Value::String("array-root".to_string()),
        );

        let request_read = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_REQUEST",
                Some(b"id"),
            )
        };
        assert_eq!(request_read.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        assert_eq!(
            unsafe { request_read.value.as_ref() },
            Some(&Value::String("array-root".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(request_read) };

        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(post_root) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_root_reference_replacements_share_direct_cells_and_keyed_array_mutation(
    ) {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn snapshot_value(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
        ) -> Value {
            let snapshot = unsafe {
                phpc_native_request_state_superglobal_snapshot_value(request_state, root)
            };
            let value = unsafe { snapshot.as_ref() }
                .expect("request root snapshots should return a value")
                .clone();
            unsafe { phpc_native_value_free(snapshot) };
            value
        }

        unsafe fn replace_reference(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
            reference: NativeReferenceHandle,
        ) {
            let mut diagnostic = NativeDiagnosticHandle::null();
            let replaced = unsafe {
                phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                    request_state,
                    root,
                    reference,
                    &mut diagnostic,
                )
            };
            if !diagnostic.is_null() {
                let message = native_diagnostic_message_for_test(diagnostic);
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                panic!("{message}");
            }
            assert!(replaced);
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = NativeValueHandle::from_value(value);
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let post_root = unsafe { string_handle(b"_POST") };
        let request_root = unsafe { string_handle(b"_REQUEST") };
        let invalid_root = unsafe { string_handle(b"_NOPE") };
        let roots = [
            (get_root, b"_GET".as_slice()),
            (post_root, b"_POST".as_slice()),
            (request_root, b"_REQUEST".as_slice()),
        ];
        let reference = native_reference_from_value(Value::String("seed".to_string()));
        assert!(!phpc_native_reference_is_null(reference));

        let stale_value = NativeValueHandle::from_value(Value::String("stale".to_string()));
        for (root, bag) in roots {
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_value(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    b"stale".as_ptr(),
                    b"stale".len(),
                    stale_value,
                )
            });
            unsafe { replace_reference(request_state, root, reference) };

            let stale_read = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(b"stale"),
                )
            };
            assert_eq!(
                stale_read.status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
            );
            assert_eq!(unsafe { stale_read.value.as_ref() }, Some(&Value::Null));
            unsafe { phpc_native_request_state_operation_result_free(stale_read) };
            assert_eq!(
                unsafe { snapshot_value(request_state, root) },
                Value::String("seed".to_string())
            );
        }
        unsafe { phpc_native_value_free(stale_value) };

        let mut referenced_array = PhpArray::new();
        referenced_array.insert(
            ArrayKey::string("id"),
            Value::String("array-ref".to_string()),
        );
        unsafe { set_reference_value(reference, Value::Array(referenced_array)) };
        for (_, bag) in roots {
            let keyed_read = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(b"id"),
                )
            };
            assert_eq!(keyed_read.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(
                unsafe { keyed_read.value.as_ref() },
                Some(&Value::String("array-ref".to_string()))
            );
            unsafe { phpc_native_request_state_operation_result_free(keyed_read) };
        }

        let keyed_value = NativeValueHandle::from_value(Value::Int(9));
        let keyed_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"new",
                keyed_value,
            )
        };
        unsafe { phpc_native_value_free(keyed_value) };
        assert_request_state_presence_result_for_test(
            keyed_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        assert_eq!(
            unsafe { snapshot_value(request_state, get_root) },
            Value::Array({
                let mut array = PhpArray::new();
                array.insert(
                    ArrayKey::string("id"),
                    Value::String("array-ref".to_string()),
                );
                array.insert(ArrayKey::string("new"), Value::Int(9));
                array
            })
        );

        unsafe { set_reference_value(reference, Value::String("updated".to_string())) };
        for (root, _) in roots {
            assert_eq!(
                unsafe { snapshot_value(request_state, root) },
                Value::String("updated".to_string())
            );
        }

        unsafe { set_reference_value(reference, Value::Null) };
        for (root, _) in roots {
            assert_eq!(unsafe { snapshot_value(request_state, root) }, Value::Null);
        }

        let mut diagnostic = NativeDiagnosticHandle::null();
        assert!(!unsafe {
            phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                request_state,
                invalid_root,
                reference,
                &mut diagnostic,
            )
        });
        assert!(!diagnostic.is_null());
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        diagnostic = NativeDiagnosticHandle::null();
        assert!(!unsafe {
            phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                request_state,
                get_root,
                NativeReferenceHandle::null(),
                &mut diagnostic,
            )
        });
        assert!(!diagnostic.is_null());
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        unsafe { phpc_native_reference_free(reference) };
        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(post_root) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_root_value_replacements_update_existing_reference_cells() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn snapshot_value(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
        ) -> Value {
            let snapshot = unsafe {
                phpc_native_request_state_superglobal_snapshot_value(request_state, root)
            };
            let value = unsafe { snapshot.as_ref() }
                .expect("request root snapshots should return a value")
                .clone();
            unsafe { phpc_native_value_free(snapshot) };
            value
        }

        unsafe fn replace_reference(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
            reference: NativeReferenceHandle,
        ) {
            let mut diagnostic = NativeDiagnosticHandle::null();
            let replaced = unsafe {
                phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                    request_state,
                    root,
                    reference,
                    &mut diagnostic,
                )
            };
            if !diagnostic.is_null() {
                let message = native_diagnostic_message_for_test(diagnostic);
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                panic!("{message}");
            }
            assert!(replaced);
        }

        unsafe fn replace_root_value(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
            value: Value,
        ) {
            let value = NativeValueHandle::from_value(value);
            let mut diagnostic = NativeDiagnosticHandle::null();
            let replaced = unsafe {
                phpc_native_request_state_superglobal_replace_value_with_diagnostic(
                    request_state,
                    root,
                    value,
                    &mut diagnostic,
                )
            };
            unsafe { phpc_native_value_free(value) };
            if !diagnostic.is_null() {
                let message = native_diagnostic_message_for_test(diagnostic);
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                panic!("{message}");
            }
            assert!(replaced);
        }

        unsafe fn reference_value(reference: NativeReferenceHandle) -> Value {
            let handle = unsafe { phpc_native_reference_value_clone(reference) };
            let value = unsafe { handle.as_ref() }
                .expect("reference value clones should return a value")
                .clone();
            unsafe { phpc_native_value_free(handle) };
            value
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let post_root = unsafe { string_handle(b"_POST") };
        let cookie_root = unsafe { string_handle(b"_COOKIE") };
        let request_root = unsafe { string_handle(b"_REQUEST") };
        let roots = [
            (get_root, b"_GET".as_slice()),
            (post_root, b"_POST".as_slice()),
            (cookie_root, b"_COOKIE".as_slice()),
            (request_root, b"_REQUEST".as_slice()),
        ];
        let reference = native_reference_from_value(Value::String("seed".to_string()));
        assert!(!phpc_native_reference_is_null(reference));

        for (root, _) in roots {
            unsafe { replace_reference(request_state, root, reference) };
        }

        unsafe { replace_root_value(request_state, get_root, Value::String("scalar".to_string())) };
        assert_eq!(
            unsafe { reference_value(reference) },
            Value::String("scalar".to_string())
        );
        for (root, _) in roots {
            assert_eq!(
                unsafe { snapshot_value(request_state, root) },
                Value::String("scalar".to_string())
            );
        }

        let mut replacement_array = PhpArray::new();
        replacement_array.insert(ArrayKey::string("id"), Value::String("array".to_string()));
        let replacement_value = Value::Array(replacement_array);
        unsafe { replace_root_value(request_state, post_root, replacement_value.clone()) };
        assert_eq!(unsafe { reference_value(reference) }, replacement_value);
        for (_, bag) in roots {
            let keyed_read = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(b"id"),
                )
            };
            assert_eq!(keyed_read.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(
                unsafe { keyed_read.value.as_ref() },
                Some(&Value::String("array".to_string()))
            );
            unsafe { phpc_native_request_state_operation_result_free(keyed_read) };
        }

        unsafe { replace_root_value(request_state, cookie_root, Value::Null) };
        assert_eq!(unsafe { reference_value(reference) }, Value::Null);
        for (root, _) in roots {
            assert_eq!(unsafe { snapshot_value(request_state, root) }, Value::Null);
        }

        unsafe { phpc_native_reference_free(reference) };
        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(cookie_root) };
        unsafe { phpc_native_string_free(post_root) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_root_value_operation_tracks_unset_and_reseeded_roots() {
        unsafe {
            let request_state = phpc_native_request_state_empty();

            let scalar_root = NativeValueHandle::from_value(Value::String("root".into()));
            let scalar_write = request_state_bag_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                scalar_root,
            );
            assert_request_state_presence_result_for_test(
                scalar_write,
                1,
                1,
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            );
            phpc_native_value_free(scalar_root);

            let scalar_read = request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ROOT_VALUE,
                b"_GET",
                None,
            );
            assert_eq!(
                scalar_read.result_kind,
                PHPC_NATIVE_REQUEST_STATE_OP_ROOT_VALUE
            );
            assert_eq!(scalar_read.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(scalar_read.is_set, 1);
            assert_eq!(scalar_read.exists, 1);
            assert_eq!(
                scalar_read.value.as_ref(),
                Some(&Value::String("root".into()))
            );
            phpc_native_request_state_operation_result_free(scalar_read);

            let unset = request_state_bag_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET,
                b"_GET",
                NativeValueHandle::null(),
            );
            assert_request_state_presence_result_for_test(
                unset,
                0,
                0,
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            );

            let keyed_after_unset = request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                Some(b"name"),
            );
            assert_eq!(
                keyed_after_unset.status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_ROOT
            );
            phpc_native_request_state_operation_result_free(keyed_after_unset);

            let root_after_unset = request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ROOT_VALUE,
                b"_GET",
                None,
            );
            assert_eq!(
                root_after_unset.result_kind,
                PHPC_NATIVE_REQUEST_STATE_OP_ROOT_VALUE
            );
            assert_eq!(
                root_after_unset.status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_ROOT
            );
            assert_eq!(root_after_unset.is_set, 0);
            assert_eq!(root_after_unset.exists, 0);
            assert_eq!(root_after_unset.value.as_ref(), Some(&Value::Null));
            phpc_native_request_state_operation_result_free(root_after_unset);

            let restored_value = NativeValueHandle::from_value(Value::String("restored".into()));
            let restored_write = request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"name",
                restored_value,
            );
            assert_request_state_presence_result_for_test(
                restored_write,
                1,
                1,
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            );
            phpc_native_value_free(restored_value);

            let restored_read = request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                Some(b"name"),
            );
            assert_eq!(restored_read.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(
                restored_read.value.as_ref(),
                Some(&Value::String("restored".into()))
            );
            phpc_native_request_state_operation_result_free(restored_read);

            phpc_native_request_state_free(request_state);
        }
    }

    #[test]
    fn native_request_state_reference_backed_roots_apply_keyed_path_and_append_mutations() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn replace_reference(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
            reference: NativeReferenceHandle,
        ) {
            let mut diagnostic = NativeDiagnosticHandle::null();
            let replaced = unsafe {
                phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                    request_state,
                    root,
                    reference,
                    &mut diagnostic,
                )
            };
            if !diagnostic.is_null() {
                let message = native_diagnostic_message_for_test(diagnostic);
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                panic!("{message}");
            }
            assert!(replaced);
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = NativeValueHandle::from_value(value);
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn reference_value(reference: NativeReferenceHandle) -> Value {
            let value = unsafe { phpc_native_reference_value_clone(reference) };
            let cloned = unsafe { value.as_ref() }
                .expect("reference value clones should return a value")
                .clone();
            unsafe { phpc_native_value_free(value) };
            cloned
        }

        unsafe fn read_path(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            keys: &[&[u8]],
        ) -> Value {
            let result = unsafe {
                request_state_path_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    keys,
                )
            };
            assert_eq!(result.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            let value = unsafe { result.value.as_ref() }
                .expect("request path read should return a value")
                .clone();
            unsafe { phpc_native_request_state_operation_result_free(result) };
            value
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let post_root = unsafe { string_handle(b"_POST") };
        let cookie_root = unsafe { string_handle(b"_COOKIE") };
        let request_root = unsafe { string_handle(b"_REQUEST") };
        let roots = [
            (get_root, b"_GET".as_slice()),
            (post_root, b"_POST".as_slice()),
            (cookie_root, b"_COOKIE".as_slice()),
            (request_root, b"_REQUEST".as_slice()),
        ];
        let reference = native_reference_from_value(Value::Null);

        for (root, _) in roots {
            unsafe { replace_reference(request_state, root, reference) };
        }

        let name_value = NativeValueHandle::from_value(Value::String("Ada".to_string()));
        let name_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"name",
                name_value,
            )
        };
        unsafe { phpc_native_value_free(name_value) };
        assert_request_state_presence_result_for_test(
            name_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        assert_eq!(
            unsafe { read_path(request_state, b"_POST", &[b"name"]) },
            Value::String("Ada".to_string())
        );

        let nested_value = NativeValueHandle::from_value(Value::Int(42));
        let nested_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_POST",
                &[b"profile", b"id"],
                nested_value,
            )
        };
        unsafe { phpc_native_value_free(nested_value) };
        assert_request_state_presence_result_for_test(
            nested_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        assert_eq!(
            unsafe { read_path(request_state, b"_GET", &[b"profile", b"id"]) },
            Value::Int(42)
        );

        let append_value = NativeValueHandle::from_value(Value::String("tail".to_string()));
        let append = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_APPEND,
                b"_COOKIE",
                &[b"items"],
                append_value,
            )
        };
        unsafe { phpc_native_value_free(append_value) };
        assert_request_state_presence_result_for_test(
            append,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        assert_eq!(
            unsafe { read_path(request_state, b"_REQUEST", &[b"items", b"0"]) },
            Value::String("tail".to_string())
        );

        let unset = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET,
                b"_REQUEST",
                b"name",
                NativeValueHandle::null(),
            )
        };
        assert_request_state_presence_result_for_test(
            unset,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let missing_name = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                b"_GET",
                Some(b"name"),
            )
        };
        assert_request_state_presence_result_for_test(
            missing_name,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY,
        );

        unsafe { set_reference_value(reference, Value::String("scalar".to_string())) };
        let blocked_value = NativeValueHandle::from_value(Value::Int(7));
        let blocked = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"blocked",
                blocked_value,
            )
        };
        unsafe { phpc_native_value_free(blocked_value) };
        assert_eq!(
            blocked.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );
        assert_eq!(
            unsafe { reference_value(reference) },
            Value::String("scalar".to_string())
        );

        unsafe { set_reference_value(reference, Value::Bool(false)) };
        let false_path_value = NativeValueHandle::from_value(Value::Bool(true));
        let false_path_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_POST",
                &[b"false-root", b"ok"],
                false_path_value,
            )
        };
        unsafe { phpc_native_value_free(false_path_value) };
        assert_request_state_presence_result_for_test(
            false_path_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        assert_eq!(
            unsafe { read_path(request_state, b"_COOKIE", &[b"false-root", b"ok"]) },
            Value::Bool(true)
        );

        unsafe { phpc_native_reference_free(reference) };
        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(cookie_root) };
        unsafe { phpc_native_string_free(post_root) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_root_references_promote_tables_and_reuse_cells() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn value_handle(value: Value) -> NativeValueHandle {
            NativeValueHandle::from_value(value)
        }

        unsafe fn insert_value(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            key: &[u8],
            value: Value,
        ) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_value(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                    value,
                )
            });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn snapshot_value(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
        ) -> Value {
            let snapshot = unsafe {
                phpc_native_request_state_superglobal_snapshot_value(request_state, root)
            };
            let value = unsafe { snapshot.as_ref() }
                .expect("request root snapshots should return a value")
                .clone();
            unsafe { phpc_native_value_free(snapshot) };
            value
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn assert_reference_value(reference: NativeReferenceHandle, expected: Value) {
            let value = unsafe { phpc_native_reference_value_clone(reference) };
            assert_eq!(unsafe { value.as_ref() }, Some(&expected));
            unsafe { phpc_native_value_free(value) };
        }

        fn keyed_array(key: &str, value: &str) -> Value {
            let mut array = PhpArray::new();
            array.insert(ArrayKey::string(key), Value::String(value.to_string()));
            Value::Array(array)
        }

        let request_state = phpc_native_request_state_empty();
        let cases = [
            (b"_GET".as_slice(), "get"),
            (b"_POST".as_slice(), "post"),
            (b"_REQUEST".as_slice(), "request"),
        ];

        for (bag, prefix) in cases {
            let root = unsafe { string_handle(bag) };
            unsafe {
                insert_value(
                    request_state,
                    bag,
                    b"id",
                    Value::String(format!("{prefix}-seed")),
                );
            }

            let reference = unsafe {
                phpc_native_request_state_superglobal_reference_for_root(request_state, root)
            };
            assert!(!phpc_native_reference_is_null(reference));
            assert_eq!(
                unsafe { snapshot_value(request_state, root) },
                keyed_array("id", &format!("{prefix}-seed"))
            );

            unsafe {
                set_reference_value(reference, keyed_array("id", &format!("{prefix}-shared")));
            }
            let keyed_read = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(b"id"),
                )
            };
            assert_eq!(keyed_read.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(
                unsafe { keyed_read.value.as_ref() },
                Some(&Value::String(format!("{prefix}-shared")))
            );
            unsafe { phpc_native_request_state_operation_result_free(keyed_read) };

            let second_reference = unsafe {
                phpc_native_request_state_superglobal_reference_for_root(request_state, root)
            };
            assert!(!phpc_native_reference_is_null(second_reference));
            unsafe {
                set_reference_value(second_reference, Value::String(format!("{prefix}-scalar")));
                assert_reference_value(reference, Value::String(format!("{prefix}-scalar")));
            }
            assert_eq!(
                unsafe { snapshot_value(request_state, root) },
                Value::String(format!("{prefix}-scalar"))
            );

            unsafe { phpc_native_reference_free(second_reference) };
            unsafe { phpc_native_reference_free(reference) };
            unsafe { phpc_native_string_free(root) };
        }

        let invalid_root = unsafe { string_handle(b"_NOPE") };
        assert!(unsafe {
            phpc_native_request_state_superglobal_reference_for_root(request_state, invalid_root)
        }
        .is_null());
        assert!(unsafe {
            phpc_native_request_state_superglobal_reference_for_root(
                NativeRequestStateHandle::null(),
                invalid_root,
            )
        }
        .is_null());

        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_keyed_reference_results_bind_shared_cells() {
        unsafe fn value_handle(value: Value) -> NativeValueHandle {
            NativeValueHandle::from_value(value)
        }

        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn reference_value(reference: NativeReferenceHandle) -> Value {
            let value = unsafe { phpc_native_reference_value_clone(reference) };
            let cloned = unsafe { value.as_ref() }
                .expect("reference value clones should return a value")
                .clone();
            unsafe { phpc_native_value_free(value) };
            cloned
        }

        unsafe fn assert_request_value(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            key: &[u8],
            expected: Value,
        ) {
            let value = unsafe {
                phpc_native_request_state_superglobal_value(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                )
            };
            assert_eq!(unsafe { value.as_ref() }, Some(&expected));
            unsafe { phpc_native_value_free(value) };
        }

        let request_state = phpc_native_request_state_empty();
        let cases = [
            (b"_GET".as_slice(), b"id".as_slice(), "get"),
            (b"_REQUEST".as_slice(), b"name".as_slice(), "request"),
        ];

        for (bag, key, prefix) in cases {
            let reference = unsafe {
                phpc_native_request_state_superglobal_keyed_reference_operation(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                    PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                )
            };
            assert_eq!(reference.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert!(!phpc_native_reference_is_null(reference.reference));
            unsafe {
                set_reference_value(
                    reference.reference,
                    Value::String(format!("{prefix}-value")),
                );
                assert_request_value(
                    request_state,
                    bag,
                    key,
                    Value::String(format!("{prefix}-value")),
                );
                phpc_native_request_state_reference_result_free(reference);
            }
        }

        let shared = unsafe {
            phpc_native_request_state_superglobal_keyed_reference_operation(
                request_state,
                b"_GET".as_ptr(),
                b"_GET".len(),
                b"id".as_ptr(),
                b"id".len(),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        };
        assert_eq!(shared.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        let bind = unsafe {
            phpc_native_request_state_superglobal_keyed_reference_bind_operation(
                request_state,
                b"_POST".as_ptr(),
                b"_POST".len(),
                b"alias".as_ptr(),
                b"alias".len(),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                shared.reference,
            )
        };
        assert_eq!(bind.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        unsafe {
            set_reference_value(shared.reference, Value::String("shared".to_string()));
            assert_request_value(
                request_state,
                b"_GET",
                b"id",
                Value::String("shared".to_string()),
            );
            assert_request_value(
                request_state,
                b"_POST",
                b"alias",
                Value::String("shared".to_string()),
            );
            phpc_native_request_state_operation_result_free(bind);
        }

        let cookie_root = unsafe { string_handle(b"_COOKIE") };
        let mut backing = PhpArray::new();
        backing.insert("seed", Value::String("old".to_string()));
        let root_reference = native_reference_from_value(Value::Array(backing));
        let mut diagnostic = NativeDiagnosticHandle::null();
        let replaced = unsafe {
            phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                request_state,
                cookie_root,
                root_reference,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert!(replaced);

        let target_reference = native_reference_from_value(Value::String("initial".to_string()));
        let root_bind = unsafe {
            phpc_native_request_state_superglobal_keyed_reference_bind_operation(
                request_state,
                b"_COOKIE".as_ptr(),
                b"_COOKIE".len(),
                b"alias".as_ptr(),
                b"alias".len(),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                target_reference,
            )
        };
        assert_eq!(root_bind.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        unsafe {
            set_reference_value(target_reference, Value::String("bound".to_string()));
            assert_request_value(
                request_state,
                b"_COOKIE",
                b"alias",
                Value::String("bound".to_string()),
            );
        }
        let Value::Array(root_snapshot) = (unsafe { reference_value(root_reference) }) else {
            panic!("reference-backed request root should remain an array after keyed bind");
        };
        assert_eq!(
            root_snapshot.get_cloned("alias"),
            Some(Value::String("bound".to_string()))
        );

        let root_source = unsafe {
            phpc_native_request_state_superglobal_keyed_reference_operation(
                request_state,
                b"_COOKIE".as_ptr(),
                b"_COOKIE".len(),
                b"seed".as_ptr(),
                b"seed".len(),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        };
        assert_eq!(root_source.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        unsafe {
            set_reference_value(root_source.reference, Value::String("changed".to_string()));
            assert_request_value(
                request_state,
                b"_COOKIE",
                b"seed",
                Value::String("changed".to_string()),
            );
            phpc_native_request_state_operation_result_free(root_bind);
            phpc_native_request_state_reference_result_free(root_source);
            phpc_native_reference_free(target_reference);
            phpc_native_reference_free(root_reference);
            phpc_native_string_free(cookie_root);
        }

        let bad_key = unsafe {
            phpc_native_request_state_superglobal_keyed_reference_operation(
                request_state,
                b"_GET".as_ptr(),
                b"_GET".len(),
                ptr::null(),
                0,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION,
            )
        };
        assert_eq!(
            bad_key.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION
        );
        assert!(phpc_native_reference_is_null(bad_key.reference));
        let bad_key_diagnostic = bad_key.status_diagnostic();
        assert!(!bad_key_diagnostic.is_null());
        unsafe { phpc_native_diagnostic_free(bad_key_diagnostic) };

        let bad_bind = unsafe {
            phpc_native_request_state_superglobal_keyed_reference_bind_operation(
                request_state,
                b"_COOKIE".as_ptr(),
                b"_COOKIE".len(),
                b"id".as_ptr(),
                b"id".len(),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                NativeReferenceHandle::null(),
            )
        };
        assert_eq!(
            bad_bind.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI
        );
        unsafe {
            phpc_native_request_state_operation_result_free(bad_bind);
            phpc_native_request_state_reference_result_free(shared);
            phpc_native_request_state_free(request_state);
        }
    }

    #[test]
    fn native_request_state_path_reference_results_bind_nested_cells() {
        unsafe fn value_handle(value: Value) -> NativeValueHandle {
            NativeValueHandle::from_value(value)
        }

        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn path_reference(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            keys: &[&[u8]],
        ) -> NativeRequestStateReferenceResult {
            let ptrs = keys.iter().map(|key| key.as_ptr()).collect::<Vec<_>>();
            let lens = keys.iter().map(|key| key.len()).collect::<Vec<_>>();
            unsafe {
                phpc_native_request_state_superglobal_path_reference_operation(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    ptrs.as_ptr(),
                    lens.as_ptr(),
                    keys.len(),
                    PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                )
            }
        }

        unsafe fn bind_path_reference(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            keys: &[&[u8]],
            reference: NativeReferenceHandle,
        ) -> NativeRequestStateOperationResult {
            let ptrs = keys.iter().map(|key| key.as_ptr()).collect::<Vec<_>>();
            let lens = keys.iter().map(|key| key.len()).collect::<Vec<_>>();
            unsafe {
                phpc_native_request_state_superglobal_path_reference_bind_operation(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    ptrs.as_ptr(),
                    lens.as_ptr(),
                    keys.len(),
                    PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                    reference,
                )
            }
        }

        unsafe fn assert_request_path_value(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            keys: &[&[u8]],
            expected: Value,
        ) {
            let ptrs = keys.iter().map(|key| key.as_ptr()).collect::<Vec<_>>();
            let lens = keys.iter().map(|key| key.len()).collect::<Vec<_>>();
            let value = unsafe {
                phpc_native_request_state_superglobal_path_operation(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag.as_ptr(),
                    bag.len(),
                    ptrs.as_ptr(),
                    lens.as_ptr(),
                    keys.len(),
                    PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                )
            };
            assert_eq!(value.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(unsafe { value.value.as_ref() }, Some(&expected));
            unsafe { phpc_native_request_state_operation_result_free(value) };
        }

        let request_state = phpc_native_request_state_empty();
        let source = unsafe {
            path_reference(
                request_state,
                b"_GET",
                &[b"outer".as_slice(), b"slot".as_slice()],
            )
        };
        assert_eq!(source.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        assert!(!phpc_native_reference_is_null(source.reference));
        unsafe {
            set_reference_value(source.reference, Value::String("source".to_string()));
            assert_request_path_value(
                request_state,
                b"_GET",
                &[b"outer".as_slice(), b"slot".as_slice()],
                Value::String("source".to_string()),
            );
        }

        let bind = unsafe {
            bind_path_reference(
                request_state,
                b"_POST",
                &[b"copy".as_slice(), b"slot".as_slice()],
                source.reference,
            )
        };
        assert_eq!(bind.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        unsafe {
            phpc_native_request_state_operation_result_free(bind);
            set_reference_value(source.reference, Value::String("shared".to_string()));
            assert_request_path_value(
                request_state,
                b"_GET",
                &[b"outer".as_slice(), b"slot".as_slice()],
                Value::String("shared".to_string()),
            );
            assert_request_path_value(
                request_state,
                b"_POST",
                &[b"copy".as_slice(), b"slot".as_slice()],
                Value::String("shared".to_string()),
            );
        }

        let cookie_root = unsafe { string_handle(b"_COOKIE") };
        let root = unsafe {
            phpc_native_request_state_superglobal_reference_for_root(request_state, cookie_root)
        };
        assert!(!phpc_native_reference_is_null(root));
        unsafe {
            set_reference_value(root, Value::Null);
        }
        let nested = unsafe {
            path_reference(
                request_state,
                b"_COOKIE",
                &[b"box".as_slice(), b"leaf".as_slice()],
            )
        };
        assert_eq!(nested.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        unsafe {
            set_reference_value(nested.reference, Value::String("root-ref".to_string()));
            assert_request_path_value(
                request_state,
                b"_COOKIE",
                &[b"box".as_slice(), b"leaf".as_slice()],
                Value::String("root-ref".to_string()),
            );
        }

        let invalid = unsafe { path_reference(request_state, b"_GET", &[]) };
        assert_eq!(invalid.status, PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI);
        assert!(phpc_native_reference_is_null(invalid.reference));

        unsafe {
            phpc_native_request_state_reference_result_free(source);
            phpc_native_reference_free(root);
            phpc_native_string_free(cookie_root);
            phpc_native_request_state_reference_result_free(nested);
            phpc_native_request_state_free(request_state);
        }
    }

    #[test]
    fn native_request_state_append_reference_results_bind_root_and_nested_cells() {
        unsafe fn value_handle(value: Value) -> NativeValueHandle {
            NativeValueHandle::from_value(value)
        }

        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn append_reference(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            keys: &[&[u8]],
            reference: NativeReferenceHandle,
        ) -> NativeRequestStateOperationResult {
            let ptrs = keys.iter().map(|key| key.as_ptr()).collect::<Vec<_>>();
            let lens = keys.iter().map(|key| key.len()).collect::<Vec<_>>();
            let (ptrs, lens) = if keys.is_empty() {
                (ptr::null(), ptr::null())
            } else {
                (ptrs.as_ptr(), lens.as_ptr())
            };
            unsafe {
                phpc_native_request_state_superglobal_path_reference_append_operation(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    ptrs,
                    lens,
                    keys.len(),
                    PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                    reference,
                )
            }
        }

        unsafe fn append_reference_source(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            keys: &[&[u8]],
        ) -> NativeRequestStateReferenceResult {
            let ptrs = keys.iter().map(|key| key.as_ptr()).collect::<Vec<_>>();
            let lens = keys.iter().map(|key| key.len()).collect::<Vec<_>>();
            let (ptrs, lens) = if keys.is_empty() {
                (ptr::null(), ptr::null())
            } else {
                (ptrs.as_ptr(), lens.as_ptr())
            };
            unsafe {
                phpc_native_request_state_superglobal_path_reference_append_source_operation(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    ptrs,
                    lens,
                    keys.len(),
                    PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                )
            }
        }

        unsafe fn assert_request_path_value(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            keys: &[&[u8]],
            expected: Value,
        ) {
            let ptrs = keys.iter().map(|key| key.as_ptr()).collect::<Vec<_>>();
            let lens = keys.iter().map(|key| key.len()).collect::<Vec<_>>();
            let value = unsafe {
                phpc_native_request_state_superglobal_path_operation(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag.as_ptr(),
                    bag.len(),
                    ptrs.as_ptr(),
                    lens.as_ptr(),
                    keys.len(),
                    PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                )
            };
            assert_eq!(value.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(unsafe { value.value.as_ref() }, Some(&expected));
            unsafe { phpc_native_request_state_operation_result_free(value) };
        }

        let request_state = phpc_native_request_state_empty();
        let source_reference = native_reference_from_value(Value::String("seed".to_string()));
        let root_append =
            unsafe { append_reference(request_state, b"_GET", &[], source_reference) };
        assert_request_state_presence_result_for_test(
            root_append,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        unsafe {
            set_reference_value(source_reference, Value::String("root-target".to_string()));
            assert_request_path_value(
                request_state,
                b"_GET",
                &[b"0".as_slice()],
                Value::String("root-target".to_string()),
            );
        }

        let root_source = unsafe { append_reference_source(request_state, b"_POST", &[]) };
        assert_eq!(root_source.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        assert!(!phpc_native_reference_is_null(root_source.reference));
        unsafe {
            set_reference_value(
                root_source.reference,
                Value::String("root-source".to_string()),
            );
            assert_request_path_value(
                request_state,
                b"_POST",
                &[b"0".as_slice()],
                Value::String("root-source".to_string()),
            );
        }

        let mirror_bind = unsafe {
            phpc_native_request_state_superglobal_keyed_reference_bind_operation(
                request_state,
                b"_COOKIE".as_ptr(),
                b"_COOKIE".len(),
                b"mirror".as_ptr(),
                b"mirror".len(),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                root_source.reference,
            )
        };
        assert_eq!(mirror_bind.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        unsafe {
            phpc_native_request_state_operation_result_free(mirror_bind);
            set_reference_value(root_source.reference, Value::String("shared".to_string()));
            assert_request_path_value(
                request_state,
                b"_POST",
                &[b"0".as_slice()],
                Value::String("shared".to_string()),
            );
            assert_request_path_value(
                request_state,
                b"_COOKIE",
                &[b"mirror".as_slice()],
                Value::String("shared".to_string()),
            );
        }

        let nested_source =
            unsafe { append_reference_source(request_state, b"_REQUEST", &[b"items".as_slice()]) };
        assert_eq!(nested_source.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        unsafe {
            set_reference_value(
                nested_source.reference,
                Value::String("nested-source".to_string()),
            );
            assert_request_path_value(
                request_state,
                b"_REQUEST",
                &[b"items".as_slice(), b"0".as_slice()],
                Value::String("nested-source".to_string()),
            );
        }

        let cookie_root = unsafe { string_handle(b"_COOKIE") };
        let cookie_reference = unsafe {
            phpc_native_request_state_superglobal_reference_for_root(request_state, cookie_root)
        };
        assert!(!phpc_native_reference_is_null(cookie_reference));
        unsafe {
            set_reference_value(cookie_reference, Value::Null);
        }
        let reference_backed_append = unsafe {
            append_reference(
                request_state,
                b"_COOKIE",
                &[b"box".as_slice()],
                source_reference,
            )
        };
        assert_request_state_presence_result_for_test(
            reference_backed_append,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        unsafe {
            set_reference_value(
                source_reference,
                Value::String("reference-backed".to_string()),
            );
            assert_request_path_value(
                request_state,
                b"_COOKIE",
                &[b"box".as_slice(), b"0".as_slice()],
                Value::String("reference-backed".to_string()),
            );
            set_reference_value(cookie_reference, Value::String("scalar".to_string()));
        }
        let blocked =
            unsafe { append_reference_source(request_state, b"_COOKIE", &[b"blocked".as_slice()]) };
        assert_eq!(
            blocked.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );
        assert!(phpc_native_reference_is_null(blocked.reference));

        unsafe {
            phpc_native_request_state_reference_result_free(blocked);
            phpc_native_reference_free(cookie_reference);
            phpc_native_string_free(cookie_root);
            phpc_native_request_state_reference_result_free(nested_source);
            phpc_native_request_state_reference_result_free(root_source);
            phpc_native_reference_free(source_reference);
            phpc_native_request_state_free(request_state);
        }
    }

    #[test]
    fn native_request_state_keyed_mutation_updates_multiple_superglobal_bags() {
        let request_state = phpc_native_request_state_empty();
        let get_key = b"cart-id";
        let get_value = NativeValueHandle::from_value(Value::String("A\0B".to_string()));
        let get_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                get_key,
                get_value,
            )
        };
        assert_request_state_presence_result_for_test(
            get_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );

        let get_read = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                Some(get_key),
            )
        };
        assert_eq!(get_read.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(get_read.exists, 1);
        assert_eq!(get_read.is_set, 1);
        assert_eq!(
            unsafe { get_read.value.as_ref() },
            Some(&Value::String("A\0B".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(get_read) };

        let files_key = b"upload";
        let files_value = NativeValueHandle::from_value(Value::Int(7));
        let files_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_FILES",
                files_key,
                files_value,
            )
        };
        assert_request_state_presence_result_for_test(
            files_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let files_array = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                b"_FILES",
                None,
            )
        };
        assert_eq!(files_array.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_ARRAY);
        let files_array_ref =
            unsafe { files_array.array.as_ref() }.expect("files array result is owned");
        assert_eq!(files_array_ref.value.len(), 1);
        assert_eq!(
            files_array_ref.value.get_cloned(ArrayKey::string("upload")),
            Some(Value::Int(7))
        );
        unsafe { phpc_native_request_state_operation_result_free(files_array) };

        let get_unset = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET,
                b"_GET",
                get_key,
                NativeValueHandle::null(),
            )
        };
        assert_request_state_presence_result_for_test(
            get_unset,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let get_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                b"_GET",
                Some(get_key),
            )
        };
        assert_request_state_presence_result_for_test(
            get_presence,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY,
        );

        let invalid_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_POST",
                b"missing-value",
                NativeValueHandle::null(),
            )
        };
        assert_eq!(invalid_write.result_kind, 0);
        assert_eq!(
            invalid_write.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI
        );

        let invalid_kind = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                99,
                b"_POST",
                b"slot",
                NativeValueHandle::null(),
            )
        };
        assert_eq!(invalid_kind.result_kind, 0);
        assert_eq!(
            invalid_kind.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_OPERATION
        );

        unsafe { phpc_native_value_free(files_value) };
        unsafe { phpc_native_value_free(get_value) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_path_mutation_shares_nested_key_semantics() {
        let request_state = phpc_native_request_state_empty();
        let nested_keys: [&[u8]; 3] = [b"cart", b"item", b"name"];
        let nested_value = NativeValueHandle::from_value(Value::String("P\0Q".to_string()));
        let nested_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_POST",
                &nested_keys,
                nested_value,
            )
        };
        assert_request_state_presence_result_for_test(
            nested_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let nested_read = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_POST",
                &nested_keys,
            )
        };
        assert_eq!(nested_read.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(nested_read.exists, 1);
        assert_eq!(nested_read.is_set, 1);
        assert_eq!(
            unsafe { nested_read.value.as_ref() },
            Some(&Value::String("P\0Q".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(nested_read) };

        let null_root = NativeValueHandle::from_value(Value::Null);
        let null_root_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_REQUEST",
                b"root",
                null_root,
            )
        };
        assert_request_state_presence_result_for_test(
            null_root_write,
            0,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let null_path_value = NativeValueHandle::from_value(Value::Int(12));
        let null_path_keys: [&[u8]; 2] = [b"root", b"leaf"];
        let null_path_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_REQUEST",
                &null_path_keys,
                null_path_value,
            )
        };
        assert_request_state_presence_result_for_test(
            null_path_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let null_path_read = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_REQUEST",
                &null_path_keys,
            )
        };
        assert_eq!(
            unsafe { null_path_read.value.as_ref() },
            Some(&Value::Int(12))
        );
        unsafe { phpc_native_request_state_operation_result_free(null_path_read) };

        let false_root = NativeValueHandle::from_value(Value::Bool(false));
        let false_root_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_COOKIE",
                b"root",
                false_root,
            )
        };
        assert_request_state_presence_result_for_test(
            false_root_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let false_path_value = NativeValueHandle::from_value(Value::Bool(true));
        let false_path_keys: [&[u8]; 2] = [b"root", b"enabled"];
        let false_path_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_COOKIE",
                &false_path_keys,
                false_path_value,
            )
        };
        assert_request_state_presence_result_for_test(
            false_path_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let false_path_read = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_COOKIE",
                &false_path_keys,
            )
        };
        assert_eq!(
            unsafe { false_path_read.value.as_ref() },
            Some(&Value::Bool(true))
        );
        unsafe { phpc_native_request_state_operation_result_free(false_path_read) };

        let root_append_value = NativeValueHandle::from_value(Value::String("root".to_string()));
        let root_append = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_APPEND,
                b"_GET",
                &[],
                root_append_value,
            )
        };
        assert_request_state_presence_result_for_test(
            root_append,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let root_append_read = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                &[b"0"],
            )
        };
        assert_eq!(
            unsafe { root_append_read.value.as_ref() },
            Some(&Value::String("root".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(root_append_read) };

        let nested_append_value =
            NativeValueHandle::from_value(Value::String("nested".to_string()));
        let nested_append_keys: [&[u8]; 2] = [b"append", b"items"];
        let nested_append = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_APPEND,
                b"_POST",
                &nested_append_keys,
                nested_append_value,
            )
        };
        assert_request_state_presence_result_for_test(
            nested_append,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let nested_append_read = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_POST",
                &[b"append", b"items", b"0"],
            )
        };
        assert_eq!(
            unsafe { nested_append_read.value.as_ref() },
            Some(&Value::String("nested".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(nested_append_read) };

        let scalar_root = NativeValueHandle::from_value(Value::String("x".to_string()));
        let scalar_root_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"scalar",
                scalar_root,
            )
        };
        assert_request_state_presence_result_for_test(
            scalar_root_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let scalar_path_value = NativeValueHandle::from_value(Value::Int(99));
        let scalar_path_keys: [&[u8]; 2] = [b"scalar", b"child"];
        let scalar_path_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                &scalar_path_keys,
                scalar_path_value,
            )
        };
        assert_eq!(scalar_path_write.result_kind, 0);
        assert_eq!(
            scalar_path_write.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );

        let nested_unset = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET,
                b"_POST",
                &nested_keys,
                NativeValueHandle::null(),
            )
        };
        assert_request_state_presence_result_for_test(
            nested_unset,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let nested_presence = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                b"_POST",
                &nested_keys,
            )
        };
        assert_request_state_presence_result_for_test(
            nested_presence,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY,
        );

        let invalid_path = unsafe {
            phpc_native_request_state_superglobal_path_mutation_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET,
                b"_POST".as_ptr(),
                b"_POST".len(),
                ptr::null(),
                ptr::null(),
                0,
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(invalid_path.result_kind, 0);
        assert_eq!(
            invalid_path.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI
        );

        unsafe { phpc_native_value_free(scalar_path_value) };
        unsafe { phpc_native_value_free(scalar_root) };
        unsafe { phpc_native_value_free(false_path_value) };
        unsafe { phpc_native_value_free(false_root) };
        unsafe { phpc_native_value_free(nested_append_value) };
        unsafe { phpc_native_value_free(root_append_value) };
        unsafe { phpc_native_value_free(null_path_value) };
        unsafe { phpc_native_value_free(null_root) };
        unsafe { phpc_native_value_free(nested_value) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_rebuilds_request_and_snapshots_backing_tables() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn insert_string(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            key: &[u8],
            value: &str,
        ) {
            let value = NativeValueHandle::from_value(Value::String(value.to_string()));
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_value(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                    value,
                )
            });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn assert_value_echo_and_free(handle: NativeValueHandle, expected: &[u8]) {
            assert_eq!(native_value_echo_bytes_for_test(handle), expected);
            unsafe { phpc_native_value_free(handle) };
        }

        unsafe fn assert_snapshot_slot(snapshot: NativeValueHandle, key: &str, expected: &str) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request snapshot should materialize an array value");
            };
            assert_eq!(
                array.get(ArrayKey::string(key)),
                Some(&Value::String(expected.to_string()))
            );
        }

        unsafe fn assert_missing_snapshot_slot(snapshot: NativeValueHandle, key: &str) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request snapshot should materialize an array value");
            };
            assert_eq!(array.get(ArrayKey::string(key)), None);
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let request_root = unsafe { string_handle(b"_REQUEST") };
        let invalid_root = unsafe { string_handle(b"_NOPE") };
        let order_gp = unsafe { string_handle(b"GP") };
        let order_cg = unsafe { string_handle(b"CG") };
        let order_g = unsafe { string_handle(b"G") };
        let request_order_pg = unsafe { string_handle(b"PG") };
        let empty_request_order = unsafe { string_handle(b"") };
        let variables_order_egpsc = unsafe { string_handle(b"EGPSC") };
        let variables_order_cg = unsafe { string_handle(b"CG") };

        unsafe { insert_string(request_state, b"_GET", b"id", "get") };
        unsafe { insert_string(request_state, b"_POST", b"id", "post") };
        unsafe { insert_string(request_state, b"_COOKIE", b"id", "cookie") };
        unsafe { insert_string(request_state, b"_COOKIE", b"sid", "cookie-session") };
        unsafe { insert_string(request_state, b"_REQUEST", b"stale", "stale-request") };

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_order(request_state, order_gp)
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"post",
            );
        }

        let request_snapshot = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, request_root)
        };
        let get_snapshot = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, get_root)
        };
        assert!(!request_snapshot.is_null());
        assert!(!get_snapshot.is_null());
        unsafe {
            assert_snapshot_slot(request_snapshot, "id", "post");
            assert_missing_snapshot_slot(request_snapshot, "sid");
            assert_missing_snapshot_slot(request_snapshot, "stale");
            assert_snapshot_slot(get_snapshot, "id", "get");
        }

        unsafe { insert_string(request_state, b"_POST", b"id", "post-after-snapshot") };
        unsafe {
            assert_snapshot_slot(request_snapshot, "id", "post");
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_POST".as_ptr(),
                    b"_POST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"post-after-snapshot",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_order(request_state, order_cg)
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"get",
            );
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"sid".as_ptr(),
                    b"sid".len(),
                ),
                b"cookie-session",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_order(request_state, order_g)
        });
        let request_after_g = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, request_root)
        };
        unsafe {
            assert_snapshot_slot(request_after_g, "id", "get");
            assert_missing_snapshot_slot(request_after_g, "sid");
            phpc_native_value_free(request_after_g);
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_policy(
                request_state,
                request_order_pg,
                variables_order_cg,
            )
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"get",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_policy(
                request_state,
                empty_request_order,
                variables_order_egpsc,
            )
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"cookie",
            );
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"sid".as_ptr(),
                    b"sid".len(),
                ),
                b"cookie-session",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_policy(
                request_state,
                NativeStringHandle::null(),
                variables_order_cg,
            )
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"get",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, invalid_root)
        }
        .is_null());
        assert!(!unsafe {
            phpc_native_request_state_rebuild_request_from_order(
                NativeRequestStateHandle::null(),
                order_g,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_rebuild_request_from_policy(
                request_state,
                NativeStringHandle::null(),
                NativeStringHandle::null(),
            )
        });

        unsafe { phpc_native_value_free(request_snapshot) };
        unsafe { phpc_native_value_free(get_snapshot) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_string_free(order_gp) };
        unsafe { phpc_native_string_free(order_cg) };
        unsafe { phpc_native_string_free(order_g) };
        unsafe { phpc_native_string_free(request_order_pg) };
        unsafe { phpc_native_string_free(empty_request_order) };
        unsafe { phpc_native_string_free(variables_order_egpsc) };
        unsafe { phpc_native_string_free(variables_order_cg) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_populates_sapi_roots_from_symbol_table_sources() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn write_symbol(table: NativeSymbolTableHandle, name: &[u8], value: Value) {
            let value = NativeValueHandle::from_value(value);
            assert!(unsafe {
                phpc_native_symbol_table_write(table, name.as_ptr(), name.len(), value)
            });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn snapshot(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
        ) -> NativeValueHandle {
            unsafe { phpc_native_request_state_superglobal_snapshot_value(request_state, root) }
        }

        unsafe fn assert_slot(snapshot: NativeValueHandle, key: &str, expected: Value) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request root snapshot should be an array");
            };
            assert_eq!(array.get(ArrayKey::string(key)), Some(&expected));
        }

        unsafe fn assert_missing(snapshot: NativeValueHandle, key: &str) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request root snapshot should be an array");
            };
            assert_eq!(array.get(ArrayKey::string(key)), None);
        }

        unsafe fn assert_order(snapshot: NativeValueHandle, expected: &[&str]) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request root snapshot should be an array");
            };
            let names: Vec<&str> = array
                .entries()
                .iter()
                .map(|entry| match &entry.key {
                    ArrayKey::String(name) => name.as_str(),
                    other => panic!("expected string request key, got {other:?}"),
                })
                .collect();
            assert_eq!(names, expected);
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let cookie_root = unsafe { string_handle(b"_COOKIE") };
        let server_root = unsafe { string_handle(b"_SERVER") };
        let files_root = unsafe { string_handle(b"_FILES") };
        let request_root = unsafe { string_handle(b"_REQUEST") };
        let invalid_root = unsafe { string_handle(b"_NOPE") };
        let order_cg = unsafe { string_handle(b"CG") };

        let get_source = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(get_source, b"id", Value::String("get".to_string()));
            write_symbol(get_source, b"page", Value::Int(7));
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                get_root,
                get_source,
            )
        });

        unsafe {
            write_symbol(get_source, b"id", Value::String("get-mutated".to_string()));
            write_symbol(
                get_source,
                b"late",
                Value::String("late-source".to_string()),
            );
        }
        let get_snapshot = unsafe { snapshot(request_state, get_root) };
        unsafe {
            assert_slot(get_snapshot, "id", Value::String("get".to_string()));
            assert_slot(get_snapshot, "page", Value::Int(7));
            assert_missing(get_snapshot, "late");
            assert_order(get_snapshot, &["id", "page"]);
        }

        let server_snapshot = {
            assert!(unsafe {
                phpc_native_request_state_populate_superglobal_from_symbol_table(
                    request_state,
                    server_root,
                    get_source,
                )
            });
            unsafe { snapshot(request_state, server_root) }
        };
        unsafe {
            assert_slot(
                server_snapshot,
                "id",
                Value::String("get-mutated".to_string()),
            );
            assert_slot(
                server_snapshot,
                "late",
                Value::String("late-source".to_string()),
            );
            assert_order(server_snapshot, &["id", "page", "late"]);
        }

        let cookie_source = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(
                cookie_source,
                b"id",
                Value::String("cookie-stale".to_string()),
            );
            write_symbol(cookie_source, b"stale", Value::String("stale".to_string()));
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                cookie_root,
                cookie_source,
            )
        });

        let cookie_replacement = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(
                cookie_replacement,
                b"id",
                Value::String("cookie".to_string()),
            );
            write_symbol(
                cookie_replacement,
                b"sid",
                Value::String("cookie-session".to_string()),
            );
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                cookie_root,
                cookie_replacement,
            )
        });
        let cookie_snapshot = unsafe { snapshot(request_state, cookie_root) };
        unsafe {
            assert_slot(cookie_snapshot, "id", Value::String("cookie".to_string()));
            assert_slot(
                cookie_snapshot,
                "sid",
                Value::String("cookie-session".to_string()),
            );
            assert_missing(cookie_snapshot, "stale");
        }

        let mut upload = PhpArray::new();
        upload.insert(
            ArrayKey::string("name"),
            Value::String("file.txt".to_string()),
        );
        let files_source = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(files_source, b"upload", Value::Array(upload.clone()));
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                files_root,
                files_source,
            )
        });
        let files_snapshot = unsafe { snapshot(request_state, files_root) };
        unsafe {
            assert_slot(files_snapshot, "upload", Value::Array(upload));
        }

        let request_source = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(
                request_source,
                b"manual",
                Value::String("manual-request".to_string()),
            );
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                request_root,
                request_source,
            )
        });
        let manual_request_snapshot = unsafe { snapshot(request_state, request_root) };
        unsafe {
            assert_slot(
                manual_request_snapshot,
                "manual",
                Value::String("manual-request".to_string()),
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_order(request_state, order_cg)
        });
        let rebuilt_request_snapshot = unsafe { snapshot(request_state, request_root) };
        unsafe {
            assert_slot(
                rebuilt_request_snapshot,
                "id",
                Value::String("get".to_string()),
            );
            assert_slot(
                rebuilt_request_snapshot,
                "sid",
                Value::String("cookie-session".to_string()),
            );
            assert_missing(rebuilt_request_snapshot, "manual");
            assert_missing(rebuilt_request_snapshot, "stale");
        }

        assert!(!unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                NativeRequestStateHandle::null(),
                get_root,
                get_source,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                invalid_root,
                get_source,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                get_root,
                NativeSymbolTableHandle::null(),
            )
        });

        unsafe { phpc_native_value_free(get_snapshot) };
        unsafe { phpc_native_value_free(server_snapshot) };
        unsafe { phpc_native_value_free(cookie_snapshot) };
        unsafe { phpc_native_value_free(files_snapshot) };
        unsafe { phpc_native_value_free(manual_request_snapshot) };
        unsafe { phpc_native_value_free(rebuilt_request_snapshot) };
        unsafe { phpc_native_symbol_table_free(get_source) };
        unsafe { phpc_native_symbol_table_free(cookie_source) };
        unsafe { phpc_native_symbol_table_free(cookie_replacement) };
        unsafe { phpc_native_symbol_table_free(files_source) };
        unsafe { phpc_native_symbol_table_free(request_source) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_string_free(cookie_root) };
        unsafe { phpc_native_string_free(server_root) };
        unsafe { phpc_native_string_free(files_root) };
        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_string_free(order_cg) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_symbol_and_request_reference_slots_share_cells_across_roots() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn value_handle(value: Value) -> NativeValueHandle {
            NativeValueHandle::from_value(value)
        }

        unsafe fn write_symbol(table: NativeSymbolTableHandle, name: &[u8], value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe {
                phpc_native_symbol_table_write(table, name.as_ptr(), name.len(), value)
            });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn read_symbol(table: NativeSymbolTableHandle, name: &[u8]) -> NativeValueHandle {
            unsafe { phpc_native_symbol_table_read(table, name.as_ptr(), name.len()) }
        }

        unsafe fn assert_value(handle: NativeValueHandle, expected: Value) {
            assert_eq!(unsafe { handle.as_ref() }, Some(&expected));
            unsafe { phpc_native_value_free(handle) };
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn assert_snapshot_slot(snapshot: NativeValueHandle, key: &str, expected: Value) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("snapshot should be an array");
            };
            assert_eq!(array.get_cloned(ArrayKey::string(key)), Some(expected));
        }

        let symbols = phpc_native_symbol_table_new();
        unsafe { write_symbol(symbols, b"root", Value::String("initial".to_string())) };

        let root_reference =
            unsafe { phpc_native_symbol_table_reference_for_slot(symbols, b"root".as_ptr(), 4) };
        assert!(!phpc_native_reference_is_null(root_reference));
        unsafe { set_reference_value(root_reference, Value::String("from-ref".to_string())) };
        unsafe {
            assert_value(
                read_symbol(symbols, b"root"),
                Value::String("from-ref".to_string()),
            );
        }

        assert!(unsafe {
            phpc_native_symbol_table_set_reference(symbols, b"alias".as_ptr(), 5, root_reference)
        });
        unsafe { set_reference_value(root_reference, Value::String("shared".to_string())) };
        unsafe {
            assert_value(
                read_symbol(symbols, b"root"),
                Value::String("shared".to_string()),
            );
            assert_value(
                read_symbol(symbols, b"alias"),
                Value::String("shared".to_string()),
            );
        }

        let created_reference =
            unsafe { phpc_native_symbol_table_reference_for_slot(symbols, b"created".as_ptr(), 7) };
        assert!(!phpc_native_reference_is_null(created_reference));
        unsafe { set_reference_value(created_reference, Value::Int(42)) };
        unsafe {
            assert_value(read_symbol(symbols, b"created"), Value::Int(42));
        }

        let symbol_snapshot = unsafe { phpc_native_symbol_table_snapshot_value(symbols) };
        unsafe {
            assert_snapshot_slot(symbol_snapshot, "root", Value::String("shared".to_string()));
            assert_snapshot_slot(
                symbol_snapshot,
                "alias",
                Value::String("shared".to_string()),
            );
            assert_snapshot_slot(symbol_snapshot, "created", Value::Int(42));
        }
        unsafe { set_reference_value(root_reference, Value::String("after-snapshot".to_string())) };
        unsafe {
            assert_snapshot_slot(symbol_snapshot, "root", Value::String("shared".to_string()));
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let post_root = unsafe { string_handle(b"_POST") };
        let invalid_root = unsafe { string_handle(b"_NOPE") };
        let id_name = unsafe { string_handle(b"id") };
        let alias_name = unsafe { string_handle(b"alias") };
        let invalid_name = unsafe { string_handle(&[0xff]) };

        let request_reference = unsafe {
            phpc_native_request_state_superglobal_reference_for_slot(
                request_state,
                get_root,
                id_name,
            )
        };
        assert!(!phpc_native_reference_is_null(request_reference));
        unsafe {
            set_reference_value(request_reference, Value::String("request-ref".to_string()));
            assert_value(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_GET".as_ptr(),
                    b"_GET".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                Value::String("request-ref".to_string()),
            );
        }

        assert!(unsafe {
            phpc_native_request_state_superglobal_set_reference(
                request_state,
                post_root,
                alias_name,
                root_reference,
            )
        });
        unsafe {
            set_reference_value(
                root_reference,
                Value::String("shared-with-post".to_string()),
            );
            assert_value(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_POST".as_ptr(),
                    b"_POST".len(),
                    b"alias".as_ptr(),
                    b"alias".len(),
                ),
                Value::String("shared-with-post".to_string()),
            );
        }

        let get_snapshot = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, get_root)
        };
        let post_snapshot = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, post_root)
        };
        unsafe {
            assert_snapshot_slot(get_snapshot, "id", Value::String("request-ref".to_string()));
            assert_snapshot_slot(
                post_snapshot,
                "alias",
                Value::String("shared-with-post".to_string()),
            );
        }

        assert!(unsafe {
            phpc_native_symbol_table_reference_for_slot(
                NativeSymbolTableHandle::null(),
                b"root".as_ptr(),
                4,
            )
        }
        .is_null());
        assert!(!unsafe {
            phpc_native_symbol_table_set_reference(
                NativeSymbolTableHandle::null(),
                b"root".as_ptr(),
                4,
                root_reference,
            )
        });
        assert!(unsafe {
            phpc_native_request_state_superglobal_reference_for_slot(
                NativeRequestStateHandle::null(),
                get_root,
                id_name,
            )
        }
        .is_null());
        assert!(unsafe {
            phpc_native_request_state_superglobal_reference_for_slot(
                request_state,
                invalid_root,
                id_name,
            )
        }
        .is_null());
        assert!(unsafe {
            phpc_native_request_state_superglobal_reference_for_slot(
                request_state,
                get_root,
                invalid_name,
            )
        }
        .is_null());
        assert!(!unsafe {
            phpc_native_request_state_superglobal_set_reference(
                request_state,
                get_root,
                id_name,
                NativeReferenceHandle::null(),
            )
        });

        unsafe { phpc_native_value_free(symbol_snapshot) };
        unsafe { phpc_native_value_free(get_snapshot) };
        unsafe { phpc_native_value_free(post_snapshot) };
        unsafe { phpc_native_reference_free(root_reference) };
        unsafe { phpc_native_reference_free(created_reference) };
        unsafe { phpc_native_reference_free(request_reference) };
        unsafe { phpc_native_symbol_table_free(symbols) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_string_free(post_root) };
        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_string_free(id_name) };
        unsafe { phpc_native_string_free(alias_name) };
        unsafe { phpc_native_string_free(invalid_name) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_symbol_table_reference_paths_alias_variables_arrays_and_appends() {
        unsafe fn value_handle(value: Value) -> NativeValueHandle {
            NativeValueHandle::from_value(value)
        }

        unsafe fn write_symbol(table: NativeSymbolTableHandle, name: &[u8], value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe {
                phpc_native_symbol_table_write(table, name.as_ptr(), name.len(), value)
            });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn write_symbol_path(table: NativeSymbolTableHandle, name: &str, value: Value) {
            let key = unsafe { value_handle(Value::String(name.to_string())) };
            let value = unsafe { value_handle(value) };
            let mut diagnostic = NativeDiagnosticHandle::null();
            assert!(unsafe {
                phpc_native_symbol_table_set_value_by_path_with_diagnostic(
                    table,
                    &key,
                    1,
                    value,
                    &mut diagnostic,
                )
            });
            assert!(diagnostic.is_null());
            unsafe { phpc_native_value_free(key) };
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn assert_symbol_value(
            table: NativeSymbolTableHandle,
            name: &[u8],
            expected: &[u8],
        ) {
            let value = unsafe { phpc_native_symbol_table_read(table, name.as_ptr(), name.len()) };
            assert_eq!(native_value_echo_bytes_for_test(value), expected);
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn assert_reference_value(reference: NativeReferenceHandle, expected: &[u8]) {
            let value = unsafe { phpc_native_reference_value_clone(reference) };
            assert_eq!(native_value_echo_bytes_for_test(value), expected);
            unsafe { phpc_native_value_free(value) };
        }

        let table = phpc_native_symbol_table_new();
        let source = b"source";
        let alias = b"alias";
        let array = b"array";
        let list = b"list";
        let list_alias = b"list_alias";
        let scalar = b"scalar";
        let value_alias = b"value_alias";
        let slot_key = unsafe { value_handle(Value::String("slot".to_string())) };
        let zero_key = unsafe { value_handle(Value::Int(0)) };
        let source_value_key = unsafe { value_handle(Value::String("source".to_string())) };
        let value_alias_key = unsafe { value_handle(Value::String("value_alias".to_string())) };
        let value_list_key = unsafe { value_handle(Value::String("value_list".to_string())) };

        unsafe { write_symbol(table, source, Value::String("initial".to_string())) };
        let source_ref = unsafe {
            phpc_native_symbol_table_reference_for_path(
                table,
                source.as_ptr(),
                source.len(),
                ptr::null(),
                0,
                false,
            )
        };
        assert!(!phpc_native_reference_is_null(source_ref));
        assert!(unsafe {
            phpc_native_symbol_table_bind_reference_path(
                table,
                alias.as_ptr(),
                alias.len(),
                ptr::null(),
                0,
                false,
                source_ref,
            )
        });
        unsafe { write_symbol_path(table, "alias", Value::String("through-alias".to_string())) };
        unsafe { assert_symbol_value(table, source, b"through-alias") };

        assert!(unsafe {
            phpc_native_symbol_table_bind_reference_path(
                table,
                array.as_ptr(),
                array.len(),
                &slot_key,
                1,
                false,
                source_ref,
            )
        });
        unsafe { set_reference_value(source_ref, Value::String("through-array".to_string())) };
        let array_ref = unsafe {
            phpc_native_symbol_table_reference_for_path(
                table,
                array.as_ptr(),
                array.len(),
                &slot_key,
                1,
                false,
            )
        };
        assert!(!phpc_native_reference_is_null(array_ref));
        unsafe { assert_reference_value(array_ref, b"through-array") };

        let append_ref = unsafe {
            phpc_native_symbol_table_reference_for_path(
                table,
                list.as_ptr(),
                list.len(),
                ptr::null(),
                0,
                true,
            )
        };
        assert!(!phpc_native_reference_is_null(append_ref));
        assert!(unsafe {
            phpc_native_symbol_table_bind_reference_path(
                table,
                list_alias.as_ptr(),
                list_alias.len(),
                ptr::null(),
                0,
                false,
                append_ref,
            )
        });
        unsafe {
            write_symbol_path(
                table,
                "list_alias",
                Value::String("through-append".to_string()),
            )
        };
        let appended_slot = unsafe {
            phpc_native_symbol_table_reference_for_path(
                table,
                list.as_ptr(),
                list.len(),
                &zero_key,
                1,
                false,
            )
        };
        assert!(!phpc_native_reference_is_null(appended_slot));
        unsafe { assert_reference_value(appended_slot, b"through-append") };

        let value_path_source_ref = unsafe {
            phpc_native_symbol_table_reference_for_value_path(table, &source_value_key, 1, false)
        };
        assert!(!phpc_native_reference_is_null(value_path_source_ref));
        unsafe {
            set_reference_value(
                value_path_source_ref,
                Value::String("through-value-root".to_string()),
            )
        };
        unsafe { assert_symbol_value(table, source, b"through-value-root") };

        assert!(unsafe {
            phpc_native_symbol_table_bind_reference_value_path(
                table,
                &value_alias_key,
                1,
                false,
                value_path_source_ref,
            )
        });
        unsafe {
            set_reference_value(
                value_path_source_ref,
                Value::String("through-value-bind".to_string()),
            )
        };
        unsafe { assert_symbol_value(table, value_alias, b"through-value-bind") };

        let value_path_append_ref = unsafe {
            phpc_native_symbol_table_reference_for_value_path(table, &value_list_key, 1, true)
        };
        assert!(!phpc_native_reference_is_null(value_path_append_ref));
        unsafe {
            set_reference_value(
                value_path_append_ref,
                Value::String("through-value-append".to_string()),
            )
        };
        let value_path_appended_slot = unsafe {
            let keys = [value_list_key, zero_key];
            phpc_native_symbol_table_reference_for_value_path(
                table,
                keys.as_ptr(),
                keys.len(),
                false,
            )
        };
        assert!(!phpc_native_reference_is_null(value_path_appended_slot));
        unsafe { assert_reference_value(value_path_appended_slot, b"through-value-append") };

        unsafe { write_symbol(table, scalar, Value::Int(7)) };
        let invalid_ref = unsafe {
            phpc_native_symbol_table_reference_for_path(
                table,
                scalar.as_ptr(),
                scalar.len(),
                &slot_key,
                1,
                false,
            )
        };
        assert!(phpc_native_reference_is_null(invalid_ref));

        unsafe { phpc_native_reference_free(source_ref) };
        unsafe { phpc_native_reference_free(array_ref) };
        unsafe { phpc_native_reference_free(append_ref) };
        unsafe { phpc_native_reference_free(appended_slot) };
        unsafe { phpc_native_reference_free(value_path_source_ref) };
        unsafe { phpc_native_reference_free(value_path_append_ref) };
        unsafe { phpc_native_reference_free(value_path_appended_slot) };
        unsafe { phpc_native_value_free(slot_key) };
        unsafe { phpc_native_value_free(zero_key) };
        unsafe { phpc_native_value_free(source_value_key) };
        unsafe { phpc_native_value_free(value_alias_key) };
        unsafe { phpc_native_value_free(value_list_key) };
        unsafe { phpc_native_symbol_table_free(table) };
    }

    #[test]
    fn native_request_state_operation_result_diagnostic_covers_status_family() {
        for result in [
            NativeRequestStateOperationResult::value(
                Value::String("ok".to_string()),
                true,
                true,
                NativeRequestStateOperationStatus::Ok,
            ),
            NativeRequestStateOperationResult::array(
                PhpArray::new(),
                true,
                NativeRequestStateOperationStatus::Ok,
            ),
            NativeRequestStateOperationResult::presence(
                true,
                true,
                NativeRequestStateOperationStatus::Ok,
            ),
            NativeRequestStateOperationResult::presence(
                false,
                false,
                NativeRequestStateOperationStatus::MissingKey,
            ),
            NativeRequestStateOperationResult::bag_presence(
                true,
                NativeRequestStateOperationStatus::Ok,
            ),
        ] {
            let diagnostic = phpc_native_request_state_operation_result_diagnostic(result);

            assert!(diagnostic.is_null());
            unsafe { phpc_native_request_state_operation_result_free(result) };
            unsafe { phpc_native_diagnostic_free(diagnostic) };
        }

        let missing_value = NativeRequestStateOperationResult::value(
            Value::Null,
            false,
            false,
            NativeRequestStateOperationStatus::MissingKey,
        );
        let missing_diagnostic =
            phpc_native_request_state_operation_result_diagnostic(missing_value);
        assert!(!missing_diagnostic.is_null());
        assert_eq!(
            native_diagnostic_message_for_test(missing_diagnostic),
            NATIVE_REQUEST_STATE_MISSING_KEY_READ_MESSAGE
        );
        assert_eq!(
            unsafe { phpc_native_diagnostic_severity_at(missing_diagnostic, 0) },
            NativeDiagnosticSeverity::Warning.tag()
        );
        unsafe { phpc_native_request_state_operation_result_free(missing_value) };
        unsafe { phpc_native_diagnostic_free(missing_diagnostic) };

        let request_state = phpc_native_request_state_empty();
        let get_root = NativeStringHandle::from_vec(b"_GET".to_vec());
        let key = NativeStringHandle::from_vec(b"absent".to_vec());
        let missing_read = unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                phpc_native_string_bytes(get_root),
                phpc_native_string_len(get_root),
                phpc_native_string_bytes(key),
                phpc_native_string_len(key),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        };
        assert_eq!(
            phpc_native_request_state_operation_result_report_diagnostic(missing_read),
            NATIVE_REQUEST_STATE_MISSING_KEY_READ_MESSAGE.len()
        );
        unsafe { phpc_native_request_state_operation_result_free(missing_read) };

        let missing_presence = unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                phpc_native_string_bytes(get_root),
                phpc_native_string_len(get_root),
                phpc_native_string_bytes(key),
                phpc_native_string_len(key),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        };
        assert_eq!(
            phpc_native_request_state_operation_result_report_diagnostic(missing_presence),
            0
        );
        unsafe { phpc_native_request_state_operation_result_free(missing_presence) };
        unsafe { phpc_native_string_free(key) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_request_state_free(request_state) };

        for (status, expected) in [
            (
                NativeRequestStateOperationStatus::InvalidOperation,
                "native request-state operation failed: invalid operation tag",
            ),
            (
                NativeRequestStateOperationStatus::InvalidAbi,
                "native request-state operation failed: invalid ABI operands",
            ),
            (
                NativeRequestStateOperationStatus::NullState,
                "native request-state operation failed: null request state",
            ),
            (
                NativeRequestStateOperationStatus::UnknownBag,
                "native request-state operation failed: unknown request bag",
            ),
            (
                NativeRequestStateOperationStatus::UnsupportedKeyedBag,
                "native request-state operation failed: keyed access is not supported for this request bag",
            ),
            (
                NativeRequestStateOperationStatus::UnsupportedKeyCoercion,
                "native request-state operation failed: unsupported PHP key coercion",
            ),
            (
                NativeRequestStateOperationStatus::UnsupportedKeyedValue,
                "native request-state operation failed: keyed request-state value is not array-accessible",
            ),
        ] {
            let result = NativeRequestStateOperationResult::unsupported(status);
            let diagnostic = phpc_native_request_state_operation_result_diagnostic(result);

            assert!(!diagnostic.is_null());
            assert_eq!(native_diagnostic_message_for_test(diagnostic), expected);

            unsafe { phpc_native_diagnostic_free(diagnostic) };
        }

        let invalid_status = NativeRequestStateOperationResult {
            status: 0,
            ..NativeRequestStateOperationResult::null()
        };
        let diagnostic = phpc_native_request_state_operation_result_diagnostic(invalid_status);
        assert!(!diagnostic.is_null());
        assert_eq!(
            native_diagnostic_message_for_test(diagnostic),
            "native request-state operation failed: invalid result status"
        );

        unsafe { phpc_native_diagnostic_free(diagnostic) };
    }

    #[test]
    fn native_array_appends_scalars_and_reads_integer_slots() {
        let array = phpc_native_array_empty();

        assert!(unsafe { phpc_native_array_append_scalar(array, phpc_native_int(41)) });
        assert!(unsafe { phpc_native_array_append_scalar(array, phpc_native_bool(true)) });
        assert_eq!(unsafe { phpc_native_array_len(array) }, 2);

        let first = unsafe { phpc_native_array_read_int(array, 0) };
        let second = unsafe { phpc_native_array_read_int(array, 1) };
        let missing = unsafe { phpc_native_array_read_int(array, 2) };

        assert_eq!(native_value_echo_bytes_for_test(first), b"41");
        assert_eq!(native_value_echo_bytes_for_test(second), b"1");
        assert!(missing.is_null());

        unsafe { phpc_native_value_free(first) };
        unsafe { phpc_native_value_free(second) };
        unsafe { phpc_native_value_free(missing) };
        unsafe { phpc_native_array_free(array) };
    }

