    #[test]
    fn native_value_array_query_operand_list_extracts_array_columns() {
        let mut first = PhpArray::new();
        first.insert("id", Value::String("a".to_string()));
        first.insert("name", Value::String("Ada".to_string()));
        let mut second = PhpArray::new();
        second.insert("id", Value::String("b".to_string()));
        second.insert("name", Value::String("Bee".to_string()));
        let mut missing_index = PhpArray::new();
        missing_index.insert("name", Value::String("NoId".to_string()));
        let mut rows = PhpArray::new();
        rows.append(Value::Array(first)).unwrap();
        rows.append(Value::Array(second)).unwrap();
        rows.append(Value::Array(missing_index)).unwrap();

        let rows_handle = NativeValueHandle::from_value(Value::Array(rows));
        let column_key = NativeValueHandle::from_value(Value::String("name".to_string()));
        let index_key = NativeValueHandle::from_value(Value::String("id".to_string()));
        let operands = [column_key, index_key];
        let mut diagnostic = NativeDiagnosticHandle::null();
        let indexed = unsafe {
            phpc_native_value_array_query_operation_with_operands_and_diagnostic(
                rows_handle,
                operands.as_ptr(),
                operands.len(),
                0,
                NATIVE_VALUE_ARRAY_QUERY_COLUMN,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());

        let a_key = NativeValueHandle::from_value(Value::String("a".to_string()));
        let indexed_a = unsafe {
            phpc_native_value_offset_operation_with_diagnostic(
                indexed,
                a_key,
                NativeStringOffsetOperation::Read as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(indexed_a), b"Ada");

        let b_key = NativeValueHandle::from_value(Value::String("b".to_string()));
        let indexed_b = unsafe {
            phpc_native_value_offset_operation_with_diagnostic(
                indexed,
                b_key,
                NativeStringOffsetOperation::Read as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(indexed_b), b"Bee");

        let zero_key = phpc_native_value_from_scalar(phpc_native_int(0));
        let indexed_missing = unsafe {
            phpc_native_value_offset_operation_with_diagnostic(
                indexed,
                zero_key,
                NativeStringOffsetOperation::Read as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(indexed_missing), b"NoId");

        let bad_index_key = phpc_native_value_from_scalar(phpc_native_bool(true));
        let bad_index_operands = [column_key, bad_index_key];
        let bad_index = unsafe {
            phpc_native_value_array_query_operation_with_operands_and_diagnostic(
                rows_handle,
                bad_index_operands.as_ptr(),
                bad_index_operands.len(),
                0,
                NATIVE_VALUE_ARRAY_QUERY_COLUMN,
                &mut diagnostic,
            )
        };
        assert!(bad_index.is_null());
        assert_eq!(
            native_diagnostic_message_for_test(diagnostic),
            "unsupported call array_column(): index key must be int, string, or null in the current subset, got bool"
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        diagnostic = NativeDiagnosticHandle::null();

        let scalar = NativeValueHandle::from_value(Value::Int(42));
        let scalar_failed = unsafe {
            phpc_native_value_array_query_operation_with_operands_and_diagnostic(
                scalar,
                operands.as_ptr(),
                1,
                0,
                NATIVE_VALUE_ARRAY_QUERY_COLUMN,
                &mut diagnostic,
            )
        };
        assert!(scalar_failed.is_null());
        assert_eq!(
            native_diagnostic_message_for_test(diagnostic),
            "unsupported call array_column(): first argument must be array, got int"
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        unsafe { phpc_native_value_free(scalar_failed) };
        unsafe { phpc_native_value_free(scalar) };
        unsafe { phpc_native_value_free(bad_index) };
        unsafe { phpc_native_value_free(bad_index_key) };
        unsafe { phpc_native_value_free(indexed_missing) };
        unsafe { phpc_native_value_free(zero_key) };
        unsafe { phpc_native_value_free(indexed_b) };
        unsafe { phpc_native_value_free(b_key) };
        unsafe { phpc_native_value_free(indexed_a) };
        unsafe { phpc_native_value_free(a_key) };
        unsafe { phpc_native_value_free(indexed) };
        unsafe { phpc_native_value_free(index_key) };
        unsafe { phpc_native_value_free(column_key) };
        unsafe { phpc_native_value_free(rows_handle) };
    }

    #[test]
    fn native_array_lvalue_owner_foreach_iterable_snapshots_keys_values_and_paths() {
        fn assert_entry(
            iterable: NativeValueHandle,
            index: usize,
            expected_key: &[u8],
            expected_value: &[u8],
        ) {
            let key = unsafe { phpc_native_array_foreach_iterable_key_result(iterable, index) };
            assert_eq!(key.tag, NATIVE_ARRAY_LVALUE_OK);
            assert_eq!(native_value_echo_bytes_for_test(key.value), expected_key);
            unsafe { phpc_native_array_lvalue_result_free(key) };

            let value = unsafe { phpc_native_array_foreach_iterable_value_result(iterable, index) };
            assert_eq!(value.tag, NATIVE_ARRAY_LVALUE_OK);
            assert_eq!(
                native_value_echo_bytes_for_test(value.value),
                expected_value
            );
            unsafe { phpc_native_array_lvalue_result_free(value) };
        }

        let mut nested = PhpArray::new();
        nested.insert(ArrayKey::string("inner"), Value::String("slot".to_string()));
        let mut root = PhpArray::new();
        root.insert(ArrayKey::Int(0), Value::Int(10));
        root.insert(ArrayKey::string("named"), Value::Int(20));
        root.insert(ArrayKey::string("items"), Value::Array(nested));

        let handle = NativeArrayHandle::from_array(root);
        let owner = phpc_native_array_lvalue_owner_array(handle);
        let iterable = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(owner, std::ptr::null(), 0)
        };
        assert_eq!(iterable.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            unsafe { phpc_native_array_foreach_iterable_len(iterable.value) },
            3
        );
        assert_entry(iterable.value, 0, b"0", b"10");
        assert_entry(iterable.value, 1, b"named", b"20");

        let items_key = NativeValueHandle::from_value(Value::String("items".to_string()));
        let items_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: items_key,
        }];
        let nested_iterable = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(
                owner,
                items_path.as_ptr(),
                items_path.len(),
            )
        };
        assert_eq!(nested_iterable.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            unsafe { phpc_native_array_foreach_iterable_len(nested_iterable.value) },
            1
        );
        assert_entry(nested_iterable.value, 0, b"inner", b"slot");

        let missing_key = NativeValueHandle::from_value(Value::String("missing".to_string()));
        let missing_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: missing_key,
        }];
        let missing = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(
                owner,
                missing_path.as_ptr(),
                missing_path.len(),
            )
        };
        assert_eq!(missing.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert_eq!(
            native_diagnostic_message_for_test(missing.diagnostic),
            "invalid foreach: missing array lvalue iterable"
        );
        unsafe { phpc_native_array_lvalue_result_free(missing) };

        let append_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_APPEND,
            key: NativeValueHandle::null(),
        }];
        let append = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(
                owner,
                append_path.as_ptr(),
                append_path.len(),
            )
        };
        assert_eq!(append.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert_eq!(
            native_diagnostic_message_for_test(append.diagnostic),
            "array foreach iterable path cannot contain append segments"
        );
        unsafe { phpc_native_array_lvalue_result_free(append) };

        let out_of_range =
            unsafe { phpc_native_array_foreach_iterable_value_result(iterable.value, 99) };
        assert_eq!(out_of_range.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert_eq!(
            native_diagnostic_message_for_test(out_of_range.diagnostic),
            "array foreach value index 99 is out of range"
        );
        unsafe { phpc_native_array_lvalue_result_free(out_of_range) };

        unsafe { phpc_native_array_lvalue_result_free(nested_iterable) };
        unsafe { phpc_native_value_free(missing_key) };
        unsafe { phpc_native_value_free(items_key) };
        unsafe { phpc_native_array_lvalue_result_free(iterable) };
        unsafe { phpc_native_array_free(handle) };
    }

    #[test]
    fn native_array_lvalue_owner_foreach_iterable_supports_reference_slot_owners() {
        fn assert_entry(
            iterable: NativeValueHandle,
            index: usize,
            expected_key: &[u8],
            expected_value: &[u8],
        ) {
            let key = unsafe { phpc_native_array_foreach_iterable_key_result(iterable, index) };
            assert_eq!(key.tag, NATIVE_ARRAY_LVALUE_OK);
            assert_eq!(native_value_echo_bytes_for_test(key.value), expected_key);
            unsafe { phpc_native_array_lvalue_result_free(key) };

            let value = unsafe { phpc_native_array_foreach_iterable_value_result(iterable, index) };
            assert_eq!(value.tag, NATIVE_ARRAY_LVALUE_OK);
            assert_eq!(
                native_value_echo_bytes_for_test(value.value),
                expected_value
            );
            unsafe { phpc_native_array_lvalue_result_free(value) };
        }

        let mut outer = PhpArray::new();
        outer.insert("a", Value::String("one".to_string()));
        outer.insert("b", Value::String("two".to_string()));
        let mut root = PhpArray::new();
        root.insert("name", Value::String("root".to_string()));
        root.insert("outer", Value::Array(outer));

        let original = Value::Array(root.clone());
        let root_reference = PhpReferenceCell::new(Value::Array(root));
        let reference_handle = NativeReferenceHandle::from_cell(root_reference.clone());
        let owner = phpc_native_array_lvalue_owner_reference_slot(reference_handle);

        let iterable = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(owner, std::ptr::null(), 0)
        };
        assert_eq!(iterable.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            unsafe { phpc_native_array_foreach_iterable_len(iterable.value) },
            2
        );
        assert_entry(iterable.value, 0, b"name", b"root");

        let outer_key = NativeValueHandle::from_value(Value::String("outer".to_string()));
        let outer_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: outer_key,
        }];
        let nested_iterable = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(
                owner,
                outer_path.as_ptr(),
                outer_path.len(),
            )
        };
        assert_eq!(nested_iterable.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            unsafe { phpc_native_array_foreach_iterable_len(nested_iterable.value) },
            2
        );
        assert_entry(nested_iterable.value, 0, b"a", b"one");
        assert_entry(nested_iterable.value, 1, b"b", b"two");
        assert_eq!(
            root_reference.value_cloned(),
            original,
            "foreach iterable snapshots must not mutate the reference slot"
        );

        let scalar_reference = PhpReferenceCell::new(Value::Int(42));
        let scalar_handle = NativeReferenceHandle::from_cell(scalar_reference);
        let scalar_owner = phpc_native_array_lvalue_owner_reference_slot(scalar_handle);
        let scalar_iterable = unsafe {
            phpc_native_array_lvalue_owner_foreach_iterable_result(
                scalar_owner,
                std::ptr::null(),
                0,
            )
        };
        assert_eq!(scalar_iterable.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert_eq!(
            native_diagnostic_message_for_test(scalar_iterable.diagnostic),
            "invalid foreach: cannot iterate int array lvalue iterable"
        );

        unsafe { phpc_native_array_lvalue_result_free(scalar_iterable) };
        unsafe { phpc_native_reference_free(scalar_handle) };
        unsafe { phpc_native_array_lvalue_result_free(nested_iterable) };
        unsafe { phpc_native_value_free(outer_key) };
        unsafe { phpc_native_array_lvalue_result_free(iterable) };
        unsafe { phpc_native_reference_free(reference_handle) };
    }

    #[test]
    fn native_array_lvalue_increment_decrement_update_operation_materializes_expression_values() {
        let mut child = PhpArray::new();
        child.insert("inner", Value::Int(9));

        let mut root = PhpArray::new();
        root.insert("direct", Value::Int(4));
        root.insert("float", Value::Float(1.5));
        root.insert("string", Value::String("s".to_string()));
        root.insert("outer", Value::Array(child));

        let handle = NativeArrayHandle::from_array(root);
        let owner = phpc_native_array_lvalue_owner_array(handle);
        let direct_key = NativeValueHandle::from_value(Value::String("direct".to_string()));
        let float_key = NativeValueHandle::from_value(Value::String("float".to_string()));
        let string_key = NativeValueHandle::from_value(Value::String("string".to_string()));
        let outer_key = NativeValueHandle::from_value(Value::String("outer".to_string()));
        let inner_key = NativeValueHandle::from_value(Value::String("inner".to_string()));

        let direct_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: direct_key,
        }];
        let post_increment = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                direct_path.as_ptr(),
                direct_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE,
                NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT,
                NATIVE_ARRAY_LVALUE_INCREMENT,
                NATIVE_ARRAY_LVALUE_POSITION_POST,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(post_increment.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(post_increment.value), b"4");
        unsafe { phpc_native_array_lvalue_result_free(post_increment) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert_eq!(array.value.get("direct"), Some(&Value::Int(5)));

        let pre_increment = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                direct_path.as_ptr(),
                direct_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE,
                NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT,
                NATIVE_ARRAY_LVALUE_INCREMENT,
                NATIVE_ARRAY_LVALUE_POSITION_PRE,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(pre_increment.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(pre_increment.value), b"6");
        unsafe { phpc_native_array_lvalue_result_free(pre_increment) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert_eq!(array.value.get("direct"), Some(&Value::Int(6)));

        let float_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: float_key,
        }];
        let post_decrement_float = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                float_path.as_ptr(),
                float_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE,
                NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT,
                NATIVE_ARRAY_LVALUE_DECREMENT,
                NATIVE_ARRAY_LVALUE_POSITION_POST,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(post_decrement_float.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(post_decrement_float.value),
            b"1.5"
        );
        unsafe { phpc_native_array_lvalue_result_free(post_decrement_float) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert_eq!(array.value.get("float"), Some(&Value::Float(0.5)));

        let nested_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: outer_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: inner_key,
            },
        ];
        let nested_decrement = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                nested_path.as_ptr(),
                nested_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE,
                NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT,
                NATIVE_ARRAY_LVALUE_DECREMENT,
                NATIVE_ARRAY_LVALUE_POSITION_PRE,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(nested_decrement.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(nested_decrement.value),
            b"8"
        );
        unsafe { phpc_native_array_lvalue_result_free(nested_decrement) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        let Value::Array(outer) = array.value.get("outer").expect("outer array remains") else {
            panic!("outer slot should stay an array");
        };
        assert_eq!(outer.get("inner"), Some(&Value::Int(8)));

        let string_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: string_key,
        }];
        let string_increment = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                string_path.as_ptr(),
                string_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE,
                NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT,
                NATIVE_ARRAY_LVALUE_INCREMENT,
                NATIVE_ARRAY_LVALUE_POSITION_PRE,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(string_increment.tag, NATIVE_ARRAY_LVALUE_UNSUPPORTED);
        assert!(
            native_diagnostic_message_for_test(string_increment.diagnostic)
                .contains("supports int and float slots")
        );
        unsafe { phpc_native_array_lvalue_result_free(string_increment) };

        unsafe { phpc_native_value_free(inner_key) };
        unsafe { phpc_native_value_free(outer_key) };
        unsafe { phpc_native_value_free(string_key) };
        unsafe { phpc_native_value_free(float_key) };
        unsafe { phpc_native_value_free(direct_key) };
        unsafe { phpc_native_array_free(handle) };
    }

    #[test]
    fn native_array_lvalue_increment_decrement_missing_slots_recover_with_null_defaults() {
        fn update(
            owner: NativeArrayLvalueOwner,
            path: &[NativeArrayPathSegment],
            op: u8,
            position: u8,
        ) -> NativeArrayLvalueResult {
            unsafe {
                phpc_native_array_lvalue_owner_value_operation_result(
                    owner,
                    path.as_ptr(),
                    path.len(),
                    NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE,
                    NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT,
                    op,
                    position,
                    NativeValueHandle::null(),
                )
            }
        }

        let mut outer = PhpArray::new();
        outer.insert("null_leaf", Value::Null);
        let mut root = PhpArray::new();
        root.insert("nil", Value::Null);
        root.insert("outer", Value::Array(outer));

        let handle = NativeArrayHandle::from_array(root);
        let owner = phpc_native_array_lvalue_owner_array(handle);
        let missing_key = NativeValueHandle::from_value(Value::String("missing".to_string()));
        let nil_key = NativeValueHandle::from_value(Value::String("nil".to_string()));
        let outer_key = NativeValueHandle::from_value(Value::String("outer".to_string()));
        let leaf_key = NativeValueHandle::from_value(Value::String("leaf".to_string()));
        let null_leaf_key = NativeValueHandle::from_value(Value::String("null_leaf".to_string()));
        let down_key = NativeValueHandle::from_value(Value::String("down".to_string()));

        let direct_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: missing_key,
        }];
        let post_increment = update(
            owner,
            &direct_path,
            NATIVE_ARRAY_LVALUE_INCREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_POST,
        );
        assert_eq!(post_increment.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(post_increment.value), b"");
        assert!(
            native_diagnostic_message_for_test(post_increment.diagnostic)
                .contains("undefined array key \"missing\"")
        );
        unsafe { phpc_native_array_lvalue_result_free(post_increment) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert_eq!(array.value.get("missing"), Some(&Value::Int(1)));

        let nested_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: outer_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf_key,
            },
        ];
        let pre_increment = update(
            owner,
            &nested_path,
            NATIVE_ARRAY_LVALUE_INCREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_PRE,
        );
        assert_eq!(pre_increment.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(pre_increment.value), b"1");
        assert!(native_diagnostic_message_for_test(pre_increment.diagnostic)
            .contains("undefined array key \"leaf\""));
        unsafe { phpc_native_array_lvalue_result_free(pre_increment) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        let Value::Array(outer) = array.value.get("outer").expect("outer array remains") else {
            panic!("outer slot should stay an array");
        };
        assert_eq!(outer.get("leaf"), Some(&Value::Int(1)));

        let decrement_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: down_key,
        }];
        let pre_decrement = update(
            owner,
            &decrement_path,
            NATIVE_ARRAY_LVALUE_DECREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_PRE,
        );
        assert_eq!(pre_decrement.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(pre_decrement.value), b"");
        assert!(native_diagnostic_message_for_test(pre_decrement.diagnostic)
            .contains("undefined array key \"down\""));
        unsafe { phpc_native_array_lvalue_result_free(pre_decrement) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert_eq!(array.value.get("down"), Some(&Value::Null));

        let null_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: nil_key,
        }];
        let post_increment_null = update(
            owner,
            &null_path,
            NATIVE_ARRAY_LVALUE_INCREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_POST,
        );
        assert_eq!(post_increment_null.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(post_increment_null.diagnostic.is_null());
        assert_eq!(
            native_value_echo_bytes_for_test(post_increment_null.value),
            b""
        );
        unsafe { phpc_native_array_lvalue_result_free(post_increment_null) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert_eq!(array.value.get("nil"), Some(&Value::Int(1)));

        let nested_null_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: outer_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: null_leaf_key,
            },
        ];
        let pre_increment_null = update(
            owner,
            &nested_null_path,
            NATIVE_ARRAY_LVALUE_INCREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_PRE,
        );
        assert_eq!(pre_increment_null.tag, NATIVE_ARRAY_LVALUE_OK);
        assert!(pre_increment_null.diagnostic.is_null());
        assert_eq!(
            native_value_echo_bytes_for_test(pre_increment_null.value),
            b"1"
        );
        unsafe { phpc_native_array_lvalue_result_free(pre_increment_null) };
        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        let Value::Array(outer) = array.value.get("outer").expect("outer array remains") else {
            panic!("outer slot should stay an array");
        };
        assert_eq!(outer.get("null_leaf"), Some(&Value::Int(1)));

        unsafe { phpc_native_value_free(down_key) };
        unsafe { phpc_native_value_free(null_leaf_key) };
        unsafe { phpc_native_value_free(leaf_key) };
        unsafe { phpc_native_value_free(outer_key) };
        unsafe { phpc_native_value_free(nil_key) };
        unsafe { phpc_native_value_free(missing_key) };
        unsafe { phpc_native_array_free(handle) };
    }

    #[test]
    fn native_array_lvalue_append_increment_decrement_updates_null_slots() {
        fn update(
            owner: NativeArrayLvalueOwner,
            path: &[NativeArrayPathSegment],
            op: u8,
            position: u8,
        ) -> NativeArrayLvalueResult {
            unsafe {
                phpc_native_array_lvalue_owner_value_operation_result(
                    owner,
                    path.as_ptr(),
                    path.len(),
                    NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE,
                    NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT,
                    op,
                    position,
                    NativeValueHandle::null(),
                )
            }
        }

        let mut outer = PhpArray::new();
        outer.insert("stay", Value::String("keep".to_string()));
        let mut root = PhpArray::new();
        root.insert("outer", Value::Array(outer));

        let handle = NativeArrayHandle::from_array(root);
        let owner = phpc_native_array_lvalue_owner_array(handle);
        let append_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_APPEND,
            key: NativeValueHandle::null(),
        }];
        let outer_key = NativeValueHandle::from_value(Value::String("outer".to_string()));
        let nested_append_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: outer_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_APPEND,
                key: NativeValueHandle::null(),
            },
        ];
        let leaf_key = NativeValueHandle::from_value(Value::String("leaf".to_string()));
        let append_suffix_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_APPEND,
                key: NativeValueHandle::null(),
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf_key,
            },
        ];

        let post_increment = update(
            owner,
            &append_path,
            NATIVE_ARRAY_LVALUE_INCREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_POST,
        );
        assert_eq!(post_increment.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(post_increment.value), b"");
        unsafe { phpc_native_array_lvalue_result_free(post_increment) };

        let pre_increment = update(
            owner,
            &append_path,
            NATIVE_ARRAY_LVALUE_INCREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_PRE,
        );
        assert_eq!(pre_increment.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(pre_increment.value), b"1");
        unsafe { phpc_native_array_lvalue_result_free(pre_increment) };

        let nested_post_increment = update(
            owner,
            &nested_append_path,
            NATIVE_ARRAY_LVALUE_INCREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_POST,
        );
        assert_eq!(nested_post_increment.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            native_value_echo_bytes_for_test(nested_post_increment.value),
            b""
        );
        unsafe { phpc_native_array_lvalue_result_free(nested_post_increment) };

        let pre_decrement = update(
            owner,
            &append_path,
            NATIVE_ARRAY_LVALUE_DECREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_PRE,
        );
        assert_eq!(pre_decrement.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(pre_decrement.value), b"");
        unsafe { phpc_native_array_lvalue_result_free(pre_decrement) };

        let append_suffix = update(
            owner,
            &append_suffix_path,
            NATIVE_ARRAY_LVALUE_INCREMENT,
            NATIVE_ARRAY_LVALUE_POSITION_PRE,
        );
        assert_eq!(append_suffix.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert!(native_diagnostic_message_for_test(append_suffix.diagnostic)
            .contains("append increment/decrement suffix"));
        unsafe { phpc_native_array_lvalue_result_free(append_suffix) };

        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert_eq!(array.value.get(0), Some(&Value::Int(1)));
        assert_eq!(array.value.get(1), Some(&Value::Int(1)));
        assert_eq!(array.value.get(2), Some(&Value::Null));
        let Value::Array(outer) = array.value.get("outer").expect("outer array remains") else {
            panic!("outer slot should remain an array");
        };
        assert_eq!(outer.get(0), Some(&Value::Int(1)));
        assert_eq!(outer.get("stay"), Some(&Value::String("keep".to_string())));

        unsafe { phpc_native_value_free(leaf_key) };
        unsafe { phpc_native_value_free(outer_key) };
        unsafe { phpc_native_array_free(handle) };
    }

    #[test]
    fn native_array_lvalue_owner_write_operation_materializes_direct_nested_and_missing_paths() {
        let mut child = PhpArray::new();
        child.insert("inner", Value::String("old".to_string()));
        child.insert("stay", Value::String("keep".to_string()));

        let mut root = PhpArray::new();
        root.insert("direct", Value::Int(1));
        root.insert("outer", Value::Array(child));

        let handle = NativeArrayHandle::from_array(root);
        let owner = phpc_native_array_lvalue_owner_array(handle);
        let direct_key = NativeValueHandle::from_value(Value::String("direct".to_string()));
        let outer_key = NativeValueHandle::from_value(Value::String("outer".to_string()));
        let inner_key = NativeValueHandle::from_value(Value::String("inner".to_string()));
        let created_key = NativeValueHandle::from_value(Value::String("created".to_string()));
        let leaf_key = NativeValueHandle::from_value(Value::String("leaf".to_string()));
        let direct_value = NativeValueHandle::from_value(Value::String("written".to_string()));
        let nested_value = NativeValueHandle::from_value(Value::String("nested".to_string()));
        let created_value = NativeValueHandle::from_value(Value::Int(9));

        let direct_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: direct_key,
        }];
        let direct = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                direct_path.as_ptr(),
                direct_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                direct_value,
            )
        };
        assert_eq!(direct.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(direct) };

        let nested_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: outer_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: inner_key,
            },
        ];
        let nested = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                nested_path.as_ptr(),
                nested_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                nested_value,
            )
        };
        assert_eq!(nested.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(nested) };

        let created_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: created_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf_key,
            },
        ];
        let created = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                created_path.as_ptr(),
                created_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                created_value,
            )
        };
        assert_eq!(created.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(created) };

        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert_eq!(
            array.value.get("direct"),
            Some(&Value::String("written".to_string()))
        );
        let outer = array.value.get("outer").expect("outer array remains");
        let Value::Array(outer) = outer else {
            panic!("outer slot should remain an array");
        };
        assert_eq!(
            outer.get("inner"),
            Some(&Value::String("nested".to_string()))
        );
        assert_eq!(outer.get("stay"), Some(&Value::String("keep".to_string())));
        let created = array
            .value
            .get("created")
            .expect("missing parent path should autovivify");
        let Value::Array(created) = created else {
            panic!("created slot should be an array");
        };
        assert_eq!(created.get("leaf"), Some(&Value::Int(9)));

        let scalar_nested_value = NativeValueHandle::from_value(Value::Int(10));
        let scalar_nested_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: direct_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf_key,
            },
        ];
        let scalar_nested = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                scalar_nested_path.as_ptr(),
                scalar_nested_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                scalar_nested_value,
            )
        };
        assert_eq!(scalar_nested.tag, NATIVE_ARRAY_LVALUE_INVALID_ROOT);
        assert!(native_diagnostic_message_for_test(scalar_nested.diagnostic)
            .contains("requires the shared scalar-to-array warning/recovery boundary"));
        unsafe { phpc_native_array_lvalue_result_free(scalar_nested) };

        unsafe { phpc_native_value_free(scalar_nested_value) };
        unsafe { phpc_native_value_free(created_value) };
        unsafe { phpc_native_value_free(nested_value) };
        unsafe { phpc_native_value_free(direct_value) };
        unsafe { phpc_native_value_free(leaf_key) };
        unsafe { phpc_native_value_free(created_key) };
        unsafe { phpc_native_value_free(inner_key) };
        unsafe { phpc_native_value_free(outer_key) };
        unsafe { phpc_native_value_free(direct_key) };
        unsafe { phpc_native_array_free(handle) };
    }

    #[test]
    fn native_array_lvalue_owner_write_operation_materializes_nested_append_paths() {
        let mut existing_child = PhpArray::new();
        existing_child.insert("stay", Value::String("keep".to_string()));

        let mut root = PhpArray::new();
        root.insert("outer", Value::Array(existing_child));
        root.insert("root", Value::String("R".to_string()));

        let handle = NativeArrayHandle::from_array(root);
        let owner = phpc_native_array_lvalue_owner_array(handle);
        let outer_key = NativeValueHandle::from_value(Value::String("outer".to_string()));
        let created_key = NativeValueHandle::from_value(Value::String("created".to_string()));
        let leaf_key = NativeValueHandle::from_value(Value::String("leaf".to_string()));
        let existing_append_value = NativeValueHandle::from_value(Value::String("A".to_string()));
        let missing_append_value = NativeValueHandle::from_value(Value::String("B".to_string()));
        let suffix_append_value = NativeValueHandle::from_value(Value::String("C".to_string()));

        let existing_append_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: outer_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_APPEND,
                key: NativeValueHandle::null(),
            },
        ];
        let existing_append = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                existing_append_path.as_ptr(),
                existing_append_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                existing_append_value,
            )
        };
        assert_eq!(existing_append.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(existing_append) };

        let missing_append_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: created_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_APPEND,
                key: NativeValueHandle::null(),
            },
        ];
        let missing_append = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                missing_append_path.as_ptr(),
                missing_append_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                missing_append_value,
            )
        };
        assert_eq!(missing_append.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(missing_append) };

        let suffix_append_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_APPEND,
                key: NativeValueHandle::null(),
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf_key,
            },
        ];
        let suffix_append = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                suffix_append_path.as_ptr(),
                suffix_append_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                suffix_append_value,
            )
        };
        assert_eq!(suffix_append.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(suffix_append) };

        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        let outer = array.value.get("outer").expect("outer array remains");
        let Value::Array(outer) = outer else {
            panic!("outer slot should remain an array");
        };
        assert_eq!(outer.get("stay"), Some(&Value::String("keep".to_string())));
        assert_eq!(
            outer.get(0),
            Some(&Value::String("A".to_string())),
            "append below an existing keyed child should use the child's append cursor"
        );
        let created = array
            .value
            .get("created")
            .expect("missing parent append path should autovivify");
        let Value::Array(created) = created else {
            panic!("created slot should be an array");
        };
        assert_eq!(created.get(0), Some(&Value::String("B".to_string())));
        let appended = array
            .value
            .get(0)
            .expect("root append with suffix should append a child array");
        let Value::Array(appended) = appended else {
            panic!("root append slot should be an array");
        };
        assert_eq!(appended.get("leaf"), Some(&Value::String("C".to_string())));

        let unset_append = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                existing_append_path.as_ptr(),
                existing_append_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET,
                0,
                0,
                0,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(unset_append.tag, NATIVE_ARRAY_LVALUE_INVALID_KEY);
        assert!(native_diagnostic_message_for_test(unset_append.diagnostic)
            .contains("unset path cannot contain an append segment"));
        unsafe { phpc_native_array_lvalue_result_free(unset_append) };

        unsafe { phpc_native_value_free(suffix_append_value) };
        unsafe { phpc_native_value_free(missing_append_value) };
        unsafe { phpc_native_value_free(existing_append_value) };
        unsafe { phpc_native_value_free(leaf_key) };
        unsafe { phpc_native_value_free(created_key) };
        unsafe { phpc_native_value_free(outer_key) };
        unsafe { phpc_native_array_free(handle) };
    }

    #[test]
    fn native_array_lvalue_owner_unset_operation_materializes_direct_and_nested_paths() {
        let mut child = PhpArray::new();
        child.insert("inner", Value::String("drop".to_string()));
        child.insert("stay", Value::String("keep".to_string()));

        let mut root = PhpArray::new();
        root.insert("direct", Value::Int(1));
        root.insert(2, Value::Int(2));
        root.insert("outer", Value::Array(child));

        let handle = NativeArrayHandle::from_array(root);
        let owner = phpc_native_array_lvalue_owner_array(handle);
        let direct_key = NativeValueHandle::from_value(Value::String("direct".to_string()));
        let int_key = NativeValueHandle::from_value(Value::Int(2));
        let outer_key = NativeValueHandle::from_value(Value::String("outer".to_string()));
        let inner_key = NativeValueHandle::from_value(Value::String("inner".to_string()));

        let direct_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: direct_key,
        }];
        let direct = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                direct_path.as_ptr(),
                direct_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET,
                0,
                0,
                0,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(direct.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(direct) };

        let int_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: int_key,
        }];
        let int_unset = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                int_path.as_ptr(),
                int_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET,
                0,
                0,
                0,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(int_unset.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(int_unset) };

        let nested_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: outer_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: inner_key,
            },
        ];
        let nested = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                nested_path.as_ptr(),
                nested_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET,
                0,
                0,
                0,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(nested.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(nested) };

        let array = unsafe { handle.as_ref() }.expect("array handle remains live");
        assert!(!array.value.contains_key("direct"));
        assert!(!array.value.contains_key(2));
        let outer = array
            .value
            .get("outer")
            .expect("outer array remains after nested unset");
        let Value::Array(outer) = outer else {
            panic!("outer slot should remain an array");
        };
        assert!(!outer.contains_key("inner"));
        assert_eq!(
            outer.get("stay"),
            Some(&Value::String("keep".to_string())),
            "nested unset should not remove sibling keys"
        );

        unsafe { phpc_native_value_free(inner_key) };
        unsafe { phpc_native_value_free(outer_key) };
        unsafe { phpc_native_value_free(int_key) };
        unsafe { phpc_native_value_free(direct_key) };
        unsafe { phpc_native_array_free(handle) };
    }

    #[test]
    fn native_array_lvalue_owner_reference_slot_routes_value_operation_families() {
        let leaf_reference = PhpReferenceCell::new(Value::String("start".to_string()));
        let mut nested = PhpArray::new();
        nested.insert_reference("leaf", leaf_reference.clone());

        let mut root = PhpArray::new();
        root.insert("outer", Value::Array(nested));
        root.insert("counter", Value::Int(4));

        let root_reference = PhpReferenceCell::new(Value::Array(root));
        let reference_handle = NativeReferenceHandle::from_cell(root_reference.clone());
        let owner = phpc_native_array_lvalue_owner_reference_slot(reference_handle);

        let outer_key = NativeValueHandle::from_value(Value::String("outer".to_string()));
        let leaf_key = NativeValueHandle::from_value(Value::String("leaf".to_string()));
        let counter_key = NativeValueHandle::from_value(Value::String("counter".to_string()));
        let created_key = NativeValueHandle::from_value(Value::String("created".to_string()));
        let replacement = NativeValueHandle::from_value(Value::String("written".to_string()));
        let created_value =
            NativeValueHandle::from_value(Value::String("materialized".to_string()));

        let leaf_path = [
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: outer_key,
            },
            NativeArrayPathSegment {
                tag: NATIVE_ARRAY_PATH_KEY,
                key: leaf_key,
            },
        ];
        let write = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                leaf_path.as_ptr(),
                leaf_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                replacement,
            )
        };
        assert_eq!(write.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(
            leaf_reference.value_cloned(),
            Value::String("written".to_string())
        );
        unsafe { phpc_native_array_lvalue_result_free(write) };

        let read = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                leaf_path.as_ptr(),
                leaf_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_READ,
                0,
                0,
                0,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(read.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(read.value), b"written");
        unsafe { phpc_native_array_lvalue_result_free(read) };

        let isset = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                leaf_path.as_ptr(),
                leaf_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_ISSET,
                0,
                0,
                0,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(isset.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(isset.value), b"1");
        unsafe { phpc_native_array_lvalue_result_free(isset) };

        let counter_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: counter_key,
        }];
        let increment = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                counter_path.as_ptr(),
                counter_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UPDATE,
                NATIVE_ARRAY_LVALUE_VALUE_RESULT_INCREMENT_DECREMENT,
                NATIVE_ARRAY_LVALUE_INCREMENT,
                NATIVE_ARRAY_LVALUE_POSITION_PRE,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(increment.tag, NATIVE_ARRAY_LVALUE_OK);
        assert_eq!(native_value_echo_bytes_for_test(increment.value), b"5");
        unsafe { phpc_native_array_lvalue_result_free(increment) };

        let unset = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                owner,
                leaf_path.as_ptr(),
                leaf_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_UNSET,
                0,
                0,
                0,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(unset.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(unset) };

        let Value::Array(root_after_unset) = root_reference.value_cloned() else {
            panic!("reference owner root should remain an array");
        };
        assert_eq!(root_after_unset.get("counter"), Some(&Value::Int(5)));
        let Value::Array(outer_after_unset) = root_after_unset
            .get("outer")
            .expect("outer array should remain")
        else {
            panic!("outer slot should remain an array");
        };
        assert!(!outer_after_unset.contains_key("leaf"));

        let null_root = PhpReferenceCell::new(Value::Null);
        let null_handle = NativeReferenceHandle::from_cell(null_root.clone());
        let null_owner = phpc_native_array_lvalue_owner_reference_slot(null_handle);
        let created_path = [NativeArrayPathSegment {
            tag: NATIVE_ARRAY_PATH_KEY,
            key: created_key,
        }];
        let materialized = unsafe {
            phpc_native_array_lvalue_owner_value_operation_result(
                null_owner,
                created_path.as_ptr(),
                created_path.len(),
                NATIVE_ARRAY_LVALUE_VALUE_OPERATION_WRITE,
                0,
                0,
                0,
                created_value,
            )
        };
        assert_eq!(materialized.tag, NATIVE_ARRAY_LVALUE_OK);
        unsafe { phpc_native_array_lvalue_result_free(materialized) };
        let Value::Array(null_after_write) = null_root.value_cloned() else {
            panic!("null reference owner should materialize to an array for writes");
        };
        assert_eq!(
            null_after_write.get("created"),
            Some(&Value::String("materialized".to_string()))
        );

        unsafe { phpc_native_reference_free(null_handle) };
        unsafe { phpc_native_value_free(created_value) };
        unsafe { phpc_native_value_free(replacement) };
        unsafe { phpc_native_value_free(created_key) };
        unsafe { phpc_native_value_free(counter_key) };
        unsafe { phpc_native_value_free(leaf_key) };
        unsafe { phpc_native_value_free(outer_key) };
        unsafe { phpc_native_reference_free(reference_handle) };
    }

    #[test]
    fn native_string_distance_operations_reuse_value_to_string_boundary() {
        let left = NativeValueHandle::from_value(Value::String("kitten".to_string()));
        let right = NativeValueHandle::from_value(Value::String("sitting".to_string()));
        let binary_left = NativeValueHandle::from_value(Value::String("A\0B\u{ff}".to_string()));
        let binary_right = NativeValueHandle::from_value(Value::String("A\0C\u{ff}".to_string()));
        let scalar_left = phpc_native_value_from_scalar(phpc_native_int(42042));
        let scalar_right = phpc_native_value_from_scalar(phpc_native_int(42));
        let mut diagnostic = NativeDiagnosticHandle::null();

        let distance = unsafe {
            phpc_native_value_string_distance_operation_with_diagnostic(
                left,
                right,
                1,
                1,
                1,
                NativeStringDistanceOperation::Levenshtein as u8,
                &mut diagnostic,
            )
        };
        assert_eq!(distance, 3);
        assert!(diagnostic.is_null());

        let weighted_distance = unsafe {
            phpc_native_value_string_distance_operation_with_diagnostic(
                binary_left,
                binary_right,
                1,
                2,
                1,
                NativeStringDistanceOperation::Levenshtein as u8,
                &mut diagnostic,
            )
        };
        assert_eq!(weighted_distance, 2);
        assert!(diagnostic.is_null());

        let similarity = unsafe {
            phpc_native_value_string_distance_operation_with_diagnostic(
                binary_left,
                binary_right,
                1,
                1,
                1,
                NativeStringDistanceOperation::SimilarText as u8,
                &mut diagnostic,
            )
        };
        assert_eq!(similarity, 4);
        assert!(diagnostic.is_null());

        let scalar_distance = unsafe {
            phpc_native_value_string_distance_operation_with_diagnostic(
                scalar_left,
                scalar_right,
                1,
                1,
                1,
                NativeStringDistanceOperation::Levenshtein as u8,
                &mut diagnostic,
            )
        };
        assert_eq!(scalar_distance, 3);
        assert!(diagnostic.is_null());

        let resource = NativeValueHandle::from_value(Value::Resource(7));
        let failed = unsafe {
            phpc_native_value_string_distance_operation_with_diagnostic(
                resource,
                right,
                1,
                1,
                1,
                NativeStringDistanceOperation::Levenshtein as u8,
                &mut diagnostic,
            )
        };
        assert_eq!(failed, 0);
        assert_eq!(
            native_diagnostic_message_for_test(diagnostic),
            "invalid string conversion: resource cannot be converted to string"
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        let unsupported = unsafe {
            phpc_native_value_string_distance_operation_with_diagnostic(
                left,
                right,
                1,
                1,
                1,
                99,
                &mut diagnostic,
            )
        };
        assert_eq!(unsupported, 0);
        assert_eq!(
            native_diagnostic_message_for_test(diagnostic),
            "invalid string conversion: native string distance operation failed: unsupported operation tag"
        );
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        unsafe { phpc_native_value_free(resource) };
        unsafe { phpc_native_value_free(scalar_right) };
        unsafe { phpc_native_value_free(scalar_left) };
        unsafe { phpc_native_value_free(binary_right) };
        unsafe { phpc_native_value_free(binary_left) };
        unsafe { phpc_native_value_free(right) };
        unsafe { phpc_native_value_free(left) };
    }

    #[test]
    fn native_diagnostic_severity_contract_spans_conversion_and_blockers() {
        assert_eq!(NativeDiagnosticSeverity::Notice.tag(), 1);
        assert_eq!(NativeDiagnosticSeverity::Warning.tag(), 2);
        assert_eq!(NativeDiagnosticSeverity::Error.tag(), 3);
        assert_eq!(NativeDiagnosticSeverity::Blocker.tag(), 4);

        assert!(phpc_native_diagnostic_severity_is_known(
            NativeDiagnosticSeverity::Error.tag()
        ));
        assert!(phpc_native_diagnostic_severity_is_known(
            NativeDiagnosticSeverity::Blocker.tag()
        ));
        assert!(!phpc_native_diagnostic_severity_is_known(250));
        assert_eq!(
            phpc_native_diagnostic_severity_mask(NativeDiagnosticSeverity::Warning.tag()),
            1_u32 << 1
        );
        assert_eq!(phpc_native_diagnostic_severity_mask(250), 0);
        assert_eq!(
            phpc_native_diagnostic_error_control_suppression_mask(),
            phpc_native_diagnostic_severity_mask(NativeDiagnosticSeverity::Notice.tag())
                | phpc_native_diagnostic_severity_mask(NativeDiagnosticSeverity::Warning.tag())
        );

        let mut diagnostic = NativeDiagnosticHandle::null();
        let conversion = unsafe {
            phpc_native_value_from_string_with_diagnostic(
                NativeStringHandle::null(),
                &mut diagnostic,
            )
        };
        assert!(conversion.is_null());
        assert_eq!(
            unsafe { phpc_native_diagnostic_severity_at(diagnostic, 0) },
            NativeDiagnosticSeverity::Error.tag()
        );
        assert!(unsafe {
            phpc_native_diagnostic_contains_severity(
                diagnostic,
                NativeDiagnosticSeverity::Error.tag(),
            )
        });
        assert!(!unsafe {
            phpc_native_diagnostic_contains_severity(
                diagnostic,
                NativeDiagnosticSeverity::Blocker.tag(),
            )
        });
        unsafe { phpc_native_diagnostic_free(diagnostic) };
        unsafe { phpc_native_value_free(conversion) };

        let comparison = phpc_native_scalar_compare(phpc_native_int(1), 99, phpc_native_int(1));
        let diagnostic = phpc_native_comparison_result_diagnostic(comparison);
        assert_eq!(
            unsafe { phpc_native_diagnostic_severity_at(diagnostic, 0) },
            NativeDiagnosticSeverity::Blocker.tag()
        );
        assert!(unsafe {
            phpc_native_diagnostic_contains_severity(
                diagnostic,
                NativeDiagnosticSeverity::Blocker.tag(),
            )
        });
        assert!(!unsafe { phpc_native_diagnostic_contains_severity(diagnostic, 250) });
        unsafe { phpc_native_comparison_result_free(comparison) };

        let warning_message = b"include warning";
        let warning = unsafe {
            phpc_native_diagnostic_from_severity_message_bytes(
                NativeDiagnosticSeverity::Warning.tag(),
                warning_message.as_ptr(),
                warning_message.len(),
            )
        };
        assert_eq!(
            unsafe { phpc_native_diagnostic_severity_at(warning, 0) },
            NativeDiagnosticSeverity::Warning.tag()
        );
        assert!(unsafe {
            phpc_native_diagnostic_contains_severity(
                warning,
                NativeDiagnosticSeverity::Warning.tag(),
            )
        });
        assert_eq!(
            native_diagnostic_message_for_test(warning),
            "include warning"
        );
        unsafe { phpc_native_diagnostic_free(warning) };
    }

