    #[test]
    fn class_table_can_remove_last_declared_class_for_registration_rollback() {
        let mut classes = PhpClassTable::new();

        let first = classes.declare_class("First").unwrap();
        let second = classes.declare_class("Second").unwrap();

        classes.remove_last_declared_class(second);
        assert!(classes.lookup_class("Second").is_none());
        assert_eq!(classes.lookup_class("First").unwrap().id(), first);

        let second = classes.declare_class("Second").unwrap();
        assert_eq!(second.index(), 1);
    }

    #[test]
    fn class_metadata_tracks_php_property_and_method_lookup_rules() {
        let mut classes = PhpClassTable::new();
        let id = classes.declare_class("Counter").unwrap();
        let class = classes.get_mut(id).unwrap();

        class
            .add_property(PhpPropertyMetadata::instance("value", Visibility::Private))
            .unwrap();
        class
            .add_property(PhpPropertyMetadata::instance("Value", Visibility::Public))
            .unwrap();
        class
            .add_method(PhpMethodMetadata::instance("increment", Visibility::Public))
            .unwrap();

        assert_eq!(
            class.property("value").unwrap().visibility(),
            Visibility::Private
        );
        assert_eq!(
            class.property("Value").unwrap().visibility(),
            Visibility::Public
        );
        assert!(class.property("VALUE").is_none());
        assert_eq!(class.method("INCREMENT").unwrap().name(), "increment");

        let error = class
            .add_method(PhpMethodMetadata::instance("Increment", Visibility::Public))
            .unwrap_err();
        assert_eq!(
            error.kind(),
            &RuntimeErrorKind::DuplicateClassMember {
                class_name: "Counter".to_string(),
                member_kind: ClassMemberKind::Method,
                member_name: "Increment".to_string(),
            }
        );
        assert_eq!(
            error.message(),
            "class Counter already defines method Increment"
        );

        let error = class
            .add_property(PhpPropertyMetadata::instance("value", Visibility::Public))
            .unwrap_err();
        assert_eq!(
            error.message(),
            "class Counter already defines property value"
        );
    }

    #[test]
    fn object_shape_contains_only_instance_properties_in_declaration_order() {
        let mut classes = PhpClassTable::new();
        let id = classes.declare_class("Packet").unwrap();
        let class = classes.get_mut(id).unwrap();

        class
            .add_property(PhpPropertyMetadata::instance("id", Visibility::Public))
            .unwrap();
        class
            .add_property(PhpPropertyMetadata::static_property(
                "nextId",
                Visibility::Private,
            ))
            .unwrap();
        class
            .add_property(PhpPropertyMetadata::instance(
                "payload",
                Visibility::Protected,
            ))
            .unwrap();

        let shape = class.object_shape();

        assert_eq!(shape.class_id(), id);
        assert_eq!(
            shape.instance_properties(),
            &["id".to_string(), "payload".to_string()]
        );
    }

    #[test]
    fn static_property_storage_initializes_per_request_defaults_and_resets() {
        let mut classes = PhpClassTable::new();
        let counter_id = classes.declare_class("Counter").unwrap();
        let class = classes.get_mut(counter_id).unwrap();
        class
            .add_property(PhpPropertyMetadata::static_property(
                "count",
                Visibility::Public,
            ))
            .unwrap();
        class
            .add_property(
                PhpPropertyMetadata::static_property("typed", Visibility::Public)
                    .with_type_decl(Some("int".to_string())),
            )
            .unwrap();
        class
            .add_property(PhpPropertyMetadata::static_property(
                "untyped",
                Visibility::Public,
            ))
            .unwrap();

        let mut defaults = PhpStaticPropertyDefaults::new();
        defaults
            .add(&classes, counter_id, "count", Value::Int(1))
            .unwrap();

        let mut first = PhpStaticPropertyStorage::from_class_table(&classes, &defaults).unwrap();
        let second = PhpStaticPropertyStorage::from_class_table(&classes, &defaults).unwrap();
        let receiver = PhpStaticPropertyReceiver::Class(counter_id);

        assert_eq!(first.len(), 3);
        assert_eq!(
            first
                .read(
                    &classes,
                    receiver,
                    "count",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            Value::Int(1)
        );
        assert_eq!(
            first
                .read(
                    &classes,
                    receiver,
                    "untyped",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            Value::Null
        );

        let uninitialized = first
            .read(
                &classes,
                receiver,
                "typed",
                PhpStaticPropertyAccessContext::external(),
            )
            .unwrap_err();
        assert_eq!(
            uninitialized.kind(),
            &RuntimeErrorKind::UninitializedTypedProperty {
                class_name: "Counter".to_string(),
                property_name: "typed".to_string(),
            }
        );
        assert_eq!(
            first
                .read_for_isset(
                    &classes,
                    receiver,
                    "typed",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            None
        );

        first
            .write(
                &classes,
                receiver,
                "count",
                Value::Int(2),
                PhpStaticPropertyAccessContext::external(),
            )
            .unwrap();
        assert_eq!(
            first
                .read(
                    &classes,
                    receiver,
                    "count",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            Value::Int(2)
        );
        assert_eq!(
            second
                .read(
                    &classes,
                    receiver,
                    "count",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            Value::Int(1)
        );
        first
            .unset(
                &classes,
                receiver,
                "count",
                PhpStaticPropertyAccessContext::external(),
            )
            .unwrap();
        assert_eq!(
            first
                .read(
                    &classes,
                    receiver,
                    "count",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            Value::Null
        );
        first
            .write(
                &classes,
                receiver,
                "typed",
                Value::Int(9),
                PhpStaticPropertyAccessContext::external(),
            )
            .unwrap();
        first
            .unset(
                &classes,
                receiver,
                "typed",
                PhpStaticPropertyAccessContext::external(),
            )
            .unwrap();
        assert_eq!(
            first
                .read(
                    &classes,
                    receiver,
                    "typed",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap_err()
                .message(),
            "typed property Counter::$typed must not be accessed before initialization"
        );
        assert_eq!(
            first
                .read_for_isset(
                    &classes,
                    receiver,
                    "typed",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            None
        );
        first
            .unset(
                &classes,
                receiver,
                "untyped",
                PhpStaticPropertyAccessContext::external(),
            )
            .unwrap();
        assert_eq!(
            first
                .read(
                    &classes,
                    receiver,
                    "untyped",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            Value::Null
        );

        first.reset_from_class_table(&classes, &defaults).unwrap();
        assert_eq!(
            first
                .read(
                    &classes,
                    receiver,
                    "count",
                    PhpStaticPropertyAccessContext::external()
                )
                .unwrap(),
            Value::Int(1)
        );

        first.clear();
        assert!(first.is_empty());
        let cleanup_error = first
            .read(
                &classes,
                receiver,
                "count",
                PhpStaticPropertyAccessContext::external(),
            )
            .unwrap_err();
        assert_eq!(
            cleanup_error.message(),
            "invalid property access: static property storage for Counter::$count has not been initialized for this request"
        );
    }

